insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'EZK', $b$Y-Êsêkiêl$b$, $b$["SĂMɃŬT Y-ÊSÊKIÊL"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','EZK',1,1,null,$b$Năm rơh pe jât, ta khay puăn, năng prăm khay nây, dôl gâp gŭ ndrel ma phung bu nă, bu mprơh tă bơh bri dak hăn gŭ ta kơh dak krong Kêbar, phung trôk pơk mpơl, jêh ri gâp geh nau tâm saơ mah Brah Ndu.$b$,true),
('bunong-vn','EZK',1,2,null,$b$Ta năng prăm khay nây, (jêng năm rơh prăm nau bu mprơh Hađăch Jêhôjakin tă bơh bri dak),$b$,false),
('bunong-vn','EZK',1,3,null,$b$Yêhôva ngơi ma kôranh ƀư brah Y-Êsêkiêl, kon bu klâu Y-Busi, tâm n'gor Kaldê, ta kơh krong Kêbar; jêh ri ta nây ti Yêhôva dơm ta păng.$b$,false),
('bunong-vn','EZK',1,4,null,$b$Dôl gâp uănh, aơ geh phŭt văch tât tă bơh dor lơ, jêh ri geh ndâr toyh, geh nau ang gŭ jŭm păng, jêh ri geh ŭnh hit ƀa ƀơ tă bơh tŭk, jêh ri tâm nklang ŭnh nây geh nâm bu kông nchrat lơp.$b$,true),
('bunong-vn','EZK',1,5,null,$b$Tâm ndâr tŭk geh rup nâm bu puăn mlâm mpô mpa rêh. Nâm bu pô aơ rup săk jăn khân păng: Khân păng geh rup săk jăn bunuyh,$b$,false),
('bunong-vn','EZK',1,6,null,$b$ƀiă lah ăp mpô mpa rêh nây geh puăn muh măt jêh ri puăn plơp nting năr.$b$,false),
('bunong-vn','EZK',1,7,null,$b$Jâng khân păng sŏng, jêh ri mpang jâng khân păng nâm bu jâng kon ndrôk nkuăng, jêh ri jâng khân păng nchrat lơp nâm bu kông bu lĕ tho.$b$,false),
('bunong-vn','EZK',1,8,null,$b$Tâm dâng nting năr, ta khân păng khân păng geh ti bunuyh da dê. Puăn mlâm mpô mpa rêh nây geh muh măt jêh ri nting năr, jêh ri$b$,false),
('bunong-vn','EZK',1,9,null,$b$nting năr khân păng tâm rđĭl; tơ lah hăn, ăp mlâm khân păng hăn sŏng, mâu blau rle chiau ma ôh.$b$,false),
('bunong-vn','EZK',1,10,null,$b$Bi ma muh măt khân păng, ăp puăn mlâm geh muh măt bunuyh; jêh ri geh muh măt yau mŭr ta pŭng pa ma, geh muh măt ndrôk mpeh pa chiau; jêh ri lĕ puăn mlâm geh muh măt klang da dê.$b$,false),
('bunong-vn','EZK',1,11,null,$b$Tâm ban pô nây lĕ muh măt khân păng. Ntĭng năr khân păng dĭ rlet klơ; ăp mlâm geh bar plơp nting năr tâm rđĭl, jêh ri geh bar plơp nting năr nkrum săk jăn khân păng.$b$,false),
('bunong-vn','EZK',1,12,null,$b$Ăp mlâm hăn sŏng pa năp; ta ntŭk huêng brah hăn, khân păng hăn ta nây, mâu blau rle chiau ma ôh.$b$,false),
('bunong-vn','EZK',1,13,null,$b$Tâm nklang puăn mlâm mpô mpa rêh nây geh ndơ nâm bu rnga ŭnh, jêh ri ŭnh chai hăn rsong ta vah vang puăn mlâm mpô mpa rêh nây; ŭnh nchrang jêh ri geh lơp luh tă bơh ŭnh nây.$b$,false),
('bunong-vn','EZK',1,14,null,$b$Lĕ mpô mpa rêh nây hăn ngăch ngăn ta-aơ ta-ri nâm bu lơp.$b$,false),
('bunong-vn','EZK',1,15,null,$b$Pô ri, dôl gâp uănh ma puăn mlâm mpô mpa rêh nây, aơ, ta neh geh du mlâm jâng ndeh gŭ êp pŭng puăn mlâm mpô mpa rêh nây, ăp mlâm tâm puăn pŭng geh du mlâm jâng ndeh da dê.$b$,true),
('bunong-vn','EZK',1,16,null,$b$Bi ma rup jâng ndeh nây, bu uănh nâm bu lŭ nglar khlay krisôlit; jêh ri lĕ rngôch puăn jâng nây tâm ban da dê, bu ƀư khân păng nâm bu jâng ndeh gŭ tâm trôm jâng ndeh êng ri.$b$,false),
('bunong-vn','EZK',1,17,null,$b$Tơ lah hăn leo pa năp, khân păng hăn puăn trong, mâu blau rle chiau ma ôh.$b$,false),
('bunong-vn','EZK',1,18,null,$b$Puăn mlâm jâng ndeh rvang jêh ri geh năp; rgŏ rvang năp gŭ jŭm geh măt da dê.$b$,false),
('bunong-vn','EZK',1,19,null,$b$Tơ lah puăn mlâm mpô mpa geh hăn, puăn mlâm jâng ndeh nây hăn êp pŭng khân păng; lĕ rngôch mpô mpa rêh hao tă bơh neh, puăn mlâm jâng ndeh nây hao tâm ban lĕ.$b$,false),
('bunong-vn','EZK',1,20,null,$b$Ta ntŭk huêng brah hăn, khân păng hăn lĕ, jêh ri puăn mlâm jâng ndeh hao ndrel ma khân păng, yor lah puăn mlâm mpô mpa rêh nây gŭ tâm ăp mlâm jâng ndeh.$b$,false),
('bunong-vn','EZK',1,21,null,$b$Tơ lah puăn mlâm mpô mpa rêh hăn, khân păng hăn đŏng; tơ lah puăn mlâm mpô mpa rêh hao, puăn mlâm jâng ndeh hao ndrel ma khân păng đŏng; yor lah huêng brah puăn mlâm mpô mpa rêh nây gŭ tâm dâng ndeh.$b$,false),
('bunong-vn','EZK',1,22,null,$b$Ta klơ bôk puăn mlâm mpô mpa rêh, geh nâm bu bok mpân, chrêk nâm bu lŭ rsang, krit ngăn lĭ lam bôk khân păng.$b$,true),
('bunong-vn','EZK',1,23,null,$b$Tâm dâng bok mpân nây, nting năr khân păng lĭ sŏng, nting năr nkrum săk jăn khân păng.$b$,true),
('bunong-vn','EZK',1,24,null,$b$Tơ lah khân păng hăn, gâp tăng nteh rpuh nting năr khân păng nâm bu n'gôr dak toyh djhu djhut, nâm bu bâr Nơm Geh Nau Brah, nteh drơu drơu nâm bu bâr ta han âk; tơ lah khân păng gŭ gâng, khân păng nhop nting năr khân păng.$b$,false),
('bunong-vn','EZK',1,25,null,$b$Geh bâr du luh tă bơh bok mpân bôk khân păng; tơ lah khân păng gŭ gâng nhop lĕ nting năr.$b$,false),
('bunong-vn','EZK',1,26,null,$b$Ta klơ đŭng bôk khân păng geh nâm bu sưng hađăch, nâm bu lŭ khlay Saphir; jêh ri nơm gŭ ta sưng hađăch uănh nâm bu rup du huê bunuyh.$b$,true),
('bunong-vn','EZK',1,27,null,$b$Ntơm bơh gang bŭt hao rlơ̆ klơ gâp saơ nâm bu kông lơp rmah jêh bu tho, nâm bu geh ŭnh gŭ jŭm; jêh ri ntơm bơh gang bŭt trŭnh tâm dâng gâp saơ nâm bu ŭnh, jêh ri geh nau ang gŭ jŭm păng.$b$,false),
('bunong-vn','EZK',1,28,null,$b$Nchrat nchrang nâm bu bêh tung-tĭng ta tŭk dôl bri mih, tâm ban nây lĕ geh nau ang gŭ jŭm păng. Nây jêng nau tâm mpơl rup nau chrêk rmah Yêhôva. Tơ lah gâp saơ nau nây, gâp chŭn muh măt tâm neh, jêh ri gâp tăng bâr du huê Nơm ngơi ma gâp.$b$,false),
('bunong-vn','EZK',2,1,null,$b$Păng lah ma gâp, ơ kon bunuyh jâng may dâk hom jêh ri gâp mra ngơi ma may.$b$,true),
('bunong-vn','EZK',2,2,null,$b$Tơ lah păng ngơi ma gâp, Huêng Brah lăp gŭ tâm gâp jêh ri ăn gâp dâk ma jâng gâp; jêh ri gâp tăng păng ngơi ma gâp.$b$,false),
('bunong-vn','EZK',2,3,null,$b$Păng lah ma gâp, hơi kon bunuyh, gâp prơh may hăn ma kon sau Israel, du mpôl băl vay mơng tâm rdâng, khân păng tâm rdâng jêh đah gâp; khân păng jêh ri phung che khân păng rlau jêh nau vay gâp tât nar aơ.$b$,true),
('bunong-vn','EZK',2,4,null,$b$Phung ƀon lan nây sưr jêh ri dăng bôk. Gâp prơh may hăn ma khân păng, jêh ri ăn may lah ma khân păng, pô aơ nau Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',2,5,null,$b$Gĭt lah khân păng iăt nau may mâu lah mâu iăt (yor lah khân păng jêng ngih mơng vay tâm rdâng) khân păng mra gĭt geh jêh du huê kôranh nơm mbơh lor ta nklang khân păng.$b$,false),
('bunong-vn','EZK',2,6,null,$b$Bi may, hơi kon bunuyh, lơi ta klach đah khân păng ôh, mâu lĕ klach ma nau khân păng ngơi, nđâp tơ lah rtau lok gŭ jŭm may jêh ri may gŭ tâm nklang ndŭr vơng (ndŭr ving) kđôi lĕ. Ngơi ngăn, nđâp tơ lah khân păng jêng ngih phung mơng vay tâm rdâng, may lơi ta klach ôh ma nau khân păng ngơi, mâu lĕ rdja nuih ta năp măt khân păng.$b$,false),
('bunong-vn','EZK',2,7,null,$b$Pô ri, ăn may mbơh nau gâp ngơi ma khân păng, gĭt lah khân păng iăt nau may mâu lah mâu iăt, yor lah khân păng jêng du rplay ƀon mơng vay tâm rdâng.$b$,false),
('bunong-vn','EZK',2,8,null,$b$Ƀiă lah bi may, hơi kon bunuyh, iăt hom nau gâp lah ma may; lơi tâm rdâng ôh nâm bu ngih mơng vay tâm rdâng nây; hă trôm mbung may jêh ri sa ndơ gâp ăn ma may.$b$,true),
('bunong-vn','EZK',2,9,null,$b$Tơ lah gâp uănh, aơ du đah ti yơr ma gâp jêh ri aơ, ti may ndjôt du ndrom sămƀŭt klôt hŏ chih jêh.$b$,true),
('bunong-vn','EZK',2,10,null,$b$Du ndrom sămƀŭt nây ta năp gâp; jêh ri sămƀŭt nây geh nau chih mpeh klơ jêh ri mpeh tâm dâng, jêh ri bu hŏ chih jêh ta nây nau ngơi nhĭm nhhiăng, nau klân rvê, jêh ri nau rêh ni.$b$,false),
('bunong-vn','EZK',3,1,null,$b$Păng lah ma gâp, hơi kon bunuyh, sa hom moh ndơ may saơ; sa hom sămƀŭt klôt aơ, jêh ri hăn ngơi hom ma ngih Israel.$b$,true),
('bunong-vn','EZK',3,2,null,$b$Pô ri gâp hă trôm mbung gâp jêh ri păng ăn gâp sa sămƀŭt klôt nây.$b$,true),
('bunong-vn','EZK',3,3,null,$b$Păng lah ma gâp, hơi kon bunuyh, sa hom sămƀŭt klôt gâp ăn may aơ jêh ri ăn bêng ndŭl ma sămƀŭt klôt aơ. Pô ri gâp sa păng; jêh ri păng jêng njŭng, nâm bu dak sŭt tâm trôm mbung gâp.$b$,false),
('bunong-vn','EZK',3,4,null,$b$Păng lah ma gâp, hơi kon bunuyh, hăn hom ma ngih Israel, jêh ri mbơh nau gâp ngơi ma khân păng.$b$,true),
('bunong-vn','EZK',3,5,null,$b$Yor lah gâp mâu prơh may hăn ôh ma mpôl ngơi nau bu năch, jêh ri jêr gĭt vât (rbăng), ƀiă lah ma ngih Israel.$b$,false),
('bunong-vn','EZK',3,6,null,$b$Mâu prơh ôh may hăn ma âk phung ntil mpôl ngơi nau bu năch jêh ri jêr gĭt rbăng, nau khân păng ngơi nây may mâu dơi gĭt rbăng ôh. N'hêl nê̆ tơ lah gâp prơh may hăn tât ma khân păng, khân păng mra iăt may.$b$,true),
('bunong-vn','EZK',3,7,null,$b$Ƀiă lah ngih Israel mâu iăt nau may ôh, yor lah păng mâu ŭch iăt gâp; yor lah lĕ rngôch ngih Israel jêng dăng bôk dăng kleng da dê.$b$,false),
('bunong-vn','EZK',3,8,null,$b$Aơ, gâp ƀư dăng muh măt may tâm rdâng đah muh măt khân păng, jêh ri kleng may dăng tâm rdâng dah kleng khân păng.$b$,false),
('bunong-vn','EZK',3,9,null,$b$Gâp ƀư kleng may dăng nâm bu lŭ; lơi ta klach đah khân păng ôh, mâu lĕ rdja nuih ta năp măt khân păng, nđâp tơ lah khân păng jêng du rplay ƀon mơng vay tâm rdâng.$b$,false),
('bunong-vn','EZK',3,10,null,$b$Păng lah đŏng ma gâp, hơi kon bunuyh, lĕ rngôch nau gâp mra ngơi ma may ăn may rom tâm nuih n'hâm may, jêh ri iăt ma trôm tôr may.$b$,false),
('bunong-vn','EZK',3,11,null,$b$Hăn hom, tât ma phung bu mprơh tă bơh bri đak, ma phung kon sau ƀon lan may nơm, jêh ri lah ma khân păng, pô aơ nau Yêhôva Brah Ndu lah, gĭt khân păng iăt mâu ŭch iăt ôh.$b$,false),
('bunong-vn','EZK',3,12,null,$b$Rnôk nây Huêng Brah chông gâp leo klơ, jêh ri gâp tăng nteh pa kơi gâp nau n'găr neh ntu ktang ngăn: Mât ton ma nau chrêk rmah Yêhôva tâm ntŭk Păng gŭ!$b$,true),
('bunong-vn','EZK',3,13,null,$b$Jêng nteh rpuh nting năr puăn mlâm mpô mpa rêh rpuh ndrăng khân păng, nteh nây nâm bu n'găr neh ntu ktang ngăn.$b$,true),
('bunong-vn','EZK',3,14,null,$b$Pô ri, Huêng Brah chông gâp leo rlet klơ jêh ri leo rdu gâp ma ntŭk êng; gâp hăn, nuih n'hâm gâp rngot biănh ngăn jêh ri du nuih, ti Yêhôva dơm ta gâp jâk jêr ngăn.$b$,false),
('bunong-vn','EZK',3,15,null,$b$Gâp hăn tât ma phung bu mprơh jêh tă bơh bri dak hăn gŭ ta ƀon Têlavip, gŭ ta kơh dak krong Kêban. Gâp gŭ tâm nklang khân păng, tâm pơh nar, lĕ ra-ai nuih n'hâm jêh.$b$,false),
('bunong-vn','EZK',3,16,null,$b$Lôch pơh nar, Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',3,17,null,$b$Nơm kâp gak ma phung Israel; lah may tăng gâp buay, ăn may ntang gâp mbơh ma khân păng nau gâp ăn khân păng njrăng.$b$,false),
('bunong-vn','EZK',3,18,null,$b$Nâm bu ntĭt gâp lah ma du huê bunuyh mhĭk: Lah gay ma tâm rklaih nau rêh may, ăn may cha lơi, may mra khĭt. Lah gâp lah pô nây, may mâu buay ôh păng, pô ri păng mra khĭt yor nau mhĭk păng; ƀiă lah gâp mra ăn krêp mham păng ta ti may.$b$,true),
('bunong-vn','EZK',3,19,null,$b$Ƀiă lah lah may buay păng jêh ri păng ăt sâl ƀư tih, ƀư mhĭk, păng mra khĭt yor nau mhĭk păng; bi ma may, dơi tâm rklaih jêh huêng may nơm.$b$,false),
('bunong-vn','EZK',3,20,null,$b$Tâm ban lĕ, tơ lah du huê bunuyh sŏng cha lơi nau sŏng păng ƀư nkhơng nau kue, jêh ri gâp mra dơm du ntil nau chêh prah pa năp păng, păng mra ma khĭt. Nau nây, yor lah may mâu mbơh ôh ma bunuyh nây njrăng, yor nây păng mra khĭt tâm nau tih păng; jêh ri kan sŏng păng hŏ ƀư jêh gâp mâu hôm dơi kah gĭt ôh; ƀiă lah mham păng mra ăn kăr (krêp) ta ti may.$b$,false),
('bunong-vn','EZK',3,21,null,$b$Ƀiă lah tơ lah may mbơh ăn nơm sŏng njrăng mâu ƀư tih ôh, jêh ri păng mâu lĕ ƀư tih, n'hêl nanê̆ păng mra rêh, yor lah păng hŏ iăt jêh nau đă njrăng; jêh ri may, tâm rklaih jêh huêng may nơm.$b$,true),
('bunong-vn','EZK',3,22,null,$b$Ti Yêhôva dơm ta gâp, jêh ri păng lah ma gâp, dâk hăn hom ma ntŭk neh lâng, jêh ri ta nây gâp mra ngơi ma may.$b$,true),
('bunong-vn','EZK',3,23,null,$b$Pô ri gâp dâk hăn ma ntŭk neh lâng, ta-aơ, gâp saơ nau chrêk rmah Yêhôva gŭ ta nây, nâm bu nau chrêk rmah gâp hŏ saơ jêh ta kơh krong Kêbar; jêh ri gâp chon chŭn muh măt ta neh.$b$,false),
('bunong-vn','EZK',3,24,null,$b$Ƀiă lah Huêng Brah lăp tâm gâp jêh ri ăn gâp dâk, păng ngơi ma gâp jêh ri lah: Hăn hom, krŭng êng may nơm tâm ngih may.$b$,false),
('bunong-vn','EZK',3,25,null,$b$Hơi kon bunuyh, bu mra chăp may ma rse ndrăn, pô ri may mâu dơi luh du ta nklang phung ƀon lan ôh;$b$,false),
('bunong-vn','EZK',3,26,null,$b$jêh ri gâp mra ăn mpiăt may khan ta mơr dơ̆ may: May mra mlo mâu hôm dơi nduyh khân păng ôh; yor lah khân păng jêng du rplay ƀon vay mơng tâm rdâng.$b$,false),
('bunong-vn','EZK',3,27,null,$b$Ƀiă lah tơ lah gâp ngơi ma may, gâp mra pơk trôm mbung may, jêh ri may mra lah ma khân păng, pô aơ Yêhôva Brah Ndu lah; mbu nơm ŭch iăt, ăn păng gŭ iăt; jêh ri mbu nơm dun mâu ŭch iăt ôh, ăn păng dun hom; yor lah khân păng jêng du rplay ƀon vay mơng tâm rdâng.$b$,false),
('bunong-vn','EZK',4,1,null,$b$Aƀaơ, Hơi kon bunuyh, sŏk hom du rlat neh yăng dơm păng ăn pa năp may, jêh ri ƀư rup du rplay ƀon ta klơ neh yăng nây, jêng ƀon Yêrusalem.$b$,true),
('bunong-vn','EZK',4,2,null,$b$May nchueng lơh ma ƀon nây, ndâk njêng pôih jêh ri ƀư mpêr tâm rdâng đah păng; dăp phung ta han nchueng lơh, jêh ri nkra mâng ƀư klưh lơi mpêr jŭm ƀon tâm rdâng đah păng.$b$,false),
('bunong-vn','EZK',4,3,null,$b$Sŏk đŏng du plơp loih rlat, jêh ri ndâk păng jêng mpêr loih vah vang may đah ƀon, jêh ri rle muh măt may rlet ma ƀon nây; jêh ri ndơm nâm bu ƀon lĕ nchueng. Aơ jêng du nau mbên ăn ma ngih Israel.$b$,true),
('bunong-vn','EZK',4,4,null,$b$Jêh nây, may bêch nkêng pa chiau, jêh ri may mra anh nau tih ngih Israel; yor lah ndah nâm nar may bêch nkêng nây, dah nây lĕ may mra anh nau tih khân păng.$b$,true),
('bunong-vn','EZK',4,5,null,$b$Yor lah gâp hŏ nal nar ma may ndah nâm năm may mra bêch, geh pe rhiăng du rsen nar, (sĭn jât nar) di đah năm khân păng ƀư tih; dah nây lĕ may mra anh nau tih ma ngih Israel.$b$,false),
('bunong-vn','EZK',4,6,null,$b$Pô ri, tơ lah may hŏ ƀư lôch jêh nar nây, jêh ri may bêch tay đŏng, bêch nkêng rle pa ma, jêh ri anh nau tih ăn ma ngih Yuđa; rlau puăn jât nar, gâp nal ăn may du nar jêng du năm.$b$,false),
('bunong-vn','EZK',4,7,null,$b$Ăn may n'gĭl rle muh măt may ma nau bu nchueng ƀon Yêrusalem, klôn ti ao ma nau nchueng lơh ƀon Yêrusalem; may mbơh lor nau tâm rdâng đah khân păng.$b$,false),
('bunong-vn','EZK',4,8,null,$b$Aơ, gâp sŏk rse ndrăn chăp may, jêh ri may mâu hôm blau bêch nkêng gay plăch săk pa chiau pa ma ôh, kŏ tât may ƀư lôch lĕ nar may nchueng ƀon.$b$,false),
('bunong-vn','EZK',4,9,null,$b$Jêh ri sŏk hom ba răch (ba ƀlê) jêh ri ba orgơ, play tuh jêh ri play bai, koi jêh ri ba, dơm ăn ndơ nây tâm ngan pala, jêh ri piăng let ndrel ndơ nây, dŏng ndơ nây ăn ma may sa; ndah nâm jŏ nar may bêch nkêng dah nây lĕ may mra sa ndơ nây, geh pe rhiăng du rsen nar (pe rhiăng sĭn jât nar).$b$,true),
('bunong-vn','EZK',4,10,null,$b$Ndơ may dŏng sa ăn may rnhueh bar jât sêkel ăp nar; may mra sa păng du nar du tơ̆ .$b$,false),
('bunong-vn','EZK',4,11,null,$b$Ăn may rnhueh đŏng dak may nhêt, du kô̆ tâm prao hin, jêh ri nhêt du nar du tơ̆ .$b$,false),
('bunong-vn','EZK',4,12,null,$b$May mra sa piăng let nây nâm bu du glo piăng let bar orgơ, ăn may sŏk ek bunuyh gâm ndơ nây kŏ tât sĭn tra năp măt khân păng.$b$,false),
('bunong-vn','EZK',4,13,null,$b$Yêhôva lah: Ƀư pô nây phung ƀon lan Israel mra sa piăng let ƀơ̆ ƀơch khân păng, tâm nklang phung ntil mpôl bunuyh ta ntŭk gâp mra mprơh du khân păng.$b$,false),
('bunong-vn','EZK',4,14,null,$b$Gâp lah, Ơ Yêhôva Brah Ndu! Aơ, gâp mâu mâp ƀư ƀơ̆ huêng gâp nơm ôh; ntơm bơh gâp jê̆ tât aƀaơ ri, gâp mâu mâp sa ôh mpô mpa khĭt măp mâu lah mpô mpa bri hêk sa, mâu lĕ geh ndơ ƀơ̆ lăp jêh tâm trôm mbung gâp.$b$,false),
('bunong-vn','EZK',4,15,null,$b$Păng plơ̆ lah ma gâp: Uănh hom, gâp mra ăn ma may ek ndrôk ntrok an ek bunuyh, klơ nây may dơi nđông piăng let may.$b$,false),
('bunong-vn','EZK',4,16,null,$b$Pô nây, păng plơ̆ lah tay ma gâp, Hơi kon bunuyh, aơ, gâp mra n'hŭch piăng let khân păng sa ăp nar tâm ƀon Yêrusalem; khân păng mra rnhueh piăng let khân păng sa jêh ri sa ma nau klach. Khân păng mra rnhueh dak khân păng nhêt jêh ri nhêt ma nau uh ah.$b$,false),
('bunong-vn','EZK',4,17,null,$b$Gâp mra ƀư nau aơ gay ma khân păng mâu tŏng piăng let jêh ri dak, tâm uănh măt ndrăng khân păng ma nau uh ah, jêh ri khân păng jêng ra-ai huơi lơn ăp nar yor ma nau kue khân păng.$b$,true),
('bunong-vn','EZK',5,1,null,$b$Hơi kon bunuyh, bi nâm bu may, sŏk hom du n'gâr đao dao dŭt hơr, dŏng ndơ nây nâm bu pêih poih têp, jêh ri poih bôk sŏk (sŏk) may jêh ri têp kang may; sŏk njing rnhueh, jêh ri tâm pă brai sŏk may.$b$,true),
('bunong-vn','EZK',5,2,null,$b$Du kô̆ tâm pe ăn may su lơi tâm ŭnh ta nklang ƀon, tơ lah lĕ lôch jêh nar nchueng ƀon; jêh nây sŏk du kô̆ tâm pe êng, ăn may dŏng đao sreh păng jŭm ƀon; nglĕ dŭt nây dŏng sŏk du kô̆ tâm pe ăn may ntô̆ tâm sial, jêh ri gâp nơm ro mra tŏk đao tĭng pa lơ lơh khân păng.$b$,false),
('bunong-vn','EZK',5,3,null,$b$Tâm lĕ rngôch ndơ hôm e, ăn may sŏk djê̆-lê̆ brai sŏk (sŏk) kât ta ntôr ao jâr may;$b$,false),
('bunong-vn','EZK',5,4,null,$b$bi ma ndơ dăch dŭt, tă bơh brai sŏk may kât nây, ăn may sŏk hom ƀa ƀă jêh ri mƀăr lơi păng tâm ŭnh jêh ri ăn ŭnh sa. Tă bơh nây geh luh du ŭnh tât ma lĕ rngôch ngih Israel.$b$,false),
('bunong-vn','EZK',5,5,null,$b$Pô aơ Yêhôva Brah Ndu lah: Aơ jêng ƀon Yêrusalem, gâp hŏ ndâk jêh păng ta nklang lĕ ntil mpôl bunuyh, jêh ri geh âk bri dak gŭ jŭm păng.$b$,true),
('bunong-vn','EZK',5,6,null,$b$Ma nau ƀai păng tâm rdâng đah nau vay gâp rlau lơn ma lĕ bri dak êng gŭ jŭm păng; yor khân păng dun cha lơi nau vay gâp.$b$,false),
('bunong-vn','EZK',5,7,null,$b$Yor ri, Yêhôva Brah Ndu lah pô aơ: Yor lah khân may jêng phung ƀư uh ah lơn ma phung ntil mpôl gŭ jŭm khân may, jêh ri mâu chuat ôh tĭng ndô̆ nau vay gâp, mâu lĕ ŭch djôt prăp nau gâp ntăm, nđâp ma khân may mâu ƀư tĭng nau ntăm phung ntil mpôl bunuyh gŭ jŭm khân may.$b$,false),
('bunong-vn','EZK',5,8,null,$b$Yor nây, Yêhôva Brah Ndu lah pô aơ: Aơ, gâp, gâp nơm yơh tâm rdâng ma may, jêh ri gâp mra ăn tât nau phat dôih ma may ta năp măt phung ntil mpôl bunuyh êng.$b$,true),
('bunong-vn','EZK',5,9,null,$b$Jêh ri yor lĕ rngôch nau gâp tâm rmot may hŏ ƀư jêh, gâp mra ƀư ma may nau gâp ê hŏ mâp ƀư ôh, jêh ri du nar kăndơ̆ mâu mra ƀư đŏng ôh.$b$,true),
('bunong-vn','EZK',5,10,null,$b$Tâm nklang khân may, phung mbơ̆ mra sa puăch (puăch) kon, kon mra sa puăch (puăch) mbơ̆ . Gâp mra ƀư ăn nau phat dôih tât ma khân may; jêh ri lĕ rngôch phung khân may hôm e klen, gâp mra ƀư ăn păng nhhơt roh sial rdu.$b$,false),
('bunong-vn','EZK',5,11,null,$b$Yêhôva Brah Ndu lah: N'hêl nê̆ tĭng nâm gâp gŭ rêh, yor khân may hŏ ƀư ƀơ̆ ƀơch jêh ntŭk kloh ueh gâp tă bơh lĕ nau mhĭk gâp tâm rmot, yor ri gâp mra ƀư rai may; măt gâp mâu mra nhhuach ma may jêh ri mâu mra yô̆ may ôh.$b$,true),
('bunong-vn','EZK',5,12,null,$b$Du kô̆ tâm pe tâm phung ƀon lan may mra khĭt ma nau ji nkhĭt jêh ri khĭt ma nau ât ji ngot ta nklang may, du kô̆ tâm pe chôt khĭt ma tak đao gŭ jŭm may; jêh ri du kô̆ tâm pe phung tâm may gâp mra ăn nhhơt roh sial rdu jêh ri gâp tŏk đao dao kâp ƀư ma khân păng.$b$,true),
('bunong-vn','EZK',5,13,null,$b$Tâm ban nây lĕ gâp mra nkhŭt lĕ nau gâp nuih, jêh ri ăn tât nau gâp ji nuih ma khân păng kŏ tât mpay gâp mra gŭ mpăn; jêh ri tơ lah gâp ƀư lĕ lôch jêh nau gâp nuih ma khân păng pô ri khân păng mra gĭt gâp, nây gâp nơm jêng Yêhôva hŏ ngơi jêh nau nây ma nau gơih gâp.$b$,true),
('bunong-vn','EZK',5,14,null,$b$Rlau ma nây, gâp mra njêng may ntŭk rngol, jêng du ntil ndơ bu mưch rmot ta nklang phung ntil mpôl bunuyh gŭ jŭm may jêh ri ta năp măt lĕ rngôch phung prot dăch may,$b$,false),
('bunong-vn','EZK',5,15,null,$b$Pô ri tơ lah gâp mra hao ji nuih nduyh nkra may, may mra bêk prêng jêh ri bu mưch rmot, ƀư leo trong bu jêh ri bri gŭ nsoih ăn ma phung bri bu gŭ jŭm may. Gâp yơh jêng Yêhôva ngơi jêh nau nây!$b$,false),
('bunong-vn','EZK',5,16,null,$b$Gâp mra pănh tâm khân may ma hăr kăch jêng nau sa sât ji ngot ƀư ăn khĭt, gâp mra pănh ŭch ƀư rai khân may; gâp mra ntop ăn nau ât ji ngot tât âk lơn ma khân may, jêh ri ƀư n'hŭch lơi piăng let ma khân may sa.$b$,false),
('bunong-vn','EZK',5,17,null,$b$Gâp mra njuăl nau sa sât ji ngot tât ma khân may; jêh ri njuăl mpô mpa bri janh ƀư ma khân may rêh krit êng. Nau ji tưp nkhĭt jêh ri nau pling mham mra tât ma khân may; jêh ri gâp mra ăn nau tâm lơh tât đŏng ma may. Gâp yơh jêng Yêhôva ngơi jêh nau nây.$b$,false),
('bunong-vn','EZK',6,1,null,$b$Nau Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',6,2,null,$b$“Hơi kon bunuyh, rle uănh hom muh măt may rlet phung yôk Israel, jêh ri mbơh lor tâm rdâng đah khân păng,$b$,false),
('bunong-vn','EZK',6,3,null,$b$jêh ri lah: Hơi khân may phung yôk Israel, iăt hom nau Yêhôva Brah Ndu ngơi! Brah Ndu ngơi ma phung nâm, ma phung gôl yôk, sop brŏng, jêh ri ma phung rlŭng: Aơ, gâp, gâp nơm yơh, mra ăn tât nau tâm lơh đah khân may, jêh ri gâp mra ƀư rai ntŭk prêh khân may.$b$,false),
('bunong-vn','EZK',6,4,null,$b$Nơng khân may ƀư brah mra jêng rngol, jêh ri bu mra ƀư deh (pă) lơi n'gâng khân may mbah ma brah măt nar. Gâp mra klŭp mƀăr phung khân may lĕ khĭt bu nkhĭt pa năp rup brah khân may.$b$,true),
('bunong-vn','EZK',6,5,null,$b$Gâp mra dơm săk jăn nuyh khĭt ƀon lan Israel pa năp rup brah khân păng, jêh ri gâp mra srih mbrach nting may jŭm nơng khân may.$b$,false),
('bunong-vn','EZK',6,6,null,$b$Ăp ntŭk khân may gŭ, ƀon toyh khân may jêng ndơ bu ƀư rai; aơ ntŭk prêh khân may mra klưh rlâm jêng rngol, rup brah khân may mbang chah lĕ ƀhiau, n'gâng khân may mbah brah măt nar rai hăch rhên, jêh ri lĕ rngôch kan khân may ƀư roh dơm dam.$b$,false),
('bunong-vn','EZK',6,7,null,$b$Bunuyh khĭt mra cha lôt ta nklang khân may; jêh ri khân may mra gĭt gâp jêng Yêhôva!$b$,false),
('bunong-vn','EZK',6,8,null,$b$Ƀiă lah gâp mra lơi ƀa ƀă tâm phung khân may ăt hôm rêh. Mra geh phung khân may hŏ klaih tă bơh tak đao du gŭ ta nklang phung bri bu, yor lah khân may lĕ du pru pra jêh tâm bri êng.$b$,true),
('bunong-vn','EZK',6,9,null,$b$Lĕ rngôch bunuyh tâm phung khân may hŏ dơi klaih nây mra kah gĭt ma gâp dôl gŭ tâm bri dak bu leo khân may jêng bu nă, tơ lah gâp ƀư chah jêh nuih n'hâm khân păng rŏng ma nau tih hŏ cha lơi gâp jêh; jêh ri măt khân păng lĕ chieh jêh khân păng ŭch tĭng ndô̆ rup brah khân păng. Rnôk nây khân păng tâm rmot êng ma khân păng nơm; yor lĕ nau mhĭk khân păng hŏ ƀư jêh yor tă lĕ rngôch kan tâm rmot khân păng nơm.$b$,false),
('bunong-vn','EZK',6,10,null,$b$Jêh ri khân păng mra gĭt gâp jêng Yêhôva, jêh ri nau gâp ngơi mâu jêng dơm dam ôh ma nau gâp ƀư nau mhĭk aơ ma khân păng.$b$,true),
('bunong-vn','EZK',6,11,null,$b$Pô aơ Yêhôva Brah Ndu lah: “Tap hom ti khân may jêh ri ntrâm jâng, jêh ri lah, ơ tih ngăn! Yor lah lĕ rngôch nau mhĭk dĭng Brah Ndu tâm rmot ngih Israel hŏ ƀư jêh; yor lah păng mra khĭt ma tak đao, nau sa sât ji ngot, jêh ri nau ji nkhĭt.$b$,true),
('bunong-vn','EZK',6,12,null,$b$Nơm gŭ ngai mra khĭt ma nau ji tưp nkhĭt. Nơm gŭ dăch mra chôt khĭt ma tak đao. Nơm hôm e klen, bu mâu nkhĭt ôh, mra khĭt ma nau sa sât ji ngot; ma đah khân păng, gâp mra ăn tât lĕ nau gâp ji nuih.$b$,false),
('bunong-vn','EZK',6,13,null,$b$Tơ lah phung bu nkhĭt nây, khân păng mplâng khĭt nklang rup brah gŭ jŭm nơng khân păng, ta klơ yôk prêh, ta klơ lĕ rngôch mpư̆ yôk, tâm dâng ăp tơm si ndrêh, jêh ri tâm dâng ăp tơm si pŭm, ăp ntŭk khân păng nhhơr ndơ ƀâu kah ma lĕ rngôch rup brah khân păng, nôk nây khân may mra gĭt gâp jêng Yêhôva.$b$,true),
('bunong-vn','EZK',6,14,null,$b$Pô ri gâp mra yơr ti gâp ƀư ma khân păng, jêh ri ăn bri dak khân păng jêng rngol, jêh ri roh yot tâm lĕ rngôch ntŭk khân păng gŭ, ntơm bơh bri rdah tât ma ƀon Dibla. Nôk nây khân păng mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',7,1,null,$b$Yêhôva ngơi ma gâp: Bi may,$b$,true),
('bunong-vn','EZK',7,2,null,$b$Hơi kon bunuyh, pô aơ nau Yêhôva Brah Ndu ngơi ma n'gor bri Israel: Nau tât nglĕ dŭt! Nau tât nglĕ dŭt hŏ tât jêh ma puăn njônh bri!$b$,false),
('bunong-vn','EZK',7,3,null,$b$Aƀaơ aơ, jêng nau tât nglĕ dŭt ma may, jêh ri gâp mra nkhŭt nau gâp ji nuih ma may, jêh ri phat dôih may tĭng nâm trong may chuat hăn; jêh ri gâp mra tâm rmal may yor lĕ nau mhĭk gâp tâm rmot may hŏ ƀư jêh.$b$,false),
('bunong-vn','EZK',7,4,null,$b$Măt gâp uănh mâu nhhuach ôh ma may; mâu lĕ gâp mra geh nau yô̆ ma may; ƀiă lah gâp tâm rmal may yor ma trong may hăn, dôl nau mhĭk gâp tâm rmot gŭ ta nklang may. Khân may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',7,5,null,$b$Pô aơ Yêhôva Brah Ndu lah: Du nau rêh ni, geh knŏng du nau rêh ni! Aơ, nau nây tât jêh.$b$,true),
('bunong-vn','EZK',7,6,null,$b$Nau nglĕ dŭt tât jêh, nau nglĕ dŭt aơ tât jêh; păng dâk tâm lơh đah may, aơ, nau nây tât jêh!$b$,false),
('bunong-vn','EZK',7,7,null,$b$Nau rêh ni tât jêh ma may, Hơi phung gŭ tâm n'gor bri, nau roh yot nal ăn may lĕ tât, rô̆ hŏ tât, nar hŏ dăch jêh, jêng nar geh nau uh ah, mâu hôm geh ôh nau troh hâk răm klơ yôk.$b$,false),
('bunong-vn','EZK',7,8,null,$b$Hôm jê̆ lê̆ gâp mra nkhŭt nau gâp ji nuih ma may, jêh ri ăn mpay nau gâp nuih ma may, jêh ri phat dôih may tĭng nâm trong may chuat hăn; jêh ri gâp mra tâm rmal may yor lĕ rngôch nau gâp rmot may hŏ ƀư jêh.$b$,false),
('bunong-vn','EZK',7,9,null,$b$Măt gâp uănh mâu nhhuach ôh ma may, mâu lĕ gâp mra geh nau yô̆ ma may; gâp tâm rmal may tĭng trong may chuat hăn, nau gâp rmot may gŭ ta nklang may. Rnôk nây khân may mra gĭt gâp jêng Yêhôva, jêng Nơm dong khân may.$b$,false),
('bunong-vn','EZK',7,10,null,$b$Aơ nar nây tât! Aơ păng tât jêh! Nau rêh ni ma may tât jêh; nau kue hŏ luh kao jêh, nau sưr lĕ chăt nse jêh.$b$,true),
('bunong-vn','EZK',7,11,null,$b$Nau ƀư mhĭk văch ma toyh jêh jêng mâng nau ƀai; mâu geh du huê bunuyh tâm phung khân păng hôm e, ndô ndơ âk rmeh khân păng jêh ri nau ndrŏng kuăng khân păng kŏ mâu hôm lĕ, mâu lĕ hôm geh nơm khlay ta nklang khân păng.$b$,false),
('bunong-vn','EZK',7,12,null,$b$Rô̆ nây tât jêh, nar nây dăch jêh. Lơi ăn nơm rvăt hâk răm ôh, mâu lĕ ăn nơm tăch klâng ndrê, yor lah nau ji nuih tât jêh ma lĕ rngôch phung âk khân păng.$b$,false),
('bunong-vn','EZK',7,13,null,$b$Yor lah nơm tăch mâu mra plơ̆ tay ma ndơ păng hŏ tăch jêh ôh, dôl khân păng gŭ rêh. Yor lah nau ji nuih hŏ tât jêh ma phung âk khân păng; jêh ri mâu mra plơ̆ rŭch ôh. Yor lah nau kue khân păng, mâu geh du huê dơi prăp nau rêh păng ôh.$b$,true),
('bunong-vn','EZK',7,14,null,$b$Khân păng hŏ uh jêh nŭng, jêh ri ndrăp jêh ma nau tâm lơh; ƀiă lah mâu geh nơm hăn ma nau tâm lơh ôh, yor lah nau gâp nuih gŭ ta lĕ rngôch phung âk khân păng.$b$,true),
('bunong-vn','EZK',7,15,null,$b$Mpeh pa dih geh tak đao, mpeh tâm trôm geh nau ji tưp nkhĭt jêh ri sa sât ji ngot! Mbu moh bunuyh gŭ tâm mir mra khĭt ma tak đao; mbu nơm gŭ tâm trôm ƀon, khĭt nau sa sât ji ngot jêh ri nau tưp nkhĭt.$b$,true),
('bunong-vn','EZK',7,16,null,$b$Ƀiă lah đơ phung dơi du mra klaih, jêh ri khân păng gŭ ta ka lơ yôk nâm bu plŭk gŭ tâm rlŭng, lĕ rngôch khân păng nhĭm vơl, ăp nơm yor nau kue khân păng ƀư jêh.$b$,false),
('bunong-vn','EZK',7,17,null,$b$Lĕ rngôch ti jêng ra-ai jêh, jêh ri lĕ rngôch kômâk jêng rbăn huơi nâm bu dak!$b$,false),
('bunong-vn','EZK',7,18,null,$b$Khân păng mra nsoh ƀau, jêh ri nau krit put nklâm khân păng; lĕ rngôch muh măt prêng da dê, jêh ri lĕ rngôch bôk jêng plưn da dê.$b$,false),
('bunong-vn','EZK',7,19,null,$b$Khân păng mƀăr lơi prăk khân păng tâm trong toyh, jêh ri mah khân păng jêng ndơ ƀơ̆ ƀơch; prăk jêh ri mah khân păng mâu dơi tâm rklaih khân păng ôh tâm nar Yêhôva ji nuih; khân păng mâu dơi mpay ôh ma ndơ nây gay hơm bêng ndŭl khân păng. Yor lah ndơ nây jêng ndơ ƀư chêh prah tâm nau kue khân păng!$b$,false),
('bunong-vn','EZK',7,20,null,$b$Lĕ rngôch ndơ nkrơ̆ săk khân păng hŏ jêng nau sưr ma păng jêh ri khân păng sŏk dŏng ndơ nây khân păng nkra rup trah gâp rmot jêh ri ndơ mhĭk ƀa ƀă. Yor nây, gâp mra ăn ndơ nây jêng ndơ ƀơ̆ -ƀơch ma khân păng!$b$,false),
('bunong-vn','EZK',7,21,null,$b$Gâp mra jao ndơ nây tâm ti phung bu năch jêng ndơ pit in tâm ban lĕ; jêh ri khân păng mra ƀư bơ̆ ndơ nây.$b$,true),
('bunong-vn','EZK',7,22,null,$b$Gâp mra pôn ndâp muh măt gâp ma khân păng, gay ma khân păng dơi ƀư bơ̆ lơi ntŭk khlay gâp; phung ntŭng mra lăp jêh ri ƀư ƀơ̆ ô băl.$b$,false),
('bunong-vn','EZK',7,23,null,$b$Ndrăp hom rse rvăk! Yor lah n'gor bri bêng ma nau ƀư pling mham, jêh ri ƀon bêng ma nau tih mhĭk,$b$,true),
('bunong-vn','EZK',7,24,null,$b$gâp mra njŭn leo phung ntil mpôl bunuyh mhĭk lơn ŭch pit in ngih khân păng; gâp mra ăn tât nau nglĕ dŭt ma nau sưr khân păng, jêh ri ntŭk kloh ueh khân păng mra ƀư ƀơ̆ lơi.$b$,false),
('bunong-vn','EZK',7,25,null,$b$Tơ lah nau ƀư rai tât! Khân păng mra joi nau đăp mpăn, ƀiă lah mâu dơi geh ôh.$b$,false),
('bunong-vn','EZK',7,26,null,$b$Du nau rêh ni êng đŏng tĭng ndô̆. Lư nau mhĭk jêh ri nau mhĭk êng tĭng ndô̆, khân păng joi du nau tâm saơ tă bơh kôranh nơm mbơh lor, ƀiă lah phung kôranh ƀư brah mâu hôm geh nti nau vay ôh, jêh ri phung bu bŭnh bu ranh mâu hôm dơi kơl nau mĭn ôh.$b$,false),
('bunong-vn','EZK',7,27,null,$b$Hađăch mra klân rvê phung kôranh chiă uănh bêng ma nau rdja nuih, jêh ri ti phung ƀon lan tâm n'gor bri sâr râm yor nau klach. Tĭng nâm trong khân păng chuat hăn, gâp mra ƀư ma khân păng, jêh ri tĭng nâm nau khân păng mĭn gâp mra phat dôih khân păng; jêh ri khân păng mra gĭt ma gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',8,1,null,$b$Năm rơh prao, khay prao, ta năng prăm tâm khay nây, dôl gâp gŭ tâm ngih gâp, ndrel ma phung bu ranh Yuđa gŭ pa năp gâp, ti Yêhôva Brah Ndu pah ta gâp.$b$,true),
('bunong-vn','EZK',8,2,null,$b$Nôk nây gâp saơ, jêh ri aơ, geh nau tâm mpơl nâm bu rup du huê bunuyh: Tă bơh gang bŭt dâk geh ŭnh, jêh ri ntơm bơh bŭt rlet klơ geh nau nchrat lơp nâm bu kông chrêk.$b$,true),
('bunong-vn','EZK',8,3,null,$b$Păng yor ti jêh ri chăl sŏk (sŏk) ta klơ bôk gâp; jêh ri Huêng Brah chông gâp leo klơ vah vang trôk đah neh, jêh ri tâm nau tâm saơ bơh Brah Ndu leo gâp tât ma ƀon Yêrusalem, ta ntŭk lăp mpông pêr tâm nkual tâm trôm, mpeh dor pa lơ; ta nây bu lĕ dơm jêh rup trah nau ntôn, rup brah nây nsônh ma nau ntôn.$b$,false),
('bunong-vn','EZK',8,4,null,$b$Aơ, nau chrêk rmah Brah Ndu Israel gŭ ta nây, nâm bu gâp hŏ uănh nau tâm saơ ta bri rdah.$b$,false),
('bunong-vn','EZK',8,5,null,$b$Păng lah ma gâp, Hơi kon bunuyh, n'gơr uănh hom mpeh dor pa lơ. Pô ri gâp n'gơr măt uănh mpeh dor pa lơ, jêh ri aơ, mpeh dor pa lơ mpông pêr nơng, ntŭk trong lăp, geh rup brah nau ntôn nây.$b$,true),
('bunong-vn','EZK',8,6,null,$b$Păng lah đŏng ma gâp, Hơi kon bunuyh, may saơ lĕ nau khân păng ƀư aơ, jêng nau mhĭk ngăn gâp tâm rmot toyh ma ngih Israel hŏ ƀư tih ta aơ, gay mprơh gâp ngai bơh ntŭk kloh ueh gâp? Ƀiă lah may mra saơ ăt geh nau mhĭk êng đŏng gâp tâm rmot toyh lơn.$b$,false),
('bunong-vn','EZK',8,7,null,$b$Pô ri, păng leo gâp tât mpông nkual nhuang; gâp mêt uănh, saơ du trôm ta mpêr.$b$,true),
('bunong-vn','EZK',8,8,null,$b$Păng lah ma gâp, Hơi kon bunuyh, kuar hom mpêr aơ, tơ lah gâp kuar jêh mpêr, jêh ri saơ du mlâm mpông.$b$,false),
('bunong-vn','EZK',8,9,null,$b$Păng lah ma gâp, lăp hom jêh uănh nau mhĭk gâp tâm rmot ma khân păng gŭ ƀư ta aơ.$b$,false),
('bunong-vn','EZK',8,10,null,$b$Pô ri gâp lăp, uănh saơ; jêh ri aơ, geh ăp ntil rup brah mpa vơr jêh ri mpô mpa ƀơ̆ ƀơch, jêh ri lĕ rngôch rup brah ngih Israel.$b$,true),
('bunong-vn','EZK',8,11,null,$b$Pa năp rup nây geh pơh jât nuyh bu ranh ngih Israel dâk, ndrel ma Y-Jasania kon bu klâu Y-Saphan. Ăp nơm djôt gri su ndơ ƀâu kah, jêh ri nhhŭk ndơ ƀâu kah n'hôl rlet klơ.$b$,true),
('bunong-vn','EZK',8,12,null,$b$Păng lah ma gâp, Hơi kon bunuyh, may lĕ saơ jêh nau phung bu ranh ngih Israel ăp nuyh ƀư tâm ntŭk ngo klĕng, trôm jrô kach nsêr rup brah khân păng? Yor lah khân păng lah pô aơ: Yêhôva mâu saơ ôh; Yêhôva hŏ cha lơi jêh bri aơ!$b$,true),
('bunong-vn','EZK',8,13,null,$b$Păng lah ma gâp: May mra saơ nau mhĭk êng đŏng gâp tâm rmot toyh khân păng ƀư.$b$,false),
('bunong-vn','EZK',8,14,null,$b$Jêh ri păng leo gâp rlet ma ntŭk lăp mpông pêr dor pa lơ tâm ngih Yêhôva; jêh ri aơ, geh phung bu ur gŭ nhĭm vơl ma Y-Tamus.$b$,true),
('bunong-vn','EZK',8,15,null,$b$Păng lah ma gâp, May saơ lĕ nau aơ, Hơi kon bunuyh? Ăt may mra saơ nau mhĭk gâp tâm rmot toyh lơn ma nau aơ.$b$,false),
('bunong-vn','EZK',8,16,null,$b$Jêh nây, păng leo gâp lăp nkual nhuang ta trôm ngih Yêhôva; aơ, ntŭk trong lăp ngih brah Yêhôva, ta vah vang ndring jêh ri nơng, gâp saơ geh tâm bar jât ma prăm nuyh bu klâu, khân păng ndôn kơi mpeh ma ngih Yêhôva, jêh ri rle muh măt rlet pa lơ, gŭ mbah yơk ma măt nar mpeh pa lơ.$b$,true),
('bunong-vn','EZK',8,17,null,$b$Păng lah ma gâp, May lĕ saơ nau aơ, Hơi kon bunuyh? Ngih Yuđa ƀư nau mhĭk lĕ rngôch nau gâp tâm rmot păng ƀư tih ta aơ, jêng du ntil nau jê̆ lê̆ lĕ? Yor lah păng ƀư nau djơh mhĭk khân păng kŏ bêng bri neh; jêh ri nsônh nuih gâp ji nuih. Aơ, khân păng sŏk n'gĭng tơm si dăch trôm muh khân păng:$b$,true),
('bunong-vn','EZK',8,18,null,$b$Pô ri yơh gâp mra ƀư ma nau ji nuih; măt gâp uănh mâu mra yô̆ klâng đŏng ôh; nđâp tơ lah khân păng kuăl nter tăng tât ma tôr gâp, gâp mâu hôm ŭch n'gĭl iăt khân păng ôh.$b$,false),
('bunong-vn','EZK',9,1,null,$b$Rnôk nây Păng nter kuăl nteh tăng tât ma tôr gâp, lah: “Ăn phung mât uănh ƀon toyh aơ, văch dăch hom, ăp nơm djôt ndơ lơh rai.”$b$,true),
('bunong-vn','EZK',9,2,null,$b$Aơ, geh prao nuyh tă bơh mpông mpêr ta klơ mpeh ma dor pa lơ văch tât, ăp nơm djôt ndơ tâm lơh; jêh ri ndrel khân păng geh du huê nsoh ao rôt mhay ta gang ƀŭt păng vân ndơ dơi nchih. Khân păng lăp jêh ri dâk ta meng nơng kông.$b$,false),
('bunong-vn','EZK',9,3,null,$b$Nau chrêk rmah Brah Ndu Israel hao jêh klaih bơh Chêrubim ntŭk păng vay gŭ, hăn tât ta mbong mpông ngih; jêh ri Yêhôva kuăl bunuyh nsoh ao bok mhay, gang bŭt vân geh ndơ nchih.$b$,true),
('bunong-vn','EZK',9,4,null,$b$Păng lah: “Hăn rgăn ƀon Yêrusalem jêh ri chih du nau gĭt mbên ta kleng phung bu klâu vay nter jêh ri rngot yor lĕ rngôch nau mhĭk gâp rmot hŏ ƀư jêh nklang ƀon aơ.”$b$,false),
('bunong-vn','EZK',9,5,null,$b$Jêh nây Păng lah ma phung êng ŭch gay ăn tôr gâp tăng, hăn rgăn hom tâm ƀon tĭng pa kơi bu klâu nsoh ao bok mhay, jêh ri lơh ro; phung ƀon lan; lơi ăn măt khân may uănh nhhuach ôh, jêh ri lơi yô̆ klâng.$b$,true),
('bunong-vn','EZK',9,6,null,$b$Nkhĭt ƀă bu-bŭnh bu-ranh, ƀă mom-ndăm, ƀă druh-rlung, ƀă kon-toh kon se, ƀă bu-ur, nkhĭt lĕ hom; ƀiă lah lơi lơh ôh bu klâu geh chih nau mbên ta kleng; jêh ri ntơm hom tă bơh tâm jrô kloh gâp. Pô ri khân păng ntơm nkhĭt phung bu ranh gŭ pa năp ngih,$b$,true),
('bunong-vn','EZK',9,7,null,$b$jêh ri Păng lah ma khân ô băl: “Ƀư ƀơ̆ hom ngih, ăn bêng ma bunuyh khĭt tâm nkual nhuang ƀon! Hăn hom.” Pô ri khân păng hăn jêh ri nkhĭt bunuyh tâm ƀon.$b$,false),
('bunong-vn','EZK',9,8,null,$b$Dôl khân păng gŭ nkhĭt, bu cha lơi gâp gŭ êng du huê. Gâp chon mon kŭnh muh măt ta neh jêh ri nter, Ơ Yêhôva Brah Ndu! May ŭch nkhŭt nau ji nuih tâm ƀon Yêrusalem gay ƀư rai lơi lĕ rngôch phung Israel, mâu lah mâm ƀư?”$b$,false),
('bunong-vn','EZK',9,9,null,$b$Păng lah pô aơ: Nau tih mhĭk ngih Israel jêh ri Yuđa hŏ jru hâu ngăn, bri neh bêng ma nau pling mham, jêh ri ƀon bêng nau kue; yor lah khân păng lah, Yêhôva hŏ cha lơi jêh bri neh, jêh ri Yêhôva mâu saơ ôh.$b$,true),
('bunong-vn','EZK',9,10,null,$b$Bi gâp, măt gâp mâu mra nhhuach ôh, mâu mra yô̆ klâng lĕ; ƀiă lah gâp mra ntŭp nau khân păng ƀư ta klơ bôk khân păng nơm.$b$,false),
('bunong-vn','EZK',9,11,null,$b$Aơ, bunuyh nsoh ao bok mhay djôt ndơ chih ta gang bŭt păng plơ̆ sĭt mbơh lah: “Gâp ƀư jêh tĭng nâm nau May hŏ ntăm ma gâp.”$b$,true),
('bunong-vn','EZK',10,1,null,$b$Gâp trong uănh, aơ, ta bok put mpơl ta klơ khân păng nâm bu lŭ chrêk Saphir, uănh nâm bu du mlâm sưng hađăch.$b$,true),
('bunong-vn','EZK',10,2,null,$b$Păng lah ma bunuyh nsoh ao bok mhay: “Lăp hom tâm rvang jâng ndeh gŭ rvah tâm rdâng phung chêrubim, ăn bêng đah ti may ma ŭnh rnga tă bơh vah vang phung chêrubim, jêh ri nsrih ndơ nây ta klơ ƀon Yêrusalem.” Bunuyh aơ lăp ntŭk nây ta năp măt gâp.$b$,false),
('bunong-vn','EZK',10,3,null,$b$Tơ lah păng lăp, phung chêrubim tât ta bong mpông ngih;$b$,false),
('bunong-vn','EZK',10,4,null,$b$ngih bêng ndâr tŭk, jêh ri tâm nhuang bêng nau chrat-ang chrêk ma lơp Yêhôva.$b$,false),
('bunong-vn','EZK',10,5,null,$b$Nteh rpuh nting năr chêrubim bu tăng kŏ tât ta nkual nhuang pa dih, nâm bu bâr Brah Ndu Nơm Geh Lĕ Nau Brah, tơ lah Păng ngơi.$b$,false),
('bunong-vn','EZK',10,6,null,$b$Tơ lah Yêhôva ntăm ma bu klâu nsoh ao bok mhay: “Sŏk hom ŭnh tă bơh vah jâng ndeh rvah, bơh vah vang phung chêrubim.” Păng lăp jêh ri dâk ta meng du mlâm jâng ndeh.$b$,true),
('bunong-vn','EZK',10,7,null,$b$Jêh ta nây, du huê chêrubim tă ta nklang phung chêrubim, jêh ri sŏk ŭnh leo ăn tâm ti bunuyh nsoh ao bok mhay; bunuyh aơ sŏk jêh ri luh du hăn.$b$,false),
('bunong-vn','EZK',10,8,null,$b$Pô nây, phung chêrubim tâm mpơl nâm bu geh rup du đah ti bunuyh tâm dâng nting năr khân păng.$b$,false),
('bunong-vn','EZK',10,9,null,$b$Gâp trong uănh, aơ, geh puăn mlâm jâng ndeh rđĭl ta meng phung chêrubim, du mlâm jâng ndeh rđĭl ta meng ăp chêrubim nây; jêh ri jâng ndeh nây tâm mpơl nâm bu lŭ chrêk Krisôlit.$b$,true),
('bunong-vn','EZK',10,10,null,$b$Bi ma rup, lĕ puăn chêrubim nây jêng tâm ban da dê, nâm bu jâng ndeh gŭ tâm trôm jâng ndeh êng ri.$b$,false),
('bunong-vn','EZK',10,11,null,$b$Tơ lah khân păng hăn, khân păng hăn puăn njônh tra năp păng nơm mâu n'gĭl pa ma, pa chiau dôl khân păng hăn. Tĭng nâm jâng pa năp hăn, jâng êng tĭng ndô̆, mâu n'gĭl chiau ma ôh dôl khân păng hăn.$b$,true),
('bunong-vn','EZK',10,12,null,$b$Lam săk jăn khân păng nđâp ma chŭr kuyh khân păng, ti jêh ri nting năr khân păng, jêh ri lĕ rngôch jâng ndeh prăp ăn ma puăn chêrubim nây bêng ma trôm măt gŭ jŭm.$b$,true),
('bunong-vn','EZK',10,13,null,$b$Rnôk nây gâp tăng bu ntơ jâng ndeh nây, “jâng ndeh rvah ndăch.”$b$,false),
('bunong-vn','EZK',10,14,null,$b$Ăp chêrubim geh puăn muh măt, muh măt sa ơm jêng muh măt chêrubim, muh măt rơh bar jêng muh măt bunuyh, muh măt rơh pe jêng muh măt yau mŭr, muh măt rơh puăn jêng muh măt klang.$b$,false),
('bunong-vn','EZK',10,15,null,$b$Pô nây, phung chêrubim hao klơ: Nây jêng mpa rêh gâp hŏ saơ jêh ta dak krong Kêbar.$b$,true),
('bunong-vn','EZK',10,16,null,$b$Tơ lah phung chêrubim hăn, jâng ndeh hăn ta meng khân păng; jêh ri tơ lah phung chêrubim lĭ nting năr khân păng ŭch hao klơ tă bơh neh, jâng ndeh mâu n'gĭl chiau ma ôh.$b$,false),
('bunong-vn','EZK',10,17,null,$b$Tơ lah phung chêrubim gŭ, jâng ndeh gŭ tâm ban lĕ; jêh ri tơ lah chêrubim hao, jâng ndeh hao ndrel khân păng lĕ; yor lah huêng brah mpa rêh gŭ tâm dâng ndeh nây lĕ.$b$,false),
('bunong-vn','EZK',10,18,null,$b$Jêh ri nau chrêk rmah Yêhôva luh tă bơh bong mpông ngih jêh ri hăn gŭ ta klơ chêrubim.$b$,true),
('bunong-vn','EZK',10,19,null,$b$Phung chêrubim lĭ nting năr khân păng jêh ri hao rlet klơ tă bơh neh ta năp măt gâp, dôl khân păng hăn jâng ndeh. Êp meng khân păng hăn ndrel, jêh ri khân păng gŭ ntŭk lăp mpông pêr pa lơ ngih Yêhôva; jêh ri nau chrêk rmah Brah Ndu Israel gŭ ta klơ khân păng.$b$,false),
('bunong-vn','EZK',10,20,null,$b$Aơ jêng mpa rêh gâp saơ jêh tâm dâng Brah Ndu Israel ta dak krong Kêbar; jêh ri gâp gĭt khân păng jêng phung chêrubim.$b$,true),
('bunong-vn','EZK',10,21,null,$b$Ăp chêrubim geh puăn muh măt, jêh ri puăn nting năr; tâm dâng nting năr geh rup nâm bu ti bunuyh.$b$,true),
('bunong-vn','EZK',10,22,null,$b$Bi ma muh măt, khân păng, nây jêng nâm bu muh măt mpơl jêh ma gâp saơ ta dak krong Kêbar. Jêh ri khân păng hăn sŏng rlet pa năp da dê.$b$,false),
('bunong-vn','EZK',11,1,null,$b$Pô nây đŏng, Huêng Brah chông gâp leo klơ, jêh ri njŭn leo gâp tât mpông pêr pa lơ ngih Yêhôva, jêng mpông mpeh pa lơ. Aơ, mpông ntŭk lăp mpông pêr geh bar jât ma prăm nuyh; jêh ri gâp saơ ta nklang khân păng Y-Jasania kon bu klâu Y-Asur, jêh ri Y-Pêlatia kon bu klâu Y-Bênaya jêng phung kôranh ƀon lan da dê.$b$,true),
('bunong-vn','EZK',11,2,null,$b$Păng lah ma gâp, “Hơi kon bunuyh, aơ jêng phung bu klâu ŭch mĭn ƀư nau kue, jêh ri nchơt nklă plĕch rlăm tâm ƀon aơ.$b$,false),
('bunong-vn','EZK',11,3,null,$b$Khân păng lah pô aơ: Aƀaơ ri ê-tât ôh rnôk ndâk ngih! Ƀon aơ jêng glah ƀŭng, he jêng nglay puăch (puăch)?$b$,false),
('bunong-vn','EZK',11,4,null,$b$Yor ri mbơh lor hom nau tâm rdâng đah khân păng; hơi kon bunuyh, mbơh lor hom.”$b$,false),
('bunong-vn','EZK',11,5,null,$b$Huêng Brah Yêhôva jŭr ta gâp, jêh ri lah: Lah hom, pô aơ nau Yêhôva lah: Hơi ngih Israel! Khân may hŏ ngơi jêh ri ƀư pô nây; yor lah gâp gĭt lĕ nau tât tâm nau mĭn khân may.$b$,true),
('bunong-vn','EZK',11,6,null,$b$Khân may hŏ nkhĭt âk râk ngăn bunuyh tâm ƀon aơ, jêh ri ƀư bêng ma bunuyh khĭt tâm lam ăp trong sâng.$b$,false),
('bunong-vn','EZK',11,7,null,$b$Yor nây, Yêhôva lah pô aơ: Bunuyh khĭt khân may hŏ dơm jêh ta nklang ƀon aơ, nây jêng puăch (puăch), ƀon jêng glah ƀŭng; bi khân may gâp mra mprơh du luh tă bơh ƀon aơ.$b$,false),
('bunong-vn','EZK',11,8,null,$b$Khân may klach jêh ma tak đao; jêh ri gâp mra ăn tak đao tât ma khân may, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',11,9,null,$b$Gâp mra ngluh khân may tă bơh ƀon aơ, jêh ri jao khân may tâm ti phung bu năch, jêh ri ăn tât nau phat dôih ma khân may.$b$,false),
('bunong-vn','EZK',11,10,null,$b$Khân may mra cha lôt ma tak đao, gâp mra phat dôih khân may ta n'har bri Israel, jêh ri khân may mra gĭt gâp jêng Yêhôva.$b$,true),
('bunong-vn','EZK',11,11,null,$b$Ƀon aơ mâu mra jêng glah ƀŭng ma khân may ôh, mâu lĕ khân may mra jêng puăch (puăch) ta nklang păng; gâp mra phat dôih khân may ta n'har bri Israel.$b$,true),
('bunong-vn','EZK',11,12,null,$b$Rnôk nây khân may mra gĭt gâp jêng Yêhôva; yor lah khân may mâu chuat tĭng ndô̆ ôh nau gâp ntăm, mâu lĕ ŭch tông ma nau vay gâp; ƀiă lah ƀư tĭng nkhơng nau vay phung mpôl băl bunuyh gŭ jŭm khân may.$b$,false),
('bunong-vn','EZK',11,13,null,$b$Dôl gâp gŭ mbơh, Y-Pêlatia kon bu klâu Y-Bênaya khĭt. Pô ri gâp chon mon chŭn muh măt ta neh jêh ri nter ma bâr huy, lah: Ơ Yêhôva Brah Ndu! May mra ƀư rai ngăn lĕ phung Israel hôm e klen aơ?$b$,true),
('bunong-vn','EZK',11,14,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',11,15,null,$b$Hơi kon bunuyh, phung gŭ tâm ƀon Yêrusalem hŏ ngơi phung oh nâu may, oh nâu may nơm, phung mpôl may bu lĕ mprơh jêh tă bơh bri neh, lĕ ngih Israel, lĕ rngôch khân păng, lah pô aơ: Khân păng lĕ du ngai jêh bơh Yêhôva; bu ăn jêh bri aơ pha he chăm?$b$,false),
('bunong-vn','EZK',11,16,null,$b$Yor nây, lah hom ma khân păng. Pô aơ nau Yêhôva lah: Gâp mprơh khân păng ngai ta nklang phung băl mpôl bunuyh êng, hŏ ƀư chah rai khân păng tâm âk bri dak, ƀiă lah gâp ăt jêng ntŭk kloh ueh ma khân păng jâng jai tâm bri khân păng hăn tât.$b$,false),
('bunong-vn','EZK',11,17,null,$b$Yor nây lah hom, Pô aơ Yêhôva lah: Gâp mra tâm rgum khân may tă bơh ƀon lan lĕ mpôl bunuyh, sŏk sĭt khân may tă bơh bri khân may pru pra jêh, jêh ri gâp mra plơ̆ ăn ma khân may n'gor bri Israel.$b$,false),
('bunong-vn','EZK',11,18,null,$b$Khân păng mra plơ̆ tât ta nây, jêh ri khân păng mra mƀăr lơi lĕ rngôch ntil nau mhĭk ƀơ ƀơch jêh ri lĕ rngôch ndơ gâp tâm rmot du bơh ntŭk nây.$b$,true),
('bunong-vn','EZK',11,19,null,$b$Gâp mra ăn ma khân păng nuih n'hâm mhe, jêh ri dơm tâm khân păng nau mĭn mhe; gâp mra sŏk lơi nuih n'hâm dăng khân păng, jêh ri ăn ma khân păng nuih n'hâm rdơ̆ ,$b$,false),
('bunong-vn','EZK',11,20,null,$b$ri mơ khân păng mra chuat tĭng nau gâp ntăm jêh ri djôt prăp nau vay gâp jêh ri tông păng; khân păng mra jêng ƀon lan gâp, jêh ri gâp mra jêng Brah Ndu ma khân păng.$b$,false),
('bunong-vn','EZK',11,21,null,$b$Ƀiă lah, bi ma phung geh nuih n'hâm tĭng ndô̆ ndơ ƀơ̆ ƀơch jêh ri nau gâp tâm rmot; pô ri gâp mra ntŭp nau khân păng ƀư ta klơ bôk khân păng nơm, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',11,22,null,$b$Rnôk nây, phung chêrubim lĕ nting năr, jêh ri geh jâng ndeh ta meng khân păng; jêh ri nau chrêk rmah Brah Ndu Israel gŭ ta klơ khân păng.$b$,true),
('bunong-vn','EZK',11,23,null,$b$Nau chrêk rmah Brah Ndu hao rlet klơ tă bơh nklang ƀon, jêh ri gŭ ta klơ yôk mpeh pa meng pa lơ ƀon.$b$,false),
('bunong-vn','EZK',11,24,null,$b$Huêng Brah chông gâp leo klơ jêh ri njŭn gâp ăn tâm saơ đah Huêng Brah, Brah Ndu lăp n'gor bri Kaldê, tât ntŭk gŭ phung bu mprơh du tă bri nơm. Jêh ri nau tâm saơ hŏ tâm mpơl jêh gâp saơ hao du ma gâp.$b$,true),
('bunong-vn','EZK',11,25,null,$b$Rnôk nây gâp mbơh ma phung bu mprơh du tă bơh bri nơm lĕ rngôch nau Yêhôva mpơl jêh ăn gâp gĭt.$b$,true),
('bunong-vn','EZK',12,1,null,$b$Nau Yêhôva ngơi đŏng ma gâp:$b$,true),
('bunong-vn','EZK',12,2,null,$b$Hơi kon bunuyh, may gŭ ta nklang du phung ƀon lan vay tâm rdâng, phung geh trôm măt dơi saơ ƀiă lah mâu saơ ôh; geh tôr aơ tăng ƀiă lah mâu ŭch iăt ôh; yor lah nây jêng du mlâm ngih vay tâm rdâng.$b$,false),
('bunong-vn','EZK',12,3,null,$b$Pô ri, Hơi kon bunuyh, ndrăp hom ndô ndơ may djôt leo du trơn, tă bơh n'gor hăn jêng nâm bu bună jêh ri du trơn nôk nar ăn khân păng uănh. Ta năp măt khân păng tă bơh ntŭk may nơm gŭ jêh ri trơn hăn ntŭk êng; tơ lah khân păng jêng du mlâm ngih tâm rdâng kđôi, nanê̆ khân păng mra gĭt vât.$b$,true),
('bunong-vn','EZK',12,4,null,$b$Ăn may djôt leo ndô ndơ may dôl nôk nar ta năp măt khân păng, nâm bu ndô ndơ djôt leo hăn jêng bună ma bri êng; jêh ri may nơm hăn kêng mhaơ, ta năp măt khân păng, nâm bu bunuyh hăn jêng bună ma bri êng.$b$,false),
('bunong-vn','EZK',12,5,null,$b$Ăt ta năp măt khân păng tâm ban lĕ, may lôch trôm tâm mpêr, jêh ta nây tă tâm trôm nây, djôt leo ngluh ndô ndơ pa dih.$b$,true),
('bunong-vn','EZK',12,6,null,$b$Ta năp măt khân păng may ăn ndô ndơ klơ săng-nglik, jêh ri djôt leo hăn dôl bri măng. May nkŭm muh măt, gay lơi hôm may saơ ôh n'gor bri aơ; yor lah găp hŏ njêng may ƀư du nau mbên ma ngih Israel.$b$,true),
('bunong-vn','EZK',12,7,null,$b$Gâp ƀư tĭng nau Kôranh Brah hŏ ntăm ma gâp: Gâp djôt leo ndô ndơ hăn dôl nôk nar nâm bu ndô ndơ, djôt leo hăn jêng bună ma bri êng, tât kêng mhaơ ma ti gâp nơm gâp lôk trôm tâm mpêr. Gâp djôt leo ndô ndơ tâm dôl măng, jêh ri mbăk ta klơ săng nglik gâp ta năp măt khân păng.$b$,true),
('bunong-vn','EZK',12,8,null,$b$Ơm ôi Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',12,9,null,$b$Hơi kon bunuyh, ngih Israel, jêng ngih tâm rdâng nây geh lĕ ôp ma may pô aơ: Moh may ƀư?$b$,false),
('bunong-vn','EZK',12,10,null,$b$Plơ̆ lah hom ma khân păng pô aơ: Kôranh Brah Yêhôva lah ma gâp: Nau anh jâk aơ di ma phung kôranh tâm ƀon Yêrusalem jêh ri ma lĕ rngôch ngih Israel gŭ tâm ƀon nây.$b$,true),
('bunong-vn','EZK',12,11,null,$b$May lah hom, Gâp jêng du ntil ndơ tâm mbên ma khân may: Nâm bu gâp hŏ ƀư jêh, tâm ban pô nây lĕ bu mra ƀư ma khân păng; khân păng mra du luh tă bơh n'gor bri mra hăn krŭng, mra hăn jêng bună.$b$,false),
('bunong-vn','EZK',12,12,null,$b$Kôranh ta nklang khân păng mra anh ndô ndơ klơ săng-nglik păng jêh ri du luh dôl bri măng. Khân păng mra lôk trôm ta mpêr anh ndơ du luh ta nây păng put muh măt, kŏ tât păng mâu dơi saơ ôh bri nây ma măt păng.$b$,true),
('bunong-vn','EZK',12,13,null,$b$Jêh ri gâp mra nthăng geh dăk gâp; jêh ri gâp mra njŭn păng ma ƀon Babilôn tâm bri phung Kaldê. Ƀiă lah păng mâu mra saơ bri nây ôh; jêh ri păng mra khĭt ta nây.$b$,false),
('bunong-vn','EZK',12,14,null,$b$Pô nây, lĕ rngôch phung gŭ jŭm păng, phung kơl păng, jêh ri lĕ rngôch phung ta han păng, gâp mra ƀư chah rai pru pra tĭng phŭt sial, jêh ri gâp mra tŏk đao tĭng gôk khân păng.$b$,false),
('bunong-vn','EZK',12,15,null,$b$Tơ lah gâp ƀư chah rai ăn khân păng nhhơt ta nklang phung mpôl băl bunuyh jêh ri srih pru pra ăn khân păng ma bri dak êng, khân păng mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',12,16,null,$b$Nđâp tơ lah pô nây, gâp mra om, lơi ƀa ƀă tâm phung khân păng klaih tă bơh tak đao, tă bơh nau sa sât ji ngot, jêh ri tă bơh nau ji tưp nkhĭt, ŭch gay khân păng dơi mbơh lĕ nau mhĭk gâp tâm rmot khân păng hŏ ƀư jêh, tâm nklang phung mpôl băl bunuyh khân păng mra hăn gŭ, jêh ri khân păng mra dơi gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',12,17,null,$b$Pô nây, Yêhôva ngơi đŏng ma gâp:$b$,true),
('bunong-vn','EZK',12,18,null,$b$Hơi kon bunuyh, sa hom piăng let tâm nau krit klach, nhêt dak nđâp ma nau râm nsâr jêh ri klach.$b$,false),
('bunong-vn','EZK',12,19,null,$b$Jêh ri mbơh hom ma ƀon lan tâm n'gor, pô aơ Yêhôva Brah Ndu lah di ma phung gŭ tâm ƀon Yêrusalem, jêh ri tâm n'gor Israel: Khân păng sa piăng let khân păng ma nau klach, jêh ri nhêt dak ma nau uh ah, yor lah bu mra pit in lĕ rngôch ndô ndơ tâm n'gor bri khân păng, yor lah nau ƀai lĕ rngôch phung gŭ tâm n'gor nây ƀư jêh.$b$,false),
('bunong-vn','EZK',12,20,null,$b$Bu ƀư rai ƀon toyh geh âk bunuyh gŭ, mra jêng yôk rsong, jêh ri bri dak mra jêng rngol; jêh ri khân may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',12,21,null,$b$Yêhôva ngơi đŏng ma gâp:$b$,true),
('bunong-vn','EZK',12,22,null,$b$Hơi kon bunuyh, geh du nau hôr tâm n'gor bri Israel, lah: Nar jêng jŏ jong, lĕ rngôch nau tâm saơ mpơl mâu geh tâm di ôh! Mâm bu rblang nau nây?$b$,false),
('bunong-vn','EZK',12,23,null,$b$Pô nây mbơh hom ma khân păng, Pô aơ nau Yêhôva Brah Ndu lah: Gâp mra ăn lôch nau hôr aơ, jêh ri khân păng mâu mra dŏng păng đŏng ôh, jêng du nau hôr tâm bri Israel. Ƀiă lah lah hom ma khân păng, Nar tât jêh, jêh ri lĕ nau tâm saơ ntơm di n'hêl nanê̆.$b$,false),
('bunong-vn','EZK',12,24,null,$b$Yor lah mâu mra geh đŏng ôh nau tâm saơ mƀruh mâu lah gru rƀên ndơm tâm ngih Israel.$b$,false),
('bunong-vn','EZK',12,25,null,$b$Ƀiă lah gâp ro yơh Yêhôva mra ngơi, jêh ri nau nây mra tât ngăn. Nau nây mâu hôm mra ntoch đŏng ôh, ƀiă lah tât ro tâm rnôk rô̆ khân may, Ơ ngih phung dăng tâm rdâng! Gâp mra ngơi jêh ri ăn tât ngăn nau nây, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',12,26,null,$b$Yêhôva ngơi đŏng ma gâp:$b$,false),
('bunong-vn','EZK',12,27,null,$b$“Hơi kon bunuyh, aơ ngih Israel lah, ‘Nau păng tâm saơ di đah jŏ nar kăndơ̆ .’$b$,false),
('bunong-vn','EZK',12,28,null,$b$Pô ri lah hom ma khân păng: ‘Pô aơ Yêhôva Brah Ndu lah:’ Mâu geh du rplay ngơi gâp mra rơi hêng ôh, ƀiă lah nau gâp ngơi jêh mra tât ngăn, Yêhôva Brah Ndu lah.”$b$,false),
('bunong-vn','EZK',13,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',13,2,null,$b$Hơi kon bunuyh, mbơh lor hom tâm rdâng đah phung kôranh nơm mbơh lor Israel, mbơh lor jêh ri lah hom ma phung mbơh lor tĭng nâm khân păng mĭn: Iăt hom nau Yêhôva ngơi!$b$,false),
('bunong-vn','EZK',13,3,null,$b$Yêhôva Brah Ndu lah: Rêh ni ngăn ma phung kôranh nơm mbơh lor rluk tĭng ndô̆ nau mĭn khân păng nơm, jêh ri mâu geh du ntil ndơ tâm saơ ôh!$b$,false),
('bunong-vn','EZK',13,4,null,$b$Ơ phung Israel, phung kôranh nơm mbơh lor khân may jêng nâm bu mpik tâm ntŭk bun ndơ lĕ rai!$b$,false),
('bunong-vn','EZK',13,5,null,$b$Phung khân may mâu mâp lăp ôh ntŭk trôm lĕ bruh jêh ri ndâk mon nâp mpêr ma ngih Israel, gay dơi nâp ta nar dâk tâm lơh tâm nar Yêhôva.$b$,false),
('bunong-vn','EZK',13,6,null,$b$Khân păng ngơi jêh nau mƀruh jêh ri ƀư nau ƀŭk rƀên mƀruh; khân păng lah, Yêhôva lah, ƀiă lah Yêhôva mâu mâp prơh khân păng hăn ôh; jêh ri ăt khân păng mĭn ma Yêhôva ăn tât di nau khân păng ngơi.$b$,false),
('bunong-vn','EZK',13,7,null,$b$Tơ lah gâp mâu mâp lah, ƀiă lah khân may lah pô aơ: Yêhôva geh lah, pô ri khân may mâu saơ hĕ nau tâm saơ nklă jêh ri nau ƀŭk rƀên mƀruh, mâm di lĕ nau khân may lah: Yêhôva lah?$b$,false),
('bunong-vn','EZK',13,8,null,$b$Pô ri Yêhôva lah pô aơ: Yor lah khân may ngơi jêh nau ndơm jêh ri saơ jêh nau mƀruh, yor nây, aơ, gâp tâm rdâng đah khân may, Yêhôva Brah Ndu lah.$b$,true),
('bunong-vn','EZK',13,9,null,$b$Ti gâp mra tâm rdâng đah phung kôranh nơm mbơh lor, phung tâm saơ nau mƀruh jêh ri ngơi nau gru rƀên mƀruh. Khân păng mâu mra gŭ ôh tâm nau phung ƀon lan gâp tâm rƀŭn, mâu bu chih ôh amoh khân păng tâm ndrom sămƀŭt chih amoh ngih Israel, mâu lĕ khân păng mra lăp tâm bri Israel; jêh ri khân păng mra gĭt gâp jêng Yêhôva Brah Ndu.$b$,false),
('bunong-vn','EZK',13,10,null,$b$Yor lah n'hêl nanê̆, khân păng ndơm jêh ƀon lan gâp, lah: “Nau đăp mpăn,” ƀiă lah mâu geh nau đăp mpăn ôh; jêh ni tơ lah geh phung ƀon lan ndâk du mlâm mpêr aơ, phung kôranh nơm mbơh lor aơ mhĭng ma klo nglang;$b$,false),
('bunong-vn','EZK',13,11,null,$b$lah hom ma phung mhĭng klo nglang ta mpêr nây mra rlâm! Mra geh dak mih toyh ngăn, pler toyh mra tŭp jêh ri phŭt sial ktang mra mplŭng păng.$b$,false),
('bunong-vn','EZK',13,12,null,$b$Aơ, tơ lah mpêr klưh rlâm, bu mâu mra lah hĕ ma khân may, “Ntŭk klo nglang bu mhĭng jêh ta mpêr nây?”$b$,true),
('bunong-vn','EZK',13,13,null,$b$Yor nây Yêhôva Brah Ndu lah pô aơ: Ma nau gâp ji nuih gâp mra ăn tât phŭt sial toyh; mra geh dak mih toyh mra ƀư rai mpêr nây dôl gâp ji nuih.$b$,false),
('bunong-vn','EZK',13,14,null,$b$Gâp mra ƀư rlâm lơi mpêr khân may lĕ mhĭng ma klo nglang, jêh ri ăn păng cha lôt ta neh, kŏ tât rlơk mpơl mbon păng; tơ lah păng lĕ rlâm, khân may mra khĭt tâm mpêr klân khân may; jêh ri khân may mra gĭt gâp jêng Yêhôva.$b$,true),
('bunong-vn','EZK',13,15,null,$b$Tâm ban lĕ gâp mra nkhŭt nau gâp ji nuih ma mpêr, jêh ri ma phung mhĭng klo nglang ta mpêr nây; jêh ri gâp mra lah ma khân may, “Mâu hôm geh mpêr ôh, mâu lĕ hôm geh bunuyh mhĭng klo nglang,$b$,false),
('bunong-vn','EZK',13,16,null,$b$nây jêng phung kôranh nơm mbơh lor Israel mbơh lor lah ma Yêrusalem, uănh nau tâm saơ đăp mpăn ma ƀon aơ, ƀiă lah mâu geh nau nđăp mpăn ôh, Yêhôva Brah Ndu lah.”$b$,false),
('bunong-vn','EZK',13,17,null,$b$Bi may, Hơi kon bunuyh, rle muh măt may mpeh ma phung kon bu ur ƀon lan may, jêng phung mbơh lor tĭng nâm nau khân păng nơm mĭn; jêh ri may mbơh lor hom nau tâm rdâng đah khân păng,$b$,true),
('bunong-vn','EZK',13,18,null,$b$jêh ri lah, Yêhôva Brah Ndu lah pô aơ: Rêh ni ngăn ma phung bu ur jĭm bok rƀên dok ta ti khân păng, jêh ri tĭng kơt jong gleh dŏng ƀư bok nkŭm bôk, gay nchron nhŭp huêng bunuyh! Khân may mra joi nhŭp huêng bunuyh phung ƀon lan gâp, jêh ri prăp huêng păng hôm rêh geh nau khlay ma khân may nơm lĕ?$b$,false),
('bunong-vn','EZK',13,19,null,$b$Khân may ƀư ƀơ̆ jêh gâp ta nklang phung ƀon lan gâp ŭch gay geh du mbăt ƀiă lah orgơ, jêh ri ŭch geh du gla piăng let, gay ŭch nkhĭt bunuyh mâu khư đah nau khĭt ôh, jêh ri om rêh phung mâu khư ma nau rêh ôh, ma nau khân may mƀruh ma phung ƀon lan gâp, khân păng tŭp lâm iăt nau khân may mƀruh.$b$,false),
('bunong-vn','EZK',13,20,null,$b$Yor nây Yêhôva Brah Ndu lah, pô aơ: Aơ, gâp tâm rdâng đah bok rƀên khân may, ma ndơ nây khân may nchron nhŭp huêng bunuyh nâm bu joi nhŭp sĭm, jêh ri gâp mra nkhêk lơi ndơ nây tă bơh ti khân may; jêh ri gâp mra ăn kon mpeh huêng khân may nhŭp jêh, nâm bu sĭm.$b$,true),
('bunong-vn','EZK',13,21,null,$b$Gâp mra ăp nkhêk đŏng bok khân may nkŭm bôk, jêh ri rklaih phung ƀon lan gâp tă bơh ti khân may, khân păng mâu mra gŭ tâm ti khân may ôh gay hăn nchron joi đŏng; rnôk nây khân may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',13,22,null,$b$Yor lah khân may sŏk nau nchơt mƀruh ƀư rngot nuih n'hâm phung sŏng srăng, nđâp tơ lah gâp mâu mâp ƀư rdja nuih khân păng ôh, jêh ri khân may nsŭk phung ƀai, kŏ tât păng mâu cha lơi ôh bơh trong nau mhĭk păng gay dơi geh nau rêh.$b$,false),
('bunong-vn','EZK',13,23,null,$b$Yor nau nây, khân may mâu mra saơ ôh nau tâm saơ ndơm, mâu lĕ hôm ƀư đŏng nau rƀên. Gâp mra tâm rklaih phung ƀon lan gâp klaih bơh ti khân may, jêh ri khân may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',14,1,null,$b$Geh ƀa ƀă phung bu bŭnh bu ranh Israel văch ta gâp, gŭ pa năp gâp.$b$,true),
('bunong-vn','EZK',14,2,null,$b$Rnôk nây Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',14,3,null,$b$Hơi kon bunuyh, phung aơ prăp rup brah tâm nuih n'hâm khân păng, jêh ri dơm nau kue pa năp khân păng nơm ƀư chêh prah; pô ri jêng ji lĕ gâp ŭch gay ăn khân păng ôp gâp?$b$,false),
('bunong-vn','EZK',14,4,null,$b$Yor ri, ngơi hom ma khân păng, jêh ri lah: Yêhôva Brah Ndu lah pô aơ: Mbu nơm tâm ngih Israel prăp rup brah tâm nuih n'hâm păng jêh ri dơm nau kue pa năp măt păng nơm ƀư ăn chêh prah, tơ lah bunuyh nây văch tât mra kôranh nơm mbơh lor, gâp nơm, Yêhôva mra plơ̆ sĭt lah ma păng yor lah rup brah păng âk ngăn ngên,$b$,true),
('bunong-vn','EZK',14,5,null,$b$gay ma gâp dơi sŭk nsôr ăn nuih n'hâm ngih Israel, phung nkhah du jêh tă bơh gâp yor rup brah khân păng.$b$,false),
('bunong-vn','EZK',14,6,null,$b$Yor nây, lah hom ma ngih Israel, Yêhôva Brah Ndu lah pô aơ: Rmal hom, cha lơi lĕ rup brah khân may; jêh ri rle muh măt du tă bơh lĕ nau mhĭk gâp tâm rmot khân may lĕ ƀư jêh.$b$,true),
('bunong-vn','EZK',14,7,null,$b$Pô nây ngăn yơh, lĕ rngôch phung tâm ngih Israel, lĕ rngôch bu năch gŭ njơh tâm n'gor bri Israel, mbu nơm nkhah păng nơm ngai đah gâp, prăp rup brah păng tâm nuih n'hâm, jêh ri dơm nau kue pa năp măt păng ƀư ăn chêh prah, ƀiă lah ăt văch tât ma kôranh nơm mbơh lor, yor păng nơm ŭch gay ôp gâp, gâp nơm yơh Yêhôva mra plơ̆ lah ma păng.$b$,false),
('bunong-vn','EZK',14,8,null,$b$Jêh ri gâp mra tâm rdâng đah nơm nây, gâp mra ăn păng du nau mbên jêh ri du nau bu mưch rmot, jêh ri ngroh lơi păng bơh ta nklang phung ƀon lan gâp; jêh ri khân may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',14,9,null,$b$Tơ lah kôranh nơm mbơh lor geh nau ntrôl jêh ri ngơi du bâr, gâp nơm Yêhôva hŏ ntrôl jêh kôranh nơm mbơh lor nây, jêh ri gâp mra yơr ti gâp ƀư ma păng, jêh ri ƀư ngroh lơi păng bơh ta nklang phung ƀon lan gâp Israel.$b$,false),
('bunong-vn','EZK',14,10,null,$b$Khân păng mra dơn nau tâm rmal ma kôranh nơm mbơh lor jêh ri nau tâm rmal ma nơm joi ôp nây mra jêng tâm ban dơm,$b$,false),
('bunong-vn','EZK',14,11,null,$b$gay ăn ngih Israel mâu hôm nkhah du đah gâp ôh, mâu lĕ hôm ƀư ƀơ̆ ma khân păng nơm ma nau khân păng rlau nau vay nây, ƀiă lah gay ăn khân păng dơi jêng phung ƀon lan gâp, jêh ri gâp dơi jêng Brah Ndu khân păng, Yêhôva Brah Ndu lah nau nây.$b$,false),
('bunong-vn','EZK',14,12,null,$b$Pô ri, geh nau Yêhôva ngơi ma gâp pô aơ:$b$,true),
('bunong-vn','EZK',14,13,null,$b$“Hơi kon bunuyh, tơ lah du rplay bri ƀư tih đak gâp mâu ƀư di răp jăp ôh, jêh ri tơ lah gâp yơr ti gâp ƀư ma bri nây, jêh ri ƀư n'hŭch lơi ndơ sông sa ma khân păng, ăn nau sa sât ji ngot ma bri nây, jêh ri ƀư rai lĕ bunuyh jêh ri mpô mpa bri tâm bri nây,$b$,false),
('bunong-vn','EZK',14,14,null,$b$nđâp tơ lah tâm bri nây geh pe nuyh aơ, geh Y-Nôê, Y-Daniel, jêh ri Y-Yôp, khân păng dơi tâm rklaih knŏng huêng khân păng nơm yor nau sŏng srăng khân ô băl, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',14,15,null,$b$Tơ lah gâp ăn mpô mpa bri rgăn tâm bri nây, jêh ri ƀư rai lơi bri, ăn bri nây jêng rngol, kŏ tât mâu hôm geh bunuyh hăn prot ta nây đŏng ôh yor lah mpô mpa bri nây janh,$b$,true),
('bunong-vn','EZK',14,16,null,$b$nđâp tơ lah pe nuyh bu klâu aơ gŭ tâm bri nây, Brah Yêhôva lah, ngăn nâm bu gâp rêh, khân păng tâm ban lĕ mâu dơi tâm rklaih ôh kon bu ur mâu lah kon bu klâu khan ô băl, knŏng êng săk khân păng nơm yơh klaih, ƀiă lah bri mra jêng rngol.$b$,false),
('bunong-vn','EZK',14,17,null,$b$Mâu lah, tơ lah gâp ăn nau tâm lơh tât ma bri nây, lah pô aơ: Ăn geh nau tâm lơh ngăn bri nây; kŏ tât gâp ƀư rai lơi bunuyh jêh ri mpô mpa păng,$b$,true),
('bunong-vn','EZK',14,18,null,$b$nđâp tơ lah tâm bri nây geh pe nuyh gŭ ta nây; Brah Yêhôva lah, ngăn nâm bu gâp rêh, khân păng tâm ban lĕ mâu dơi tâm rklaih ôh kon bu ur mâu lah kon bu klâu khân păng, ƀiă lah êng săk khân păng nơm dơi klaih.$b$,false),
('bunong-vn','EZK',14,19,null,$b$Mâu lah, tơ lah gâp njuăl nau ji tưp nkhĭt tât tâm bri nây, jêh ri nkhŭt nau gâp ji nuih ta klơ bri nây ma nau hoch mham, gay ƀư ngroh lơi bunuyh jêh ri mpô mpa tâm bri nây;$b$,false),
('bunong-vn','EZK',14,20,null,$b$nđâp tơ lah Y-Nôê, Y-Daniel, jêh ri Y-Yôp gŭ tâm bri nây, Brah Yêhôva lah, ngăn nâm bu gâp rêh, khân păng tâm ban lĕ mâu dơi tâm nklaih ôh du huê kon bu ur mâu lah kon bu klâu khân păng, knŏng dơi tâm rklaih huêng khân păng nơm yor nau sŏng srăng khân ô băl.$b$,false),
('bunong-vn','EZK',14,21,null,$b$Pô ri, Yêhôva Brah Ndu lah: Rlau lơn ma nây lĕ tơ lah gâp njuăl ma ƀon Yêrusalem puăn ntil nau phat dôih jru ngăn, nau tâm lơh, nau sa sât ji ngot, mpô mpa bri janh ƀư djơh, jêh ri nau ji tưp nkhĭt gay ƀư ngroh lơi bunuyh jêh ri mpô mpa tâm bri nây!$b$,false),
('bunong-vn','EZK',14,22,null,$b$Ƀiă lah ăt mra geh lĕ phung klaih tâm bri dak hôm e rêh, phung kon bu ur jêh ri kon bu klâu djôt leo ngluh. Khân păng mra văch ma khân may, jêh ri tơ lah khân may saơ nau khân păng gŭ ngao jêh ri nau khân păng ƀư, khân păng mra văch ma khân may, jêh ri tơ lah khân may saơ nau khân păng gŭ ngao jêh ri nau khân păng ƀư, khân may mra geh nau bonh leng yor nau mhĭk gâp lĕ ƀư ăn tât jêh ma ƀon nây.$b$,false),
('bunong-vn','EZK',14,23,null,$b$Khân păng mra bonh leng khân may tơ lah khân may saơ nau khân păng gŭ ngao jêh ri khân păng ƀư, jêh ri khân may mra gĭt gâp mâu ƀư ôh lĕ rngôch nau nây tâm ƀon Yêrusalem tơ lah mâu geh nau, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',15,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',15,2,null,$b$“Hơi kon bunuyh, mâm rtau play yôr yar jêng khlay lơn ma n'gĭng tơm si êng lĕ, rtau play yôr yar nây gŭ ndrel ma tơm si tâm krŏng?$b$,false),
('bunong-vn','EZK',15,3,null,$b$Dơi lĕ sŏk rtau păng njêng du ntil ndơ? Phung bunuyh mâp sŏk lĕ ndơ dŏng pơ̆ ng gay yông du ntil ndơ ta păng?$b$,true),
('bunong-vn','EZK',15,4,null,$b$Aơ, bu mƀăr păng tâm ŭnh gay ƀư long, tơ lah ŭnh sa tă bơh bar đah ding chiông jêh ri ta nklang jêng sa ônh, păng hôm jêng khlay ma du ntil ndơ lĕ?$b$,false),
('bunong-vn','EZK',15,5,null,$b$Aơ, tơ lah ŭnh ê-hŏ sa păng, kŏ mâu jêng dŏng ma du ntil ndơ lĕ; ang ma lĕ ŭnh de sa, păng lĕ lêk rai jêh, jêh ri lĕ jêng sa-ônh, moh ndơ bu hôm dơi dŏng păng ma du ntil ndơ êng!$b$,false),
('bunong-vn','EZK',15,6,null,$b$Yor ri, Yêhôva Brah Ndu lah: Nâm bu rtau play yôr yar dop ndrel tơm si tâm krŏng gâp mƀăr jêh tâm ŭnh, tâm ban pô nây lĕ gâp mra ƀư ma phung gŭ tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','EZK',15,7,null,$b$Gâp mra tâm rdâng đah khân păng; nđâp tơ lah khân păng klaih tă bơh ŭnh kđôi lĕ; ăt ŭnh đŏng mra sa khân păng.$b$,false),
('bunong-vn','EZK',15,8,null,$b$Gâp mra ăn bri nây jêng rngol, yor lah khân păng hŏ ƀư tih jêh, Yêhôva Brah Ndu lah nau nây.”$b$,false),
('bunong-vn','EZK',16,1,null,$b$Yêhôva ngơi đŏng ma gâp:$b$,true),
('bunong-vn','EZK',16,2,null,$b$“Hơi kon bunuyh, ăn phung ƀon lan Yêrusalem gĭt nau mhĭk gâp tâm rmot ma khân păng hŏ ƀư jêh,$b$,false),
('bunong-vn','EZK',16,3,null,$b$jêh ri lah hom, pô aơ nau Yêhôva Brah Ndu lah ma ƀon Yêrusalem: Ntŭk ntơm sa ơm jêh ri nau bu deh ma ay jêng ta n'gor Kanaan; mbơ̆ ay jêng du huê Amôrit, jêh ri mê̆ ay jêng du huê Hêtit.$b$,false),
('bunong-vn','EZK',16,4,null,$b$Nar bu deh ma ay, bu mâu koh ôh klŏ ay, mâu lĕ bu nđŭm gay ăn kloh ay, mâu lĕ bu rpôt ay ma dak boh mâu lah bu put ay ma bok.$b$,false),
('bunong-vn','EZK',16,5,null,$b$Mâu geh ôh nơm uănh ma ay geh nau yô̆, gay ŭch ƀư du ntil nau kan nây ăn ay, yor nuih n'hâm yô̆ ma ay; ƀiă lah bu mƀăr ay pa dih, yor lah bu tâm rmot ma ay nar bu deh ma ay.$b$,false),
('bunong-vn','EZK',16,6,null,$b$Tơ lah gâp rgăn dăch ay, saơ ay pung tâm mham ay nơm, gâp lah mah ay pô aơ: Nđâp tơ lah ay pung tâm mham nơm. Rêh hom!$b$,true),
('bunong-vn','EZK',16,7,null,$b$Gâp ăn ay văch ma toyh nâm bu ndơ bu tăm jêh tâm bri. Pô ri ay hŏ văch ma toyh, jêh ri jêng prêh, jêh ri văch ma druh jêh, toh ay lĕ bŭt jêh, jêh ri sŏk ay jong jêh, ƀiă lah ăt ay gŭ rhôk.$b$,false),
('bunong-vn','EZK',16,8,null,$b$Tơ lah gâp rgăn dăch ay jêh ri uănh ma ay, aơ, ay hŏ tât năm gĭt tâm rŏng jêh; jêh ri gâp nkŭm ay ma chiăng ao jâr gâp jêh ri nkŭm nau rhôk ay. N'hêl nanê̆ gâp ton tâm rnglăp jêh ri tâm nkol đah ay Yêhôva Brah Ndu lah, jêh ri ay jêng ndơ gâp jêh.$b$,true),
('bunong-vn','EZK',16,9,null,$b$Gâp nđŭm ay ma dak jêh ri rao kloh mham ay, jêh ri mhĭng ay ma dak si ƀâu kah.$b$,false),
('bunong-vn','EZK',16,10,null,$b$Gâp nsoh ăn ay tâm ban lĕ ma bok ao bu cheh jêh ri ntrŭp ntô jot ntâu ma ay, vân bŭt ay ma bok mhay rhên, jêh ri mpân ay ma bok ek ndrŭng.$b$,false),
('bunong-vn','EZK',16,11,null,$b$Gâp sŏk ndơ nkrơ̆ ăn ay ma drăp ndơ ueh, ăn dok kông tâm ti ay, jêh ri văn nhong tâm trô ko,$b$,false),
('bunong-vn','EZK',16,12,null,$b$gâp nsro rgên ta trôm muh ay, mblo thek ta tôr ay, jêh ri ndô ta klơ bôk ay du mlâm đon hađăch ueh.$b$,false),
('bunong-vn','EZK',16,13,null,$b$Pô ri, ay dơi nkrơ̆ mah mah, ma prăk; ao jâr ăn ay ma bok mhay rhên, ma bok ek ndrŭng, ma ndơ bu cheh; ay sa rnih muy, dak sŭt, jêh ri dak play ôlivơ, ay văch ma toyh ma nau ueh ngăn, jêh ri jêng nâm bu hađăch bu ur.$b$,true),
('bunong-vn','EZK',16,14,null,$b$Nau lư n'găr bu tăng lam bri dak yor nau ueh ay. Yor lah nau ueh ay jêng rah vah yor nau chrêk rmah gâp ăn jêh ma ay, Yêhôva Brah Ndu lah.”$b$,false),
('bunong-vn','EZK',16,15,null,$b$“Ƀiă lah ay nsing ma nau ueh ay, jêh ri ƀư nau văng tĭr yor nau lư n'găr ay, jêh ri ay jao ay nơm ƀư nau văng tĭr ma lĕ rngôch phung rgăn dăch ay.$b$,true),
('bunong-vn','EZK',16,16,null,$b$Ay sŏk ƀa ƀă bok ao ay jêh ri ƀư ma ay nơm ntŭk mbah yơk ueh, jêh ri ta nây ay ƀư nau văng tĭr; nau văng tĭr tâm ban pô nây mâu khư dơi geh ôh, mâu lĕ geh đŏng n'ho ro.$b$,false),
('bunong-vn','EZK',16,17,null,$b$Tâm ban lĕ ay sŏk lŭ khlay ƀư ma prăk jêh ri ƀư ma ay nơm rup phung bu klâu, jêh ri ma phung nây ay ƀư nau văng tĭr.$b$,false),
('bunong-vn','EZK',16,18,null,$b$Ay sŏk bok bu cheh ay nkŭm khân păng, jêh ri mpơl ăn dak play ôlivơ jêh ri ndơ ƀâu kah ta năp khân păng.$b$,false),
('bunong-vn','EZK',16,19,null,$b$Tâm ban lĕ ndơ sông sa gâp hŏ ăn jêh ma ay gâp siăm jêh ay ma rnih muy, dak play ôlivơ jêh ri dak sŭt, ay mpơl păng ta năp khân păng, jêng n'hôl ƀâu kah. Ngăn yơh, geh nau nây, Yêhôva Brah Ndu lah!$b$,false),
('bunong-vn','EZK',16,20,null,$b$Ay sŏk phung kon bu klâu jêh ri phung kon bu ur ay, phung ay deh ăn gâp, jêh ri phung nây ay ƀư brah jêh ma khân păng gay ma khân păng sa. Ay kơp nau văng tĭr ay ƀư jêng jê̆ lĕ?$b$,false),
('bunong-vn','EZK',16,21,null,$b$Kŏ tât ay hŏ nkhĭt kon gâp, jêh ri hăn jao jêh khân ô băl jêng ndơ nhhơr gŭch ma khân păng.$b$,false),
('bunong-vn','EZK',16,22,null,$b$Tâm lĕ nau gâp tâm rmot ay ƀư jêh ri nau ka n'hong ay hŏ ƀư jêh, ay mâu kah gĭt ôh ma rnôk ay druh mom, dôl ay gŭ rhôk pung tâm mham ay nơm.$b$,true),
('bunong-vn','EZK',16,23,null,$b$Pa kơi nây, ma lĕ nau ƀai ay ƀư rêh ni, rêh ni ngăn ma ay! Yêhôva Brah Ndu lah:$b$,true),
('bunong-vn','EZK',16,24,null,$b$Ay ndâk ma ay nơm du mlâm jrô jong, rêh ni ƀư ma ay nơm du mlâm jrô jong, jêh ri ƀư ma ay nơm ntŭk prêh tâm lĕ rngôch trong nkual ƀon toyh,$b$,false),
('bunong-vn','EZK',16,25,null,$b$ta ntơm lĕ rngôch trong toyh ay ndâk ntŭk prêh ay jêh ri dŏng nau nkrơ̆ ueh ay jêng nau tâm rmot, nhhơr jao ay nơm ma mbu nơm prot dăch ay, jêh ri ƀư lir nau văng tĭr ay.$b$,false),
('bunong-vn','EZK',16,26,null,$b$Tâm ban lĕ ay hŏ ƀư nau văng tĭr đah phung Êjipt, jêng phung chiau meng ay, ma nau tâm geh ƀư lir nau văng tĭr ay gay nsônh nau ji nuih gâp.$b$,false),
('bunong-vn','EZK',16,27,null,$b$Pô ri, hŏ yơr ti gâp ma ay; jêh ri ƀư n'hŭch kô̆ gâp ăn jêh ma ay, jêh ri jao ay ma phung rlăng ay kơnh, ma phung kon bu ur Philistin, phung hih rhâl ma nau văng tĭr ay.$b$,false),
('bunong-vn','EZK',16,28,null,$b$Tâm ban lĕ ay ƀư nau văng tĭr đah phung Asiri, yor lah ay mâu blau mpay ôh; n'hêl nanê̆ ay ƀư jêh nau ka n'hong đah khân păng, ê-hŏ ay mpay đŏng lĕ.$b$,false),
('bunong-vn','EZK',16,29,null,$b$Ay ƀư lir tâm ban lĕ nau văng tĭr ay ma n'gor Kanaan n'ho ma n'gor Kaldê blau tăch rgâl; jêh ri nđâp ma phung aơ ay mâu hŏ đŏng mpay.$b$,false),
('bunong-vn','EZK',16,30,null,$b$Nuih n'hâm ay bêng ma nau văng tĭr, Yêhôva Brah Ndu lah, yor lah ay ƀư jêh lĕ nau aơ, jêng kan ma du huê ka n'hong ngăn;$b$,true),
('bunong-vn','EZK',16,31,null,$b$dôl ndâk jrô jong ay ta tơm trong sâng, jêh ri ƀư jrô prêh ay tâm ăp nkual ƀon. Ƀiă lah ay mâu jêng nâm bu du huê bu ur văng tĭr ôh, yor lah ay mâu sŏk ôh nau nkhôm tă bơh bu.$b$,false),
('bunong-vn','EZK',16,32,null,$b$Ay jêng du huê ur văng tĭr, nơm rom bu năch ntrok ma sai păng nơm!$b$,false),
('bunong-vn','EZK',16,33,null,$b$Phung bu klâu ăn ndơ ma lĕ rngôch phung bu ur văng tĭr, ƀiă lah ay ăn ndơ ma lĕ rngôch tĭr ay; nkhôm khân păng ăn văch tât ma ay tă bơh lam ntŭk gay ƀư nau văng tĭr đah ay.$b$,false),
('bunong-vn','EZK',16,34,null,$b$Pô ri ay hŏ jêng mha ma phung bu ur êng tâm nau ay ƀư văng tĭr mâu geh nơm dăn ma ay ôh; jêh ri ay nkhôm khân păng, bi ma bu mâu ăn du ntil ndơ ôh ma ay. Nây jêng ay mha ngăn ma đah bu êng!$b$,false),
('bunong-vn','EZK',16,35,null,$b$Yor nây, Ơ bu ur văng tĭr, iăt hom nau Brah Ndu ngơi:$b$,true),
('bunong-vn','EZK',16,36,null,$b$Pô aơ Yêhôva Brah Ndu lah: Yor lah nau prêng ay hŏ mpơl jêh ri nau rhôk ay mpơl dôl ay ƀư nau tâm geh đah phung tĭr ay, jêh ri yor lĕ rngôch rup brah ay, jêh ri yor ay ƀư pling jêh mham phung kon ay nhhơr jêh ma rup brah nây,$b$,false),
('bunong-vn','EZK',16,37,null,$b$yor nây, aơ gâp mra rgum lĕ rngôch phung tĭr ay, đah phung nây ay geh nau maak, lĕ rngôch phung ay rŏng jêh ri lĕ rngôch phung ay tâm rmot; gâp mra rgum tă bơh phung gŭ jŭm ƀư ma ay, jêh ri mra mpơl rhôk ay ma khân păng, khân păng mra saơ lĕ rngôch.$b$,false),
('bunong-vn','EZK',16,38,null,$b$Gâp mra phat nkra ay nâm bu phat nkra bu ur lơi sai jêh ri phung bu ur nkhŭt mham; gâp mra sŏk mham tâm nau gâp ji nuih jêh ri ntôn grang ăn tŭp ta klơ ay.$b$,false),
('bunong-vn','EZK',16,39,null,$b$Gâp mra jao ay ma ti phung tĭr ay tâm ban lĕ, jêh ri khân păng mra ƀư rai lơi jrô rvang ay jêh ri ƀư rlâm lĕ rngôch ntŭk prêh ay; jêh ri khân păng mra doh lơi bok ao ay jêh ri sŏk lŭ khlay ay, jêh ri lơi ay ăn gŭ rhôk.$b$,false),
('bunong-vn','EZK',16,40,null,$b$Khân păng mra leo du phung ta han tâm lơh đah ay, jêh ri khân păng mra klŭp ay ma lŭ jêh ri koh gâl đah đao dao.$b$,false),
('bunong-vn','EZK',16,41,null,$b$Khân păng mra su ngih vâl ay jêh ri phat dôih ay ta năp măt âk phung bu ur. Gâp mra kan ay mâu ăn ay ƀư văng tĭr ôh, jêh ri ay mâu mra ăn nau nkhôm dŏng ôh ma phung tĭr ay.$b$,false),
('bunong-vn','EZK',16,42,null,$b$Pô ri gâp mra ăn mpay nau gâp ji nuih ma ay, jêh ri nau gâp ntôn grang mra du bơh ay; gâp mra gŭ đăp mpăn, jêh ri mâu hôm ji nuih ôh.$b$,false),
('bunong-vn','EZK',16,43,null,$b$Yor lah ay mâu kah gĭt ôh ma rnôk ay druh mom, ƀiă lah nsônh gâp ji nuih ma lĕ nau aơ; yor nây, aơ gâp mra ăn tŭp nau ay ƀư jêh ta klơ bôk ay nơm, Yêhôva Brah Ndu lah; ay mâu hôm ntop đŏng ôh hĕ nau văng tĭr aơ tâm lĕ rngôch nau gâp tâm rmot ma ay?$b$,false),
('bunong-vn','EZK',16,44,null,$b$Aơ, mbu nơm ngơi hôr mra ngơi nau hôr aơ ma ay, tĭng nâm me leo, kon druh pô nây lĕ$b$,true),
('bunong-vn','EZK',16,45,null,$b$Ay jêng kon bu ur ma mê̆ ay, nơm tâm rmot ma sai păng jêh ri ma kon păng; jêh ri ay jêng oh bu ur ma phung oh nur ay, phung tâm rmot ma sai khân păng jêh ri ma phung kon khân păng. Mê̆ ay jêng du huê bu ur Hêtit, jêh ri mbơ̆ ay jêng du huê bu klâu Amôrit.$b$,false),
('bunong-vn','EZK',16,46,null,$b$Nur ay jêng ƀon Samari, nơm gŭ ndrel ma phung kon bu ur păng, gŭ mpeh pa chiau ay; oh bu ur ay jêng ƀon Sôdôm ndrel ma kon bu ur păng, gŭ mpeh pa ma ay.$b$,false),
('bunong-vn','EZK',16,47,null,$b$Bi ay, mâu chuat hăn ôh tâm trong khân păng, jêh ri mâu ƀư tĭng nâm nau mhĭk gâp tâm rmot khân păng ƀư; mâu jŏ ôh ay jêng tih lơn ma khân păng tâm lĕ rngôch trong ay hăn.$b$,false),
('bunong-vn','EZK',16,48,null,$b$Tĭng nâm gâp gŭ rêh, Yêhôva Brah Ndu lah, oh bu ur ay ƀon Sôdôm, jêh ri phung kon bu ur păng mâu mâp ƀư ôh nâm bu ay jêh ri phung kon bu ur ay ƀư.$b$,true),
('bunong-vn','EZK',16,49,null,$b$Aơ, jêng nau tih mhĭk oh bu ur ay ƀon Sôdôm jêh ri phung kon bu ur păng; gŭ ngao geh nau sưr, ndơ sông sa rlau keh, jêng ndrŏng gŭ ueh mpăn; ƀiă lah păng mâu kah gĭt sĭt n'gĭl kơl phung kro o-ach jêh ri phung mâu geh ndô ndơ.$b$,true),
('bunong-vn','EZK',16,50,null,$b$Khân păng jêng sưr, jêh ri ƀư nau mhĭk nau gâp tâm rmot ta năp gâp; yor nây gâp ƀư rai khân păng tơ lah gâp saơ nau nây.$b$,false),
('bunong-vn','EZK',16,51,null,$b$Ƀon Samari mâu mâp ƀư du n'gul nau tih ay ƀư; ay ƀư jêh nau mhĭk gâp tâm rmot âk lơn ma khân păng, jêh ri tơ lah tâm rđĭl đah oh nur ay jêng sŏng lơn ma ay yor lĕ rngôch nau mhĭk gâp tâm rmot ay hŏ ƀư jêh.$b$,false),
('bunong-vn','EZK',16,52,null,$b$Tâm ban lĕ dơn hom nau prêng ay nơm, yor lah tơ lah tâm rđĭl đah ay nau phat dôih ma phung oh nur ay jêng hŭch djê̆ ma ay; yor nau tih ay ƀư jêng mhĭk lơn ma khân păng, khân păng jêng sŏng lơn ma ay. Pô nây lĕ ăn ay prêng hom jêh ri dơn nau bu tâm rmot ma ay, yor lah phung oh nur ay jêng sŏng lơn ma ay.$b$,false),
('bunong-vn','EZK',16,53,null,$b$“Ƀiă lah gâp mra njŭn leo tă bơh nau jêng bu nă plơ̆ sĭt nau ueh uĭn ma ƀon Sôdôm jêh ri ma phung kon bu ur păng, jêh ri gâp mra ăn nau ueh uĭn ma bu nă ƀon Samari jêh ri phung kon bu ur păng plơ̆ sĭt, jêh ri tâm ban lĕ phung bu nă ay gŭ ta nklang khân păng plơ̆ sĭt đŏng,$b$,true),
('bunong-vn','EZK',16,54,null,$b$gay ma ay dơn nau bu tâm rmot ma ay jêh ri prêng yor lĕ nau ay ƀư jêh, jêng du nau bonh leng ma khân păng.$b$,false),
('bunong-vn','EZK',16,55,null,$b$Bi ma phung oh nur ay, ƀon Sôdôm jêh ri jêh ri kon bu ur păng, mra plơ̆ sĭt ma nau khân păng jêng sa-ơm, jêh ri ƀon Samari ndrel ma kon bu ur păng mra plơ̆ sĭt ma nau khân păng jêng sa ơm; jêh ri ay ndrel ma kon bu ur ay ăt tâm ban lĕ mra plơ̆ sĭt nâm bu sa ơm.$b$,false),
('bunong-vn','EZK',16,56,null,$b$Tâm rnôk ay jêng sưr, ay mâu ntơ ôh amoh oh ay, ƀon Sôdôm;$b$,false),
('bunong-vn','EZK',16,57,null,$b$dôl nây nau mhĭk ay ê-hŏ mpơl ôh, aƀaơ ay hŏ jêng jêh nâm bu păng, du ntil nau phung gŭ jŭm păng tâm rmot ma ay nduyh, phung kon bu ur n'gor Syri jêh ri lĕ rngôch n'gor chiau meng păng, jêh ri kon bu ur Philistin.$b$,false),
('bunong-vn','EZK',16,58,null,$b$Aƀaơ ay hŏ dơn nau tâm rmal yor nau văng tĭr ay. Jêh ri nau mhĭk gâp tâm rmot ay ƀư jêh, Yêhôva lah.”$b$,false),
('bunong-vn','EZK',16,59,null,$b$Pô aơ nau Yêhôva Brah Ndu lah: Gâp mra ƀư ma ay nâm bu ay hŏ ƀư jêh. Ay tâm rmot jêh ma nau ay hŏ ton dôl ay cha lơi rlau nau tâm rnglăp gâp.$b$,true),
('bunong-vn','EZK',16,60,null,$b$Nđâp tơ lah pô nây, ăt gâp mra kah gĭt nau gâp tâm rnglăp jêh ma ay dôl rnôk ay druh mom, jêh ri gâp mra ƀư mâp đah ay nau tâm rnglăp gŭ n'ho ro.$b$,true),
('bunong-vn','EZK',16,61,null,$b$Rnôk nây ay mra kah gĭt ma trong ay hăn jêh ri prêng tơ lah ay rom oh nur ay, jêh ri gâp mra ăn khân păng ma ay jêng nâm bu kon bu ur, ƀiă lah mâu di ôh yor nau tâm rnglăp gâp ƀư jêh đah ay.$b$,false),
('bunong-vn','EZK',16,62,null,$b$Pô ri gâp mra ƀư nâp nau gâp tâm rnglăp ma ay, jêh ri ay mra gĭt gâp jêng Yêhôva,$b$,false),
('bunong-vn','EZK',16,63,null,$b$gay ma ay dơi kah gĭt jêh ri geh nau prêng, jêh ri mâu hôm hă trôm mbung ay ôh yor nau ay prêng, tơ lah gâp yô̆ ma ay lĕ rngôch nau ay ƀư jêh, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',17,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',17,2,null,$b$Hơi kon bunuyh, mbơh hom du ntil nau hôr, jêh ri ngơi nau ntĭt ma ngih Israel.$b$,false),
('bunong-vn','EZK',17,3,null,$b$Lah hom, pô aơ Yêhôva Brah Ndu lah: Du mlâm klang toyh geh tĭng năr toyh jêh ri rsau nting năr jong, geh rsau âk jêh ri âk ntil dak tât ma n'gor bri Liban jêh ri sŏk chiông tơm si sêdar;$b$,false),
('bunong-vn','EZK',17,4,null,$b$păng nkêch n'gĭng nse dŭt prêh, leo tât ndơ nây ma bri tăch rgâl, jêh ri dơm păng tâm ƀon tăch drăp.$b$,false),
('bunong-vn','EZK',17,5,null,$b$Jêh ri păng sŏk ntil bơh bri ay jêh ri tuch ntil nây tâm neh jêng; dơm păng dăch ntŭk âk dak n'hor, jêh ri tăm tơm nây nâm bu tăm tơm si,$b$,false),
('bunong-vn','EZK',17,6,null,$b$jêh ri păng chăt hon jêh ri jêng tơm play yôr yar dêh dơm, jêh ri n'gĭng păng hung mpeh ma klang, jêh ri reh păng sŏr du ntŭk tâm dâng; pô ri păng jêng du tơm play yôr yar, geh n'gĭng jêh ri nkŭr.$b$,false),
('bunong-vn','EZK',17,7,null,$b$Ƀiă lah geh đŏng du mlâm klang toyh êng geh nting năr toyh, jêh ri rsau âk; aơ tơm play yôr yar tă bơh neh păng tăm hung reh jêh ri chăt mbah leo rlet ma klang, gay ma klang nây dơi djrah dak ma păng.$b$,true),
('bunong-vn','EZK',17,8,null,$b$Bu hŏ tăm tơm play yôr yar dăch ntŭk âk dak, tâm neh ueh gay ma păng geh n'gĭng âk jêh ri geh play, jêh ri jêng du tơm play yôr yar ueh reh.$b$,true),
('bunong-vn','EZK',17,9,null,$b$Lah hom, pô aơ Yêhôva Brah Ndu lah: Tơm yôr yar chăt hao ueh lĕ? Klang nây mâu hĕ păng rôk lơi reh păng, grăch lơi play păng, kŏ tât lĕ rngôch nkŭr n'ha mra kro lĕ ƀhiau, geh lĕ? Mâu kâp ôh geh nting tur dăng, mâu lĕ kâp âk bunuyh gay rôk reh păng.$b$,false),
('bunong-vn','EZK',17,10,null,$b$Aơ, hŏ tăm jêh păng ta ntŭk mbor đang bu hŏ tăm.$b$,false),
('bunong-vn','EZK',17,11,null,$b$Pô nây, geh nau Yêhôva ngơi, lah ma gâp pô aơ:$b$,true),
('bunong-vn','EZK',17,12,null,$b$Lah hom ma ngih vay mâu gĭt hĕ mâm bu rblang ma nau nây? Mbơh hom ma khân păng. Aơ, hađăch Babilôn hŏ hăn tât ta ƀon Yêrusalem; hŏ nhŭp jêh hađăch jêh ri lĕ rngôch phung kôranh djôt leo ndrel khân păng rlet ma Babilôn.$b$,false),
('bunong-vn','EZK',17,13,null,$b$Jêh ri hađăch nây hŏ săch jêh du huê bunuyh tă bơh mpôl băl hađăch, njêng nau tâm rnglăp ndrel păng, ăn păng ngơi ton, jêh ri hŏ ndjôt leo jêh phung kôranh tâm bri nây leo hăn tĭng păng,$b$,false),
('bunong-vn','EZK',17,14,null,$b$gay ăn bri dak geh nau hêt rhôi, mâu hôm tâm rdâng đŏng ôh, jêh ri ma nau djôt prăp nau tâm rnglăp, ri mơ bri dak ăt dơi hôm gŭ ƀa ƀơ.$b$,false),
('bunong-vn','EZK',17,15,null,$b$Ƀiă lah hađăch hŏ tâm rdâng đah hađăch Babilôn, hŏ mprơh hăn jêh phung kâp tâm tang hăn ma n'gor bri Êjipt, gay ma phung Êjipt dơi ăn seh ma hađăch jêh ri du phung ta han âk. Păng mra dơi lĕ? Du huê bunuyh dơi klaih lĕ dôl ƀư pô nây? Dơi lĕ păng cha lơi rlau nau hŏ tâm rnglăp jêh ri ăt dơi klaih lĕ?$b$,false),
('bunong-vn','EZK',17,16,null,$b$Tĭng nâm gâp gŭ rêh, Yêhôva lah, n'hêl nanê̆ tâm ntŭk hađăch Babilôn gŭ, bunuyh păng hŏ njêng hađăch jêh, yor lah păng tâm rmot nau ton jêh ri cha lơi rlau nau tâm rnglăp đah hađăch Babilôn, păng mra khĭt đah hađăch ta nklang ƀon Babilôn.$b$,false),
('bunong-vn','EZK',17,17,null,$b$Pharaôn jêh ri phung ta han ktang păng jêh ri du phung âk mâu mra kơl păng ôh tâm nau tâm lơh, tơ lah bu lĕ njêng pơih jêh ri ƀư mpêr nchueng jŭm ƀon gay nkhĭt âk bunuyh.$b$,true),
('bunong-vn','EZK',17,18,null,$b$Yor lah Sêdêkia tâm rmot jêh ma nau ton, jêh ri cha lơi rlau jêh nau tâm rnglăp; aơ, sŏk ti lơh ro, yor lah păng ton jêh ƀiă lah ăt hôm ƀư lĕ rngôch nau aơ, păng mâu mra klaih ôh.$b$,false),
('bunong-vn','EZK',17,19,null,$b$Yor nây, Yêhôva Brah Ndu lah: Tĭng nâm gâp gŭ rêh, n'hêl nanê̆ nau gâp ton jêh păng tâm rmot, jêh ri nau gâp tâm rnglăp păng rlau jêh, gâp mra tôp nau nây ta klơ bôk păng nơm.$b$,true),
('bunong-vn','EZK',17,20,null,$b$Gâp mra drăng nhuăl ta klơ păng, păng mra geh văk nhuăl gâp; gâp mra leo păng rlet ma Babilôn, ta nây gâp mra phat dôih nau păng ƀlăch ƀlêr đah gâp.$b$,false),
('bunong-vn','EZK',17,21,null,$b$Lĕ rngôch phung ta han păng nchuăt du mra chôt khĭt ma tak đao, jêh ri phung hôm-e klen mra chah-rai du tĭng lĕ rngôch sial. Rnôk nây khân may mra gĭt gâp nơm, jêng Yêhôva ngơi nau nây.$b$,false),
('bunong-vn','EZK',17,22,null,$b$Pô aơ Yêhôva Brah Ndu lah: Gâp nơm mra sŏk nkeh ta chiông prêh klơ tơm si Sêdar, jêh ri tăm đŏng ta ntŭk êng; gâp mra nkêch lơi nkŭr ta chiông prêh klơ dŭt du n'gĭng nkeh nse, jêh ri gâp mra tăm ndơ nây ta klơ yôk dŭt prêh.$b$,false),
('bunong-vn','EZK',17,23,null,$b$Nanê̆ gâp mra tăm ndơ nây ta mpư̆ yôk Israel; păng mra chăt n'gĭng jêh ri geh play; mra jêng du tơm si Sêdar ueh reh, lĕ rngôch phung sĭm mra văch nde tâm dâng păng; lĕ rngôch ntil sĭm mra ƀư rsuăn tâm pŭm n'gĭng păng.$b$,false),
('bunong-vn','EZK',17,24,null,$b$Lĕ rngôch tơm si tâm bri mra gĭt ma gâp, Yêhôva, hŏ njŭr tơm si prêh jêh ri n'hao tơm si dêh, ăn kro lơi tơm si ndrêh jêh ri ăn tơm si lĕ kro dơi chăt jêng. Gâp nơm yơh, Yêhôva, hŏ ngơi nau nây, jêh ri gâp mra ƀư dơi jêng nau nây ro.$b$,false),
('bunong-vn','EZK',18,1,null,$b$Yêhôva ngơi đŏng ma gâp:$b$,true),
('bunong-vn','EZK',18,2,null,$b$Mâm khân may mĭn dôl rŏ nau hôr aơ di ma bri Israel: Phung mbơ̆ sa play kriăk ƀâu srat ma phung kon nkhơng kĭr sêk, nau nây moh bu ntĭt?$b$,false),
('bunong-vn','EZK',18,3,null,$b$Tĭng nâm gâp gŭ rêh, Yêhôva Brah Ndu lah, khân may mâu mra dŏng đŏng ôh nau hôr aơ tâm bri Israel.$b$,true),
('bunong-vn','EZK',18,4,null,$b$Aơ, lĕ rngôch huêng jêng ndơ gâp; huêng mbơ̆ nđâp huêng kon jêng ndơ gâp. Huêng ƀư tih mra khĭt.$b$,false),
('bunong-vn','EZK',18,5,null,$b$Tơ lah du huê bunuyh jêng sŏng jêh ri ƀư tĭng nâm nau vay jêh ri di:$b$,true),
('bunong-vn','EZK',18,6,null,$b$Păng mâu sa ôh ndơ ta ntŭk klơ yôk mâu lah n'gơr măt leo ma phung rup brah ngih Israel, mâu ƀư ƀơ̆ ôh ur chiau meng păng mâu lah mâu gŭ êp ôh ma du huê bu ur dôl păng tât khay;$b$,false),
('bunong-vn','EZK',18,7,null,$b$bunuyh mâu ƀư djơh bu ôh, ƀiă lah mplơ̆ sĭt ma nơm manh ndơ nchăm, lơi ta ntŭng ôh ndơ bu, ăn piăng let ma nơm ji ngot, sâm nsoh bok ao ma nơm bêch kuh, rhôk,$b$,false),
('bunong-vn','EZK',18,8,null,$b$mâu ăn bu manh prăk gay sa kao, mâu lah sa n'hao ôh, nkân ti păng mâu ƀư nau kue ôh, ƀư nau di ngăn ndrăng mpôl bunuyh,$b$,false),
('bunong-vn','EZK',18,9,null,$b$chuat tĭng ndô̆ nau gâp ntăm, jêh ri djôt prăp răp jăp nau vay gâp păng jêng sŏng srăng ngăn ngên, n'hêl nanê̆ păng mra rêh ueh, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',18,10,null,$b$Tơ lah păng deh nkeng ma du huê kon jêng bunuyh ƀai, jêng nơm ƀư pling mham, mâu lah ƀư du ntil nau tih hŏ lah jêh nây,$b$,true),
('bunong-vn','EZK',18,11,null,$b$nđâp tơ lah păng nơm mâu mâp ƀư ôh nau nây, ƀiă lah kon phung sa ndơ ta ntŭk yôk prêh, ƀư ƀơ̆ ur chiau meng păng,$b$,false),
('bunong-vn','EZK',18,12,null,$b$tŭn jot phung kro o-ach jêh ri phung mâu geh ndô-ndơ, ntŭng ndô-ndơ bu, mâu tâm ôh rnon bu, n'gơr muh măt leo ma phung rup brah, ƀư nau mhĭk jêng nau gâp tâm rmot,$b$,false),
('bunong-vn','EZK',18,13,null,$b$ăn bu manh prăk gay sa kao jêh ri ŭch sa ndơ (n'hao); pô ri păng nây dơi rêh lĕ? Mâu, păng mâu mra rêh ôh! Yor lah păng ƀư jêh lĕ rngôch nau mhĭk gâp tâm rmot aơ, n'hêl nanê̆ păng mra khĭt, mham păng mra tŭp ta klơ păng nơm.$b$,false),
('bunong-vn','EZK',18,14,null,$b$Ƀiă lah, tơ lah bunuyh aơ deh kon bu klâu, kon nây gĭt saơ lĕ nau tih mbơ̆ păng hŏ ƀư jêh, păng klach, mâu hôm ƀư ôh pô nây;$b$,true),
('bunong-vn','EZK',18,15,null,$b$tơ lah kon nây mâu sa ndơ ntŭk yôk prêh, tơ lah păng mâu n'gơr ôh măt leo ma rup brah ngih phung Israel, tơ lah mâu ƀư ƀơ̆ ur chiau meng păng,$b$,false),
('bunong-vn','EZK',18,16,null,$b$tơ lah păng mâu ƀư mhĭk ma bu, tơ lah păng mâu sŏk rhŏm ôh ndơ bu nchăm, mâu ntŭng ôh ndô ndơ bu, ƀiă lah ăn piăng let ma phung ji ngot jêh ri sâm nsoh bok ao ma phung bêch kuh rhôk,$b$,false),
('bunong-vn','EZK',18,17,null,$b$Nkân ti păng mâu ƀư ôh nau kue, mâu sa kao mâu lah sa ndơ (n'hao) ôh, djôt prăp nau vay gâp jêh ri chuat tĭng ndô̆ nau gâp ntăm, păng mâu mra khĭt ôh yor nau tih mbơ̆ păng; n'hêl nanê̆ păng mra rêh ueh.$b$,false),
('bunong-vn','EZK',18,18,null,$b$Bi ma mbơ̆ păng mra khĭt yor nau tih păng nơm, yor lah păng ƀư nau thăm rmat ŭch sa prăk, ntŭng ndô ndơ oh nâu păng, jêh ri păng ƀư mâu ueh ta nklang phung ƀon lan păng.$b$,false),
('bunong-vn','EZK',18,19,null,$b$Ƀiă lah khân may ăt geh lah, mâm ƀư kon bu klâu mâu hĕ păng anh nau tih mbơ̆ păng? Tơ lah kon bu klâu hŏ ƀư jêh tĭng nâm nau vay jêh ri nau sŏng, jêh ri djôt prăp ma nau njrăng lĕ rngôch nau gâp ntăm, n'hêl nanê̆ păng mra rêh ueh.$b$,true),
('bunong-vn','EZK',18,20,null,$b$Huêng ƀư tih mra khĭt. Kon bu klâu mâu mra tuy nau tih mbơ̆ păng, mâu lĕ mbơ̆ mra anh nau tih kon bu klâu păng; nau sŏng srăng du huê bunuyh sŏng mra prăp ma păng nơm, jêh ri nau ƀai du huê bunuyh ƀai mra tŭp ta păng nơm.$b$,true),
('bunong-vn','EZK',18,21,null,$b$Ƀiă lah tơ lah du huê bunuyh ƀai cha lơi lĕ rngôch nau tih păng hŏ ƀư jêh, jêh ri djôt prăp lĕ rngôch nau vay gâp, jêh ri ƀư tĭng nâm nau vay jêh ri nau sŏng, n'hêl nanê̆ mra rêh ueh, păng mâu mra khĭt ôh.$b$,true),
('bunong-vn','EZK',18,22,null,$b$Mâu hôm geh du ntil nau tih ôh păng hŏ ƀư mra kah gĭt tay ŭch rdâng ma păng; păng mra gŭ rêh yor nau sŏng srăng păng hŏ ƀư jêh.$b$,true),
('bunong-vn','EZK',18,23,null,$b$Yêhôva lah pô aơ: Gâp geh nau maak lĕ ma nau khĭt du huê bunuyh ƀai? Ueh ngăn ngên ma păng rmal nau tih jêh ri păng gŭ rêh maak lĕ?$b$,false),
('bunong-vn','EZK',18,24,null,$b$Ƀiă lah tơ lah du huê bunuyh sŏng srăng cha lơi nau sŏng srăng păng, jêh ri păng ƀư nau kue, tơ lah păng tĭng bu ƀư lĕ rngôch nau mhĭk gâp tâm rmot nâm bu bunuyh tih vay ƀư, păng mra dơi rêh lĕ? Mâu geh du ntil nau sŏng srăng păng hŏ ƀư mra dơi kah gĭt tay; yor păng jêng tih jêh, jêh ri nau tih păng hŏ ƀư, pô ri păng mra khĭt tâm nau nây.$b$,false),
('bunong-vn','EZK',18,25,null,$b$Ƀiă lah ăt khân may lah, “Trong Yêhôva mâu sŏng ôh. Iăt hom aƀaơ ri, Ơ ngih Israel: Trong gâp mâu sŏng ôh hĕ? Mâu di trong khân may hĕ jêng mâu sŏng ôh?$b$,true),
('bunong-vn','EZK',18,26,null,$b$Tơ lah du huê bunuyh sŏng cha lơi nau sŏng srăng păng, jêh ri păng ƀư nau kue, tơ lah păng mra khĭt yor nau nây. Nây yor nau kue păng hŏ ƀư jêng păng khĭt.$b$,false),
('bunong-vn','EZK',18,27,null,$b$Ƀiă lah, tơ lah du huê bunuyh ƀai cha lơi nau ƀai păng ƀư, jêh ri tơ lah păng ƀư tĭng nau vay jêh ri nau sŏng, păng mra tâm rklaih huêng păng.$b$,false),
('bunong-vn','EZK',18,28,null,$b$Yor lah păng mĭn rvê jêh ri cha lơi lĕ rngôch nau tih păng hŏ ƀư jêh, n'hêl nanê̆ păng mra rêh ngăn jêh ri păng mâu mra khĭt ôh.$b$,true),
('bunong-vn','EZK',18,29,null,$b$Ƀiă lah ăt ngih Israel lah, trong Yêhôva mâu jêng sŏng ôh. Ơ ngih Israel, trong gâp mâu sŏng ôh hĕ? Mâu di trong khân may hĕ jêng mâu sŏng ôh?$b$,false),
('bunong-vn','EZK',18,30,null,$b$Yor nây gâp mra phat dôih khân may, Ơ ngih Israel, ăp nơm tĭng nâm kan păng ƀư, Yêhôva Brah Ndu lah. Rmal hom jêh ri cha lơi lĕ rngôch nau tih khân may; klach lah nau kue khân may ƀư rai khân may nơm.$b$,true),
('bunong-vn','EZK',18,31,null,$b$Sŏk mƀăr lơi lĕ rngôch nau tih khân may ƀư jêh đah gâp, jêh ri sŏk hom ma khân may nơm nuih n'hâm mhe jêh ri huêng brah mhe! Mâm ƀư khân may ŭch khĭt, Ơ ngih Israel?$b$,true),
('bunong-vn','EZK',18,32,null,$b$Yor lah gâp mâu maak ôh tâm nau du huê bunuyh tih khĭt, Yêhôva Brah Ndu lah, pô ri khân may plơ̆ sĭt hom, gay ma rêh!”$b$,false),
('bunong-vn','EZK',19,1,null,$b$Bi may, nhĭm vơl hom yor phung kôranh Israel,$b$,true),
('bunong-vn','EZK',19,2,null,$b$jêh ri lah: Mê̆ may kăl-e ri mâm păng jêng? Jêng du mlâm yau mŭr me gŭ kuen ta nklang phung yau mŭr nkuăng; gŭ rong kon păng ta nklang phung yau mŭr kon.$b$,false),
('bunong-vn','EZK',19,3,null,$b$Păng rong du mlâm tâm phung kon păng, păng jêng du mlâm yau mŭr rah, nti kăp mpa, jêh ri păng hêk sa bunuyh.$b$,false),
('bunong-vn','EZK',19,4,null,$b$Phung mpôl băl bunuyh lư n'găr ma păng; khân păng nhŭp ô băl tâm trôm ntu khân păng. Khân păng têk mphâk ô băl ma mâng nglĕ klĕ leo tât ma n'gor bri Êjipt.$b$,false),
('bunong-vn','EZK',19,5,null,$b$Tơ lah yau mŭr me gŭ kâp jŏ jêh, yor nau păng kâp gân lĕ roh jêh, păng sŏk kon păng êng ri đŏng,$b$,false),
('bunong-vn','EZK',19,6,null,$b$jêh ri rong ô băl jêng du mlâm yau mŭr rah, jêh ri păng nti kăp mpa, păng hêk sa bunuyh.$b$,false),
('bunong-vn','EZK',19,7,null,$b$Păng ƀư rlâm pôih nâp khân păng, jêh ri ƀư rai ƀon toyh khân păng; n'gor bri aơ nđâp ma lĕ rngôch phung gŭ tâm nây geh nau uh ah yor tăng bâr păng rđuh (ngrông).$b$,false),
('bunong-vn','EZK',19,8,null,$b$Pô ri phung mpôl băl bunuyh văch tâm rdâng đah păng tă bơh lĕ rngôch n'gor gŭ jŭm păng; khân păng drăng nhuăl ma păng; bu geh nhŭp tâm trôm ntu khân păng.$b$,false),
('bunong-vn','EZK',19,9,null,$b$Ma nglĕ klĕ mphâk jêh ri krŭng păng tâm ndrung, jêh nây têk leo tât ma hađăch n'gor bri Babilôn; khân păng ăn păng jêng bu nă, gay bu mâu hôm tăng bâr păng ngrông ta klơ yôk Israel.$b$,false),
('bunong-vn','EZK',19,10,null,$b$Mê̆ may jêng nâm bu du tơm play kriăk ƀâu tâm mham may, tăm jêh dăch n'hor dak, glet play âk rklê jêh ri chăt âk n'gĭng yor lah geh dak âk.$b$,true),
('bunong-vn','EZK',19,11,null,$b$N'gĭng păng nâp ngăn, tât jêng mâng jra ma kôranh chiă uănh. Tơm păng prêh ngăn lĕ n'gĭng păng dŭt pŭm; mpơl prêh ngăn ngên, jêh ri bu saơ yor păng prêh klơ jêh ri yor păng âk n'gĭng.$b$,false),
('bunong-vn','EZK',19,12,null,$b$Ƀiă lah ma nau ji nuih bu rôk lơi păng, bu mƀăr tâm neh. Sial tă bơh lơ ƀư kro jêh păng; bu pĕ jêh play păng, n'gĭng păng dŭt nâp lĕ kro jêh, ŭnh sa lĕ rngôch păng!$b$,true),
('bunong-vn','EZK',19,13,null,$b$Aƀaơ ri bu tăm tay păng tâm bri rdah, tâm neh sơh jêh ri mâu geh dak;$b$,true),
('bunong-vn','EZK',19,14,null,$b$ŭnh tă luh bơh lĕ n'gĭng păng, sa lĕ play păng, kŏ tât mâu hôm ôh n'gĭng ktang đŏng, gay ƀư mâng jra ma kôranh chiă uănh. Aơ jêng nau nhĭm vơl, bu vay nhĭm tât kăndơ̆ .$b$,false),
('bunong-vn','EZK',20,1,null,$b$Tâm năm rơh pơh, năng jât khay prăm, geh bar pe nuyh phung bu bŭnh bu ranh Israel văch ôp ma Yêhôva, jêh ri gŭ pa năp gâp.$b$,true),
('bunong-vn','EZK',20,2,null,$b$Yêhôva ngơi ma gâp:$b$,false),
('bunong-vn','EZK',20,3,null,$b$Hơi kon bunuyh, ngơi hom ma phung bu ranh Israel jêh ri lah ma khân păng, Pô aơ nau Yêhôva lah: Khân may văch ŭch ôp ma gâp hĕ? Tĭng nâm gâp rêh, Yêhôva Brah Ndu lah, gâp mâu mra ăn khân may ôp ma gâp ôh.$b$,false),
('bunong-vn','EZK',20,4,null,$b$May mra phat dôih khân păng, Hơi kon bunuyh, may mra phat đŏng dôih khân păng? Pô ri ăn khân păng gĭt nau mhĭk gâp tâm rmot phung che khân păng hŏ ƀư jêh,$b$,false),
('bunong-vn','EZK',20,5,null,$b$pô ri ăn may lah hom ma khân păng pô aơ: Nau Yêhôva Brah Ndu lah: Dôl nôk gâp săch Israel, gâp ton ma kon sau ngih Yakôb, dôl gâp mpơl săk gâp nơm ma khân păng tâm n'gor bri Êjipt, gâp ton jêh ma khân may.$b$,false),
('bunong-vn','EZK',20,6,null,$b$Tâm nar nây gâp ton ma khân păng du luh tă bơh n'gor bri Êjipt lăp tâm du n'gor bri gâp joi ăn ma khân păng, du n'gor bri, jêng bri geh ndơ sông sa rmeh ler, chrêk rmah lơn ma lĕ rngôch bri.$b$,false),
('bunong-vn','EZK',20,7,null,$b$Gâp lah ma khân păng pô aơ: Ăn ăp nuyh mƀăr lơi ăn ngai bơh khân may lĕ rngôch ndơ gâp vay tâm rmot măt khân may ŭch uănh, jêh ri lơi ta ƀư ƀơ̆ ôh khân may nơm ma rup brah bri Êjipt; gâp jêng Yêhôva Brah Ndu khân may.$b$,true),
('bunong-vn','EZK',20,8,null,$b$Ƀiă lah khân păng ŭch tâm rdâng đah gâp, jêh ri mâu tông bâr gâp ôh; ăp nuyh khân păng mâu ŭch mƀăr lơi ôh ndơ gâp tâm rmot măt khân păng ŭch uănh, mâu lĕ khân păng cha lơi phung rup brah bri Êjipt. Rnôk nây gâp lah pô aơ gâp mra nkhŭt nau gâp ji nuih ta klơ khân păng, jêh ri ƀư ăn mpay nau gâp nuih ma khân păng ta nklang bri Êjipt.$b$,false),
('bunong-vn','EZK',20,9,null,$b$Ƀiă lah gâp ƀư yor ma amoh gâp nơm, gay ŭch khân păng mâu ƀư ƀơ̆ ôh amoh gâp ta năp măt ntil mpôl bunuyh bri bu, ta nklang ntŭk khân păng gŭ, ta năp măt phung nây gâp mpơl jêh gâp nơm ma khân păng dôl leo khân păng du luh tă bơh n'gor bri Êjipt.$b$,true),
('bunong-vn','EZK',20,10,null,$b$Pô ri gâp hŏ leo jêh khân păng du luh tă bơh n'gor bri Êjipt tât ma bri rdah.$b$,true),
('bunong-vn','EZK',20,11,null,$b$Gâp ăn jêh ma khân păng nau vay gâp, jêh ri gay ăn ma khân păng gĭt nau gâp ntăm, jêng nau ăn bunuyh tông nau nây, ri mơ mra rêh yor păng.$b$,false),
('bunong-vn','EZK',20,12,null,$b$Jêh ri gâp ăn nar Saƀat ma khân păng tâm ban lĕ, gâp ƀư du nau mbên ta nklang gâp jêh ri khân păng, gay ăn khân păng gĭt pô aơ gâp jêng Yêhôva prăp ăn khân păng kloh ueh.$b$,false),
('bunong-vn','EZK',20,13,null,$b$Ƀiă lah ngih Israel, tâm rdâng đah gâp tâm bri rdah; khân păng mâu ŭch chuat tĭng ndô̆ ôh nau gâp ntăm, ƀiă lah dun nau vay gâp, jêng nau ăn bunuyh tông nau nây, ri mơ mra rêh yor păng, jêh ri khân păng ƀư tih rlau keh lĕ rngôch nar Saƀat gâp. Rnôk nây gâp lah mra nkhŭt nau gâp ji nuih ta klơ khân păng tâm bri rdah, ŭch ƀư roh rai khân păng lĕ rngôch.$b$,true),
('bunong-vn','EZK',20,14,null,$b$Ƀiă lah gâp ƀư jêh nau nây yor amoh gâp, gay ma bu mâu ƀư ƀơ̆ ôh amoh gâp ta năp phung mpôl băl bunuyh bri bu, ta năp măt phung nây gâp leo du luh jêh khân păng.$b$,false),
('bunong-vn','EZK',20,15,null,$b$Pô nây, gâp hŏ ton ma khân păng tâm ban lĕ tâm bri rdah pô aơ gâp mâu mra leo khân păng lăp ôh tâm n'gor bri gâp hŏ ton ma khân păng, jêng n'gor bri geh ndơ sông sa âk rmeh, bri chrêk rmah lơn ma bri êng;$b$,false),
('bunong-vn','EZK',20,16,null,$b$yor lah khân păng dun jêh nau vay gâp, jêh ri ƀư ƀơ̆ jêh ma nar Saƀat gâp; yor lah nuih nhhơr khân păng tĭng ndô̆ rup brah khân păng nơm.$b$,false),
('bunong-vn','EZK',20,17,null,$b$Nđâp tơ lah pô nây, măt gâp uănh yô̆ nhhuach ngăn ma khân păng, yor ri gâp mâu ƀư rai ôh khân păng, gâp mâu lĕ ƀư roh rai khân păng lĕ rngôch tâm bri rdah.$b$,false),
('bunong-vn','EZK',20,18,null,$b$Gâp lah jêh ma phung kon sau khân păng tâm bri rdah, lơi ta khân păng chuat ôh tĭng ndô̆ nau vay mbơ̆ khân may, mâu lĕ djôt prăp nau vay mbơ̆ khân may, mâu lĕ djôt prăp nau khân păng ntĭnh, mâu lĕ ƀư ƀơ̆ khân may nơm ma phung rup brah khân păng.$b$,true),
('bunong-vn','EZK',20,19,null,$b$Gâp yơh Yêhôva jêng Brah Ndu khân may; chuat hom tĭng ndô̆ nau vay gâp, jêh ri njrăng djôt prăp nau gâp ntăm,$b$,false),
('bunong-vn','EZK',20,20,null,$b$jêh ri kah gĭt yơk ma nar Saƀat gâp gay ăn ma nar Saƀat dơi jêng du nau mbên ta nklang gâp đah khân may, ŭch ăn khân may dơi gĭt gâp jêng Yêhôva Brah Ndu khân may.$b$,false),
('bunong-vn','EZK',20,21,null,$b$Ƀiă lah phung kon sau rlơng nau ŭch tâm rdâng đah gâp; khân păng mâu chuat ôh tĭng ndô̆ nau vay gâp ntĭnh jêh, jêh ri mâu ŭch njrăng djôt prăp ôh nau gâp ntăm, jêng ntil nau ăn bunuyh tông nau nây, ri mơ mra rêh yor păng; jêh ri khân păng ƀư tih lĕ nar Saƀat gâp đŏng. Pô nây, gâp lah pô aơ gâp mra nkhŭt nau gâp ji nuih ta klơ khân păng, jêh ri ƀư ăn mpay nau gâp nuih ma khân păng tâm bri rdah.$b$,true),
('bunong-vn','EZK',20,22,null,$b$Ƀiă lah gâp nkân lơi ti gâp, jêh ri ƀư jêh yor amoh gâp, gay ăn bu mâu ƀư ƀơ̆ ôh amoh gâp ta năp, gay ăn bu mâu ƀư ƀơ̆ ôh amoh gâp ta năp măt phung ƀon lan nây gâp hŏ leo jêh khân păng du luh.$b$,false),
('bunong-vn','EZK',20,23,null,$b$Pô nây, gâp hŏ leo ton đah khân păng ta bri rdah pô aơ gâp mra ƀư ma khân păng chah rai pru pra ta nklang lĕ rngôch bri dak jêh ri mprơh du khân păng lam bri êng,$b$,false),
('bunong-vn','EZK',20,24,null,$b$yor lah khân păng mâu tông ôh ma nau vay gâp, ƀiă lah dun jêh nau gâp ntăm jêh ri ƀư ƀơ̆ jêh nar Saƀat gâp, jêh ri măt khân păng treng uănh ma rup brah phung mbơ̆ khân păng.$b$,false),
('bunong-vn','EZK',20,25,null,$b$Tâm ban lĕ, gâp hŏ ăn jêh ma khân păng lĕ rngôch nau vay mâu ueh ôh, jêh ri nau ntăm yor tă bơh nây khân păng mâu dơi gŭ rêh ôh;$b$,false),
('bunong-vn','EZK',20,26,null,$b$jêh ri gâp ăn khân păng jêng ƀơ̆ jêh yor tă ndơ khân păng ƀư brah, khân păng nhhơr gŭch lĕ rngôch kon khân păng deh bôk rah tâm ŭnh gay ŭch ăn gâp ƀư nkrit khân păng, kŏ tât khân păng dơi gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',20,27,null,$b$Pô ri, hơi kon bunuyh, ngơi hom ma ngih Israel jêh ri lah ma khân păng, Pô aơ nau Yêhôva Brah Ndu lah: Phung chô che khân may ngơi sưr jêh ma gâp, yor lah khân păng hŏ ƀư tih cha lơi jêh gâp.$b$,true),
('bunong-vn','EZK',20,28,null,$b$Tơ lah gâp hŏ leo jêh khân păng ma neh bri gâp ton ăn jêh ma khân păng, nôk nây khân păng saơ gôl yôk prêh mâu lah tơm si krŏng, n'ha si pŭm, ta nây khân păng nhhơr ndơ ƀư brah; khân păng hŏ phiơ ta nây ndơ ƀư brah nsônh gâp ji nuih; ăt dơm ăn ta nây lĕ ndơ nhhơr ndơ ƀâu kah, jêh ri ta nây lĕ khân păng ƀư ndơ nhêt sa.$b$,true),
('bunong-vn','EZK',20,29,null,$b$Nôk nây gâp lah ma khân păng pô aơ: Ntŭk prêh khân may hăn moh ndơ nây? (Pô ri ntŭk prêh nây bu ntơ jêng Bama tât ma nar aơ).$b$,false),
('bunong-vn','EZK',20,30,null,$b$Yor nây, lah hom ma ngih Israel pô aơ: Yêhôva Brah Ndu lah: Khân may mra ƀư ƀơ̆ êng khân may nơm tĭng nau phung chô-yau khân may hŏ ƀư nây lĕ jêh ri nkhah du tĭng ndô̆ ndơ mhĭk khân păng ƀư gâp hŏ tâm rmot?$b$,true),
('bunong-vn','EZK',20,31,null,$b$Tơ lah khân may nhhơr ndơ, jêh ri ƀư brah ma phung kon bu klâu khân may gŭch ma ŭnh, khân may ƀư ƀơ̆ khân may nơm ma lĕ rngôch rup brah tât ma nar aơ lĕ? Hơi ngih Israel, gâp mâu ăn khân may ôp hĕ? N'hêl nanê̆, tĭng nâm gâp gŭ rêh, Yêhôva Brah Ndu lah, gâp mâu mra dơn ôh nau khân may ôp!$b$,false),
('bunong-vn','EZK',20,32,null,$b$Mâu mra geh nau tât ôh nâm bu ntil nau khân may mĭn, tơ lah khân may lah pô aơ: Ăn he ŭch dơi jêng nâm bu ntil mpôl bunuyh jêh ri lĕ rngôch mpôl băl tâm bri êng, mbah yơk ma tơm si jêh ri lŭ.$b$,true),
('bunong-vn','EZK',20,33,null,$b$Tĭng nâm gâp gŭ rêh, Yêhôva Brah Ndu lah: N'hêl nanê̆ ma ti brah jêh ri nting tur yơr jêh, jêh ri nkhŭt nau ji nuih, gâp mra ƀư hađăch chiă uănh khân may!$b$,false),
('bunong-vn','EZK',20,34,null,$b$Gâp mra leo khân may du luh tă bơh phung ƀon lan êng jêh ri rgum khân may tă bơh lĕ n'gor bri êng khân may pru pra jêh, ma ti brah jêh ri nting tur lĕ yơr jêh, jêh ri dôl gâp nkhŭt nau ji nuih.$b$,false),
('bunong-vn','EZK',20,35,null,$b$Gâp mra leo khân may njŭn lăp tâm bri rdah phung ƀon lan êng, jêh ri ta nây gâp mra ăn gŭ pa năp phat dôih khân may.$b$,false),
('bunong-vn','EZK',20,36,null,$b$Nâm bu gâp phat dôih jêh phung che khân may tâm bri rdah n'gor bri Êjipt tâm ban pô nây lĕ gâp mra phat dôih khân may, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',20,37,null,$b$Gâp mra ƀư ma khân may rgăn tâm dâng mâng jra, jêh ri mra leo khân may lăp tâm nkhăt nkol ma nau tâm rnglăp.$b$,true),
('bunong-vn','EZK',20,38,null,$b$Gâp mra mprơh du bơh khân may lĕ rngôch phung vay tâm rdâng, jêh ri phung ƀư tih rlăng ma gâp. Nđâp tơ lah gâp mra njŭn khân păng du luh tă bơh bri ntŭk khân păng gŭ njơh, ƀiă lah khân păng mâu mra lăp tâm n'gor bri Israel ôh. Nôk nây khân may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',20,39,null,$b$Bi khân may, Hơi ngih Israel, Pô aơ nau Yêhôva Brah Ndu lah: Hăn hom, ăp nơm tâm phung khân may hăn rhŏ ma rup brah păng nơm! Ƀiă lah jêh nau nây, n'hêl nanê̆ khân may mra iăt nau gâp, jêh ri mâu mra ƀư ƀơ̆ amoh gâp đŏng ôh ma ndơ khân may ƀư brah jêh ri ma rup brah khân may.$b$,true),
('bunong-vn','EZK',20,40,null,$b$Yor lah ta klơ yôk kloh gâp, klơ yôk prêh Israel, Yêhôva lah: Ta nây lĕ rngôch ngih Israel mra pah kan ma gâp tâm bri neh; ta nây gâp mra vơt dơn khân păng, jêh ri ta nây đŏng gâp mra ntăm ăn khân may nhhơr ndơ, jêh ri lĕ rngôch play bôk năm lĕ ndơ khân may nhhơr, ndrel ma lĕ rngôch ndơ ƀư brah kloh ueh khân may.$b$,true),
('bunong-vn','EZK',20,41,null,$b$Gâp mra vơt dơn khân may nâm bu ndơ n'hôl ƀâu kah, tơ lah gâp djôt leo khân may luh bơh ta nklang phung mpôl băl êng, jêh ri tâm rgum khân may tă bơh bri khân may hŏ du pru pra, jêh ri gâp mra mpơl nau kloh ueh gâp tâm nklang khân may ta năp măt phung ntil mpôl bunuyh.$b$,true),
('bunong-vn','EZK',20,42,null,$b$Ri mơ khân may gĭt gâp jêng Yêhôva, tơ lah gâp njŭn khân may lăp tâm n'gor bri Israel, bri gâp hŏ ton ăn jêh ma phung che khân may.$b$,false),
('bunong-vn','EZK',20,43,null,$b$Ta nây khân may mra kah gĭt tay trong khân may hăn jêh ri lĕ rngôch nau khân may hŏ ƀư ƀơ̆ khân may nơm; jêh ri khân may mra nduyh êng ma khân may nơm yor lĕ rngôch nau mhĭk khân may hŏ ƀư jêh.$b$,false),
('bunong-vn','EZK',20,44,null,$b$Jêh ri khân may mra gĭt gâp jêng Yêhôva, tơ lah gâp mra ƀư yor amoh gâp nơm gay vơt khân may, lơi chuat tĭng ôh trong mhĭk, jêh ri kan pah mhĭk khân may ƀư, hơi ngih Israel, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',20,45,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',20,46,null,$b$Hơi kon bunuyh, rle uănh muh măt may leo rđŭng pa dâng, jêh ri mbơh lor tâm rdâng đah bri krŏng n'gor rđŭng.$b$,false),
('bunong-vn','EZK',20,47,null,$b$Lah hom ma bri krŏng n'gor rđŭng dâng, Iăt hom nau Yêhôva ngơi: Pô aơ Yêhôva Brah Ndu lah, Aơ gâp mra sĭnh ŭnh ta nklang khân may, jêh ri ŭnh nây mra hŭt sa lĕ rngôch tơm si ndrêh ta nklang khân may, jêh ri lĕ rngôch tơm si kro; mpiăt ŭnh hit mâu mra nhhât ôh, jêh ri lĕ rngôch muh măt tă bơh n'gor rđŭng dâng tât ta n'gor dor lơ mra jêng nhhuay ŭnh.$b$,false),
('bunong-vn','EZK',20,48,null,$b$Lĕ rngôch bunuyh mra saơ gâp nơm Yêhôva sĭnh jêh ŭnh nây; ŭnh nây mâu mra nhhât ôh.$b$,false),
('bunong-vn','EZK',20,49,null,$b$Jêh ri lah, Vơ, Ơ Yêhôva Brah Ndu! Khân păng lah di ma gâp, păng ngơi hôr nau nây?$b$,false),
('bunong-vn','EZK',21,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',21,2,null,$b$“Hơi kon bunuyh, rle uănh hom muh măt leo ma ƀon Yêrusalem jêh ri nti tâm rdâng đah jrô kloh ueh; mbơh lor hom nau tâm rdâng đah bri Israel,$b$,false),
('bunong-vn','EZK',21,3,null,$b$jêh ri lah ma bri Israel: Pô aơ Yêhôva Brah: Aơ, gâp tâm rdâng ma may, jêh ri gâp mra tŏk đao dao gâp jêh ri nkhĭt nđâp ma phung sŏng jêh ri phung ƀai bơh ta nklang may.$b$,false),
('bunong-vn','EZK',21,4,null,$b$Yor lah gâp mra nkhĭt lơi nđâp phung sŏng jêh ri phung ƀai, pô ri đao dao gâp mra luh bơh ndrop păng ƀư ma lĕ rngôch bunuyh tă bơh bri rđŭng tât ma dor lơ.$b$,false),
('bunong-vn','EZK',21,5,null,$b$Jêh ri lĕ rngôch bunuyh mra gĭt ma gâp nơm Yêhôva tŏk jêh đao dao bơh ndrop; gâp mâu mra ntrŭp ôh đao dao tâm ndrop păng.$b$,false),
('bunong-vn','EZK',21,6,null,$b$Pô ri nter hom, hơi kon bunuyh; nter hom ma nuih n'hâm phit jêh ri krit rngot ta năp khân păng.$b$,false),
('bunong-vn','EZK',21,7,null,$b$Tơ lah khân păng lah ma may pô aơ: Moh nau may nter? Ăn may lah pô aơ: Yor nau mhe mhan. Yor nau nây tât, ƀư ăn lĕ rngôch nuih n'hâm mra djoh jêh ri lĕ rngôch ti jêng huơi, lĕ rngôch nau mĭn mra jêng rdja, jêh ri lĕ rngôch kômâk mra jêng rbăn nâm bu dak. Aơ, nau mra tât jêh ri jêng ngăn, Yêhôva Brah Ndu lah.”$b$,false),
('bunong-vn','EZK',21,8,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',21,9,null,$b$“Hơi kon bunuyh, mbơh lor jêh ri lah hom, Pô aơ Yêhôva lah, lah hom: Du n'gâr đao dao, du n'gâr đao dao lĕ bu tôl jêh, jêh ri lĕ mblai chrêk đŏng!$b$,false),
('bunong-vn','EZK',21,10,null,$b$Bu tôl jêh prăp sreh nkhĭt; păng lơp chrêk gay tâm rduh nâm bu lơp nglaih. He mra ƀư nau maak lĕ? Khân may tâm rmot jêh ma mâng jra, Hơi, ndrel ma ăp ntil ndơ bu ƀư ma tơm si.$b$,false),
('bunong-vn','EZK',21,11,null,$b$Pô ri bu hŏ ntĭnh tôl ăn chrêk đao dao nây, gay bu dơi djôt păng; bu tôl jêh ri păng hơr jêh gay ăn ma ti nơm nkhĭt bu.$b$,true),
('bunong-vn','EZK',21,12,null,$b$Hơi kon bunuyh, nter hom jêh ri nhĭm nhhiăng; yor lah đao dao nây ƀư ma phung ƀon lan gâp, mra ƀư ma lĕ rngôch phung kôranh Israel; bu jao jêh khân păng ma đao dao ndrel ma phung ƀon lan gâp. Pô ri tap hom tơm blu may.$b$,true),
('bunong-vn','EZK',21,13,null,$b$Nau rlong uănh mra tât ngăn. Moh nau khân may tâm rmot ma mâng jra dong? Mâng nây mra dơi, Yêhôva Brah Ndu lah,$b$,false),
('bunong-vn','EZK',21,14,null,$b$Pô ri mbơh lor hom, Hơi kon bunuyh, tap hom ti may jêh ri ăn đao dao sreh rkêch bar pe tơ̆ ; nây jêng đao dao ŭch kơi sreh bunuyh rmanh tât khĭt: Jêng đao dao ma nau tâm nkhĭt toyh ngăn ma khân păng gŭ jŭm chiau meng,$b$,false),
('bunong-vn','EZK',21,15,null,$b$Nây jêng gay ăn nuih n'hâm khân păng djoh jêh, ăn ntop âk bunuyh chôt khĭt, ta ăp ntŭk mpông pêr khân păng. Gâp hŏ ăn jêh đao dao rduh lơh, vơ! Bu lĕ tôl mblai jêh păng tât chrêk nâm bu lơp nglaih, hŏ hơr ngăn nkra ma nau tâm nkhĭt.”$b$,false),
('bunong-vn','EZK',21,16,null,$b$“Ơ đao dao, sreh ăn tăch mpeh pa ma jêh ri mpeh pa chiau tĭng nâm măt đao lăp hăn.$b$,true),
('bunong-vn','EZK',21,17,null,$b$Gâp tâm ban lĕ mra tap bar đah mpang ti, jêh ri gâp mra mpay nau gâp ji nuih, gâp nơm Yêhôva ngơi nau nây.$b$,false),
('bunong-vn','EZK',21,18,null,$b$Yêhôva ngơi đŏng ma gâp:$b$,true),
('bunong-vn','EZK',21,19,null,$b$Hơi kon bunuyh, may tâm ban lĕ, treh nchŏng bar mbor trong hăn ăn đao dao hađăch Babilôn mra văch tât; lĕ bar trong nây mra luh văch tât tă bơh du n'gor bri. Ƀư hom jrăng gâng tâm nal, ndâk păng ta tơm trong hăn ma du rplay ƀon ri;$b$,false),
('bunong-vn','EZK',21,20,null,$b$treh nchŏng trong ma đao dao tât ma ƀon Rabla tâm n'gor phung Amôn jêh ri trong êng tât ma n'gor Yuđa jêh ri tât ma ƀon Yêrusalem ƀon geh pôih ta han.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','EZK',21,21,null,$b$Yor lah hađăch Babilôn dâk ta nglah trong ta ntŭk bar mlâm tơm trong, ŭch ƀư nau pol; păng rsŭng tâm nchroh ma hăr, păng ôp ma rup brah têraphim, jêh ri sek uănh klơm (ntơh hăr)$b$,false),
('bunong-vn','EZK',21,22,null,$b$Gâp nchroh di ma ƀon Yêrusalem gŭ ta ti pa ma păng, gay hă trôm mbung ŭch nter, ŭch troh nter, djôt mâng gay dong rlâm mpông pêr, gay n'hao neh ŭch ƀư mpêr, gay rdâk ngih tŭm ma nau tâm lơh.$b$,false),
('bunong-vn','EZK',21,23,null,$b$Ƀiă lah phung ton săk gŭ răp jăp ndrel păng mra mĭn jêng n'hŭm pol nau mƀruh; ƀiă lah hađăch Babilôn mra nkah khân păng kah gĭt nau khân păng jêng tih, gay nhŭp khân păng jêng bu nă.$b$,false),
('bunong-vn','EZK',21,24,null,$b$Yor ri, Yêhôva Brah Ndu lah pô aơ: Yor lah khân may hŏ nkah ăn kah gĭt tay nau kue khân may nơm, ma nau mpơl nau tih khân may, pô ri tâm lĕ rngôch nau khân may ƀư nau tih khân may hŏ mpơl jêh yor lah khân may ăn bu kah gĭt, bu mra nhŭp khân may leo jêng bu nă.$b$,true),
('bunong-vn','EZK',21,25,null,$b$Bi may, Hơi kôranh phung Israel, bunuyh djơh mhĭk nâm bu sôt rmanh tât khĭt nây, nar rmal may hŏ tât jêh, nglĕ dŭt tâm nau djơh mhĭk may.$b$,false),
('bunong-vn','EZK',21,26,null,$b$Pô aơ nau Yêhôva Brah Ndu lah: Prăp lơi hom đon hađăch aơ, jêh ri doh lơi bok mpân bôk aơ; nau aơ mâu hôm tâm ban ôh nâm bu kơt sa ơm! Bu mra n'hao phung dêh rhêt, jêh ri ntrŭnh lơi phung sưr.$b$,false),
('bunong-vn','EZK',21,27,null,$b$Gâp mra bun păng mbŭch rai yot, mbŭch rai yot, mbŭch rai yot păng; nau aơ ăt mâu hôm lĕ, kŏ tât ndah jŏ Nơm khư văch tât; jêh ri ma nơm nây yơh gâp mra ăn nau chiă uănh nây.$b$,false),
('bunong-vn','EZK',21,28,null,$b$Bi may, Hơi kon bunuyh, mbơh lor jêh ri lah hom, pô aơ nau Yêhôva Brah Ndu lah ma phung Amôn jêh ri ma nau khân păng ngơi rlơn, rlơng nau bu, Yêhôva Brah Ndu lah pô aơ. Ngơi hom: Du n'gâr đao dao, đao dao hŏ bu tŏk jêh ma nau tâm nkhĭt, bu tôl chrêk jêh, jêh ri gay tâm rduh chrêk nâm bu lơp nglaih!$b$,true),
('bunong-vn','EZK',21,29,null,$b$Dôl khân păng saơ, nau may tâm saơ mƀruh dôl khân păng pol nau mƀruh ma may bu mra prơh may koh trô ko phung ƀai sôt rmanh nkhĭt lơi, nar rmal khân păng hŏ tât, tâm rnôk phat dôih kêng nglĕ dŭt tât jêh.$b$,false),
('bunong-vn','EZK',21,30,null,$b$Nsro đao tâm ndrop păng! Nây jêng ntŭk hŏ njêng may, tâm ntŭk bu deh ma may, gâp mra phat dôih may.$b$,true),
('bunong-vn','EZK',21,31,null,$b$Gâp nkhŭt nau gâp ji nuih ta klơ may; sŏk ŭnh nau gâp ji nuih khôm ta klơ may, jêh ri gâp mra jao may tâm ti phung djơh mhĭk, blau nkhĭt nuyh.$b$,false),
('bunong-vn','EZK',21,32,null,$b$Khân may mra jêng long sênh ŭnh; bu mra ƀư pling mham may ta bri may; jêh ri bu mâu hôm kah gĭt may ôh; yor lah gâp nơm, Yêhôva ngơi jêh nau nây.”$b$,false),
('bunong-vn','EZK',22,1,null,$b$Yêhôva ngơi đŏng ma gâp, lah:$b$,true),
('bunong-vn','EZK',22,2,null,$b$Hơi kon bunuyh, bi may mra phat dôih, may mra phat dôih lĕ ma ƀon pling mham aơ? Pô ri mbơh hom ăn păng gĭt lĕ rngôch nau mhĭk gâp tâm rmot păng hŏ ƀư.$b$,false),
('bunong-vn','EZK',22,3,null,$b$Ăn may lah: Pô aơ nau Yêhôva Brah Ndu lah: Du rplay ƀon pling mham gŭ ta nklang păng, gay ăn tât nar phat dôih jêh ri ƀon ƀư rup brah nsŭk êng săk nơm ƀư nau ƀơ̆ ƀơch păng nơm!$b$,false),
('bunong-vn','EZK',22,4,null,$b$Yor tă mham may hŏ pling jêh, may jêng tih jêh, jêh ri ƀư ƀơ̆ may nơm ma rup brah may hŏ ƀư. Pô nây may hŏ ƀư ăn nar bu phat dôih ma may lĕ dăch, dăch lôch rnôk tâm nal ma may tât jêh. Yor ri, gâp ăn may jêng ndơ prêng ma ntil mpôl bunuyh, ƀư ăn lĕ rngôch bri dak bu gơm mưch.$b$,false),
('bunong-vn','EZK',22,5,null,$b$Phung gŭ dăch jêh ri phung gŭ ngai bơh may mra gơm mưch ma may, jêng ƀon bu lư nau djơh, bêng ma nau drơu drơu.$b$,false),
('bunong-vn','EZK',22,6,null,$b$Aơ, phung kôranh Israel gŭ tâm may, ăp nơm tĭng nâm n'hâm suan, kâp pling mham.$b$,true),
('bunong-vn','EZK',22,7,null,$b$Ta ntŭk may, bu tâm rmot mê̆ mbơ̆ ; ta ntŭk may, bu tŭn jot ma nơm njơh ƀât lât; ta ntŭk may, bu nsŭk ma phung kon đơi ƀư tih nđâp ma phung rêh ndrô.$b$,true),
('bunong-vn','EZK',22,8,null,$b$May mưch rmot jêh ma ndơ kloh ueh gâp, jêh ƀư ƀơ̆ nar Saƀat gâp!$b$,false),
('bunong-vn','EZK',22,9,null,$b$Ta ntŭk may, geh phung nchơt nklă njêng nau ŭch pling mham; jêh ri geh phung tâm may sông sa ta klơ yôk; ta ntŭk may, geh bunuyh ƀư tih văng tĭr.$b$,false),
('bunong-vn','EZK',22,10,null,$b$Ta ntŭk may, geh bunuyh pơk mpơl nau rhôk phung mbơ̆ khân păng; ta ntŭk may, geh bunuyh ƀư ƀơ̆ đah bu ur dôl geh trâl khay.$b$,true),
('bunong-vn','EZK',22,11,null,$b$Ta ntŭk may, bunuyh aơ ƀư nau mhĭk gâp tâm rmot đah ur bu chiau meng păng; geh nuyh êng ƀư ndjơh đah ƀăn păng nơm; bunuyh êng đŏng tâm bri ƀư ƀơ̆ oh khân păng, kon bu ur mbơ̆ păng.$b$,false),
('bunong-vn','EZK',22,12,null,$b$Ta ntŭk may, phung bu klâu sŏk drăp bu băk mưn gay pling mham bu; may hŏ sa kao jêh ri sa ndơ bơh phung chiau meng may, ma nau thăm rmat; jêh ri may lĕ chuêl jêh gâp. Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',22,13,null,$b$Pô ri, aơ, gâp tap mpang ti yor nau tih may sa ndơ, jêh ri yor mham pling jêh ta nklang may.$b$,true),
('bunong-vn','EZK',22,14,null,$b$Tơ lah tât nar gâp mra lơh may, dơi lĕ nau ktang may ăt hôm jêng ktang tâm rnôk gâp lơh đah may? Gâp nơm, Yêhôva hŏ ngơi jêh, jêh ri mra ƀư ngăn nau nây.$b$,false),
('bunong-vn','EZK',22,15,null,$b$Gâp mra ƀư ma may chah rai pru pra du ran ntil mpôl bunuyh êng, mprơh may lam bri dak êng, jêh ri gâp mra ƀư rai lơi nau ƀơ̆ ƀơch tă bơh nklang may.$b$,false),
('bunong-vn','EZK',22,16,null,$b$Rnôk nây, tơ lah bu ƀư ƀơ̆ khân may ta năp măt phung ntil mpôl bunuyh, may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',22,17,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',22,18,null,$b$Hơi kon bunuyh, ngih Israel jêng jêh ndơ ƀơ̆ ma gâp; lĕ rngôch khân păng jêng prăk, kông, loih, ndrak tâm ŭnh năk, nây jêng ndơ bu nkret.$b$,false),
('bunong-vn','EZK',22,19,null,$b$Yor ri, Yêhôva Brah Ndu lah: Yor lah lĕ rngôch khân may jêng ndơ ƀơ̆ , yor nây aơ, gâp rgum khân may ta nklang ƀon Yêrusalem.$b$,true),
('bunong-vn','EZK',22,20,null,$b$Tâm ban bu rgum prăk, kông, loih, ndrak jêh ri nkret tâm ŭnh năk gay khôm ŭnh ƀư lêk ndơ nây, tâm ban nây lĕ gâp mra rgum khân may dôl gâp hao ji nuih jêh ri nuih, jêh ri gâp mra dơm khân may tâm ŭnh năk jêh ri ƀư lêk (nglêk) khân may.$b$,false),
('bunong-vn','EZK',22,21,null,$b$Gâp mra rgum khân may jêh ri khôm ŭnh nau gâp ji nuih ma khân may, jêh ri khân may lêk tâm nklang ŭnh nây.$b$,false),
('bunong-vn','EZK',22,22,null,$b$Nâm bu prăk lêk tâm ŭnh năk, tâm ban nây lĕ khân may mra lêk ta nklang nau gâp ji nuih; jêh ri khân may mra gĭt gâp jêng Yêhôva nkhŭt jêh nau gâp ji nuih ma khân may.$b$,true),
('bunong-vn','EZK',22,23,null,$b$Yêhôva ngơi đŏng ma gâp:$b$,false),
('bunong-vn','EZK',22,24,null,$b$Hơi kon bunuyh, lah hom ma bri neh, May jêng du rplay bri mâu kloh ôh, kŏ mâu geh dak mih lĕ tâm nar gâp nuih.$b$,false),
('bunong-vn','EZK',22,25,null,$b$Phung kôranh mbơh lor păng njêng nklă ta nklang păng nâm bu du mlâm yau mŭr gŭ ngrông dôl grang hêk mpa păng kăp; khân păng lĕ sa jêh huêng bunuyh; khân păng sŏk jêh drăp ndơ jêh ri ndơ khlay; khân păng njêng jêh âk bu ur khĭt sai ta nklang ƀon.$b$,false),
('bunong-vn','EZK',22,26,null,$b$Lĕ rngôch phung kôranh ƀư brah păng ƀư tih đah nau vay gâp, jêh ri ƀư ƀơ̆ jêh ndơ kloh ueh gâp; khân păng mâu kơp rnglah êng ôh moh ndơ jêng kloh ueh; moh ndơ jêng ƀơ̆ đah ndơ kănđai, mâu lĕ khân păng mâp nti nau rnglah êng ndơ kloh ma đah ndơ mâu kloh ôh, jêh ri khân păng mâu chrê ôh ma nar Saƀat gâp, pô nây khân păng ƀư ƀơ̆ gâp ta nklang khân păng.$b$,false),
('bunong-vn','EZK',22,27,null,$b$Phung kôranh ta nklang păng nâm bu so bri hêk sa mpa bu kăp, knŏng ŭch pling mham, ƀư roh lơi huêng, gay pit in drăp ndơ.$b$,false),
('bunong-vn','EZK',22,28,null,$b$Phung kôranh mbơh lor păng nsut ma klo nglang, geh nau tâm saơ mƀruh jêh ri ƀư nau pol mƀruh ma khân păng, ngơi n'hi, pô aơ nau Yêhôva Brah Ndu lah ƀiă lah Yêhôva mâu mâp ngơi ôh.$b$,false),
('bunong-vn','EZK',22,29,null,$b$Phung ƀon lan tâm n'gor bri ƀư nau thăm man jêh ri nau ntŭng ndô ndơ bu; khân păng tŭn jot phung o-ach jêh ri phung mâu geh ndơ, jêh ri tŭn jot bunuyh gŭ njơh ƀât lât mâu ƀư nau tâm di.$b$,false),
('bunong-vn','EZK',22,30,null,$b$Gâp joi du huê bunuyh ta nklang khân păng, gay ndâk mpêr ƀon toyh, gŭ dâk ta ntŭk lĕ rluh ta năp gâp, gay ma gâp mâu ƀư rai păng ôh; ƀiă lah gâp joi mâu dơi geh du huê bunuyh.$b$,true),
('bunong-vn','EZK',22,31,null,$b$Yor ri gâp nkhŭt nau ji nuih ta klơ khân păng, jêh ri gâp sŏk ŭnh ji nuih su khân păng; gâp hŏ ƀư jêh nau khân păng ƀư ntŭp ta klơ bôk khân păng nơm Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',23,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',23,2,null,$b$“Hơi kon bunuyh, geh bar hê bu ur, kon bu ur du me bă;$b$,false),
('bunong-vn','EZK',23,3,null,$b$khân păng ƀư nau văng tĭr tâm n'gor bri Êjipt; khân păng ƀư nau văng tĭr dôl khân păng druh mom; ta nây bu pet toh khân păng jêh ri bi ndŭl druh tang tat khân păng.$b$,false),
('bunong-vn','EZK',23,4,null,$b$Amoh nur jêng H'Ôhôla jêh ri amoh oh păng jêng H'Ôhôliba. Khân păng jêng ndơ ma gâp, jêh ri deh kon bu ur, kon bu klâu. H'Ôhôla jêng ƀon Samari, jêh ri H'Ôhôliba jêng ƀon Yêrusalem.$b$,false),
('bunong-vn','EZK',23,5,null,$b$H'Ôhôla ƀư nau văng tĭr dôl păng jêng ndơ gâp; păng rŏng ma tĭr păng phung Asiri, phung chiau meng păng.$b$,true),
('bunong-vn','EZK',23,6,null,$b$Nsoh ao chăng, phung kôranh ta han jêh ri kôranh chiă uănh, lĕ rngôch khân păng jêng bu klâu ndăm ueh bu kơnh, vay ncho seh.$b$,false),
('bunong-vn','EZK',23,7,null,$b$Păng ƀư nau tâm dŏng đah phung bu klâu ndăm ueh lơn ngăn tâm phung Asiri; jêh ri păng ƀư ƀơ̆ păng nơm ma lĕ rngôch rup brah ăp nơm păng rŏng.$b$,false),
('bunong-vn','EZK',23,8,null,$b$Păng mâu lơi ôh nau ka n'hong păng ƀư jêh ntơm bơh rnôk păng gŭ tâm n'gor bri Êjipt; yor lah păng druh mom phung bu klâu bêch jêh ndrel păng jêh ri bi jêh ndŭl druh păng jêh ri ƀư mpay nau khân păng tâm kơnh đah păng.$b$,false),
('bunong-vn','EZK',23,9,null,$b$Yor nây gâp jao jêh păng, tâm ti tĭr păng, tâm ti phung Asiri, ma phung nây păng rŏng.$b$,false),
('bunong-vn','EZK',23,10,null,$b$Phung nây mpơl nau rhôk păng; khân păng sŏk phung bu ur jêh ri phung kon bu klâu păng, jêh ri khân păng nkhĭt ô băl nơm ma đao. Păng hŏ jêng nau bu nkoch ntêh rmot tâm phung bu ur; yor lah khân păng hŏ ƀư jêng nau phat dôih ma păng.$b$,true),
('bunong-vn','EZK',23,11,null,$b$Oh bu ur păng H'Ôhôliba saơ nau nây, ƀiă lah păng jêng ka n'hong tih lơn ma păng đah phung păng rŏng, jêng glăm lơn ma nur păng.$b$,true),
('bunong-vn','EZK',23,12,null,$b$Păng rŏng ma phung Asiri, phung kôranh ta han, jêh ri phung kôranh chiă uănh, jêng phung chiau meng păng, nkrơ̆ nsoh ăp ntil ao loih, vay ncho seh, lĕ rngôch jêng bu klâu ueh bu kơnh.$b$,false),
('bunong-vn','EZK',23,13,null,$b$Gâp saơ bu ƀư ndrih jêh păng, jêh ri lĕ bar hê oh nur chuat hăn du trong dơm.$b$,false),
('bunong-vn','EZK',23,14,null,$b$Tơ lah păng saơ bu kach rup bu klâu ta klơ mpêr, rup phung Kaldê ma dak nglang, pô ri păng lơ hâu ƀư nau văng tĭr păng.$b$,false),
('bunong-vn','EZK',23,15,null,$b$Khân păng vân rse bŭt jêh ri mpân kưn rjai ta klơ bôk, lĕ rngôch bu uănh ma khân păng nâm bu kôranh ta han. Khân păng njêng nâm bu phung Babilôn tă bơh bri Kaldê.$b$,false),
('bunong-vn','EZK',23,16,null,$b$Tơ lah păng saơ nau nây, păng rŏng ma khân păng, jêh ri prơh hăn bunuyh mbơh ma khân păng tâm n'gor Kaldê.$b$,false),
('bunong-vn','EZK',23,17,null,$b$Phung Babilôn văch ma păng jêh ri bêch ndrel păng; jêh ri khân păng ƀư ndjrih ma nau khân păng kơnh; jêh ri tơ lah khân păng lĕ ƀư ndjrih jêh păng, păng ƀư ƀơ̆ êng păng nơm đah khân păng; jêh ri nuih n'hâm păng lĕ dĭl jêh.$b$,false),
('bunong-vn','EZK',23,18,null,$b$Păng hŏ mpơl jêh nau văng tĭr păng, jêh ri sưr ma nau păng rhôk, pô ri nuih n'hâm gâp ji nuih ngăn ma păng, nâm bu hŏ ji nuih jêh ma nur păng.$b$,false),
('bunong-vn','EZK',23,19,null,$b$Ƀiă lah păng ăt hôm ƀư nau ka n'hong lơ hâu lơn, kah gĭt tay ma rnôk păng druh mom jêh ri nôk păng ƀư nau văng tĭr tâm n'gor bri Êjipt,$b$,false),
('bunong-vn','EZK',23,20,null,$b$Jêh ri rŏng ma phung tĭr ơm păng, ta nây geh đŏng nâm bu đŏng seh bri, jêh ri geh nau tâm jơng nâm bu seh.$b$,false),
('bunong-vn','EZK',23,21,null,$b$Pô ri, ay klân rvê ngăn ma nau văng tĭr dôl ay druh mom, tơ lah phung Êjipt bi ndŭl druh tang-tat ay, jêh ri pet toh ay.$b$,false),
('bunong-vn','EZK',23,22,null,$b$Yor nây, Hơi H'Ôhôliba, Yêhôva Brah Ndu lah pô aơ: Aơ, gâp mra nsônh tĭr ay tâm rdâng đah ay, phung nây ay lĕ dĭl ji nuih ngăn, jêh ri leo khân păng tât tă bơh lam njônh bri tâm rdâng đah ay;$b$,true),
('bunong-vn','EZK',23,23,null,$b$nâm bu phung Babilôn, lĕ rngôch phung Kaldê, phung Pêkôt, phung Sôa, jêh ri Kôa, jêh ri lĕ rngôch phung Asiri ndrel ma khân păng, jêng phung bu klâu ndăm ueh-reh bu kơnh, phung kôranh chiă uănh jêh ri phung kôranh ta han, lĕ rngôch khân păng jêng kôranh ta han jêh ri phung ta han tâm lơh, lĕ rngôch ncho seh da dê.$b$,false),
('bunong-vn','EZK',23,24,null,$b$Khân păng văch tă bơh dor lơ ncho ndeh seh jêh ri ndeh nđuih, jêh ri phung ƀon lan âk râk tât tâm lơh đah ay; khân păng nchueng jŭm chiau meng ay djôt leo khêl toyh, khêl jê̆, jêh ri ndô môk loih; gâp mra jao kan phat dôih tĭng nâm nau vay khân păng.$b$,false),
('bunong-vn','EZK',23,25,null,$b$Gâp mra leo nau gâp ji nuih rlet ma ay, gay ăn phung nuih mra ƀư ma ay ma nau duh nuih. Khân păng mra koh trôm muh jêh ri tôr ay jêh ri phung ay hôm-e klen mra cha lôt ma đao. Khân păng mra nhŭp kon bu ur kon bu klâu ay; jêh ri phung ay hôm-e klen ŭnh mra hŭt.$b$,false),
('bunong-vn','EZK',23,26,null,$b$Tâm ban lĕ, khân păng mra doh bok ao ay jêh ri pit in ndơ nkrơ̆ khlay ay.$b$,false),
('bunong-vn','EZK',23,27,null,$b$Pô nây yơh gâp ƀư dŭt lơi nau ay văng tĭr jêh ri ƀư nau ka n'hong ay djôt leo tă bơh n'gor bri Êjipt; kŏ tât ay mâu hôm n'gor măt uănh khân păng, jêh ri mâu hôm kah rvê ma Êjipt đŏng ôh.$b$,true),
('bunong-vn','EZK',23,28,null,$b$Yor lah Yêhôva Brah Ndu lah pô aơ: Aơ, gâp mra jao ay tâm ti phung ay tâm rmot, tâm ti phung ay lĕ ji nuih biănh;$b$,false),
('bunong-vn','EZK',23,29,null,$b$Jêh ri khân păng mra ƀư ma ay ma nau tâm rmot, jêh ri du nchuăn lĕ rngôch play n'hâm suan ay pah kan, gay ăn ay bêch kuh rhôk, pô ri nau rhôk nau ay ƀư mra mpơl, nau ay văng tĭr jêh ri nau ka n'hong.$b$,false),
('bunong-vn','EZK',23,30,null,$b$Ăn tât nau aơ ma ay nơm, jêh ri ƀư ƀơ̆ jêh ay nơm ma rup brah khân păng.$b$,false),
('bunong-vn','EZK',23,31,null,$b$Ay hŏ tĭng ndô̆ trong nur ay; yor ri gâp mra ăn kachok păng nhêt tâm ti ay.$b$,true),
('bunong-vn','EZK',23,32,null,$b$Pô aơ nau Yêhôva Brah Ndu lah: Ay mra nhêt kachok nur ay, kachok nây jêng jru jêh ri huy, bu bun âk ngăn; bu mra gơm mưch ma ay jêh ri ntêh rmot.$b$,false),
('bunong-vn','EZK',23,33,null,$b$Ay mra bêng ma nau nhŭl ndrănh jêh ri rngot rvê; yor kachok nur ay Samari, jêng kachok tâm nau nhhu nkrit jêh ri jêng rngol$b$,false),
('bunong-vn','EZK',23,34,null,$b$Ay mra nhêt kachok nây, kŏ tât lĕ, jêh ri sêk ay gĭnh tât hăch rhên jêh ri rek êng toh ay nơm. Yor lah gâp hŏ lah jêh, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',23,35,null,$b$Yor nây, pô aơ Yêhôva Brah Ndu lah: Yor lah ay lĕ chuêl gâp jêh, jêh ri ndôn pa kơi ay ăn ma gâp, pô nây ăn ay dơn nau tât yor nau ay văng tĭr jêh ri nau ay ƀư ka n'hong.$b$,true),
('bunong-vn','EZK',23,36,null,$b$Yêhôva lah ma gâp: Hơi kon bunuyh mâu hĕ may phat dôih ma H'Ôhôla jêh ri H'Ôhôliba? Pô ri mbơh hom ma khân păng gĭt lĕ nau khân păng ƀư mhĭk gâp tâm rmot.$b$,true),
('bunong-vn','EZK',23,37,null,$b$Yor lah khân păng hŏ văng tĭr, geh ta ti khân păng krêp mham; khân păng hŏ văng tĭr jêh đah rup brah khân păng; nđâp khân păng nhhơr ndơ sông sa ma rup brah nây, jêng phung kon khân păng deh jêh ma gâp.$b$,false),
('bunong-vn','EZK',23,38,null,$b$Nđâp khân păng ƀư kan aơ ma gâp: Tâm du nar khân păng ƀư ƀơ̆ jrô kloh ueh gâp, jêh ri ƀư nkhơng lĕ rngôch nar Saƀat gâp;$b$,false),
('bunong-vn','EZK',23,39,null,$b$jêh khân păng nkhĭt lơi kon păng nơm nhhơr ma rup brah, tâm nar nây khân păng lăp tâm ntŭk jrô kloh ueh gâp gay ƀư ƀơ̆ ƀơch! Nau nây yơh khân păng ƀư ta nklang ngih gâp!$b$,false),
('bunong-vn','EZK',23,40,null,$b$Nđâp ma khân păng prơh hăn du huê bunuyh hăn jă kuăl bunuyh tă bơh bri ngai văch tât ndrel păng, aơ, khân păng hŏ tât; yor phung nây ay hŏ ŭm rao jêh, ay chih kach trôm măt ay, jêh ri ay ndrăp nkrơ̆ săk ay.$b$,false),
('bunong-vn','EZK',23,41,null,$b$Ay gŭ ta klơ sưng bêch, pa năp sưng nây geh du mlâm sưng sông ay dơm ndơ ƀâu kah ta ntŭk nây jêh ri dak play ôlivơ gâp.$b$,false),
('bunong-vn','EZK',23,42,null,$b$Ndrel ma păng bu tăng bâr phung âk ƀư nau maak; jêh ri ndrel ma phung bu klâu bunuyh ƀon lan vay nhŭl ndrănh bu hŏ njŭn leo tă bơh bri rdah; khân păng dok kông ta ti bar hê oh nur, jêh ri ndô đon lơp rmah ta klơ bôk.$b$,false),
('bunong-vn','EZK',23,43,null,$b$Pô ri gâp geh lah ma bunuyh hŏ bu ranh yor nau văng tĭr pô aơ: Aƀaơ khân păng ƀư nau văng tĭr đah păng, jêh ri păng đah phung nây.$b$,true),
('bunong-vn','EZK',23,44,null,$b$Yor lah phung nây văch tât ma păng nâm bu văch ma bu ur văng tĭr. Pô ri yơh khân păng hăn ma H'Ôhôla jêh ri H'Ôhôliba gay ŭch nau dŏng tĭr.$b$,false),
('bunong-vn','EZK',23,45,null,$b$Ƀiă lah phung bunuyh sŏng mra phat dôih ma păng văng tĭr jêh ri ma bu ur pling mham bu; yor lah khân păng jêng phung văng tĭr, jêh ri kăr mham tâm ti khân păng.$b$,false),
('bunong-vn','EZK',23,46,null,$b$Yor ri, Yêhôva lah pô aơ: Gâp mra leo du phung âk hao lơh đah khân păng, jêh ri njêng ma khân păng du phung bu ƀư nkrit jêh ri ndơ bu tâm pit.$b$,true),
('bunong-vn','EZK',23,47,null,$b$Phung âk nây mra sŏk lŭ klŭp khân păng, jêh ri sŏk đao ntâp sreh khân păng; nkhĭt kon bu ur bu klâu khân păng, jêh ri n'ho su ngih vâl khân păng.$b$,false),
('bunong-vn','EZK',23,48,null,$b$Pô ri yơh gâp mra ƀư ăn lĕ nau văng tĭr tâm bri tâm bri dak, gay ăn ma lĕ rngôch phung bu ur gĭt njrăng-jêh ri mâu hôm ƀư ôh nau lâm rlau nâm bu khân ay may ƀư.$b$,false),
('bunong-vn','EZK',23,49,null,$b$Bu mra ntŭp nau lâm rlau khân ay may ta khân ay may nơm, jêh ri khân ay may mra dơn nau tâm rmal yor nau tih khân ay may mbah rup brah; jêh ri ay may mra gĭt gâp jêng Yêhôva Brah Ndu.$b$,false),
('bunong-vn','EZK',24,1,null,$b$Năm rơh sĭn, khay jât, năng jât geh nau Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',24,2,null,$b$Hơi kon bunuyh, chih hom kơp moh nar aơ, jêng nar aơ yơh; nar aơ ro hađăch Babilôn văch dăch ntơm chueng ƀon toyh Yêrusalem.$b$,false),
('bunong-vn','EZK',24,3,null,$b$Ngơi du nau hôr ma phung ƀon lan vay tâm rdâng, jêh ri lah hom ma khân păng, Yêhôva lah pô aơ: N'gân hom glah, gâm hom, troch hom dak tâm glah nây đŏng;$b$,false),
('bunong-vn','EZK',24,4,null,$b$chê̆ tâm glah nây âk gâl mlay puăch, lĕ rngôch gâl ueh, gang ƀŭt jêh ri nglik; ăn bêng glah ma nting dŭt ueh.$b$,false),
('bunong-vn','EZK',24,5,null,$b$Joi săch du mlâm biăp ueh ngăn tâm phung, jêh ri nsro long tâm dâng glah, gay gâm puăch nây, gâm ndrel ma nting ta nây lĕ, ăn khuh.$b$,false),
('bunong-vn','EZK',24,6,null,$b$Yor nây pô aơ nau Yêhôva Brah Ndu lah: Rêh ni ngăn ma phung ƀon pling mham, ma glah lĕ ek găm tâm trôm, jêh ri ek găm nây mâu blau kloh ôh! Sŏk tă tâm nây du kô̆ du kô̆ ăn lĕ, lơi ƀư nau lah nchroh ôh.$b$,true),
('bunong-vn','EZK',24,7,null,$b$Yor lah mham păng pling jêh hôm e ta nklang păng; păng pling mham nây ta klơ lŭ chrêk, păng mâu pling ôh mham nây ta neh gay brôi lơi ô băl.$b$,true),
('bunong-vn','EZK',24,8,null,$b$Nây jêng nau ŭch nsônh ji nuih gâp, gay ăn gâp har plơng bôk, gâp lĕ pling jêh mham păng ta klơ lŭ chrêk, kŏ tât păng mâu hôm dơi nkŭm ôh.$b$,false),
('bunong-vn','EZK',24,9,null,$b$Yor ri, pô aơ Yêhôva Brah Ndu lah: Rêh ni ngăn ma ƀon phung pling mham! Gâp tâm ban lĕ mra srŏ long ăn âk.$b$,true),
('bunong-vn','EZK',24,10,null,$b$Bun long ăn âk, sĭnh ŭnh, gay nkret puăch, tât kroh dak, jêh ri ŭnh sa nting.$b$,false),
('bunong-vn','EZK',24,11,null,$b$Jêh ta nây, dơ glah dơm ta klơ sa ônh rnga, gay ăn glah nây dŭm, kŏ tât ndơ ƀơ̆ ƀơch tâm trôm lêk rai lĕ, jêh ri ek găm tâm trôm păng du lĕ ƀhiau.$b$,false),
('bunong-vn','EZK',24,12,null,$b$Păng pah kan hŏt rgănh dơm dam, ƀiă lah ek găm krêp ngăn tâm păng ê-hŏ luh du; nđâp tơ lah dơm ek găm păng tâm ŭnh kŏ mâu du luh lĕ!$b$,false),
('bunong-vn','EZK',24,13,null,$b$Ek găm nây jêng nau văng tĭr ƀơ̆ ƀơch may: Yor gâp hŏ jut kloh may jêh ri may mâu dơi jêng kloh ôh, yor ri may mâu mra dơi tho rao nau ƀơ̆ rmau may đŏng ôh, kŏ tât mpay jêh nau gâp hŏ ji nuih ma may.$b$,false),
('bunong-vn','EZK',24,14,null,$b$Gâp nơm jêng Yêhôva hŏ ngơi jêh nau nây; nau nây mra tât, gâp mra ƀư nau nây; gâp mâu mra plơ̆ rŭch ôh, gâp mâu mra nhhuach ôh, gâp mâu mra gâl ôh nau gâp mĭn; gâp mra phat dôih may tĭng nâm trong may chuat jêh ri tĭng nâm kan may pah, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',24,15,null,$b$Tâm ban lĕ geh nau Yêhôva ngơi ma gâp pô aơ:$b$,true),
('bunong-vn','EZK',24,16,null,$b$Hơi kon bunuyh, aơ gâp lĕ dăch sŏk lơi jêh nau maak tă bơh may nau măt may ŭch kơnh; ƀiă lah lơi ta may klân rvê ôh mâu lah nhhiăng nhĭm mâu lah hor dak măt ôh.$b$,false),
('bunong-vn','EZK',24,17,null,$b$Nhĭm vơl hom, ƀiă lah mâu nteh ôh; ƀiă lah lơi ta klân rvê ôh ma nơm khĭt. Mpân bok ta klơ bôk may; nsoh ntâu jot tâm jâng may. Lơi ta rdêp ôh trôm mbung may, mâu lĕ sa piăng let bu ran njơh khĭt.$b$,false),
('bunong-vn','EZK',24,18,null,$b$Pô ri ơm ôi gâp ngơi ndrel ma ƀon lan; tât kêng mhaơ ur gâp khĭt. Kah ôi taơ gâp ƀư tĭng nâm nau Yêhôva hŏ ntăm jêh ma gâp.$b$,true),
('bunong-vn','EZK',24,19,null,$b$Rnôk nây phung ƀon lan lah ma gâp pô aơ: Mâm may mâu ŭch mbơh ma hên nâm bu ntĭt nau aơ di ma hên, kŏ tât may ƀư pô nây?$b$,false),
('bunong-vn','EZK',24,20,null,$b$Gâp plơ̆ sĭt lah ma khân păng, Yêhôva ngơi ma gâp:$b$,false),
('bunong-vn','EZK',24,21,null,$b$Lah hom ma ngih Israel, Pô aơ nau Yêhôva lah: Aơ, mra ƀư ƀơ̆ jrô kloh ueh gâp, jêng ntŭk khân may ƀư nau sưr ma brah khân may, jêh ri nau trôm măt khân may ŭch kơnh, nuih n'hâm khân yô̆ klâng; jêh ri lĕ rngôch kon bu ur kon bu klâu khân may hŏ cha lơi jêh ma cha lôt yor ma đao.$b$,false),
('bunong-vn','EZK',24,22,null,$b$Rnôk nây khân may mra bu nâm ƀư gâp hŏ ƀư jêh: Khân may, mâu mra rdêp ôh trôm mbung khân may, mâu lĕ sa piăng let bu văch ran.$b$,false),
('bunong-vn','EZK',24,23,null,$b$Khân may mpân bok mro, ta klơ bôk jêh ri nsoh mro ntâu jot tâm jâng; khân may mâu klâng rvê ôh, ƀiă lah khân may mra rngot rvê ma nau kue khân ay may nơm jêh ri vơl ndrăng khân may dơm.$b$,true),
('bunong-vn','EZK',24,24,null,$b$Pô nây yơh Y-Êsêkiêl mra jêng du nau mbên ma khân ay may, tĭng nâm lĕ nau păng hŏ ƀư jêh, pô ri yơh khân ay may mra ƀư. Tơ lah nau aơ tât, rnôk nây khân ay may mra gĭt gâp jêng Yêhôva Brah Ndu.$b$,false),
('bunong-vn','EZK',24,25,null,$b$Bi may, Hơi kon bunuyh, tâm nar gâp mra sŏk lơi ntŭk brah tă bơh khân păng, nau maak jêh ri nau chrêk rmah khân păng, nau măt ŭch kơnh jêh ri nuih n'hâm khân păng rŏng, jêh ri tâm ban lĕ nđâp phung kon bu ur jêh ri kon bu klâu khân păng,$b$,true),
('bunong-vn','EZK',24,26,null,$b$ta nar nây đŏng mra geh du huê klaih ran tât ma may gay mbơh nau mhe mhan aơ ma may.$b$,false),
('bunong-vn','EZK',24,27,null,$b$Tâm nar nây, trôm mbung may mra hă ma nơm du klaih, may mra ngơi jêh ri mâu hôm jêng mlo ôh. Pô ri may mra jêng du ntil ndơ tâm mbên ma khân păng, jêh ri khân păng mra gĭt ma gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',25,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',25,2,null,$b$“Hơi kon bunuyh, n'gĭl hom muh măt may rlet phung kon sau Amôn, jêh ri mbơh lor tâm rdâng đah khân păng.$b$,false),
('bunong-vn','EZK',25,3,null,$b$Lah hom ma phung kon sau Amôn: Iăt hom nau Yêhôva Brah Ndu ngơi. Yêhôva Brah Ndu lah pô aơ: Yor lah may lah, “Ha Hai!” Ma jrô kloh ueh gâp tơ lah bu ƀư ƀơ̆ jêh, jêh ri ma bri neh Israel, tơ lah păng lĕ bu ăn jêng rngol jêh, jêh ri ma ngih Yuđa, tơ lah păng lĕ bu nhŭp ngluh tă bơh bri neh jêng bu nă,$b$,false),
('bunong-vn','EZK',25,4,null,$b$yor nau nây, aơ, gâp mra jao may jêng ndơ ndơn ma phung tă bơh bri Lơ pit in jêh ri khân păng mra ƀư pôih ta han ta nklang may jêh ri ƀư ntŭk khân păng gŭ ta nklang may; khân păng mra sa play may, jêh ri mra nhêt dak toh ndrôk may.$b$,false),
('bunong-vn','EZK',25,5,null,$b$Gâp mra ăn ƀon Raba jêng ndrung seh samô jêh ri lĕ rngôch ƀon phung Amôn jêng ntŭk ăn ma păng biăp kuen, ri mơ khân may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',25,6,null,$b$Yor lah Yêhôva lah pô aơ: Yor lah may hŏ tap ti, ntrâm jêng, nuih n'hâm bêng ma nau gơm mưch jêh ri răm maak ma bri neh Israel,$b$,false),
('bunong-vn','EZK',25,7,null,$b$yor nau nây, aơ, gâp hŏ yơr jêh ti gâp tâm rdâng đah may jêh ri mra jao may jêng ndơ ma ntil mpôl phung bunuyh pit in. Gâp mra ƀư rai may, gâp mra ngluh lơi may tă bơh phung ƀon lan, jêh ri ăn may rai yot tă bơh neh ntu. Gâp mra ƀư rai ngroh lơi may. Rnôk nây may mra gĭt gâp jêng Yêhôva.”$b$,false),
('bunong-vn','EZK',25,8,null,$b$Yêhôva Brah Ndu lah pô aơ: “Yor lah phung Môap jêh ri phung yôk Sêir lah, Aơ, ngih Yuđa jêng nâm bu lĕ rngôch bri dak êng,$b$,true),
('bunong-vn','EZK',25,9,null,$b$yor nây gâp mra pơk dĭ neh phung Môap ntơm bơh ƀon n'har neh păng, nâm bu ntĭt lĕ rngôch ƀon tâm neh khân păng ƀư nau chrêk rmah ma n'gor bri nây, jêng ƀon Bet-Jêsimôt, ƀon Baal-Mêôn, jêh ri ƀon Kiriathaim.$b$,false),
('bunong-vn','EZK',25,10,null,$b$Gâp mra jao n'gor aơ, jêh ri n'gor phung Amôn ăn ma phung ƀon lan bri Lơ. Gâp mra ăn n'gor bri aơ ma khân păng ndơn chăm, gay ma phung kon sau Amôn mâu hôm dơi kah gĭt ôh ta nklang phung mpôl băl bunuyh,$b$,false),
('bunong-vn','EZK',25,11,null,$b$jêh ri gâp mra phat dôih bri Môap. Rnôk nây khân păng mra gĭt gâp jêng Yêhôva.”$b$,false),
('bunong-vn','EZK',25,12,null,$b$Yêhôva Brah Ndu lah pô aơ: “Yor lah bri Êđôm hŏ ƀư jêh nau ha plơng đah ngih Yuđa jêh ri ƀư tih glăm lơn nau tâm plơng đah khân ô băl.$b$,true),
('bunong-vn','EZK',25,13,null,$b$Yor nây pô aơ nau Yêhôva Brah Ndu lah Gâp mra yơr ti gâp tâm rdâng đah bri Êđôm, jêh ri mra nglôch lơi bunuyh jêh ri mpô mpa gŭ tâm nây; gâp mra ƀư ma ƀon nây jêng rngol; ntơm bơh ƀon Têman tât ma ƀon Dêdan, khân păng mra chôt khĭt ma đao dao.$b$,false),
('bunong-vn','EZK',25,14,null,$b$Gâp mra har plơng ma phung Êđôm ma ti phung ƀon lan gâp Israel, jêh ri khân păng mra ƀư ma bri Êđôm tĭng nâm nau gâp nuih jêh ri ji nuih; jêh ri phung Êđôm mra gĭt nau gâp har plơng, Yêhôva Brah Ndu lah.”$b$,false),
('bunong-vn','EZK',25,15,null,$b$Yêhôva Brah Ndu lah pô aơ: “Yor lah phung Philistin tâm plơng, ƀư nau tâm plơng tĭng nâm nuih n'hâm ƀai hâu ngăn rlăng mâu dơi dŭt joi nau ƀư roh rai n'gor bri Yuđa,$b$,true),
('bunong-vn','EZK',25,16,null,$b$yor nau nây, Yêhôva lah pô aơ: Aơ, gâp yơr ti gâp ƀư ma phung Philistin, jêh ri gâp mra ƀư rai phung Kêrêthit; jêh ri gâp mra ƀư ăn khĭt lĕ rngôch phung hôm e klen n'gŏ kơh dak mƀŭt.$b$,false),
('bunong-vn','EZK',25,17,null,$b$Gâp mra ƀư nau plơng bôk toyh tâm rdâng đah khân păng ma nau phat dôih tâm nau ji nuih khân păng mra gĭt gâp jêng Yêhôva, tơ lah gâp har plơng ma khân păng.”$b$,false),
('bunong-vn','EZK',26,1,null,$b$Tâm năm rơh jât ma nguay, năng nguay bôk khay, geh nau Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',26,2,null,$b$“Hơi kon bu nuyh, yor lah ƀon Tyr ngơi geh ma ƀon Yêrusalem, “Hah hai, mpông mpêr ma phung ƀon lan, lĕ chah jêh! Mpông pêr nây pơk jêh ma gâp; di ngăn păng lĕ jêng rngol jêh, pô ri gâp mra ăn păng chăt hao đŏng.$b$,false),
('bunong-vn','EZK',26,3,null,$b$Yor nây, Yêhôva Brah Ndu lah: Aơ, gâp mra tâm rdâng đah may, Hơi ƀon Tir, jêh ri gâp mra leo âk bri dak dâk tâm lơh đah may, nâm bu phŭt chuănh njach dak mƀŭt rbuh.$b$,false),
('bunong-vn','EZK',26,4,null,$b$Khân păng mra ƀư rai lĕ rngôch mpêr ƀon Tir, jêh ri ƀư klưh rlâm lĕ ngih tŭm păng; jêh ri gâp mra koch lơi neh, ăn păng jêng klêr ntang kŏ chrêk.$b$,false),
('bunong-vn','EZK',26,5,null,$b$Ƀon nây mra gŭ ta nklang dak mƀŭt jêng ntŭk bu ih nhuăl; yor lah Yêhôva lĕ lah pô aơ: Gâp hŏ lah jêh. Ƀon Tir mra jêng ndơ ma phung bri dak bu pit in.$b$,false),
('bunong-vn','EZK',26,6,null,$b$Phung kon bu ur păng luh tâm mir ba bu mra nkhĭt ma đao dao. Rnôk nây khân păng mra gĭt gâp jêng Yêhôva.”$b$,false),
('bunong-vn','EZK',26,7,null,$b$“Yor lah Yêhôva Brah Ndu lah: Aơ gâp mra njŭn leo Nêbukatnetsar, hađăch Babilôn, jêng hađăch ma phung hađăch, nđâp ma phung seh, ndeh seh, phung ta han ncho seh, ndrel ma phung ta han âk, jêh ri phung ƀon lan âk-râk, tă bơh bri dor lơ văch tât lơh ƀon Tir.$b$,true),
('bunong-vn','EZK',26,8,null,$b$Păng mra ndjôt đao nkhĭt kon bu ur may tâm mir, păng mra njêng ƀư mpêr nchueng lơh may, jêh ri n'hao neh bât nchueng may, jêh ri yơr khêl tâm lơh đah may.$b$,false),
('bunong-vn','EZK',26,9,null,$b$Păng mra dŏng loih ƀư klưh rlâm lơi mpêr may, jêh ri păng mra kăl lơi ngih tŭm ma sung.$b$,false),
('bunong-vn','EZK',26,10,null,$b$Seh păng âk râk ngăn kŏ tât ndruyh neh jâng khân păng hăn brôi may; mpêr may mra n'gơ yor nteh n'găr phung ncho seh, ndeh nđuih, jêh ri ndeh seh, tơ lah păng lăp ta mpông pêr may tâm ban bu lăp du rplay ƀon geh du ntŭk lĕ bluh jêh.$b$,false),
('bunong-vn','EZK',26,11,null,$b$Ma nchop seh păng, păng mra jot rchal lĕ rngôch trong sâng may; păng mra nkhĭt phung ƀon lan may mra cha lôt ta neh.$b$,false),
('bunong-vn','EZK',26,12,null,$b$Khân păng pit in drăp ndơ jêh ri ăp ntil ndô ndơ may geh; păng mra ƀư klưh rlâm lơi mpêr may jêh ri ngih may; khân păng mra mƀăr lŭ, tơm si, jêh ri neh may tâm nklang dak.$b$,false),
('bunong-vn','EZK',26,13,null,$b$Gâp mra ăn rlu lơi bâr may mpât mprơ, jêh ri bu mâu mra tăng đŏng ôh bâr gong rêng may kreh.$b$,false),
('bunong-vn','EZK',26,14,null,$b$Gâp mra njêng jêng lŭ chrêk; may mra jêng du ntŭk bu ih nhuăl; jêh ri bu mâu hôm rdâk njêng đŏng ôh; yor lah gâp jêng Yêhôva hŏ lah jêh nau nây, Yêhôva lah.”$b$,false),
('bunong-vn','EZK',26,15,null,$b$“Pô aơ nau Yêhôva lah ma ƀon Tir: Tăng n'găr may nteh tŭp, bunuyh rmanh rđơh rđêng, dôl nau bu tâm nkhĭt ta nklang may, lĕ kô mƀŭt tăng n'găr mprâm lĕ mâu?$b$,true),
('bunong-vn','EZK',26,16,null,$b$Lĕ rngôch phung kôranh tâm dak mƀŭt mra trŭnh tă bơh sưng hađăch khân păng; jêh ri doh lơi ao jâr khân păng, droh lơi ao cheh-chiăk khân păng; khân păng mra nsoh ao nau râm nsâr; khân păng mra gŭ rvel ta neh jêh ri râm nsâr ƀa ƀơ, jêh ri klach ngăn yor nau tât ma may.”$b$,true),
('bunong-vn','EZK',26,17,null,$b$Khân păng mra nhĭm vơl ma may jêh ri lah ma may: “Hơi ƀon toyh geh nau lư n'găr, nâp ngăn gŭ ta nklang kô mƀŭt, jêng ntŭk may hăn gŭ; păng jêh ri phung gŭ tâm păng geh nau tât ma lĕ rngôch phung gŭ ta nây klach krit ngăn, may lĕ rai roh ngăn jêh!$b$,true),
('bunong-vn','EZK',26,18,null,$b$Aƀaơ ri phung kô dak mƀŭt râm nsâr ngăn, ta nar may lĕ cha lôt; n'hêl nanê̆ phung kôdak mƀŭt mra uh ah ma nau may rai lôch nây.$b$,false),
('bunong-vn','EZK',26,19,null,$b$Ngăn yơh, nau Yêhôva lah pô aơ; Tơ lah gâp ăn may jêng du rplay ƀon lĕ rai jêh, nâm bu ƀon bu mâu hôm geh bunuyh gŭ ôh; tơ lah gâp leo ntu brŏng jru tât ma may dak toyh nkŭm may,$b$,true),
('bunong-vn','EZK',26,20,null,$b$nôk nây gâp mra chông nklơ̆ may ndrel ma lĕ rngôch phung hŏ jŭr hăn ma Ntu Jru tât ma phung ƀon lan rnôk kăl e, Jêh ri gâp mra ăn may gŭ tâm neh ntu tâm dâng, ta nklang ndơ lĕ rai jêh rnôk kăl e, ndrel ma phung hŏ jŭr hăn ma Ntu Jru, pô ri mâu hôm geh nuyh gŭ tâm may ôh, ƀiă lah gâp mra n'gân mro mrăng tâm neh bunuyh hôm gŭ rêh.$b$,false),
('bunong-vn','EZK',26,21,null,$b$Gâp mra njŭn leo may ma nau rêh ni, jêh ri may mâu mra jêng đŏng ôh; jêh ri nđâp tơ lah bu tĭng joi may, bu mâu mra saơ may ôh, Yêhôva Brah Ndu lah.”$b$,false),
('bunong-vn','EZK',27,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',27,2,null,$b$“Hơi ƀon bu nuyh, njêng hom du nau nhĭm vơl ma ƀon Tir,$b$,false),
('bunong-vn','EZK',27,3,null,$b$jêh ri lah hom ma ƀon Tir: Hơi ƀon Tir gŭ ta mbŏng dak mƀŭt, nơm tăch rgâl đah âk phung ƀon lan ta âk ntŭk kô mƀŭt, Yêhôva lah pô aơ: Hơi ƀon Tir, may lah jêh, Nau ueh gâp jêng rah vah ngăn.$b$,false),
('bunong-vn','EZK',27,4,null,$b$N'har may gŭ ta nklang klŏ mƀŭt; phung rdâk-njêng may hŏ ƀư ăn may lĕ jêng ueh rah vah ngăn.$b$,true),
('bunong-vn','EZK',27,5,null,$b$Khân păng nkra lĕ rngôch rda may ma kađar n'ho tă bơh n'gor Sênir; khân păng sŏk du tơm si sêdar tă bơh n'gor Liban. Ŭch njêng du mlâm meh gâng kât bok drơ sial ma may;$b$,true),
('bunong-vn','EZK',27,6,null,$b$rnai vah ƀư ma tơm si tă bơh bri Basan; khân păng ƀư gre ma tơm n'ho tă bơh kô dak mƀŭt Kitim ƀư kađar ntă, jêh ri ndop mblum ma la rveh.$b$,false),
('bunong-vn','EZK',27,7,null,$b$Bok mhay bu cheh chiăk bơh bri Êjipt dŏng ƀư bok drơ sial, gay ƀư njêng bok pla (n'ha kơ) ăn may; bok ĭr jêh ri chăng krăk tă bơh kô dak bri Êlisa gay gui nde n'hâm ăn may.$b$,true),
('bunong-vn','EZK',27,8,null,$b$Phung gŭ tâm ƀon Sidôn jêh ri ƀon Arvat jêng phung sâm vah plŭng ăn may; Hơi ƀon Tir, lĕ phung njêh, blau mĭn Gŭ tâm may, khân păng jêng phung ƀĭt gai may$b$,true),
('bunong-vn','EZK',27,9,null,$b$Phung bu ranh ƀon Gêbal jêh ri phung bunuyh njêh blau ƀon nây gŭ ta nklang may, pô ri may dŏng gay ma nsĭr ntŭk chah bluh tâm Kŭmpăn may. Lĕ rngôch phung Kŭmpăn tâm dak mƀŭt ndrel ma bunuyh ƀĭt khân păng gŭ tâm may da dê, văch njưh ta meng may gay tăch rgâl drăp ndơ may.$b$,false),
('bunong-vn','EZK',27,10,null,$b$Phung Persơ, phung Lut, jêh ri phung Put jêng phung ta han may prăp ma nau tâm lơh; khân păng yông khêl jêh ri môk loih tâm may, khân păng ăn nau chrêk rmah ma may.$b$,true),
('bunong-vn','EZK',27,11,null,$b$Phung bu klâu ƀon Arvat jêh ri ƀon Hêlek gŭ ta klơ mpêr văr jŭm may, jêh ri phung bu klâu ƀon Gamat gŭ tâm ngih tŭm may; khân păng yông khêl ta klơ mpêr văr jŭm may, khân păng ăn nau ueh may jêng rah vah.$b$,true),
('bunong-vn','EZK',27,12,null,$b$“Phung Tarsis tăch rgâl đah may yor may geh âk drăp ndơ ăp ntil: Prăk, loih, thaih, ndrak tâm rgâl ma drăp ndơ may tăch.$b$,true),
('bunong-vn','EZK',27,13,null,$b$Phung Javan, Tubal jêh ri Mêsek tăch rgâl đah may; khân păng tăch bunuyh jêh ri khăl ngan kông tâm rgâl đah ndô ndơ may tăch.$b$,false),
('bunong-vn','EZK',27,14,null,$b$Phung Bet-Tôgarma tăch seh, seh tâm lơh, jêh ri seh bri tâm rgâl đah ndô ndơ may tăch.$b$,false),
('bunong-vn','EZK',27,15,null,$b$Phung ƀon lan Sêdan tăch drăp ma may, geh âk bri dak kô mƀŭt jêng ngih tăch drăp prăp ma may, khân păng mplơ̆ sĭt ma may la rveh, jêh ri tơm si khlay.$b$,false),
('bunong-vn','EZK',27,16,null,$b$Yor lah mpang ti may njêng geh âk ndô ndơ, yor ri phung Syri (phung Aram) tăch drăp đah may; khân păng tăch lŭ êrêmôt, bok chăng mpor trŭm, bok bu cheh rvanh, mhay rhên, lŭ ta dak mƀŭt, jêh ri lŭ khlay tâm rgâl đah drăp ndơ may tăch.$b$,false),
('bunong-vn','EZK',27,17,null,$b$N'gor Yuđa jêh ri n'gor Israel ăt tăch rgâl đah may tâm ban lĕ, khân păng tăch ba răch (ƀlê), play ôlivơ, play rvi dŭm bôk rah, dak sŭt, dak play ôlivơ, jêh ri dak ƀâu kah tâm rgâl đah ndơ păng tăch.$b$,false),
('bunong-vn','EZK',27,18,null,$b$Yor lah mpang ti njêng âk ntil ndơ, drăp ndơr rmeh rmai, yor ri yơh phung Damas djôt dak play kriăk ƀâu (play yôr yar) bơh Helbôn jêh ri rsau biăp nglang păng tâm rgâl đah may.$b$,false),
('bunong-vn','EZK',27,19,null,$b$Phung Dêdan jêh ri Javan leo knŏng ndơ tâm rgâl đah ndơ may tăch; tâm ndơ nây geh loih, tơm si kasia, tơm si kalamus.$b$,false),
('bunong-vn','EZK',27,20,null,$b$Lĕ phung gŭ ta Dêdan tăch ma may bok ưn seh.$b$,true),
('bunong-vn','EZK',27,21,null,$b$Phung Arabi jêh ri phung kôranh n'gor bri Kêdar tăch ma may phung biăp kon, biăp nkuăng, be nkuăng.$b$,false),
('bunong-vn','EZK',27,22,null,$b$Phung tăch drăp tă bơh bri Sêba jêh ri bri Rama tăch ngâl đah may; sŏk lĕ ntil ndơ ƀâu kah ueh lơn, jêh ri lĕ ntil lŭ khlay, jêh ri mah.$b$,true),
('bunong-vn','EZK',27,23,null,$b$Phung Haran, Kanê, Êđen, Ashur, jêh ri Kilmat tăch rgâl đah may.$b$,false),
('bunong-vn','EZK',27,24,null,$b$Phung nây tăch drăp ma may bok ao ueh ngăn, bok ao ĭr, jêh ri bok ao bu cheh, ao rvanh ăp ntil dak, geh mpor nâp ngăn mâu dơi đŏk drok ôh.$b$,false),
('bunong-vn','EZK',27,25,null,$b$Kŭmpăn tă bơh n'gor bri Tarsis rdeng leo drăp may tăch, jêh ri may geh âk rmeh jêh ma ndô ndơ rdeng tâm nklang klŏ dak mƀŭt.$b$,true),
('bunong-vn','EZK',27,26,null,$b$Ƀiă lah phung vah Kŭmpăn may leo may tât ta nklang dak klŏng toyh, jêh ri sial tă pa lơ njach may ngâm tâm nklang klŏng dak mƀŭt.$b$,true),
('bunong-vn','EZK',27,27,null,$b$Tât may rai yot, drăp ndơ, ndơ may tăch, nau may tâm tăch ngâl, bunuyh ƀĭt Kŭmpăn may, phung sâm nsĭr bluh đang ma may, phung sâm tăch ndơ may, jêh ri lĕ rngôch phung gŭ ndrel tâm may, mra cha lôt da dê ngâm rmok tâm klŏng dak mƀŭt.$b$,false),
('bunong-vn','EZK',27,28,null,$b$Tơ lah tăng bâr phung gai may nter, phung gŭ tâm bri chiau meng may râm nsâr da dê;$b$,true),
('bunong-vn','EZK',27,29,null,$b$jêh ri lĕ rngôch phung vah kŭmpăn may du luh tă bơh kŭmpăn khân păng. Phung pah kan kŭmpăn jêh ri lĕ rngôch phung ƀĭt kŭmpăn dâk ta kơh dak mƀŭt.$b$,false),
('bunong-vn','EZK',27,30,null,$b$Jêh ri nhĭm vơl hâu ngăn yor may, nhĭm ma nau rngot klâng. Khân păng sui neh muy ta klơ bôk khân păng, jêh ri rlă tâm ŭnh buh.$b$,true),
('bunong-vn','EZK',27,31,null,$b$Khân păng poih bôk plưn yor may, jêh ri nsoh ao ƀau, jêh ri khân păng nhĭm yor may ma nau rngot klâng, rvê hâu ngăn.$b$,true),
('bunong-vn','EZK',27,32,null,$b$Tâm nuih n'hâm khân păng krit rngot, nhĭm vơl yor may, jêh ri bêng nau klân rvê yor nau tât ma may: Mbu moh ƀon Tir, jêng ƀon aƀaơ hŏ rngot njăp ta nklang dak mƀŭt?$b$,true),
('bunong-vn','EZK',27,33,null,$b$Kăl e drăp ndơ may tăch tă bơh dak mƀŭt, may ăn lĕ mpay jêh ma phung âk bunuyh ƀon lan; ma drăp ndơ may âk rmeh rmai jêh ri ndơ may tăch ngâl, may ƀư ndrŏng phung hađăch ta neh ntu.$b$,true),
('bunong-vn','EZK',27,34,null,$b$Aƀaơ ri, may lĕ rai jêh yor dak mƀŭt, tâm ntŭk dak klŏng jru; drăp may tăch jêh ri lĕ rngôch phung pah kan tâm kŭmpăn may lĕ ngâm rmok ndrel ma may.$b$,true),
('bunong-vn','EZK',27,35,null,$b$Lĕ rngôch phung gŭ tâm kô dak mƀŭt hih rhâl yor nau tât ma may; phung hađăch khân păng klach ngăn, muh măt khân păng klêu rĭn nhĭn.$b$,true),
('bunong-vn','EZK',27,36,null,$b$Phung ƀon lan tăch ndrăp nsŭch yor nau tât ma may; may rai lôch jêh nau rêh ni hâu ngăn jêh ri mâu mra jêng đŏng n'ho ro.”$b$,true),
('bunong-vn','EZK',28,1,null,$b$Geh nau Yêhôva ngơi đŏng ma gâp:$b$,true),
('bunong-vn','EZK',28,2,null,$b$“Hơi kon bunuyh, lah hom ma kôranh ƀon Tir, Yêhôva Brah Ndu lah pô aơ, Yor lah nuih n'hâm may sưr ngăn, may lah, Gâp jêng du huê brah, gâp gŭ ta sưng hađăch Brah Ndu ta nklang dak mƀŭt, nđâp tơ lah nuih n'hâm may n'hao êng nơm tâm ban nuih n'hâm Brah Ndu, ƀiă lah may ăt jêng du huê bu nuyh, mâu di jêng Brah Ndu ôh.$b$,false),
('bunong-vn','EZK',28,3,null,$b$Aơ, may blau mĭn rlau lơn Y-Đaniel lĕ? Mâu geh ôh hĕ du ntil ndơ khlay ndâp dơi mpôn ma may?$b$,false),
('bunong-vn','EZK',28,4,null,$b$May hŏ dơi ndrŏng yor ma nau blau mĭn jêh ri gĭt rbăng may nơm; jêh ri prăp bun jêh mah jêh ri prăk tâm jrô prăp drăp may.$b$,true),
('bunong-vn','EZK',28,5,null,$b$Ma nau gĭt mĭn may tăch drăp, may hŏ n'hao jêh nau ndrŏng may, jêh ri nuih n'hâm may jêng sưr yor nau ndrŏng may.$b$,true),
('bunong-vn','EZK',28,6,null,$b$Yor nây Yêhôva Brah Ndu lah pô aơ: Yor lah may kơp may nơm jêng blau mĭn tâm ban nuih n'hâm Brah Ndu,$b$,false),
('bunong-vn','EZK',28,7,null,$b$Yor ri, aơ, gâp mra leo phung bu năch lơh may, phung mpôl băl bunuyh djơh lơn ma lĕ rngôch, dâk tâm lơh đah may; khân păng mra tŏk đao khân păng lơh lơi nau blau mĭn jêh ri nau ueh may, jêh ri ƀư ƀơ̆ lơi nau chrêk lơp may.$b$,false),
('bunong-vn','EZK',28,8,null,$b$Khân păng mra nklơ̆ may tŭp tâm Ntu Brŏng jru, jêh ri may mra khĭt tâm nklang klŏng dak mƀŭt, jêh ri may mra khĭt nâm bu bunuyh bu nkhĭt.$b$,true),
('bunong-vn','EZK',28,9,null,$b$Rnôk nây tra năp măt bunuyh nkhĭt may, may dơi janh lah lĕ pô aơ: Gâp jêng Brah Ndu? Dôl nôk nây may gŭ tâm ti phung nkhĭt may, may jêng knŏng du huê bunuyh, mâu di jêng Brah Ndu ôh.$b$,false),
('bunong-vn','EZK',28,10,null,$b$May mra khĭt yor ma ti phung bu năch nâm bu phung mâu ŭch bu koh ntâu ôh. Yêhôva Brah Ndu lah: Gâp nơm yơh ngơi lah nau nây.”$b$,false),
('bunong-vn','EZK',28,11,null,$b$Yêhôva ngơi đŏng ma gâp:$b$,true),
('bunong-vn','EZK',28,12,null,$b$Hơi kon bu nuyh, nhĭm vơl hom ma hađăch ƀon Tir jêh ri lah ma păng pô aơ: Yêhôva Brah Ndu lah: May rĭng nŭm lĕ rngôch, bêng ma nau blau mĭn, ueh uĭn rah vah jêh,$b$,false),
('bunong-vn','EZK',28,13,null,$b$May lĕ gŭ jêh tâm n'gar Êđen, n'gar trao Brah Ndu. May hŏ geh bêng săk ăp ntil lŭ khlay jêng ndơ n'hơm ăn may jêng lŭ karnêlian, lŭ tôpas, jêh ri lŭ jas pidi lŭ krisôlit, lŭ beril jêh ri lŭ êmêrôt. Bu lĭr ndop lŭ may jêh ri ndơ nkra nđâp ma mah. Bu nkra ndơ nây ta nar bu rhăk njêng may lĕ rơm ndrăp ơm jêh.$b$,false),
('bunong-vn','EZK',28,14,null,$b$May jêng du huê Chêrubim gak, dơi tŏ dak ngi geh bu nkŭm nking; gâp ndâk may ta klơ yôk kloh ueh Brah Ndu; may hŏ hăn pâl ta nklang nglar chrêk duh nâm bu ŭnh.$b$,true),
('bunong-vn','EZK',28,15,null,$b$Tâm trong may hăn hŏ saơ rah vah jêh, ntơm bơh nar bu rhăk njêng may, tât bu saơ nau kue tâm may.$b$,true),
('bunong-vn','EZK',28,16,null,$b$Tâm nau may tăch rgâl drăp ndơ geh âk rmeh rmai, may bêng ma nau ƀai, jêh ri may ƀư tih. Yor nay gâp mprơh nklơ̆ may nâm bu ndơ ƀơ̆ ƀơch tă bơh yôk kloh Brah Ndu, Hơi Chêrubim bu king nkŭm ri, gâp ƀư rai may ta nklang phung lŭ nglar chrêk duh nâm bu ŭnh!$b$,false),
('bunong-vn','EZK',28,17,null,$b$Nuih n'hâm may sưr rlau, yor nau ueh may; jêh ri yor nau chrêk rmah may geh ƀư ăn may ƀư tih jêh đah nau blau mĭn may. Pô ri gâp nklơ̆ may tâm neh, dơm may pa năp phung hađăch, ăn khân păng treng uănh may.$b$,false),
('bunong-vn','EZK',28,18,null,$b$May hŏ ƀư ƀơ̆ ƀơch ntŭk jrô kloh ueh may yor tă nau kue may âk ngăn, jêh ri nau may tăch rgâl drăp ndơ mâu geh sŏng ôh; pô ri gâp hŏ ăn luh ŭnh tă bơh ta nklang may; păng hŏ su jêh may, jêh ri gâp hŏ ƀư ăn may jêng ŭnh buh ma neh, pa năp măt lĕ rngôch bunuyh saơ may.$b$,false),
('bunong-vn','EZK',28,19,null,$b$Lĕ rngôch phung mpôl băl bunuyh gĭt năl may mra geh nau hih rhâl ma may: Ta aơ may lĕ tât jêh nau lôch dŭt ma may krit hâu ngăn, ƀa ƀơ n'ho ro may mâu mra hôm đŏng ôh.$b$,false),
('bunong-vn','EZK',28,20,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',28,21,null,$b$Hơi ƀon bu nuyh, rle muh măt may uănh ma ƀon Sidôn, jêh ri mbơh lor jêh ri tâm rdâng đah păng.$b$,false),
('bunong-vn','EZK',28,22,null,$b$Jêh ri lah; Pô aơ nau Yêhôva Brah Ndu lah: Aơ, gâp tâm rdâng đah may, hơi ƀon Sidôn, jêh ri gâp mra mpơl nau ƀư kloh amoh gâp ta nklang may. Khân păng mra gĭt gâp jêng Yêhôva, tơ lah gâp ma ƀư nau phat dôih ma păng, jêh ri mpơl nau kloh ueh gâp tâm păng.$b$,true),
('bunong-vn','EZK',28,23,null,$b$Gâp mra njuăl nau ji tât nkhĭl păng, jêh ri geh nau pling mham n'gŏ trong sâng păng; phung bu nkhĭt mra cha lôt ta nklang păng yor ma đao dao mra ƀư ma păng văr jŭm ăp njônh; jêh ri khân păng mra gĭt gâp yơh jêng Yêhôva.$b$,false),
('bunong-vn','EZK',28,24,null,$b$Dôl nôk nây, mâu mra geh ôh tôt lok mâu lah lok krĕ (grĕ) ma ngih Israel, tâm nklang lĕ rngôch bunuyh gŭ chiau meng khân păng, phung nây ƀư đah khân păng ma nau tâm rmot. Rnôk nây khân păng mra gĭt gâp jêng Yêhôva Brah Ndu.$b$,false),
('bunong-vn','EZK',28,25,null,$b$Pô aơ nau Yêhôva Brah Ndu lah: Tơ lah gâp hŏ rgum jêh ngih Israel tay đŏng, tă bơh phung ƀon lan ntŭk gâp ăn gŭ ƀư chah rai jêh khân păng, jêh ri gâp tâm mpơl nau kloh ueh gâp tâm khân păng ta năp măt phung mpôl băt bunuyh, rnôk nây khân păng mra gŭ tâm bri khân păng nơm, bri gâp hŏ ăn jêh ma oh mon gâp jêng Y-Yakôb.$b$,false),
('bunong-vn','EZK',28,26,null,$b$Khân păng mra gŭ ta nây đăp-rmên, mra ndâk ngih vâl jêh ri tăm play kriăk ƀâu. Khân păng gŭ đăp rmên ta ntŭk nây, tơ lah gâp hŏ ƀư jêh nau phat dôih ma lĕ rngôch phung gŭ chiau meng khân păng, jêng phung mpôl băl bunuyh lĕ ƀư jêh ma khân păng ma nau tâm rmot; jêh ri khân păng mra gĭt gâp jêng Yêhôva Brah Ndu khân păng.$b$,false),
('bunong-vn','EZK',29,1,null,$b$Tâm năm rơh jât ma nguay, khay jât, ta năng jât ma bar khay nây Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',29,2,null,$b$Hơi kon bu nuyh, rle hom muh măt may uănh rlet Pharaôn hađăch Êjipt, jêh ri mbơh lor nau tâm rdâng đah păng, jêh ri lĕ rngôch phung Êjipt.$b$,false),
('bunong-vn','EZK',29,3,null,$b$Ngơi jêh ri lah hom: Pô aơ nau Yêhôva Brah Ndu lah: Aơ, gâp tâm rdâng đah may, Hơi Pharaôn, hađăch Êjipt, bêh nhŭk-nhăk toyh rvel ta nklang dak n'hor may. May lah, Dak krong gâp jêng ndơ gâp nơm, gâp lĕ njêng jêh dak krong nây.$b$,true),
('bunong-vn','EZK',29,4,null,$b$Gâp mra dơm nglĕ klĕ ta kang may, jêh ri ka tâm dak krong mra khan ta rsiap may, jêh ri gâp mra đŏt may luh du tă bơh tâm dak krong may krêp khan ta rsiap may đŏng.$b$,false),
('bunong-vn','EZK',29,5,null,$b$Jêh ri gâp mra mprơh may rlet tâm bri rdah, may jêh ri ka tă tâm dak krong may. May mra cha lôt tâm bri mbâng, jêh ri bu mâu mra rƀŭn jêh ri tâp brôi may ôh. Gâp mra jao may ƀư mpa sa ăn ma mpô mpa ta neh jêh ri phung sĭm klơ trôk.$b$,true),
('bunong-vn','EZK',29,6,null,$b$Rnôk nây lĕ rngôch phung gŭ tâm n'gor Êjipt mra gĭt gâp jêng Yêhôva. Yor lah khân păng hŏ jêng mâng jra đah rpho ăn ngih Israel.$b$,false),
('bunong-vn','EZK',29,7,null,$b$Tơ lah khân păng kuăn may ta ti, may pă (deh) êng, jêh ri ƀư hêk lĕ rngôch săng nglik khân păng; tơ lah khân păng nsing mbin ta may, may pă (deh) jêh, jêh ri ƀư ma gang bŭt khân păng nsut.$b$,false),
('bunong-vn','EZK',29,8,null,$b$Yor ri, Yêhôva lah pô aơ: Aơ, gâp mra leo đao dao tât klơ may, jêh ri lơh rai lơi tă bơh may bunuyh jêh ri mpô mpa.$b$,false),
('bunong-vn','EZK',29,9,null,$b$N'gor bri Êjipt mra jêng rngol jêh ri nsoih dơm. Rnôk nây khân păng mra gĭt gâp jêng Yêhôva. Yor lah Pharaôn geh lah jêh pô aơ: Dak krong jêng ndơ gâp, gâp hŏ njêng jêh păng,$b$,false),
('bunong-vn','EZK',29,10,null,$b$Yor nây, aơ, gâp tâm rdâng đah may jêh ri đah n'hor dak may, jêh ri gâp ăn n'gor bri Êjipt jêng ntŭk nsoih jêh ri rngol ntơm bơh ƀon Mikdôl tât ma ƀon Syren, kŏ tât ta n'har neh n'gor bri Êthiôpi.$b$,false),
('bunong-vn','EZK',29,11,null,$b$Mâu mra geh bunuyh prot rgăn ôh ta nây, mâu lĕ geh mpô mpa rgăn ta nây, bri jêng rngol tât tâm puăn jât năm.$b$,false),
('bunong-vn','EZK',29,12,null,$b$Gâp mra ăn n'gor bri Êjipt jêng rngol ta nklang âk rplay bri dak lĕ jêng rngol jêh; jêh ri lĕ rngôch ƀon păng mra jêng rngol tâm puăn jât năm đŏng ta nklang âk rplay ƀon êng lĕ jêng nsoih jêh. Gâp mra ăn pru pra phung Êjipt ta nklang phung mpôl băl bunuyh jêh ri mprơh lơi khân păng du gŭ ta nklang âk rplay bri dak êng.$b$,true),
('bunong-vn','EZK',29,13,null,$b$Yor lah Yêhôva Brah Ndu lah pô aơ; Lôch jêh puăn jât năm, gâp mra rgum tay phung Êjipt tă bơh ta nklang phung ƀon lan tâm phung gâp hŏ mprơh du khân păng lĕ tă chah rai.$b$,false),
('bunong-vn','EZK',29,14,null,$b$Gâp mra plơ̆ ăn đŏng nau ueh uĭn ma n'gor bri Êjipt, jêh ri njŭn sĭt khân păng plơ̆ sĭt tâm bri Patrôs, bri tơm khân păng nơm ntơm sa-ơm, ƀiă lah khân păng ndâk njêng du bri knŏng jê̆ lê̆ dơm.$b$,true),
('bunong-vn','EZK',29,15,null,$b$N'gor bri Êjipt mra jêng du rplay bri jê̆ lơn tâm lê̆ rngôch bri dak, jêh ri mâu mra dơi n'hao păng nơm ta klơ phung mpôl băl bunuyh êng đŏng ôh, jêh ri gâp mra ăn khân păng huơi kŏ tât khân păng mâu hôm dơi chiă uănh phung mpôl băl bunuyh ôh.$b$,false),
('bunong-vn','EZK',29,16,null,$b$Ngih Israel mâu hôm rnơm ma khân păng ôh, dôl khân păng gŭ nklân nau kue khân păng; tơ lah khân păng rnơm ma phung Êjipt kơl. Rnôk nây khân păng mra gĭt gâp jêng Yêhôva Brah Ndu.$b$,false),
('bunong-vn','EZK',29,17,null,$b$Rnôk năm rơh bar jât ma pơh, khay nguay, ta năng nguay khay nây, Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',29,18,null,$b$Hơi kon bunuyh, Nêbukatnetsar hađăch Babilôn ăn phung ta han păng pah kan hŏt ngăn hŭch tâm rdâng đah ƀon Tir; lĕ rngôch bôk hŏ jêng plưn (hil) da dê, jêh ri săng nglik lĕ rplưch, ƀiă lah hađăch nây mâu lĕ geh drăp ndơ tă bơh ƀon Tir, gay nkhôm phung ta han păng, mâu lah ma păng nơm, gay ntrok lơi nau kan hŏt ra ah hŏ lơh jêh ƀon nây.$b$,false),
('bunong-vn','EZK',29,19,null,$b$Yor nây nau Yêhôva lah pô aơ: Aơ, gâp mra jao n'gor bri Êjipt ma Nêbukatnetsar, hađăch Babilôn, jêh ri păng mra rdeng nchuăn drăp ndơ hŏ pit in lĕ rngôch ndô ndơ tâm păng, ndơ nây mra jêng ndơ nkhôm ma phung ta han păng.$b$,false),
('bunong-vn','EZK',29,20,null,$b$Gâp hŏ ăn jêh ma păng n'gor bri Êjipt, gay nkhôm nau hŏt ra-ah păng hŏ ƀư jêh, yor lah khân păng hŏ pah kan ăn ma gâp, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',29,21,null,$b$Tâm nar nây, gâp mra ăn ngih Israel, jêh ri gâp mra ăn may hă bâr ngơi ta nklang khân păng. Rnôk nây khân păng mra gĭt gâp jêng Yêhôva.$b$,true),
('bunong-vn','EZK',30,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',30,2,null,$b$Hơi kon bunuyh, mbơh lor jêh ri lah hom: Pô aơ nau Yêhôva Brah Ndu lah: Nhĭm vơl hom, Rêh ni ngăn tâm nar aơ!$b$,false),
('bunong-vn','EZK',30,3,null,$b$Yor lah nar nây dăch jêh, nar Yêhôva hŏ dăch tât jêh; ngăn yơh, jêng nar Yêhôva; nar geh tŭk nkâm, rnôk nau phat dôih ma lĕ rngôch phung mpôl băl bunuyh.$b$,true),
('bunong-vn','EZK',30,4,null,$b$Du n'gâr đao dao mra lơh tâm N'gor bri Êjipt; jêh ri nau rngot klâng mra tât mra bri Êthiôpi, tơ lah phung bu nkhĭt, chôt khĭt tâm n'gor bri Êjipt, jêh ri bu rdeng nchuăn ƀon lan păng, jêh ri ƀư rlâm lơi mbon păng,$b$,false),
('bunong-vn','EZK',30,5,null,$b$Phung Êthiôpi, phung Put, phung Lut, lĕ rngôch phung Arabi, jêh ri phung Libi, jêh ri phung ƀon lan tâm bri dak tâm rnglăp đah khân păng chôt khĭt ma đao ndrel ma khân păng.$b$,false),
('bunong-vn','EZK',30,6,null,$b$Pô aơ Yêhôva lah: Phung kơl rđâng n'gor bri Êjipt mra cha lôt; jêh ri nau ktang bơh nau sưr khân păng mra roh. Ntơm bơh Midôl tât ma Siyen; khân păng mra chôt khĭt ma đao dao, Yêhôva Brah Ndu lah.$b$,true),
('bunong-vn','EZK',30,7,null,$b$Khân păng mra jêng rngol ta nklang tâm bri êng lĕ jêng rngol, jêh ri ƀon khân păng mra gŭ ta nklang âk ƀon êng lĕ rai jêh.$b$,true),
('bunong-vn','EZK',30,8,null,$b$Ngăn yơh, rnôk nây khân păng mra gĭt gâp jêng Yêhôva, tơ lah gâp su jêh n'gor bri Êjipt ma ŭnh, jêh ri lĕ rngôch phung kơl păng rai jêh.$b$,false),
('bunong-vn','EZK',30,9,null,$b$Tâm nar nây, mra geh phung mbơh luh tă bơh gâp ncho Kŭmpăn gay nkrit phung Êthiôpi gŭ mpăn ăn păng klach. Phung ƀon lan păng mra rngot klâng mra tât ma khân păng ta nar n'gor bri Êjipt lĕ rai; yor lah aơ, nau nây mra tât ngăn jêh!$b$,false),
('bunong-vn','EZK',30,10,null,$b$Pô aơ nau Yêhôva Brah Ndu lah: Gâp mra ƀư ngroh lơi phung bunuyh âk n'gor bri Êjipt, ma ti Nêbukatnetsar hađăch Babilôn.$b$,true),
('bunong-vn','EZK',30,11,null,$b$Hađăch nây ndrel ma phung ƀon lan păng, jêng phung djơh mhĭk ngăn tâm lĕ phung mpôl băl bunuyh, bu mra leo khân păng lăp gay lơh rai bri dak; khân păng sŏk đao tâm lơh đah n'gor bri Êjipt, jêh ri ƀư ma bri dak aơ bêng ma nting bunuyh bu nkhĭt$b$,true),
('bunong-vn','EZK',30,12,null,$b$Gâp mra ƀư suăt lơi dak krong, jêh ri tăch lơi bri dak nây tâm ti phung djơh; gâp mra ăn ti phung bu năch ƀư ma bri dak nây jêng rngol nđâp ma lĕ rngôch ntil ndơ tâm păng. Gâp nơm, jêng Yêhôva ngơi lah nau nây.$b$,false),
('bunong-vn','EZK',30,13,null,$b$Yêhôva lah pô aơ: Gâp mra nchah lơi rup brah ta ƀon Nôp. Tâm n'gor bri Êjipt mâu hôm geh hađăch ôh; jêh ri gâp mra nsrih nau klach tâm n'gor bri Êjipt.$b$,true),
('bunong-vn','EZK',30,14,null,$b$Gâp mra ƀư ma ƀon Phatrôs jêng rngol, jêh ri gâp mra su ƀon Sôan ma ŭnh, jêh ri ăn nau phat tât ma ƀon Nô,$b$,false),
('bunong-vn','EZK',30,15,null,$b$Gâp mra nkhŭt nau gâp ji nuih ma ƀon Sin, jêng ƀon nâp ngăn tâm n'gor bri Êjipt, jêh ri gâp mra ƀư rai phung ƀon lan ƀon Nô.$b$,false),
('bunong-vn','EZK',30,16,null,$b$Gâp mra su n'gor bri Êjipt ma ŭnh, ƀon Sin geh nau rêh ni toyh ngăn; bu mra lôk mpêr ƀon Nô, jêh ri ƀon Nôp mra uh ah ăp nar$b$,true),
('bunong-vn','EZK',30,17,null,$b$Phung bu klâu ndăm ƀon Ôn jêh ri ƀon Pibêset mra cha lôt khĭt ma mpiăt đao, jêh ri bunuyh ƀon lan lĕ ƀon nây mra hăn ƀư bu nă.$b$,false),
('bunong-vn','EZK',30,18,null,$b$Ta ƀon Tahpanhes, nar nây mra jêng ngo klĕng, tơ lah gâp mra ăn roh nau phung Êjipt chiă uănh ta nây, jêh ri nau dăng ktang sưr rlau păng mra lôch dŭt. Bi ma păng, mra geh tŭk nkâm bri dak nây, jêh ri phung kon bu ur păng mra hăn jêng bu nă.$b$,true),
('bunong-vn','EZK',30,19,null,$b$Pô ri yơh gâp mra phat dôih ma bri Êjipt, jêh ri khân păng mra gĭt gâp jêng Yêhôva.$b$,true),
('bunong-vn','EZK',30,20,null,$b$Tâm năm rơh jât ma nguay, khay nguay, ta năng pơh khay nây, Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',30,21,null,$b$Hơi kon bunuyh, gâp hŏ nkêch nting tur Pharaôn, hađăch Êjipt. Aơ, mâu geh ôh nơm put săm dak si gay dơi bah, mâu geh nơm put n'grêp ntŭk sôt gay tâm nsĭr tay jêh ri ăn nting tur păng dăng ktang gay ma păng plơ̆ kuăn tay đao.$b$,false),
('bunong-vn','EZK',30,22,null,$b$Yor ri, pô aơ nau Yêhôva lah: Aơ, gâp tâm rdâng đah Pharaôn, hađăch Êjipt, jêh ri nkêch lơi nting tur păng, nđâp ma nting tur hôm dăng jêh ri nting tur lĕ pă (deh), jêh ri ăn đao tŭp tă bơh ti păng.$b$,false),
('bunong-vn','EZK',30,23,null,$b$Gâp mra ƀư ăn phung Êjipt chah rai tâm nklang phung mpôl băl bunuyh, jêh ri mprơh khân păng gŭ lam bri êng.$b$,false),
('bunong-vn','EZK',30,24,null,$b$Gâp mra ăn nting tur hađăch Babilôn ntop nau dăng ktang, gay kuăn đao gâp tâm ti păng; ƀiă lah gâp nkêch lơi nting tur Pharaôn ăn pă (deh), jêh ri păng mra vơl ta năp hađăch Babilôn, tâm ban ma du huê nơm rmanh bơi ma khĭt,$b$,false),
('bunong-vn','EZK',30,25,null,$b$Gâp mra ăn nting tur hađăch Babilôn ntop nau dăng ktang, ƀiă lah nting tur hađăch Pharaôn jêng hươi, jêh ri khân păng mra gĭt gâp jêng Yêhôva, tơ lah gâp mra ăn đao gâp tâm ti hađăch Babilôn, jêh ri păng mra yơr đao nây tâm lơh đah n'gor bri Êjipt.$b$,false),
('bunong-vn','EZK',30,26,null,$b$Gâp mra ƀư ăn phung Êjipt chah rai pru tâm nklang phung mpôl băl bunuyh jêh ri mprơh khân păng du lam bri êng. Rnôk nây khân păng mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',31,1,null,$b$Tâm năm rơh jât ma nguay, năng nguay, khay pe, geh nau Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',31,2,null,$b$Hơi kon bunuyh, lah hom ma Pharaôn hađăch Êjipt jêh ri ma phung âk păng: Ma mbu đah may tâm rđĭl nau toyh may nơm?$b$,false),
('bunong-vn','EZK',31,3,null,$b$Uănh hom bri Asiri: Sa ơm păng tâm ban ma du tơm si Sêdar tâm bri Liban, geh n'gĭng ueh jêh ri n'hâm si krŏng, tơm prêh, jêh ri chiông si kŏ ban tŭk.$b$,true),
('bunong-vn','EZK',31,4,null,$b$Lĕ n'hor dak siăm păng, dak klŏng jru hoch jŭm ntŭk bu tăm păng ăn păng văch hao prêh, jêh ri dak nây luh n'hor dak hoch tât lĕ rngôch tơm si tâm bri.$b$,false),
('bunong-vn','EZK',31,5,null,$b$Pô ri tơm si nây ntoch jong, jong lơn lĕ rngôch tơm si tâm bri; n'gĭng păng toyh jêh ri jong, jêh ri păng chăt n'gĭng âk, yor geh dak âk ta reh păng.$b$,true),
('bunong-vn','EZK',31,6,null,$b$Lĕ rngôch sĭm och tâm bri ƀư rsuăn ta klơ n'gĭng păng; Tâm dâng n'gĭng păng lĕ ntil mpô mpa bri gŭ deh kon, jêh ri lĕ rngôch mpôl băl bunuyh toyh gŭ tâm dâng n'hâm păng da dê.$b$,true),
('bunong-vn','EZK',31,7,null,$b$Nau păng toyh ueh yor tă tơm păng prêh, yor n'gĭng păng jong, yor lah reh păng sŏr tâm ntŭk âk dak.$b$,true),
('bunong-vn','EZK',31,8,null,$b$Mâu dơi geh tơm si Sêdar ƀa ƀă tâm n'gar trao Brah Ndu dơi nkâm păng; tơm n'ho kŏ mâu tâm ban lĕ đah chiông păng; jêh ri tơm ntang jêng dơm dam tơ lah he tâm veh đah n'gĭng păng; mâu geh ôh tơm si tâm n'gar trao Brah Ndu jêng ueh nâm bu păng.$b$,true),
('bunong-vn','EZK',31,9,null,$b$Gâp ăn păng jêng ueh yor âk n'gĭng nthan păng, jêh ri lĕ rngôch tơm si tâm n'gar trao Brah Ndu Êđen ŭch jêng nâm bu păng.$b$,true),
('bunong-vn','EZK',31,10,null,$b$Yor nây, Yêhôva Brah Ndu lah: Yor nây, Yêhôva Brah Ndu lah: Yor lah păng ntoch jêh ri chiông păng kŏ ban tŭk, jêh ri nuih n'hâm păng sưr rlau yor nau păng prêh,$b$,true),
('bunong-vn','EZK',31,11,null,$b$gâp mra jao păng tâm ti du huê kôranh ktang tâm mpơl bunuyh. N'hêl nanê̆ păng mra ƀư ma tơm si nây tĭng nâm nau khư ma nau djơh păng. Gâp lĕ mprơh jêh păng$b$,false),
('bunong-vn','EZK',31,12,null,$b$Phung bu năch, phung djơh mhĭk lơn tâm phung mpôl bunuyh, kăl jêh ri cha lơi păng. Ta klơ yôk jêh ri tâm lĕ rngôch rlŭng n'gĭng păng lĕ klah ntŭk kơh dak, jêh ri lĕ rngôch ƀon lan ta neh ntu nchuăt du tă bơh n'hâm păng jêh ri cha lơi păng.$b$,false),
('bunong-vn','EZK',31,13,null,$b$Lĕ rngôch sĭm och tâm trôk drâm ta klơ n'gĭng păng lĕ hăch rai jêh, jêh ri lĕ rngôch mpô mpa bri mra văch nde ta nklang n'gĭng păng.$b$,false),
('bunong-vn','EZK',31,14,null,$b$Gay ma lĕ rngôch tơm si tăm n'gŏ dak n'hor mâu janh ôh sưr rlau ma nau prêh păng, mâu lah prêh chiông kŏ ban tŭk, jêh ri gay ma mâu geh ôh tơm si êng dăch dak sưr rlau prêh ir; yor lah bu jao jêh lĕ rngôch khân păng ma nau khĭt, prăp ma brŏng jru tâm dâng neh ntu, tâm nklang ntil mpôl bunuyh blau khĭt, ndrel ma phung jŭr tâm ntu jru!$b$,false),
('bunong-vn','EZK',31,15,null,$b$Pô aơ nau Yêhôva lah: Tơ lah păng jŭr tâm Ƀon Phung Khĭt gâp ăn dak jru nhĭm vơl ma păng, jêh ri nkrŭl lơi dak krong, jêh ri âk n'hong dak mâu hôm hoch ôh, brôi nđâp lơi ntu jru. Gâp ăn bri Liban rngot klâng yor păng, jêh ri lĕ rngôch tơm si tâm bri lĕ kro yor păng.$b$,true),
('bunong-vn','EZK',31,16,null,$b$Gâp ăn phung mpôl bunuyh râm nsâr klach tơ lah tăng nteh păng tŭp, tơ lah gâp klŭp mƀăr păng ma Ƀon Phung Khĭt ndrel ma phung jŭr tâm Ntu jru! Rnôk nây lĕ rngôch tơm si n'gar Êđen, jêh ri tâm lĕ rngôch tơm si ueh ngăn, ueh lơn ma lĕ rngôch tơm si ueh tâm bri Liban, lĕ rngôch tơm si ntơm sa ơm dơi geh âk dak djrah, jêh ri dơi geh nau bonh leng ta ntu jru tâm dâng neh.$b$,false),
('bunong-vn','EZK',31,17,null,$b$Khân păng tâm ban lĕ hŏ jŭr ndrel păng tâm ntŭk Ƀon Phung Khĭt, êp kêng phung bu hŏ nkhĭt jêh ma tak đao; n'hêl nanê̆ phung nây ntơm sa ơm gŭ jêh tâm dâng n'hâm gui păng ndrel ma phung mpôl bunuyh êng mra rai lôch.$b$,false),
('bunong-vn','EZK',31,18,null,$b$Ma mbu nơm đah may tâm rđĭl nau chrêk rmah jêh ri nau toyh păng ta nklang tơm si tâm n'gar Êđen? Bu mra njŭr may ndrel ma tơm si n'gar Êđen rlet ma ntu jru tâm dâng neh; may mra lâng bêch ndrel ma phung mâu koh ntâu, ndrel ma phung bu hŏ nkhĭt jêh ma tak đao. Tơm si jêng Pharaôn nđâp ma lĕ rngôch phung bunuyh âk ƀon lan păng mra tâm ban kơt nây Yêhôva Brah Ndu lah.$b$,true),
('bunong-vn','EZK',32,1,null,$b$Năm rơh jât ma bar, năng nguay khay jât ma bar, jât nau Yêhôva ngơi ma gâp, lah:$b$,true),
('bunong-vn','EZK',32,2,null,$b$Hơi kon bunuyh, nhĭm vơl hom ma Pharaôn hađăch Êjipt, jêh ri lah ma păng: May lah êng may nơm jêng du mlâm yau mŭr ta nklang lĕ ntil mpôl bunuyh, ƀiă lah may jêng nâm bu bêh nhŭk-nhăk tâm dak mƀŭt; hŏ rbŭl luh du tâm dak krong may, jêh ri may ncheh jâng ƀư ƀơ̆ lơi dak n'hor bêng dak bŏk.$b$,false),
('bunong-vn','EZK',32,3,null,$b$Pô aơ Yêhôva lah: Gâp mra seng jal gâp geh may, geh du phung ƀon lan âk khân păng mra kơl; đot mphâk may tâm jal gâp.$b$,true),
('bunong-vn','EZK',32,4,null,$b$Gâp mra mƀăr may ta neh, jêh ri klŭp may tâm nklang bri mbâng. Gâp mra ăn phung sĭm klơ trôk jŭr drâm ta may, jêh ri phung mpô mpa lam bri sa may kŏ tât hơm.$b$,true),
('bunong-vn','EZK',32,5,null,$b$Gâp mra srih puăch may tâm ăp dor yôk, jêh ri sŏk săk jăn may khĭt brôi bêng lĕ ntŭk rlŭng.$b$,false),
('bunong-vn','EZK',32,6,null,$b$Gâp mra sŏk mham may djrah lam bri may kŏ tât ta yôk, jêh ri ăp lĕ rngôch n'hor dak bêng ma mham may nơm hoch.$b$,false),
('bunong-vn','EZK',32,7,null,$b$Tơ lah gâp jut lơi may, gâp mra nkŭm trôk nđôch, jêh ri ăn phung mănh klơ trôk jêng ngo; gâp mra nkŭm măt nar ma ndâr tŭk, jêh ri khay mâu hôm nchrat ang đŏng ôh.$b$,true),
('bunong-vn','EZK',32,8,null,$b$Gâp mra ăn nau ngo klĕng lĕ rngôch rplay nau ang ta klơ trôk mâu hôm sol ang ôh ta klơ may, jêh ri ăn bri dak may jêng ngo, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',32,9,null,$b$Gâp mra ƀư uh-ah nuih n'hâm âk mpôl bunuyh, tơ lah gâp mra ƀư nau rai yot ma may tâm nklang phung mpôl băl bunuyh, tâm bri may ê-hŏ mâp gĭt năl ôh.$b$,false),
('bunong-vn','EZK',32,10,null,$b$Gâp mra ăn âk phung ƀon lan geh nau hih rhâl yor ma may, jêh ri phung hađăch khân păng mra râm nsâr yor may, tơ lah gâp yor đao dao gâp ta năp khân păng. Ntŭk nar may chôt khĭt, ăp nơm khân păng yor ma nau rêh khân păng nơm, râm nsâr klach mro ta nar may tŭp.$b$,false),
('bunong-vn','EZK',32,11,null,$b$Ngăn yơh, nau Yêhôva Brah Ndu lah pô aơ: Đao dao hađăch Babilôn mra văch tât lơh ma may.$b$,false),
('bunong-vn','EZK',32,12,null,$b$Gâp mra ăn lĕ rngôch phung ƀon lan âk may cha lôt bu nkhĭt ma đao đơ phung dăng ktang, lĕ rngôch khân păng jêng phung ƀai rnam bu klach ngăn tâm lĕ ntil mpôl bunuyh. Khân păng mra hŭch jêh nau sưr rlau n'gor bri Êjipt, jêh ri lĕ rngôch phung ƀon lan âk păng mra rai lôch.$b$,false),
('bunong-vn','EZK',32,13,null,$b$Gâp mra ƀư rai lĕ rngôch mpô mpa bri păng khĭt lĕ n'gŏ ntŭk kơh dak krong toyh, dak mâu hôm geh jâng bu nchŭ rkhăl đŏng ôh; mâu lĕ hôm nchop mpô mpa bri ƀư rkhăl dak.$b$,false),
('bunong-vn','EZK',32,14,null,$b$Rnôk nây gâp mra ƀư ma n'hor dak khân păng dơi jêng rsang, jêh ri ăn dak krong khân păng hoch nâm bu dak play ôlivơ, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',32,15,null,$b$Tơ lah gâp ăn n'gor bri Êjipt jêng ntŭk rngol, lĕ bu lơh rai lĕ rngôch, jêh ri bu kuak lĕ ndô ndơ tâm păng sa ơm hŏ geh âk rmeh ngăn, tơ lah gâp mbang lĕ rngôch phung gŭ tâm n'gor bri nây, rnôk nây khân păng mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',32,16,null,$b$Aơ jêng nau bu mra nhĭm vơl; phung kon bu ur phung mpôl bunuyh mra nhĭm vơl ma nau nây; khân păng nhĭm vơl nau nây ma n'gor bri Êjipt jêh ri ma lĕ rngôch phung ƀon lan âk păng, Yêhôva Brah Ndu lah.$b$,true),
('bunong-vn','EZK',32,17,null,$b$Tâm năm rơh jât ma bar, nar bŏng khay, geh nau Brah Ndu ngơi lah ma gâp:$b$,true),
('bunong-vn','EZK',32,18,null,$b$Hơi kon bunuyh, nhĭm vơl hom ma ƀon lan bĭk rơ̆ bri Êjipt, jêh ri ăn păng nđâp ma phung kon bu ur phung mpôl băl bunuyh geh lư n'găr jŭr tâm ntŭk jru tâm dâng neh, ndrel ma phung hŏ jŭr jêh ma trôm jru!$b$,false),
('bunong-vn','EZK',32,19,null,$b$May mâu hĕ ueh lơn ma bu? Jŭr hom, jêh ri bêch ndrel ma phung mâu koh ntâu ôh.$b$,true),
('bunong-vn','EZK',32,20,null,$b$Khân păng mra cha lôt tâm nklang phung bu kŏ nkhĭt jêh ma đao. Păng lĕ bu rơm ơm ma đao, leo hom păng mra bêch.$b$,false),
('bunong-vn','EZK',32,21,null,$b$Tă tâm nklang Ƀon Phung Khĭt, phung kôranh ta han tâm lơh janh ktang, ndrel phung kơl păng, mra ngơi lah ma păng pô aơ: Khân păng hŏ jŭr ta nây, khân păng hŏ bêch rklăk, jêng phung mâu koh ntâu ôh, phung bu hŏ nkhĭt jêh ma đao.$b$,true),
('bunong-vn','EZK',32,22,null,$b$Ta nây geh phung Asyri ndrel ma lĕ rngôch phung ƀon lan păng; văr jŭm păng geh môch da dê. Lĕ rngôch khân păng bu hŏ nkhĭt jêh ma đao;$b$,true),
('bunong-vn','EZK',32,23,null,$b$môch phung nây bu ƀư ta ntŭk ngai lơn tâm Trôm Jru, jêh ri phung ƀon lan păng dăp mbor gŭ văr jŭm môch păng, lĕ rngôch khân păng bu hŏ nkhĭt jêh ma đao, nđâp lah khân păng jêng phung bĭk rơ̆ nhhu nkrit tâm bri dak phung hôm rêh, ƀiă lah aƀaơ ri hŏ cha lôt jêh ma đao bu.$b$,false),
('bunong-vn','EZK',32,24,null,$b$Ta nây geh phung Êlam ndrel ma lĕ rngôch phung lan âk păng gŭ văr jŭm môch păng; lĕ rngôch khân păng lĕ bu nkhĭt da dê; jêh ri khân păng hŏ chôt khĭt ma đao. Phung mâu hŏ koh ntâu nây hŏ trŭnh tâm ntu jru tâm dâng neh, jêng phung ƀư nkrit nhhu bu lam bri dak phung hôm rêh; khân păng dơn anh nau bêk prêng khân păng ndrel phung trŭnh jêh tâm ntŭk trôm jru.$b$,true),
('bunong-vn','EZK',32,25,null,$b$Bu hŏ ƀư jêh ma păng du mlâm sưng bêch tâm nklang phung bu hŏ nkhĭt jêh ndrel ma lĕ rngôch phung ƀon lan âk păng, môch phung nây gŭ văr jŭm păng, lĕ rngôch jêng phung mâu hŏ koh ntâu nây bu hŏ nkhĭt jêh ma đao, yor lah khân păng lĕ tă nkrit bu tâm lam bri phung hôm rêh, khân păng dơn anh nau bêk prêng khân păng ndrel phung trŭnh jêh tâm ntŭk trôm jru, jêh ri bu dăp mbor păng tâm nklang lĕ rngôch phung bu nkhĭt.$b$,true),
('bunong-vn','EZK',32,26,null,$b$Ta nây geh phung Mêsek jêh ri phung Tubal, jêh ri lĕ rngôch ƀon lan âk khân păng; môch phung nây gŭ văr jŭm khân păng; lĕ rngôch jêng phung mâu hŏ koh ntâu bu hŏ nkhĭt jêh ma đao; yor lah khân păng lĕ tă ƀư nkrit bu lam bri dak phung hôm rêh.$b$,true),
('bunong-vn','EZK',32,27,null,$b$Khân păng mâu bêch ôh ndrel phung ta han janh ktang hŏ cha lôt jêh trŭnh hăn tâm mpôl mâu hŏ koh ntâu, phung ta han nây hŏ trŭnh tâm ntŭk Ƀon Phung Khĭt ndrel ma ndơ khân păng tâm lơh, jêh ri bu dơm đao tâm dâng bôk khân păng nơm. Ƀiă lah phung êng ri, nau djơh mhĭk păng nâm bu hŏ nchep tâm nting khân păng nơm; yor lah khân păng lĕ tă ƀư nkrit ma phung ta han janh ktang tâm lam bri phung hôm rêh.$b$,false),
('bunong-vn','EZK',32,28,null,$b$Ƀiă lah may mra khĭt ta nklang ndrel phung mâu hŏ koh ntâu, jêh ri mra bêch ndrel phung bu nkhĭt ma đao.$b$,false),
('bunong-vn','EZK',32,29,null,$b$Ta nây geh phung Êđôm, phung hađăch jêh ri lĕ rngôch phung kôranh păng, nđâp tơ lah khân păng geh nau ktang kđôi lĕ, bu rbuch păng khân păng ndrel ma phung bu hŏ nkhĭt ma đao, jêh ri bêch ndrel phung mâu hŏ koh ntâu ôh, jêh ri ndrel phung trŭnh hăn ma Trôm Jru.$b$,true),
('bunong-vn','EZK',32,30,null,$b$Ta ntŭk nây ăt tâm ban lĕ geh lĕ rngôch phung kôranh n'gor bri dor jêh ri lĕ rngôch phung Sidôn, hăn trŭnh da dê ndrel phung bu nkhĭt, nđâp lah nau janh ktang khân păng hŏ ƀư nkrit bu jêh; khân păng dơn anh nau bêk prêng; khân păng, jêng phung mâu hŏ koh ntâu nây, hŏ bêch ndrel phung bu nkhĭt jêh ma đao, jêh ri khân păng dơn anh nau bêk prêng tâm mpôl phung hăn trŭnh tâm ntŭk trôm jru.$b$,false),
('bunong-vn','EZK',32,31,null,$b$Tơ lah Pharaôn saơ phung nây, păng mra rthi nuih n'hâm păng nơm yor lĕ rngôch phung ƀon lan păng âk râk, Pharaôn jêh ri lĕ rngôch phung ta han păng, bu nkhĭt jêh ma đao dao, Yêhôva Brah Ndu lah.$b$,true),
('bunong-vn','EZK',32,32,null,$b$Yor lah păng lĕ tă ƀư nkrit nhhu bu tâm bri phung hôm rêh; pô nây bu mra rbêch păng ndrel ma phung mâu hŏ koh ntâu ôh, ndrel ma phung bu nkhĭt ma đao dao, Pharaôn jêh ri lĕ rngôch phung ƀon lan âk păng, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',33,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',33,2,null,$b$Hơi kon bunuyh, ngơi lah hom ma phung ƀon lan may pô aơ: Tơ lah gâp ăn nau tâm lơh tât ma du n'gor bri, jêh ri ƀon lan tâm bri nây săch du huê nuyh tă bơh ta nklang khân păng, jêh ri njêng ma păng nơm kâp gak ma khân păng,$b$,false),
('bunong-vn','EZK',33,3,null,$b$jêh ri tơ lah păng saơ bu leo đao dao tât ma bri dak, pô ri păng uh nŭng ăn phung ƀon lan gĭt njrăng.$b$,false),
('bunong-vn','EZK',33,4,null,$b$Rnôk nây, mbu nơm tăng bâr nŭng ƀiă lah mâu gŭ njrăng ôh, jêh ri tơ lah nau tâm lơh tât nkhĭt păng, mham bunuyh nây mra srih ta bôk păng nơm;$b$,false),
('bunong-vn','EZK',33,5,null,$b$yor lah păng lĕ tăng jêh bâr nŭng ƀiă lah mâu ŭch njâng ôh; ƀiă lah tơ lah păng gŭ njrăng jêh ri mơ dơi klaih nau rêh păng.$b$,false),
('bunong-vn','EZK',33,6,null,$b$Ƀiă lah tơ lah nơm kâp gak saơ đao tât tâm bri neh mâu ŭch uh ôh nŭng, kŏ tât ƀon lan mâu geh nau mbơh ôh, jêh ri nau tâm lơh tât nkhĭt lơi du huê phung khân păng, nơm nây mra khĭt tâm nau tih păng, ƀiă lah gâp mra srih mham ô băl ta ti nơm gak.$b$,false),
('bunong-vn','EZK',33,7,null,$b$Pô nây lĕ, Hơi kon bunuyh, gâp hŏ njêng may gay ƀư bunuyh gak ăn ma ngih Israel; tơ lah may tăng nau ngơi tă bơh bâr mbung gâp, ăn may sâm mbơh ăn khân păng njrăng.$b$,true),
('bunong-vn','EZK',33,8,null,$b$Tơ lah gâp lah ma bunuyh tih, Hơi kon bunuyh tih, Nanê̆ ngăn may mra khĭt, jêh ri lah may mâu mbơh ôh gay ăn bunuyh djơh nây cha lơi trong mhĭk păng, pô ri bunuyh djơh nây mra khĭt tâm nau ƀai păng, ƀiă lah gâp srih mham păng ta ti may.$b$,false),
('bunong-vn','EZK',33,9,null,$b$Ƀiă lah, tơ lah may ăn nơm tih njrăng gay ăn păng lơi lĕ trong tih păng, ƀiă lah păng mâu ŭch lơi ôh trong păng tih; păng mra khĭt tâm nau tih mhĭk păng, bi may hŏ rklaih jêh nau rêh may nơm.$b$,false),
('bunong-vn','EZK',33,10,null,$b$Bi may, hơi kon bunuyh, lah hom ma ngih Israel, pô aơ: Nau he rlau nau vay jêh ri nau tih hôm khan (djang) tâm he, jêh ri he ntơm roh yor nau tih nây, pô nây mâm he hôm dơi gŭ rêh?$b$,true),
('bunong-vn','EZK',33,11,null,$b$Lah hom ma khân păng, tĭng nâm gâp rêh, Yêhôva Brah Ndu lah. Gâp mâu maak ôh ma nơm tih khĭt, ƀiă lah maak gay ma nơm tih cha lơi trong tih păng jêh ri dơi rêh. Khân may cha lơi hom, cha lơi ngăn hom tă bơh trong tih khân may. Mâm ƀư khân may ŭch khĭt, Hơi ngih Israel?$b$,false),
('bunong-vn','EZK',33,12,null,$b$Bi may, hơi kon bunuyh, lah hom ma phung ƀon lan may, pô aơ: Nau sŏng srăng ma nơm sŏng mâu mra tâm rklaih păng ôh tơ lah păng ƀư tih; jêh ri bi ma nau tih nơm tih, păng mâu mra khĭt ôh yor nau tih nây tơ lah păng nhăl rmal tă bơh nau tih păng. Jêh ri tâm ban lĕ bunuyh sŏng srăng mâu mra dơi gŭ rêh ôh yor nau sŏng păng, tơ lah păng ƀư tih.$b$,true),
('bunong-vn','EZK',33,13,null,$b$Nđâp lah gâp geh lah ma nơm sŏng, n'hêl nanê̆ păng mra rêh; tơ lah păng rnơm ma nau sŏng păng nơm jêh ri ƀư tih, gâp mâu mra kah gĭt ôh ma kan sŏng păng hŏ ƀư jêh; ƀiă lah păng mra khĭt tâm nau tih păng hŏ ƀư.$b$,false),
('bunong-vn','EZK',33,14,null,$b$Tâm ban lĕ, tơ lah gâp lah ma nơm tih, N'hêl nanê̆ may mra khĭt, ƀiă lah tơ lah păng nhăl rmal tă bơh nau tih păng, jêh ri ƀư nau sŏng jêh ri di,$b$,false),
('bunong-vn','EZK',33,15,null,$b$tơ lah păng mplơ̆ sĭt ndơ păng ton ndơ păng lĕ sŏk jêh, ntrok mplơ̆ lơi ndơ păng hŏ ntŭng; jêh ri chuat tĭng ndô̆ tâm nau vay nau rêh, mâu ƀư ôh nau kue; n'hêl nanê̆ păng mra rêh, păng mâu mra khĭt ôh.$b$,false),
('bunong-vn','EZK',33,16,null,$b$Gâp mâu mra kah gĭt đŏng ôh du ntil nau tih păng hŏ ƀư. Păng hŏ ƀư tĭng ndô̆ nau vay jêh ri nau sŏng ngăn, n'hêl nanê̆ păng mra rêh.$b$,false),
('bunong-vn','EZK',33,17,null,$b$Ƀiă lah phung kon sau ƀon lan may lah, trong Yêhôva mâu sŏng ôh; ƀiă lah nây jêng trong khân păng nơm mâu sŏng ôh!$b$,true),
('bunong-vn','EZK',33,18,null,$b$Tơ lah bunuyh sŏng lơi nau sŏng jêh ri ƀư nau kue, păng mra khĭt yor nau nây.$b$,false),
('bunong-vn','EZK',33,19,null,$b$Tơ lah nơm tih cha lơi lĕ nau tih păng jêh ri ƀư di tĭng nau vay jêh ri nau sŏng ngăn, păng mra gŭ rêh yor nau nây.$b$,false),
('bunong-vn','EZK',33,20,null,$b$Ƀiă lah khân may lah, ‘Trong Yêhôva mâu sŏng ôh.’ Hơi ngih Israel, gâp mra phat dôih khân may, ăp nơm tĭng nâm kan păng ƀư.$b$,false),
('bunong-vn','EZK',33,21,null,$b$Năm rơh jât ma bar bu nhŭp hên jêng bu nă, năng prăm khay jât, du huê bunuyh klaih jêh tă bơh ƀon Yêrusalem văch tât ma gâp jêh ri lah, Ƀon Yêrusalem lĕ bu sŏk jêh.$b$,true),
('bunong-vn','EZK',33,22,null,$b$Pô ri, êp kêng mhaơ ê lor ma bunuyh klaih nây văch tât, ti Yêhôva dra ta gâp, jêh ri păng hŏ pơk bâr mbung gâp kŏ tât ôi ơm bunuyh nây tât ma gâp, pô ri trôm mbung gâp hŏ dơi hă jêh, jêh ri gâp mâu hôm mlo ôh.$b$,false),
('bunong-vn','EZK',33,23,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',33,24,null,$b$Hơi kon bunuyh, phung gŭ tâm ntŭk roh rai gŭ bun bêng bri Israel ăt rŏ lah ƀa ƀơ, Y-Abraham knŏng du huê păng, ƀiă lah păng gŭ chăm bri neh aơ dơi ăn ma he gŭ ndơn.$b$,false),
('bunong-vn','EZK',33,25,null,$b$Yor ri, lah hom ma khân păng, Pô aơ nau Yêhôva lah: Khân may sa puăch (puăch) nđăp ma mham, jêh ri khân may n'gơr muh măt leo ma rup brah khân may, jêh ri ƀư ăn nkhŭt mham; pô ri khân may mra gŭ ndơn chăm lĕ bri neh aơ?$b$,false),
('bunong-vn','EZK',33,26,null,$b$Khân may nsing rnơm ma đao, khân may ƀư nau mhĭk gâp tâm rmot; jêh ri ăp nơm tâm khân may ƀư ndjrih ur nơm chiau meng khân may; pô nây khân may dơi lĕ sŏk ndơn bri nây?$b$,false),
('bunong-vn','EZK',33,27,null,$b$Lah hom ma khân păng nau aơ: Pô aơ nau Yêhôva Brah Ndu lah: Di ngăn tĭng nâm gâp gŭ rêh, n'hêl nanê̆ phung gŭ tâm ntŭk rai roh mra chôt khĭt ma đao dao; jêh ri gâp mra jao phung gŭ tâm bri ăn ma mpô mpa sa kăp khân păng; jêh ri phung gŭ tâm pôih ta han jêh ri trôm yôk mra khĭt ma nau ji nkhĭt.$b$,true),
('bunong-vn','EZK',33,28,null,$b$Gâp mra ăn bri nây jêng rngol jêh ri rngot njăp; jêh ri nau dăng ktang păng ƀư sưr rlau mra rai lôch; jêh ri lĕ yôk Israel mra jêng rngol kŏ tât mâu geh du huê nuyh prot rgăn ta nây ôh.$b$,false),
('bunong-vn','EZK',33,29,null,$b$Rnôk nây khân păng mra gĭt gâp jêng Yêhôva, tơ lah gâp hŏ ƀư ma bri aơ jêng rngol jêh ri nsoih dơm, yor lĕ rngôch nau gâp tâm rmot khân păng hŏ ƀư.$b$,false),
('bunong-vn','EZK',33,30,null,$b$Hơi kon bunuyh, bi phung ƀon lan may gŭ rŏ mpêr ƀon jêh ri ta mpông ngih, tâm nkoch bri ndrăng khân păng; lah ma may; ăp nơm ndrel oh nâu păng lah: ‘Văch hom jêh ri iăt nau ngơi luh tă bơh Yêhôva.’ Phâm păng lah!$b$,true),
('bunong-vn','EZK',33,31,null,$b$Pô ri khân păng văch lĕ ma phung lĕ ma mpôl tât ma may; nâm bu phung ƀon lan mơng văch, gŭ pa năp măt may, jêh ri iăt nau may lah; ƀiă lah khân păng mâu ŭch tông nau nây ôh. Bâr mbung khân păng tâm mpơl âk nau rŏng, ƀiă lah nuih n'hâm khân păng rŏng ma nau khlay ma nơm!$b$,false),
('bunong-vn','EZK',33,32,null,$b$Aơ, khân păng uănh may nâm bu du huê nuyh blau mprơ bâr ueh jêh ri blau kreh gong rêng ueh ngăn; khân păng iăt nau may lah, ƀiă lah khân păng mâu ŭch tông ôh nau nây.$b$,false),
('bunong-vn','EZK',33,33,null,$b$Yor ri, tơ lah nau aơ tât jêh ri mra tât ngăn ngên! Rnôk nây khân păng gĭt du huê kôranh nơm mbơh lor gŭ jêh ta nklang khân păng.$b$,false),
('bunong-vn','EZK',34,1,null,$b$Yêhôva ma gâp:$b$,true),
('bunong-vn','EZK',34,2,null,$b$“Hơi kon bunuyh, mbơh lor hom nau tâm rdâng đah phung rmăk leo Israel; mbơh lor hom jêh ri lah ma khân păng, Pô aơ nau Yêhôva Brah Ndu lah: Rêh ni ngăn ma phung rmăk leo Israel, jêng bunuyh siăm êng khân may nơm!$b$,false),
('bunong-vn','EZK',34,3,null,$b$Mâu di hĕ phung rmăk biăp vay ăn phung biăp kon lay; ƀiă lah khân may mâu ăn ôh biăp sa mpa!$b$,false),
('bunong-vn','EZK',34,4,null,$b$Khân may mâu ƀư ôh ma phung kon biăp kuet rôi ăn dơi jêng ktang, mâu ŭch săm ăn bah phung ji, mâu ŭch put ôh phung sôt rmanh, khân may mâu ŭch njŭn sĭt ôh phung nhhơt bri, khân may mâu ŭch joi ôh phung lĕ roh nhhơt; ƀiă lah khân may ƀư nau nchâp nđâl, khân may vay chiă uănh khân păng.$b$,false),
('bunong-vn','EZK',34,5,null,$b$Yor lah mâu geh nuyh rmăk ôh pô ri khân păng roh yot. Tơ lah khân păng lĕ nhhơt jêh, khân păng nsong mblêng jêng mpa sa ma lĕ rngôch mpô mpa bri.$b$,false),
('bunong-vn','EZK',34,6,null,$b$Phung biăp gâp hăn mblêng nhhơt ta klơ lĕ rngôch nâm jêh ri ta klơ yôk prêh; phung biăp gâp nhhơt lam bri neh ntu, mâu geh ôh bunuyh mray, mâu lĕ geh bunuyh tĭng joi khân ô băl.$b$,false),
('bunong-vn','EZK',34,7,null,$b$Yor ri, Hơi phung rmăk biăp, iăt hom nau Yêhôva ngơi:$b$,true),
('bunong-vn','EZK',34,8,null,$b$Tĭng nâm gâp gŭ rêh Yêhôva Brah Ndu lah, yor lah mâu geh ôh nuyh rmăk, dĭng phung biăp gâp hŏ jêng ndơ bu lĕ pit in jêh, jêh ri ndơ sa ma lĕ rngôch ntil mpô mpa bri, jêh ri yor lah phung rmăk biăp gâp ăt mâu lĕ ŭch joi biăp gâp, ƀiă lah khân păng siăm êng khân păng nơm, jêh ri mâu ôh ŭch siăm phung biăp gâp.$b$,false),
('bunong-vn','EZK',34,9,null,$b$Yor nây, Hơi phung rmăk biăp, iăt hom nau Yêhôva ngơi:$b$,false),
('bunong-vn','EZK',34,10,null,$b$Pô aơ nau Yêhôva lah: Aơ, gâp tâm rdâng đah phung rmăk biăp nây; gâp dăn khân păng mplơ̆ sĭt ma gâp nơm biăp gâp, jêh ri khân păng mâu hôm dơi chiăp đŏng ôh biăp gâp; jêh ri ăt mâu dơi lĕ khân păng rong siăm êng khân păng nơm; ƀiă lah gâp klĕ mphâk biăp gâp luh du tă bơh trôm mbung khân păng, gay ăn biăp mâu ƀư ôh ndơ sa ăn ma khân păng.$b$,false),
('bunong-vn','EZK',34,11,null,$b$Yor lah Yêhôva lah pô aơ: Aơ, gâp, gâp nơm yơh mra tĭng joi biăp gâp, gâp mra joi păng ăn saơ$b$,true),
('bunong-vn','EZK',34,12,null,$b$Ntĭt nâm bu du huê rmăk biăp joi saơ phung biăp păng, tơ lah geh ƀa ƀă phung biăp chah rai nhhơt, tâm ban nây lĕ gâp mra joi biăp gâp; gâp mra tâm rklaih khân păng luh du bơh lĕ rngôch ntŭk khân păng hŏ nhhơt roh jêh ta nar tŭk nkâm ngo klĕng.$b$,false),
('bunong-vn','EZK',34,13,null,$b$Gâp mra djôt leo khân păng luh du tă bơh ta nklang mpôl ƀon lan bri êng, gâp mra rgum khân păng sĭt tă tâm bri neh êng khân păng nơm. Gâp mra chiă uănh khân păng ta klơ yôk Israel, êp tu dak, jêh ri lĕ rngôch ntŭk geh bunuyh gŭ tâm bri dak.$b$,false),
('bunong-vn','EZK',34,14,null,$b$Gâp mra chiăp khân păng tâm ndrêch gơ̆ nse, jêh ri ndrung n'gar khân păng mra ăn ta klơ yôk Israel; ta nây khân păng mra gŭ rlu kuen tâm ntŭk ueh, jêh ri sa ta ntŭk ndrêch gơ̆ nse jêng ta klơ yôk Israel.$b$,true),
('bunong-vn','EZK',34,15,null,$b$Nây jêng gâp nơm ro yơh jêng rmăk ma biăp gâp, jêh ri ăn khân păng rlu kuen, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',34,16,null,$b$Gâp mra tĭng joi phung lĕ roh, gâp mra leo mplơ̆ phung bu mprơh, gâp mra put săm phung kuet rven jêh ri ƀư ma phung lĕ huăr dơi jêng ktang, ƀiă lah gâp mra ƀư rai lơi phung lay jêh ri phung dăng ktang; gâp mra chiă uănh khân păng ma nau sŏng.$b$,false),
('bunong-vn','EZK',34,17,null,$b$Yêhôva lah: Bi ma may, hơi phung biăp gâp, aơ, gâp mra phat dôih ndrăng phung biăp, biăp nkuăng ma be nkuăng.$b$,true),
('bunong-vn','EZK',34,18,null,$b$Phung khân may sa gơ̆ tâm ndrêch gơ̆ ueh, kŏ tât khân may jot plên lơi gơ̆ ueh, hŏ nhêt jêh dak rsang sŏk jâng nchŭ lơi ăn rkhăl dak hôm e rmeh; mâm khân may mâu ŭch uănh nau nây jêng nau kan jê̆ lê̆ dơm hĕ?$b$,false),
('bunong-vn','EZK',34,19,null,$b$Bi phung biăp gâp mra sa gơ̆ khân may lĕ jot jêh ma jâng, jêh ri nhêt dak lĕ jâng khân may nchŭ rkhăl!$b$,true),
('bunong-vn','EZK',34,20,null,$b$Yor nây, Yêhôva Brah Ndu lah: Aơ, gâp, gâp nơm yơh mra phat dôih ndrăng biăp lay jêh ri biăp rgay.$b$,true),
('bunong-vn','EZK',34,21,null,$b$Yor lah khân may mbeng ma pŭng vĕ jêh ri săng nglik, jêh ri gĕ ma nke lĕ rngôch biăp lĕ rôi, kŏ tât khân may ƀư chah rai khân păng pru pra lam ntŭk;$b$,false),
('bunong-vn','EZK',34,22,null,$b$dĭng gâp mra tât rklaih phung biăp gâp, khân păng mâu mra ƀư ndơ sa ma bu đŏng ôh, jêh ri gâp mra phat dôih ndrăng phung biăp.$b$,false),
('bunong-vn','EZK',34,23,null,$b$Gâp mra njêng du huê rmăk biăp chiă uănh khân păng, jêng Y-Đavit, oh mon gâp. Nây jêng du huê bunuyh chiăp khân păng, păng mra ƀư bunuyh chiă uănh khân păng.$b$,false),
('bunong-vn','EZK',34,24,null,$b$Gâp, Yêhôva, mra jêng Brah Ndu khân păng, bi Y-Đavit, oh mon gâp, mra ƀư hađăch ta nklang khân păng; gâp, Yêhôva, hŏ ngơi nau nây.$b$,false),
('bunong-vn','EZK',34,25,null,$b$Rnôk nây gâp mra ƀư đah khân păng du nau tâm rnglăp đăp mpăn. Gâp mra mprơh mpô mpa bri janh lơi ăn hôm tâm nklang bri dak, gay ăn ƀon lan gâp dơi gŭ mpăn tâm bri rdah jêh ri gŭ bêch tâm krŏng.$b$,true),
('bunong-vn','EZK',34,26,null,$b$Gâp mra ƀư ăn khân păng jêh ri ntŭk jŭm yôk jêng nau ueh uĭn; gâp mra ăn dak mih tâm di yan, dak mih nây mra jêng nau ueh uĭn.$b$,false),
('bunong-vn','EZK',34,27,null,$b$Tơm si nklang bri mra play âk, jêh ri neh mra chăt hon jêng ndơ. Khân păng mra gŭ mpăn tâm bri khân păng; jêh ri khân păng mra gĭt gâp jêng Yêhôva, tơ lah gâp ƀư pă jêh mâng mbăk khân păng, jêh ri ăn khân păng jêng kon me tă bơh ti phung nhŭp khân păng ƀư jêng dĭk.$b$,false),
('bunong-vn','EZK',34,28,null,$b$Khân păng mâu mra ƀư jêng ndơ mpôl bri mra sa kăp đŏng khân păng, khân păng mra gŭ mpăn, mâu geh ôh nuyh mra nkrit khân păng.$b$,false),
('bunong-vn','EZK',34,29,null,$b$Gâp mra ăn ma khân păng n'gar play jêng ngăn, pô ri khân păng mâu mra khĭt huăr ji ngot đŏng ôh tâm bri păng, jêh ri khân păng mâu mra dơn đŏng ôh nau mpôl băl êng ƀư bêk prêng.$b$,false),
('bunong-vn','EZK',34,30,null,$b$Rnôk nây khân păng mra gĭt gâp, Yêhôva Brah Ndu khân păng, gŭ ndrel khân păng, jêh ri gĭt ngih Israel, khân păng jêng ƀon lan gâp, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',34,31,null,$b$Khân may jêng biăp gâp, jêng phung biăp tâm ndrêch gơ̆ gâp; khân may jêng bunuyh, jêh ri gâp jêng Brah Ndu khân may, Yêhôva Brah Ndu lah.”$b$,false),
('bunong-vn','EZK',35,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',35,2,null,$b$“Hơi kon bunuyh, rle muh măt may n'gĭl leo yôk Sêir jêh ri mbơh lor tâm rdâng ma păng,$b$,false),
('bunong-vn','EZK',35,3,null,$b$jêh ri lah ma păng, pô aơ nau Yêhôva Brah Ndu lah: Aơ gâp tâm rdâng đah may, Hơi yôk Sêir, jêh ri gâp mra yơr ti gâp ƀư ma may, jêh ri ƀư ăn may jêng rngol jêh ri tŭk nsoih.$b$,false),
('bunong-vn','EZK',35,4,null,$b$Gâp mra ƀư rai ƀon toyh may jêh ri may mra jêng rngol. Rnôk nây may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',35,5,null,$b$Yor lah may hôm prăp nau rlăng ƀa ƀơ ntơm bơh rô̆ kăl e; jêh ri jao phung ƀon lan Israel ma nau bu nkhĭt đah đao dôl rnôk khân păng rêh ni, dôl rnôk bu phat dôih nglĕ dŭt ma khân păng.$b$,true),
('bunong-vn','EZK',35,6,null,$b$Yor tă nau nây, Yêhôva Brah Ndu lah: Di ngăn nâm bu gâp gŭ rêh, gâp mra jao may ma nau luh mham, phung ƀư pling mham mra tĭng may; yor lah may mâu tâm rmot ôh ma mham, yor ri phung ƀư pling mham tĭng may!$b$,false),
('bunong-vn','EZK',35,7,null,$b$Pô ri gâp mra ƀư ma yôk Sêir ntŭk nsoih jêh ri rngol; jêh ri ƀư rai nđâp ma bunuyh hăn prot jêh ri bunuyh rsong.$b$,false),
('bunong-vn','EZK',35,8,null,$b$Gâp mra ƀư ăn bêng yôk ma bunuyh bu nkhĭt păng; phung bu nkhĭt ma đao mra chôt khĭt ta klơ yôk may, tâm rlŭng jêh ri ta nklang lĕ rngôch n'hor dak may.$b$,false),
('bunong-vn','EZK',35,9,null,$b$Gâp mra ƀư ma may jêng rngol n'ho ro; lĕ rngôch ƀon toyh ngih mbâl may mra mâu geh bu gŭ ôh. Rnôk nây may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',35,10,null,$b$Yor lah may lah, bar mpôl aơ jêh ri bar bri aơ mra jêng ndơ hên, jêh ri hên mra sŏk khân păng pha hên, nđâp tơ lah Yêhôva gŭ ta nây kđôi lĕ;$b$,true),
('bunong-vn','EZK',35,11,null,$b$Yor nây tĭng nâm gâp gŭ rêh Yêhôva Brah Ndu lah, gâp mra ƀư ma may ma nau ji nuih jêh ri nau nach may hŏ mpơl jêh yor may tâm rmot ma khân păng, jêh ri tơ lah gâp phat dôih may, gâp mra mpơl gâp nơm ta nklang khân păng.$b$,false),
('bunong-vn','EZK',35,12,null,$b$May mra gĭt gâp, Yêhôva, hŏ tăng lĕ nau suai rak khân may ngơi jêh tâm rdâng đah yôk Israel, lah: Lĕ yôk nây hŏ ƀư jêh ăn jêng rngol, hŏ jao ma gâp sa kăp rvăn.$b$,false),
('bunong-vn','EZK',35,13,null,$b$May ngơi n'hao êng săk nơm tâm rdâng đah gâp ma trôm mbung may, jêh ri may lir lar nau may ngơi tâm rdâng ma gâp; gâp lĕ tăng jêh nau nây!$b$,false),
('bunong-vn','EZK',35,14,null,$b$Pô aơ nau Yêhôva Brah Ndu lah: Dôl lĕ neh ntu hâk răm, gâp mra ƀư ăn may jêng rngol.$b$,true),
('bunong-vn','EZK',35,15,null,$b$Pô ri gâp ƀư ma may tâm ban lĕ. Hơi yôk Sêir, may ndrel ma lĕ bri Êđôm. Rnôk nây khân mra gĭt gâp jêng Yêhôva.”$b$,false),
('bunong-vn','EZK',36,1,null,$b$Hơi kon bunuyh, mbơh lor hom ma phung yôk Israel jêh ri lah: Hơi phung yôk Israel, iăt hom nau Yêhôva ngơi.$b$,true),
('bunong-vn','EZK',36,2,null,$b$Pô aơ, nau Yêhôva Brah Ndu lah: Yor lah ta han nơm rlăng lah jêh geh ma may, Hah hai! Jêh ri lah, Ntŭk yôk prêh bơh kăl e jêng jêh ndơ pha he,$b$,true),
('bunong-vn','EZK',36,3,null,$b$yor nây mbơh lor hom jêh ri lah, pô aơ nau Yêhôva Brah Ndu lah: Yor lah khân păng hŏ ƀư ăn khân may jêng rngol, jêh ri jot plên khân may văr jŭm pŭng meng, kŏ tât khân may jêng ndơ pha ma phung mpôl lĕ jŭm bri đơ phung hôm e klen, jêh ri khân may jêng ndơ phung ƀon lan ntêh rmot nsot ach jêh ri suai rak;$b$,false),
('bunong-vn','EZK',36,4,null,$b$yor nây, hơi phung yôk Israel, iăt hom nau Yêhôva ngơi: Yêhôva Brah Ndu lah ma phung yôk nâm jêh ri gôl yôk, ntŭk bri rlŭng, n'hong dak jiăng, bri dơm lĕ roh rai jêh ri ƀon rngol, hŏ jao ăn phung hôm klen ma phung mpôl bri dak jŭm khân may pit in jêh ri ntêh rmot;$b$,false),
('bunong-vn','EZK',36,5,null,$b$yor nau nây, Yêhôva Brah Ndu lah: Ngăn, gâp ngơi ma nau gâp ntôn duh nuih, ma phung bri bu hôm e, jêh ri ma lĕ rngôch phung Êđôm; jêng phung bêng ma nuih n'hâm răm rhơn jêh ri nau mĭn mưch rmot ngăn, khân păng ntôn lah bri neh gâp ăn khân păng ndơn chăm, gay ma khân păng sŏk pit in ndơ păng.$b$,false),
('bunong-vn','EZK',36,6,null,$b$Pô nây, mbơh lor hom ma bri Israel; mbơh hom ma phung nâm jêh ri yôk, dak n'hong dak jiăng jêh ri n'hŭt rlŭng, lah: Pô aơ nau Yêhôva lah: Ngăn gâp ngơi lah tâm nau ntôn jêh ri nau gâp ji nuih, yor lah khân may hŏ dơn nau phung mpôl bri bu ƀư bêk prêng.$b$,true),
('bunong-vn','EZK',36,7,null,$b$Yor ri, Yêhôva Brah Ndu lah: Gâp hŏ ton jêh: Lĕ rngôch bri gŭ jŭm khân may nanê̆ ngăn mra dơn nau bêk prêng!$b$,true),
('bunong-vn','EZK',36,8,null,$b$Ƀiă lah khân may, Hơi phung yôk Israel mra chăt nkeh n'gĭng khân may jêh ri play ma phung ƀon lan gâp Israel; yor lah khân păng dăch plơ̆ sĭt.$b$,true),
('bunong-vn','EZK',36,9,null,$b$Aơ, gâp gŭ mpeh ma khân may, jêh ri plơ̆ n'gĭl tay ma khân may, jêh ri mra pŏk rlơk khân may jêh ri srih ntil.$b$,false),
('bunong-vn','EZK',36,10,null,$b$Ta klơ neh khân may gâp mra ntop ăn bĭk rơ̆ bunuyh jêh ri nđâp lĕ rngôch kon sau ngih Israel. Lĕ rngôch ƀon toyh mra geh bunuyh gŭ, lĕ rngôch ntŭk lĕ djơh rai mra rdâk njêng tay đŏng.$b$,false),
('bunong-vn','EZK',36,11,null,$b$Gâp mra ăn bĭk rơ̆ bunuyh bu nun jêh ri mpô mpa ta klơ neh khân may, khân păng mra bĭk rơ̆ lơn jêh ri chăt jêng; gâp mra ăn ƀon lan khân may ma bunuyh âk nâm bu kơt sa ơm, jêh ri ăn nau ƀun lap ma khân may rlau lơn bơh ntơm sa ơm. Rnôk nây khân may mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',36,12,null,$b$Nanê̆ gâp mra ăn phung ƀon lan chuat hăn ta klơ neh khân may, jêng phung ƀon lan gâp Israel, jêh ri khân păng mra sŏk may pha khân păng nơm, jêh ri khân may mra jêng drăp ndơn ma khân păng, jêh ri khân may mâu mra ngroh lơi khân păng đŏng ôh.$b$,false),
('bunong-vn','EZK',36,13,null,$b$Pô aơ nau Yêhôva Brah Ndu lah: Yor lah bunuyh lah khân may, hơi neh, khân may mơng hêk sa bunuyh, jêh ri ƀư ngroh lơi kon sau phung bunuyh khân may,$b$,true),
('bunong-vn','EZK',36,14,null,$b$yor ri, khân may mâu hôm sa hêk bunuyh đŏng ôh, jêh ri mâu lĕ hôm ƀư ngroh lơi phung bunuyh tâm khân may, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',36,15,null,$b$Gâp mâu hôm ăn khân may tăng âk nau bri bu ntêh rmot nsot ach, jêh ri khân may mâu lĕ hôm anh ôh nau phung ƀon lan ƀư bêk prêng khân may; jêh ri khân may mâu mra ƀư chêh prah đŏng ôh phung ƀon lan khân may, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',36,16,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',36,17,null,$b$Hơi kon bunuyh, tơ lah ngih Israel gŭ jêh tâm bri neh khân păng nơm, hŏ ƀư ƀơ̆ ƀơch bri neh nây yor tă trong hăn jêh ri kan pah khân păng: Trong kan khân păng gŭ ngao pa năp nâm bu nau ƀơ̆ ƀơch du huê bu ur djơh nah bŭt.$b$,false),
('bunong-vn','EZK',36,18,null,$b$Yor ri gâp nkhŭt nau gâp ji nuih ma khân păng, yor tă bơh mham khân păng hŏ ƀư ƀơ̆ ƀơch bri neh nây ma rup brah khân păng.$b$,false),
('bunong-vn','EZK',36,19,null,$b$Gâp hŏ mprơh jêh khân păng tâm ăp bri dak bu êng, jêh ri khân păng pru pra lam bri dak êng; gâp hŏ phat jêh dôih khân păng tĭng nâm nau khân păng gŭ ngao jêh ri kan khân păng pah.$b$,false),
('bunong-vn','EZK',36,20,null,$b$Tơ lah khân păng hŏ tât jêh tâm nklang bri dak bu, khân păng hŏ ƀư tih đŏng amoh kloh ueh gâp, kŏ tât bu lah ma khân păng: Nây jêng phung ƀon lan Yêhôva; lĕ bu mprơh khân păng han du tă bơh bri Yêhôva!$b$,false),
('bunong-vn','EZK',36,21,null,$b$Ƀiă lah gâp chrê nhhuach amoh kloh ueh gâp phung ngih Israel hŏ ƀư ƀơ̆ jêh ta nklang mpôl bunuyh bri bu, jêng ntŭk ngih nây hŏ hăn tât.$b$,false),
('bunong-vn','EZK',36,22,null,$b$“Yor nây lah hom ma ngih Israel, ‘Pô aơ nau Yêhôva Brah Ndu lah: Nây mâu di ma khân may, Ơ ngih Israel, gâp ƀư nau nây; ƀiă lah yor Amoh kloh gâp khân may hŏ ƀư ƀơ̆ jêh tâm nklang mpôl băl bunuyh, ntŭk khân may hŏ tât.$b$,true),
('bunong-vn','EZK',36,23,null,$b$Gâp mra ƀư ăn kloh Amoh toyh gâp, jêng Amoh bu hŏ ƀư ƀơ̆ jêh ta nklang mpôl băl bunuyh, khân may yơh ƀư ƀơ̆ amoh nây. Yêhôva lah: Pô nây lĕ ntil mpôl, bunuyh mra gĭt gâp jêng Yêhôva, tơ lah tra năp măt khân păng gâp mra mpơl nau kloh yor tă khân may.$b$,false),
('bunong-vn','EZK',36,24,null,$b$“Gâp mra sŏk sĭt lơi phung khân may tă bơh ta nklang mpôl băl bu nuyh; gâp mra rgum tay khân may tă bơh lĕ rngôch bri, jêh ri leo sĭt khân may tâm bri êng ma khân may nơm.$b$,true),
('bunong-vn','EZK',36,25,null,$b$Gâp djrah dak rsang ma khân may, jêh ri khân may mra jêng kloh ma lĕ rngôch nau ƀơ̆ ƀơch khân may, jêh ri gâp ƀư kloh khân may tă bơh lĕ rngôch rup brah khân may.$b$,false),
('bunong-vn','EZK',36,26,null,$b$Gâp mra ăn ma khân may nuih n'hâm mhe, jêh ri gâp mra dơm ăn khân may huêng brah mhe, jêh ri gâp mra sŏk lơi bơh khân may nuih n'hâm dăng jêh ri ăn ma khân may nuih n'hâm rdơ̆ rbăn.$b$,false),
('bunong-vn','EZK',36,27,null,$b$Gâp mra dơm Huêng Brah gâp tâm khân may, jêh ri ntrôl khân may chuat tĭng ndô̆ nau vay gâp jêh ri njrăng ƀư tĭng nau gâp ntăm.$b$,true),
('bunong-vn','EZK',36,28,null,$b$Khân may mra gŭ tâm bri gâp ăn jêh ma chô-yau khân may; jêng phung ƀon lan gâp, jêh ri gâp jêng Brah Ndu khân may.$b$,false),
('bunong-vn','EZK',36,29,null,$b$Gâp mra tâm rklaih khân may bơh lĕ rngôch nau ƀơ̆ ƀơch; gâp mra kuăl ba răch ueh, ăn chăt hon ntop âk, jêh ri mâu ăn nau sa sât ji ngot tât ma khân may.$b$,true),
('bunong-vn','EZK',36,30,null,$b$Gâp mra ntop âk play đo jêh ri boh ba tă bơh mir khân may jêng rmeh rmai; gay ma khân may mâu dơn ôh nau bêk prêng yor sa sât ji ngot ta nklang bri dak bu êng.$b$,false),
('bunong-vn','EZK',36,31,null,$b$Rnôk nây khân may kah gĭt ma trong mhĭk khân may tĭng ndô̆ jêh, jêh ri nau kan khân may ƀư jêng mâu ueh ôh; jêh ri khân may tâm rmot êng khân may nơm, yor nau tih mhĭk jêh ri nau kue gâp tâm rmot khân may hŏ ƀư jêh.$b$,false),
('bunong-vn','EZK',36,32,null,$b$Mâu di yor khân may ôh gâp mra ƀư, Yêhôva Brah Ndu lah; ăn khân may gĭt rah vah nau nây. Hơi phung Israel, ăn khân may đit jêh ri prêng guam yor trong khân may chuat hăn!$b$,false),
('bunong-vn','EZK',36,33,null,$b$“Pô aơ Yêhôva Brah Ndu lah: Ta nar gâp mra ƀư kloh lĕ rngôch nau tih khân may, gâp mra ƀư tay ăn ƀon toyh khân may geh bu nuyh, jêh ri lĕ ntŭk djơh rai mra rdâk tay.$b$,true),
('bunong-vn','EZK',36,34,null,$b$Bri neh lĕ rngol bu mra chôk rlơk đŏng, mâu hôm jêng rngol ôh nâm bu kơt sa ơm ta năp măt lĕ rngôch bunuyh prot rgăn.$b$,false),
('bunong-vn','EZK',36,35,null,$b$Khân păng lah, “Bri neh aơ sa ơm jêng rngol, ƀiă lah aƀaơ hŏ jêng nâm bu n'gar Êđen; jêh ri ƀon toyh lĕ djơh rai, sa ơm jêng rngol, jêh ri hŏ rai jêh, pô ri aƀaơ geh bunuyh gŭ jêh ri geh mpêr pôih nâp ngăn”.$b$,false),
('bunong-vn','EZK',36,36,null,$b$Rnôk nây phung mpôl băl bunuyh hôm gŭ jŭm khân may mra gĭt gâp, Yêhôva, hŏ ndâk njêng tay ntŭk djơh rai, jêh ri tăm tay ta ntŭk rngol. Gâp nơm, Yêhôva hŏ ngơi nau nây, jêh ri mra ƀư tât jêng ngăn?$b$,false),
('bunong-vn','EZK',36,37,null,$b$“Pô aơ Yêhôva lah, Brah Ndu lah: Nau aơ tâm ban lĕ gâp mra ăn phung Israel dăn ma gâp, gay gâp ƀư ăn ma khân păng: Gâp mra ntop âk phung bu klâu geh nâm bu phung biăp.$b$,true),
('bunong-vn','EZK',36,38,null,$b$Lĕ rngôch ƀon djơh rai mra bêng phung bunuyh, nâm bu phung biăp gay ƀư ndơ ƀư brah, nâm bu phung biăp ta ƀon Yêrusalem tâm nar nhêt sa bu nal năng jêh. Jêh ri khân păng mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',37,1,null,$b$Ti Yêhôva dơm ta gâp; Păng chông leo gâp ma Huêng Brah Yêhôva jêh ri dơm gâp ta nklang rlŭng; rlŭng nây bêng ma nting.$b$,true),
('bunong-vn','EZK',37,2,null,$b$Pô ri Păng ăn gâp hăn nsong ta nklang nting nây, aơ, geh âk ngăn tâm rlŭng nây; jêh ri lĕ kro jêh da dê.$b$,false),
('bunong-vn','EZK',37,3,null,$b$Păng lah ma gâp, “Hơi kon bunuyh, dơi lĕ nting aơ dâk rêh đăng?” Gâp plơ̆ lah: “Ơ Yêhôva Brah Ndu, May yơh gĭt nau nây!”$b$,false),
('bunong-vn','EZK',37,4,null,$b$Păng lah tay ma gâp, “Mbơh lor hom ma nting nây jêh ri lah ma khân păng pô aơ; ‘Hơi nting rŭng (nting kro), iăt hom nau Yêhôva ngơi.’$b$,false),
('bunong-vn','EZK',37,5,null,$b$Pô aơ nau Yêhôva Brah Ndu ngơi ma nting rŭng Aơ, gâp mra ăn n'hâm phôl lăp tâm khân may, jêh ri khân may mra rêh đŏng.$b$,false),
('bunong-vn','EZK',37,6,null,$b$Gâp mra dơm rse suan tâm khân may, ăn mlay puăch dop ta klơ khân may jêh ri nkŭm khân may ma ntâu jêh ri phôl n'hâm ma khân may; jêh ri khân may mra rêh đŏng; jêh nây khân mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',37,7,null,$b$Pô nây gâp mbơh lor nâm bu Păng hŏ ntăm jêh ma gâp; jêh ri dôl gâp mbơh lor, geh n'găr, jêh ri aơ, geh n'găr neh ntu: Lĕ rngôch nting rgum tâm ntrŭp ndrel.$b$,true),
('bunong-vn','EZK',37,8,null,$b$Gâp uănh saơ, lĕ rngôch rse suan jêh ri mlay puăch lĕ tâm sĭr đah klơ nting nây; geh ntâu nkŭm khân păng, ƀiă lah mâu geh nsôr n'hâm ôh tâm trôm khân păng.$b$,false),
('bunong-vn','EZK',37,9,null,$b$Rnôk nây Yêhôva lah ma gâp pô aơ: Hơi kon bu nuyh, mbơh lor hom ma sial; mbơh lor hom jêh ri lah ma sial: Pô aơ Yêhôva lah: Hơi nau nsôr n'hâm; văch tât bơh sial puăn njônh nsôr n'hâm ta klơ lĕ rngôch bunuyh khĭt, gay ăn khân păng rêh.$b$,false),
('bunong-vn','EZK',37,10,null,$b$Pô ri gâp mbơh lor nâm bu Păng hŏ lah ma gâp, jêh ri nau nsôr n'hâm lăp tâm khân păng; khân păng dâk rêh, jêh ri dâk ma jâng khân păng, tâm rnglăp nsum jêng du phung ta han âk ngăn ngên.$b$,false),
('bunong-vn','EZK',37,11,null,$b$Păng lah ma gâp: “Hơi kon bunuyh, lĕ rngôch phung nting aơ, nây jêng nting phung Israel aơ, khân păng ngơi pô aơ: ‘Nting he lĕ rŭng jêh, nuih n'hâm kâp gân he lĕ roh, he lĕ bu ƀư rai jêh!’$b$,true),
('bunong-vn','EZK',37,12,null,$b$Pô ri mbơh lor hom jêh ri lah ma khân păng, ‘pô aơ nau Yêhôva Brah Ndu lah: Aơ gâp mra pơk môch khân may jêh ri ngluh khân may tă bơh môch, Hơi phung ƀon lan gâp; jêh ri gâp mra njŭn khân may sĭt rlet bri Israel.$b$,false),
('bunong-vn','EZK',37,13,null,$b$Jêh ri khân may mra gĭt gâp jêng Yêhôva, tơ lah gâp mra pơk môch-blang khân may, ƀư ăn khân may hao luh du tay tă bơh môch, Hơi phung ƀon lan gâp.$b$,true),
('bunong-vn','EZK',37,14,null,$b$Jêh ri gâp mra dơm Huêng Brah gâp tâm khân may jêh ri khân may mra rêh. Gâp mra njêng tay khân may tâm bri neh khân may nơm. Rnôk nây khân may mra gĭt gâp jêng Yêhôva, jêh ri gâp ƀư ăn tât ngăn nau nây, Yêhôva lah.”$b$,false),
('bunong-vn','EZK',37,15,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',37,16,null,$b$“Hơi kon bunuyh, sŏk hom du mlâm mâng jra, jêh ri chih ta klơ mâng nây, ‘Ăn ma phung Yuđa jêh ri phung kon sau Israel jêng băl ndrel păng.’ Jêh ri sŏk đŏng du mlâm mâng êng jêh ri chih ta klơ mâng pô aơ: Ăn ma Y-Yôsep, nây jêng mâng jra Êphraim, jêh ri bơh lĕ rngôch phung Israel jêng băl ndrel păng.$b$,false),
('bunong-vn','EZK',37,17,null,$b$Ăn hom mâng jra aơ ndrel mâng jra ri tâm rnglăp jêng nguay, ŭch ƀư jêng du mlâm mâng tâm ti may.$b$,false),
('bunong-vn','EZK',37,18,null,$b$Tơ lah phung ƀon lan may mra ôp may, Pô ri dăn may rblang nau tâm ntĭt aơ ma hên moh ntil nau nây?’$b$,false),
('bunong-vn','EZK',37,19,null,$b$Lah hom ma khân păng, ‘Pô aơ nau Yêhôva Brah Ndu lah: Aơ, gâp dăch sŏk mâng jra tă bơh phung Y-Yôsep, mâng nây tâm ti phung Êphraim jêh ri mpôl Israel ndrel ma păng; gâp mra tâm rnglăp mâng jra nây đah mâng jra phung Yuđa, jêh ri njêng khân păng du mlâm mâng dơm, ŭch ma khân păng lĕ bar dơi jêng nguay tâm ti gâp.’$b$,false),
('bunong-vn','EZK',37,20,null,$b$Tơ lah may djôt mâng may hŏ chih rplay sămƀŭt ta klơ; tâm rnglăp nguay tâm ti may tra năp măt khân păng,$b$,false),
('bunong-vn','EZK',37,21,null,$b$pô ri lah hom ma khân păng, ‘Pô aơ nau Yêhôva Brah Ndu lah: Aơ, gâp mra sŏk phung kon sau ƀon lan Israel tă bơh nklang mpôl băl bunuyh khân păng hŏ gŭ jêh, jêh ri gâp mra rgum khân păng tă bơh lam bri jêh ri njŭn khân păng sĭt ma bri êng ma khân păng.$b$,false),
('bunong-vn','EZK',37,22,null,$b$Gâp mra rnglăp khân păng jêng knŏng du mpôl băl tâm bri ta klơ yôk Israel. Jêh ri knŏng du huê hađăch mra chiă uănh khân păng lĕ rngôch. Khân păng mâu mra jêng bar mpôl băl, jêh ri mâu mra tâm pă bar bri đŏng ôh.$b$,true),
('bunong-vn','EZK',37,23,null,$b$Khân păng mâu mra ƀư đŏng nau ƀơ̆ ƀơch tă bơh rup brah khân păng, mâu lah tă bơh lĕ nau gâp tâm rmot, mâu lah tă bơh lĕ rngôch nau tih khân păng hŏ ƀư jêh. Gâp mra tâm rklaih khân păng tă bơh lĕ rngôch ntŭk gŭ khân păng hŏ ƀư tih. Gâp mra ƀư kloh khân păng, pô ri mơ khân păng mra ƀư phung ƀon lan gâp, gâp mra ƀư Brah Ndu khân păng.$b$,false),
('bunong-vn','EZK',37,24,null,$b$“Oh mon gâp jêng Y-Đavit ƀư hađăch chiă uănh khân păng. Lĕ rngôch khân păng mra geh knŏng du huê bunuyh chiăp; khân păng mra chuat tĭng nau gâp ntăm; khân păng mra djôt prăp nau vay gâp jêh ri ƀư tĭng nau vay gâp.$b$,true),
('bunong-vn','EZK',37,25,null,$b$Khân păng mra gŭ tâm bri gâp hŏ ăn ma oh mon gâp jêng Y-Yakôb, jêh ri jêng bri chô-yau khân păng hŏ gŭ. Khân păng, kon sau khân păng, jêh ri kon sau ma sau se khân păng mra gŭ ta nây tât ƀa ƀơ n'ho ro; oh mon gâp jêng Y-Đavit mra ƀư hađăch khân păng mro mrăng.$b$,false),
('bunong-vn','EZK',37,26,null,$b$Pô nây, gâp mra njêng đah khân păng du nau tâm rnglăp jêng kon me; nây mra jêng du nau tâm rnglăp n'ho ro ta nklang khân păng đah gâp. Gâp mra njêng khân păng jêh ri ƀư ăn bĭk rơ̆ . Gâp mra dơm jrô kloh ueh ta nklang khân păng ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','EZK',37,27,null,$b$Ntŭk ma gâp gŭ mra gŭ ndrel ta nklang khân păng; gâp mra ƀư Brah Ndu khân păng, khân păng mra ƀư ƀon lan gâp.$b$,false),
('bunong-vn','EZK',37,28,null,$b$Rnôk nây lĕ bri dak mra gĭt gâp jêng Yêhôva, nơm ƀư kloh Israel yor lah jrô kloh ueh gâp mra gŭ ta nklang khân păng ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','EZK',38,1,null,$b$Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','EZK',38,2,null,$b$“Hơi kon bunuyh, rle hom muh măt may mpeh ma Y-Gôk, tâm bri Magôk, kôranh ma phung Rôs, phung Mêsek, jêh ri phung Tubal, jêh ri mbơh lor tâm rdâng đah păng,$b$,false),
('bunong-vn','EZK',38,3,null,$b$jêh ri lah: ‘Pô aơ nau Yêhôva Brah Ndu lah: Aơ, gâp tâm rdâng ma may, Hơi Y-Gôk, kôranh ma phung Rôs, phung Mêsek, jêh ri phung Tubal;$b$,false),
('bunong-vn','EZK',38,4,null,$b$jêh ri gâp mra plĕch may, dơm nglĕ klĕ ta kang may, ăn may du luh bơh n'har bri may, may jêh ri lĕ rngôch phung ta han may, seh nđâp ma phung ta han ncho seh lĕ rngôch nsoh ao loih jêh ri rnglăp ƀư jêng du phung ta han âk ngăn, cheng âk khêl toyh khêl jê̆, jêh ri lĕ rngôch rnă đao dao da dê.$b$,false),
('bunong-vn','EZK',38,5,null,$b$Phung ta han Persơ, phung Kus, jêh ri phung Put gŭ ndrel khân păng, lĕ rngôch khân păng cheng khêl jêh ri ndô môk loih;$b$,false),
('bunong-vn','EZK',38,6,null,$b$nđâp phung Gômer jêh ri lĕ rngôch phung âk păng; phung Bet- Tôgarma tă bơh n'har bri dor ndrel ma lĕ rngôch phung mpôl âk păng-âk phung ƀon lan gŭ ndrel kơl an may.$b$,false),
('bunong-vn','EZK',38,7,null,$b$“Nkra hom jêh ri kâp ƀư hom, may jêh ri lĕ rngôch phung ƀon lan lĕ tâm rgum jêh ndrel ma may. Ăn may uănh hom bôk khân păng.$b$,true),
('bunong-vn','EZK',38,8,null,$b$Âk nar rlau, may mra sŏk dơn nau bu ntăm jêh ri dâk hăn; tâm rnôk nglĕ dŭt may mra hăn tâm lơh tâm du bri dak jêng bri hŏ dơi bu sâm rklaih jêh tă bơh đao tak jêh ri tâm rgum tay tă bơh ta nklang mpôl băl bunuyh; may mra hăn tât ta klơ yôk Israel, jêng ntŭk rngol lĕ roh rai bơh rnôk kăl e; ƀiă lah păng hŏ dơi bu njŭn sĭt tă bơh ta nklang phung mpôl băl bunuyh, jêh ri lĕ rngôch khân păng mra gŭ mpăn.$b$,false),
('bunong-vn','EZK',38,9,null,$b$May mra rduh ran pa năp, mra tât nâm bu phŭt chuănh, nâm bu ndâr tŭk nkâm lam bri, may, jêh ri phung ta han âk may, jêh ri âk ntil mpôl bunuyh ndrel ma may.$b$,true),
('bunong-vn','EZK',38,10,null,$b$“Pô aơ nau Yêhôva lah: Tâm lĕ rngôch nar nây, geh nau mĭn mra nsĭch tâm rngok may, may mra mĭn jêh ri nkra nau ƀư janh.$b$,true),
('bunong-vn','EZK',38,11,null,$b$May mra lah: Gâp mra hăn tât lơh bri dak geh ƀon mâu geh mpêr ôh; gâp mra hăn tât bơh phung ƀon lan gŭ mpăn đăp rmên lĕ rngôch ntŭk khân păng gŭ mâu geh mpêr ôh, mâu geh ôh rnăng mpông jêh ri mpông pêr.$b$,true),
('bunong-vn','EZK',38,12,null,$b$Gâp mra tâm lơh gay pit in jêh ri sŏk drăp ndơ, gay sŏk sĭt lơi ntŭk rngol nây aƀaơ lĕ geh bunuyh gŭ, jêh ri ŭch njŭn leo ƀon lan bu hŏ njŭn sĭt tă bơh ta nklang mpôl băl bunuyh lam bri, khân păng geh âk mpô mpa rong, jêh ri drăp ndơ gŭ ngao ta nklang neh ntu.”$b$,false),
('bunong-vn','EZK',38,13,null,$b$Phung Sêba jêh ri phung Dêdan, jêh ri phung tăch drăp tă bơh phung Tarsis jêh ri lĕ rngôch kon yau mŭr păng mra lah ma may, “Di lĕ may văch tât gay tŭn jot, may rgum jêh phung lĭng ta han âk may gay pit sŏk drăp ndơ, prăk mah leo nchuăn, gay veng lĕ mpô mpa rong jêh ri ndô ndơ, gay pit in âk râk ndô ndơ?”$b$,false),
('bunong-vn','EZK',38,14,null,$b$“Yor ri, Hơi kon bu nuyh, mbơh lor hom jêh ri lah ma Y-Gôk: ‘Pô aơ nau Yêhôva Brah Ndu lah: Ta nar phung ƀon lan gâp Israel, tơ lah gŭ ma nau mpăn, mâu may gĭt hĕ nau nây?$b$,true),
('bunong-vn','EZK',38,15,null,$b$Rnôk nây may mra văch tât tă bơh ntŭk may nơm, tă bơh ngai mpeh bri Dor, may, jêh ri âk phung ƀon lan ndrel may, lĕ rngôch ncho seh da dê, jêng du phung âk, du phung ta han janh ktang.$b$,false),
('bunong-vn','EZK',38,16,null,$b$Hơi Y-Gôk! May mra hăn tât lơh ƀon lan Israel gâp, nâm bu du ndâr tŭk nkâm lĕ bri. N'hêl nanê̆, tâm rnôk nglĕ dŭt, gâp mra njŭn khân may lơh bri gâp, gay ma phung mpôl băl bunuyh nti, uănh gĭt năl gâp, tơ lah gâp mra mpơl ăn nanê̆ nau kloh ueh gâp ta năp măt khân păng.$b$,true),
('bunong-vn','EZK',38,17,null,$b$“Pô aơ Yêhôva Brah Ndu lah: Kăl e ri gâp hŏ ngơi ma oh mon gâp, jêng phung mbơh lor Israel, tâm rnôk nây, âk năm rlau khân păng hŏ mbơh lor pô aơ gâp mra ăn may tât tâm rdâng đah phung ƀon lan gâp, nau nây mâu hĕ gâp ngơi ma may?$b$,true),
('bunong-vn','EZK',38,18,null,$b$Yêhôva Brah Ndu lah: Mra geh nau gâp ji nuih tâm nar nây, jêng nar Y-Gôk hăn lơh bri Israel, pô ri nau ji nuih gâp mra n'hôl duh klơ trôm muh gâp.$b$,true),
('bunong-vn','EZK',38,19,null,$b$Yor lah dôl gâp ntôn jêh ri gâp hao ji nuih gâp mbơh: N'hêl nanê̆, tâm nar nây mra geh nau n'găr neh ntu ktang ngăn tâm bri Israel.$b$,false),
('bunong-vn','EZK',38,20,null,$b$Ta năp măt gâp, phung ka tâm dak mƀŭt, phung sĭn och klơ trôk, phung mpô mpa bri, lĕ rngôch ndrŭng rvơng mpa vơr tâm neh, ma râm nsâr da dê. Phung yôk yang mra rlâm, phung yôk klêr ntang ntơm rlâm da dê, lĕ rngôch mpêr mra rlâm ta neh.$b$,false),
('bunong-vn','EZK',38,21,null,$b$Yêhôva Brah Ndu lah: Đao Gâp mra kuăl đao dao tât tâm dâng đah păng ta klơ lĕ rngôch yôk gâp. Ăp nơm mra tâm lơh ndrăng oh nâu khân păng nơm.$b$,false),
('bunong-vn','EZK',38,22,null,$b$Gâp mra phat dôih păng ma nau ji nkhĭt jêh ri ma nau pling mham. Gâp mra nkhŭt tơm mih toyh, glo dak pler, ŭnh jêh ri lŭ mô ŭnh nkhŭt ta klơ păng, ta klơ phung ta han âk păng, jêh ri phung ƀon lan hăn ndrel păng.$b$,false),
('bunong-vn','EZK',38,23,null,$b$Nây yơh gâp mra tâm mpơl nau toyh gâp jêh ri nau kloh ueh gâp, jêh ri tâm mpơl gâp nơm tra năp măt âk mpôl băl bu nuyh. Rnôk nây khân păng mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',39,1,null,$b$“Hơi kon bu nuyh, mbơh lor tâm rdâng hom đah Y-Gôk, jêh ri lah: ‘Pô aơ nau Yêhôva Brah Ndu lah: Aơ, gâp tâm rdâng ma may, Hơi Y-Gôk, kôranh phung Rôs, phung Mêsek, jêh ri phung Tubal;$b$,true),
('bunong-vn','EZK',39,2,null,$b$jêh ri gâp mra plĕch lơh rlơ̆ may. Gâp mra leo may hăn du luh tă bơh bri ngai mpeh bri Dor, jêh ri njŭn may hao rlet klơ yôk Israel.$b$,false),
('bunong-vn','EZK',39,3,null,$b$Gâp mra nkêh lơi na may ăn tŭp tă bơh ti pa chiau; jêh ri ăn tŭp lơi hăr may tă bơh ti pa ma.$b$,false),
('bunong-vn','EZK',39,4,null,$b$May mra cha lôt khĭt ta klơ phung yôk Israel, may jêh ri phung âk may jêh ri phung ƀon lan gŭ ndrel ma may; gâp jao may ma ăp ntil klang, grât jêh ri ma mpa bri sa hêk may.$b$,false),
('bunong-vn','EZK',39,5,null,$b$May mra chôt khĭt tâm mir; yor lah gâp hŏ ngơi jêh nau nây, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',39,6,null,$b$Gâp mra njuăl ŭnh mra bri Magôk jêh ri ma phung gŭ nau mpăn tâm kô mƀŭt; jêh ri khân păng mra gĭt gâp jêng Yêhôva.$b$,false),
('bunong-vn','EZK',39,7,null,$b$“Gâp mra ăn bu gĭt năl amoh kloh ueh gâp ta nklang ƀon lan Israel gâp, jêh ri gâp mâu dơi ăn bu ngơi djơh tât amoh kloh ueh gâp đŏng ôh. Lĕ ntil mpôl bunuyh mra gĭt gâp jêng Yêhôva, jêng Nơm Kloh ueh tâm bri Israel.$b$,true),
('bunong-vn','EZK',39,8,null,$b$Aơ, nau nây mra tât, jêh ri ƀư tât ngăn, Yêhôva Brah Ndu lah; nây jêng nar gâp hŏ ngơi jêh!$b$,false),
('bunong-vn','EZK',39,9,null,$b$“Rnôk nây phung gŭ tâm ăp ƀon bri Israel mra dâk hăn, jêh ri su ndơ tâm lơh khêl toyh jêh ri khêl jê̆, na jêh ri hăr, tak jêh ri jôih ri khân păng sĭnh ŭnh ndơ nây tâm pơh năm.$b$,true),
('bunong-vn','EZK',39,10,null,$b$Khân păng mâu mra joi long tâm mir, mâu chôk long tâm krŏng, sŏk ndơ tâm lơh prăp sĭnh ŭnh. Khân păng mra pit in phung hŏ pit in jêh ndô ndơ khân păng, Yêhôva Brah Ndu lah nau nây.$b$,false),
('bunong-vn','EZK',39,11,null,$b$“Tâm nar nây gâp mra ăn Y-Gôk du ntŭk tâm bri Israel prăp tâp bunuyh khĭt, tâm Rlŭng ma phung nsong dâng lơ, mpeh pa lơ dak mƀŭt; ntŭk bu tâp nây mra king lơi trong bu năch hăn nsong. Yor lah ta ntŭk nây bu mra tâp Y-Gôk jêh ri lĕ rngôch phung âk ndrel ma păng; bu mra ntơ ntŭk nây Rlŭng Haman-Gôk.$b$,true),
('bunong-vn','EZK',39,12,null,$b$Tâm pơh khay phung Israel mra tâp khân păng; gay ƀư ăn kloh tâm bri neh.$b$,false),
('bunong-vn','EZK',39,13,null,$b$Lĕ rngôch phung ƀon lan gŭ tâm n'gor bri mra tâp khân păng; jêh ri nar nây mra jêng du nar ăn khân păng kah gĭt yơh, gâp mra tâm mpơl nau chrêk rmah gâp; Yêhôva Brah Ndu lah nau nây.$b$,false),
('bunong-vn','EZK',39,14,null,$b$Khân păng ăn bunuyh hăn rgăn gay nhhol uănh bri jêh ri tâp bunuyh khĭt hôm e klen tâm neh gay ƀư ăn kloh; tât lôch pơh khay khân păng tĭng joi.$b$,true),
('bunong-vn','EZK',39,15,null,$b$Tơ lah phung hăn nhhol nây rgăn tâm n'gor bri saơ nting rŭng bu, păng bun du ntŭk jêh ri kep ntŭk ăn bu gĭt năl gay phung hăn tâp bunuyh khĭt leo tâp nting rŭng nây tâm Rlŭng Haman- Gôk.$b$,false),
('bunong-vn','EZK',39,16,null,$b$(Geh du rplay ƀon Hamôna gŭ ta nây tâm ban lĕ). Nây bu mra ƀư kloh bri neh nâm bu nây lĕ.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','EZK',39,17,null,$b$“Bi ma nay, Hơi kon bunuyh, pô aơ nau Yêhôva lah: Ngơi hom ma ăp ntil klang, grât jêh ri lĕ rngôch mpa bri, văch rgum hom, tă bơh lam ntŭk puăn njônh tât nhêt sa ƀư brah gâp nkra jêh ma khân may.’ Du nau nhêt sa toyh ta klơ yôk Israel, khân may mra sa puăch jêh ri nhêt mham.$b$,true),
('bunong-vn','EZK',39,18,null,$b$Khân may mra sa puăch phung janh ktang, jêh ri nhêt mham phung kôranh ta neh ntu, jêng nâm bu phung biăp nkuăng, biăp kok, be nkuăng, ndrôk nkuăng jêng mpô mpa lay tă bơh bri Basan.$b$,false),
('bunong-vn','EZK',39,19,null,$b$Khân may sa ngi tât hơm jêh ri nhêt mham kŏ nhŭl, ta nau nhêt sa ƀư brah gâp nkra jêh ăn khân may.$b$,false),
('bunong-vn','EZK',39,20,null,$b$Ta sưng sông gâp, khân may sa ăn hơm mlay puăch seh jêh ri mlay puăch phung janh ktang jêh ri ăp ntil phung ta han tâm lơh, Yêhôva Brah Ndu lah nau nây.$b$,true),
('bunong-vn','EZK',39,21,null,$b$“Gâp mra mpơl nau chrêk rmah gâp ăn ta nklang phung bri dak; lĕ rngôch ntil mpôl bunuyh mra saơ nau gâp phat dôih tât ngăn jêh, jêh ri ti gâp yơr jêh ta klơ khân păng.$b$,true),
('bunong-vn','EZK',39,22,null,$b$Ntơm bơh nar nây tât kăndơ̆ , phung Israel mra gĭt gâp jêng Yêhôva Brah Ndu$b$,false),
('bunong-vn','EZK',39,23,null,$b$Rnôk nây lĕ ntil mpôl bunuyh mra gĭt ma phung Israel hŏ leo hăn ƀư bu nă yor nau tih khân păng, yor lah khân păng hŏ ƀư rlăng ma gâp kŏ tât gâp pôn lơi muh măt gâp bơh khân păng; jêh ri jao khân păng chôt khĭt ma đao dao.$b$,false),
('bunong-vn','EZK',39,24,null,$b$Gâp hŏ ƀư ma khân păng tĭng nâm nau ƀơ̆ ƀơch khân păng jêh ri nau khân păng ƀư tih, jêh ri pôn lơi muh măt gâp tă bơh khân păng.$b$,false),
('bunong-vn','EZK',39,25,null,$b$“Yor nây, Yêhôva Brah Ndu lah pô aơ: Aƀaơ ri gâp mra mplơ̆ sĭt phung Y-Yakôp tă ƀư bu nă; jêh ri gâp mra yô̆ yach ma lĕ phung Israel, jêh ri yor amoh kloh ueh yơh dĭng gâp ntôn.$b$,true),
('bunong-vn','EZK',39,26,null,$b$Khân păng mra chuêl lĕ nau bêk prêng jêh ri geh nau tih tâm lĕ rngôch nau tih khân păng hŏ rlăng ma gâp, tơ lah khân păng mra gŭ mpăn tâm bri neh khân păng nơm, mâu geh ôh bunuyh hôm rvê klach.$b$,false),
('bunong-vn','EZK',39,27,null,$b$Tơ lah gâp lĕ njŭn khân păng sĭt tă bơh ta nklang phung ƀon lan êng jêh ri tâm rgum tay khân păng tă bơh bri phung rlăng khân păng; pô ri gâp mra mpơl nau kloh ueh gâp yor tă khân păng ta năp măt âk ntil mpôl bu nuyh.$b$,false),
('bunong-vn','EZK',39,28,null,$b$Khân păng mra gĭt gâp jêng Yêhôva Brah Ndu khân păng, nđâp tơ lah gâp hŏ mprơh khân păng jêng bu nă ta nklang phung bri dak êng, jêh ri gâp hŏ rgum tay khân păng sĭt tât ta bri dak khân păng nơm, mâu hôm dơi klen du huê bunuyh ôh hôm-e ta nây.$b$,false),
('bunong-vn','EZK',39,29,null,$b$Gâp mra mâu hôm pôn muh măt gâp tă bơh khân păng đŏng ôh, yor lah gâp mra nkhŭt Huêng Brah gâp ta Klơ phung Israel, Yêhôva Brah Ndu lah nau nây.$b$,true),
('bunong-vn','EZK',40,1,null,$b$Năm rơh bar jât ma prăm, rnôk hên jêng bu nă, ta bôk năm, năng jât khay nây, jêng năm jât ma puăn, tơ lah jêh bu sŏk ƀon toyh Yêrusalem, ăt tâm nar nây lĕ, ti Yêhôva dơm ta klơ gâp; jêh ri Păng leo gâp lăp tâm ƀon nây.$b$,true),
('bunong-vn','EZK',40,2,null,$b$Tâm lĕ rngôch nau tâm saơ bơh Brah Ndu, Păng leo gâp lăp bri Israel, jêh ri dơm gâp ta klơ du gôl yôk prêh ngăn, ta klơ yôk nây, mơ mpeh rđŭng, nâm bu geh ndâk du ƀon.$b$,false),
('bunong-vn','EZK',40,3,null,$b$Tơ lah Păng hŏ leo gâp lăp ta nây, gâp saơ du huê bu klâu săk jăn nâm bu kông, djôt rse ndrăn mhay jêh ri du mlâm mâng gay prăp veh; păng dâk ta trong lăp mpông pêr.$b$,true),
('bunong-vn','EZK',40,4,null,$b$Bu klâu nây lah ma gâp, “Hơi kon bunuyh, uănh hom, rkêng iăt hom jêh ri ăn nuih n'hâm gŭ mĭn ma nau gâp mra mpơl ma may; yor nây ăn may saơ lĕ ro, yor lah ri dĭng djôt leo may ta aơ. Pô ri lĕ rngôch may mra saơ da dê, nkoch hom lĕ nau may saơ ma phung Israel.”$b$,false),
('bunong-vn','EZK',40,5,null,$b$Aơ, geh mpêr jŭm pa dih nkual ngih brah, jêh ri mâng bu klâu nây djôt tâm ti prăp veh, jong hăt (cuđê), ăp hăt jong lơn du nđam. Pô ri păng veh nau mbâl mpêr, du bông mâng veh, jêh ri prêh du bông mâng lĕ.$b$,true),
('bunong-vn','EZK',40,6,null,$b$Jêh ta nây, păng hăn tât ta mpông pêr mpeh pa lơ, hao gung, jêh ri veh ndring mpông pêr, geh du bông mâng veh huy păng;$b$,false),
('bunong-vn','EZK',40,7,null,$b$jêh ri ăp jrô ta meng mpêr geh du bông mâng jong; jêh ri dĭ du bông mâng; jêh ri geh ntŭk hŏng vah vang ăp jrô meng mpêr, prăm hăt; jêh ri mbong ta mpông pêr êp ndring ta mpông pêr tâm trôm geh du bông mâng veh.$b$,false),
('bunong-vn','EZK',40,8,null,$b$Păng veh ndring mpông pêr, tâm trôm, du bông mâng.$b$,false),
('bunong-vn','EZK',40,9,null,$b$Jêh ri păng veh ndring mpông pêr, geh pham hăt; jêh ri ndor năp geh bar hăt; jêh ri ndring ta mpông pêr gŭ mpeh trôm.$b$,false),
('bunong-vn','EZK',40,10,null,$b$Geh pe mlâm jrô, ăp pŭng mpông pêr pa lơ; lĕ pe mlâm nây tâm ban da dê; jêh ri ndor năp tâm ban lĕ.$b$,false),
('bunong-vn','EZK',40,11,null,$b$Jêh ri păng veh huy ntŭk lăp mpông pêr, geh jât hăt; jêh ri huy trong mpông pêr geh jât ma pe hăt.$b$,false),
('bunong-vn','EZK',40,12,null,$b$Geh chăng du rgăn pa năp jrô ta pŭng, ăp jrô lĕ bar đah du hăt du jrô; jêh ri ăp jrô du pŭng prao hăt, pŭng đah ri prao hăt lĕ:$b$,false),
('bunong-vn','EZK',40,13,null,$b$Jêh ri păng veh mpông pêr tă pa kơi du mlâm jrô ta pŭng tât mơ pa kơi jrô đah ri, huy geh bar jât ma prăm hăt ntơm bơh du mlâm mpông tât ma mpông êng.$b$,false),
('bunong-vn','EZK',40,14,null,$b$Păng geh veh lĕ ndring bar jât hăt; jêh ri jŭm ndring ta trong mpông pêr geh nkual nhuang$b$,false),
('bunong-vn','EZK',40,15,null,$b$Ntơm bơh pa năp mpông pêr ta ntŭk lăp tât ta bôl dŭt ndring mpeh tâm trôm mpông pêr geh prăm jât hăt.$b$,false),
('bunong-vn','EZK',40,16,null,$b$Trong mpông pêr geh mpông jê̆ jŭm nây, mpeh tâm trôm ta ndor năp khân păng tâm jrô ta pŭng, jêh ri tâm ban lĕ ndring geh mpông bloh jê̆ jŭm nây mpeh tâm trôm, jêh ri rgŏ năp khân păng geh rup play đung.$b$,false),
('bunong-vn','EZK',40,17,null,$b$Jêh ta nây, păng leo gâp tât ta nkual pa dih; aơ, ntŭk nây geh âk jrô, jêh ri geh mbon trong bu krĭp lŭ jŭm nkual nây; ta klơ mbon krip lŭ nây geh pe jât mlâm jrô.$b$,true),
('bunong-vn','EZK',40,18,null,$b$Mbon krĭp lŭ ta puăn pŭng mpông pêr, jêh ri nau jong păng tâm ban mpông pêr nây jêng mbon krĭp lŭ tâm dâng lơn.$b$,true),
('bunong-vn','EZK',40,19,null,$b$Păng veh rkăng ntơm bơh mpeh pa năp mpông pêr tâm dâng lơn tât ma pa năp nkual pa dih, geh du rhiăng hăt mpeh pa lơ jêh ri mpeh dor tâm ban da dê.$b$,false),
('bunong-vn','EZK',40,20,null,$b$Păng hăn pa năp mpeh dor, jêh ri ta aơ, păng veh jong jêh ri rkăng mpông pêr dor tâm nkual pa dih.$b$,true),
('bunong-vn','EZK',40,21,null,$b$Pe mlâm jrô lĕ bar đah pŭng, lĕ ndơ ndor năp jêh ri ndring păng tâm ban ma mpông pêr sa ơm; veh jong păng geh prăm jât hăt, jêh ri huy păng bar jât ma prăm hăt.$b$,false),
('bunong-vn','EZK',40,22,null,$b$Lĕ mpông bloh jê̆, ndring păng jêh ri rup play đung păng jêng tâm ban nguay dơm đah mpông pêr pa lơ; geh pơh rplay gung hao klơ ntŭk nây, jêh ri ndring păng trôm mpeh pa năp nây.$b$,false),
('bunong-vn','EZK',40,23,null,$b$Mpeh mpông pêr dor jêh ri mpông pêr mpeh pa lơ geh mpông pêr tâm trôm nkual; Jêh ri păng veh ntơm bơh mpông pêr aơ tât ma mpông pêr ri, geh du rhiăng hăt.$b$,true),
('bunong-vn','EZK',40,24,null,$b$Jêh ri păng leo gâp mpeh rđŭng aơ, ta nây geh mpông mpêr mpeh rđŭng; păng veh ndor năp păng jêh ri ndring păng; ăt tâm ban nguay dơm đah ndor năp mpông pêr êng.$b$,true),
('bunong-vn','EZK',40,25,null,$b$Ta nây geh mpông bloh jŭm mpông pêr jêh ri tâm ndring păng, tâm ban mpông bloh tâm mpông pêr êng ri lĕ; veh jong păng prăm jât hăt, jêh ri huy păng bar jât ma prăm hăt.$b$,false),
('bunong-vn','EZK',40,26,null,$b$Geh pơh rplay gung hao ta ntŭk nây, jêh ri pa năp ăp gung nây geh du mlâm ndring pa dih; păng geh rup play đung ta ndor năp, du mlâm rup ăp bar đah nây.$b$,false),
('bunong-vn','EZK',40,27,null,$b$Jêh ri du mlâm mpông pêr mpeh rđŭng tâm nkual ta trôm; jêh ri păng veh ntơm bơh mpông pêr aơ tât mpeh rđŭng, geh du rhiăng hăt.$b$,false),
('bunong-vn','EZK',40,28,null,$b$Pô ri, păng leo gâp lăp tâm nkual tâm trôm uănh mpông pêr mpeh rđŭng; păng veh mpông pêr mpeh rđŭng, tâm ban nguay dơm.$b$,false),
('bunong-vn','EZK',40,29,null,$b$Lĕ jrô ta pŭng, ndor năp păng, jêh ri ndring păng tâm ban ma ndơ êng, jêh ri geh mpông bloh jŭm păng jêh ri tâm ndring păng tâm ban lĕ. Pa dih păng geh prăm jât hăt, jêh ri rkăng bar jât ma prăm hăt.$b$,false),
('bunong-vn','EZK',40,30,null,$b$Geh ndring jŭm nây, bar jât ma prăm hăt jong jêh ri prăm hăt huy.$b$,false),
('bunong-vn','EZK',40,31,null,$b$Ndring păng rle mpeh nkual pa dih, jêh ri ta ndor năp păng geh rup play đung; jêh ri geh pham mlâm gung hao klơ.$b$,true),
('bunong-vn','EZK',40,32,null,$b$Jêh ta nây, păng leo gâp tât nkual tâm trôm mpeh pŭng pa lơ; jêh ri păng veh mpông pêr; mpông pêr nây tâm ban ma mpông pêr êng lĕ.$b$,true),
('bunong-vn','EZK',40,33,null,$b$Jrô ta pŭng păng, ndor năp păng, jêh ri ndring păng tâm ban ma ndơ êng lĕ; jêh ri geh mpông bloh jŭm păng jêh ri tâm ndring păng. Veh jong păng geh prăm jât hăt jêh ri huy păng bar jât ma prăm hăt.$b$,false),
('bunong-vn','EZK',40,34,null,$b$Ndring păng rle mpeh ma nkual pa dih, jêh ri ta ndor năp geh rup tơm play đung, du mlâm, geh lĕ bar đah; jêh ri gung hao geh pham kơn.$b$,false),
('bunong-vn','EZK',40,35,null,$b$Jêh ri păng leo gâp tât mpông pêr dor; jêh ri păng veh mpông pêr nây, tâm ban nguay dơm.$b$,true),
('bunong-vn','EZK',40,36,null,$b$Lĕ jrô ta pŭng păng, ndor năp păng, jêh ri ndring păng tâm ban ma ndơ êng ri lĕ; jêh ri păng geh mpông bloh jŭm păng; veh jong geh prăm jât hăt, huy păng geh bar jât ma prăm hăt.$b$,false),
('bunong-vn','EZK',40,37,null,$b$Ndring păng rle mpeh nkual pa dih jêh ri ndor năp păng geh rup play đung, jêh ri geh gung hao pham kơn.$b$,false),
('bunong-vn','EZK',40,38,null,$b$Geh du mlâm jrô ndrel ma mpông êp tâm ndring mpông pêr ta ntŭk bu rao ndơ nhhơr gŭch.$b$,true),
('bunong-vn','EZK',40,39,null,$b$Tâm ndring mpông pêr geh bar mlâm sưng mpeh bar đah pŭng, ta ntŭk nây bu nkhĭt ndơ nhhơr gŭch jêh ri ndơ nhhơr chuai yor rlau nau vay, jêh ri ndơ nhhơr chuai nau tih.$b$,false),
('bunong-vn','EZK',40,40,null,$b$Mpeh pa dih ndring, ta ntŭk hao rlet mpông pêr mpeh dor, geh bar mlâm sưng; mpeh ndring pŭng đah ri, geh bar mlâm sưng tâm ban lĕ.$b$,false),
('bunong-vn','EZK',40,41,null,$b$Pô nây, geh puăn mlâm sưng ta meng mpông pêr pa dih aơ, jêh ri geh puăn mlâm sưng ta meng mpông pêr ta trôm, lĕ rngôch geh pham mlâm sưng; ta klơ sưng nây bu nkhĭt ndơ nhhơr ƀư brah.$b$,false),
('bunong-vn','EZK',40,42,null,$b$Geh đŏng puăn mlâm sưng bu trah lŭ prăp ma ndơ nhhơr gŭch, njok du hăt n'gul, rkăng du hăt n'gul đŏng, jêh ri prêh du hăt. Bu ăn ta klơ nây ndơ dŏng nkhĭt ndơ nhhơr gŭch jêh ri lĕ ndơ nhhơr êng đŏng.$b$,false),
('bunong-vn','EZK',40,43,null,$b$Geh nglĕ jong mpang ti bu kât jŭm puăn pŭng mpir tâm trôm; puăch nhhơr bu dơm klơ sưng.$b$,false),
('bunong-vn','EZK',40,44,null,$b$Mpeh pa dih mpông pêr ta trôm, geh bar jrô gay ăn phung mprơ tâm nkual ta trôm, du jrô ta meng mpông pêr dor rle năp leo rđŭng du jrô êng đŏng ta meng mpông pêr rđŭng rle năp mpeh dor.$b$,true),
('bunong-vn','EZK',40,45,null,$b$Bunuyh nây lah ma gâp, “Geh jrô rle năp mpeh rđŭng prăp ma phung kôranh ƀư brah mât uănh ngih brah.$b$,false),
('bunong-vn','EZK',40,46,null,$b$Jrô rle năp mpeh dor prăp ma phung kôranh ƀư brah mât uănh nơng ƀư brah. Nây jêng kon sau Y-Sadôk, phung nây jêng phung noi deh kon sau Y-Lêvi, êng khân păng dơi văch dăch Yêhôva gay pah kan ma Păng.$b$,false),
('bunong-vn','EZK',40,47,null,$b$Pô nây, păng veh tâm nkual, geh du rhiăng hăt jong (njok) jêh ri du rhiăng hăt rkăng (dĭ) puăn blon; jêh ri nơng gŭ pa năp ngih brah.$b$,false),
('bunong-vn','EZK',40,48,null,$b$Jêh ta nây păng leo gâp ta ndring ngih brah jêh ri veh ndor năp ndring, prăm hăt đah aơ, prăm hăt đah ri; jêh ri dĭ mpir ta meng mpông pêr geh pe hăt đah aơ, jêh ri pe hăt đah ri.$b$,true),
('bunong-vn','EZK',40,49,null,$b$Veh jong ndring geh bar jât hăt, jêh ri jât ma nguay hăt dĭ; geh gung hao ta ntŭk nây, jêh ri geh meh ta meng ndor năp lĕ bar đah, đah aơ du n'gâng, đah ri du n'gâng.$b$,false),
('bunong-vn','EZK',41,1,null,$b$Pô ri, păng leo gâp tât tâm trôm ngih brah, tât ta nhuang, păng veh ăp lĕ meh ta nây. Ăp meh geh prao hăt dĭ mpeh đah aơ, jêh ri prao hăt mpeh đah ri ăp pŭng păng.$b$,true),
('bunong-vn','EZK',41,2,null,$b$Huy mpông lăp geh jât hăt: Prăm hăt đah aơ, prăm hăt đah ri mpir ta meng lĕ bar pŭng ntŭk mpông lăp; jêh ri păng veh jong: Jrô nhuang geh puăn jât hăt; jêh ri dĭ: Bar jât hăt.$b$,false),
('bunong-vn','EZK',41,3,null,$b$Jêh ri păng lăp jrô ta trôm veh ndor năp ntŭk mpông lăp: Geh bar hăt; jêh ri prêh mpông: Prao hăt; dĭ mpông: Pơh hăt.$b$,false),
('bunong-vn','EZK',41,4,null,$b$Păng veh ta trôm dŭt, jong bar jât hăt, dĭ bar jât hăt, jêh ri păng lah ma gâp: “Aơ jêng Ntŭk Kloh Ueh Lơn.”$b$,false),
('bunong-vn','EZK',41,5,null,$b$Jêh ri păng veh mpir ngih brah, geh prăm hăt mbâl; jêh ri huy jrô kêng pŭng nây geh puăn hăt văr jŭm ngih brah.$b$,true),
('bunong-vn','EZK',41,6,null,$b$Jrô ta pŭng geh pe tăp, lĕ nây, tâm du tăp geh pe jât jrô; jrô nây tâm rđĭl đah mpir jŭm ngih, lĕ rngôch jrô ta klơ n'gân đah nây ro mâu hôm nchrong ta mpir ngih ôh.$b$,false),
('bunong-vn','EZK',41,7,null,$b$Ngih bu thoi lơ prêh lơ huy, yor lah mpir jŭm nây lơ prêh lơ huy. Bu hăn tă tâm dâng tât du tăp gâl klơ veh du tăp gâl ta nklang.$b$,false),
('bunong-vn','EZK',41,8,null,$b$Tâm ban lĕ gâp saơ ngih brah geh prêh du mbon ndăch jŭm, mbon jrô kêng pŭng bu veh geh du bông mâng veh, nâm bu ntĭt prao hăt mpang ti (prao cuđê toyh).$b$,false),
('bunong-vn','EZK',41,9,null,$b$Mbâl mpir pa dih trôm jrô ta pŭng geh prăm hăt; jêh ri ntŭk gâl mpir nây mbon păng ndop đah mbon ngih mpeh ta pŭng ngih nây.$b$,false),
('bunong-vn','EZK',41,10,null,$b$Rong hŏng vah vang jrô ta pŭng ngih jêh ri lĕ jrô êng huy geh bar jât hăt văr jŭm ngih brah.$b$,false),
('bunong-vn','EZK',41,11,null,$b$Mpông tâm jrô ta pŭng pơk ta gâl hôm rmeh, du mlâm mpông bloh mpeh dor, jêh ri mpông bloh êng mpeh rđŭng; huy gâl ntŭk hôm e rmeh nây geh prăm hăt văr jŭm.$b$,true),
('bunong-vn','EZK',41,12,null,$b$Ngih rle năp đah nkual ngih brah mpeh mơ pŭng pa dâng, huy pơh jât hăt; mpir nchueng jŭm ngih nây mbâl prăm hăt, jong du rsen hăt (sĭn jât).$b$,true),
('bunong-vn','EZK',41,13,null,$b$Pô ri păng veh ngih brah, jong du rhiăng hăt; jêh ri nkual hŏng, ngih, jêh ri mpir păng, geh du rhiăng hăt jong,$b$,false),
('bunong-vn','EZK',41,14,null,$b$tâm ban lĕ huy rkăng pa năp ngih brah mpeh pa lơ jêh ri nkual (nhuang) geh du rhiăng hăt.$b$,false),
('bunong-vn','EZK',41,15,null,$b$Jêh ta nây, păng veh jong ngih pa năp nkual (neh jâng gung) ta ntŭk pa kơi, jêh ri mpir ngih-thoi ta ntŭk lĕ bar đah geh du rhiăng hăt. Jrô ndring nhuang ngih brah jêh ri jrô tâm trôm jêh ri ndring pa dih,$b$,true),
('bunong-vn','EZK',41,16,null,$b$bu ndop tơm si văr jŭm lĕ pe mlâm jrô jêh ri mpông bloh geh ndor năp tâm trôm. Ngih brah bu ndop ma si văr jŭm, ntơm bơh tât mpông bloh bu nkŭm mpông bloh$b$,false),
('bunong-vn','EZK',41,17,null,$b$tât ta ntŭk klơ mpông, tât jrô tâm trôm, jêh ri jrô pa dih veh da dê.$b$,false),
('bunong-vn','EZK',41,18,null,$b$Bu kach nsêr rup chêrubim jêh ri tơm play đung, du mlâm tơm play đung rđah ta plăng bar chêrubim; ăp chêrubim geh bar muh măt;$b$,false),
('bunong-vn','EZK',41,19,null,$b$du mlâm muh măt bu rle mpeh đah aơ rlet ma rup tơm play đung, du mlâm muh măt rup yau mŭr kon bu rle mpeh đah ri rtet ma rup tơm play đung êng. Bu kach rup nây lam jŭm ngih brah.$b$,false),
('bunong-vn','EZK',41,20,null,$b$Ntơm bơh neh tât ta klơ mpông bu kach ta mpir rup chêrubim jêh ri rup tơm play đung.$b$,false),
('bunong-vn','EZK',41,21,null,$b$Mbong mpông jrô nhuang jêng puăn blon; jêh ri pa năp jrô kloh ueh geh ndơ rup tâm ban da dê nâm bu rup pa năp ngih brah lĕ.$b$,true),
('bunong-vn','EZK',41,22,null,$b$Nơng ƀư brah ri ma tơm si, prêh pe hăt, njok bar hăt, rkăng bar hăt, jêh ri ndap, njônh, mpir păng bu ƀư ma tơm si. Păng lah ma gâp, “Aơ jêng sưng gŭ ta năp Yêhôva”.$b$,false),
('bunong-vn','EZK',41,23,null,$b$Jrô nhuang jêh ri jrô kloh ueh geh bar mlâm mpông nsum;$b$,false),
('bunong-vn','EZK',41,24,null,$b$du mlâm mpông geh bar năng mpông ntĭl (nchăng); mpông aơ bar blah mpông ri geh bar blah mpông lĕ.$b$,false),
('bunong-vn','EZK',41,25,null,$b$Geh rup chêrubim jêh ri rup tơm play đung kach nsêr ta mpông ngih brah, ta mpir tâm ban nây lĕ. Ta klơ ndring, mpeh pa dih, geh gre bu ƀư ma tơm si.$b$,false),
('bunong-vn','EZK',41,26,null,$b$Tâm ban lĕ ăt geh ndor năp mpông bloh, jêh ri rup tơm play đung đah aơ jêh ri đah ri, ntŭk puăn pŭng ndring pa dih, jrô kêng pŭng mpir jêh ri ta mpông.$b$,true),
('bunong-vn','EZK',42,1,null,$b$Jêh ri păng leo gâp lăp tâm trôm nkual pa dih, mpeh dor, jêh ri leo gâp lăp tâm du jrô rle năp mpeh nkual ngih brah, jêh ri ngih mpeh dor.$b$,true),
('bunong-vn','EZK',42,2,null,$b$Tra pa năp jêng ntŭk geh mpông lăp mpeh dor, lĕ jrô nây jong geh du rhiăng hăt, dĭ (rkăng) prăm jât hăt.$b$,false),
('bunong-vn','EZK',42,3,null,$b$Lĕ rngôch jrô tâm tra năp (rle năp), du nting jong bar jât hăt, tâm trôm nkual; ta ntŭk nkual mbon bu krĭp lŭ pa dih, ta nây geh jrô tâm dăp jrô aơ đah jrô ri tâm lĕ pe dăp nây.$b$,false),
('bunong-vn','EZK',42,4,null,$b$Mpeh pa năp lĕ jrô nây geh trong huy bar jât hăt, mpeh tâm trôm geh du mlâm trong huy du hăt; lĕ rngôch mpông jrô rle năp mpeh dor.$b$,false),
('bunong-vn','EZK',42,5,null,$b$Lĕ jrô klơ huêt lơn jrô tâm dâng jêh ri jrô ta nklang, yor lah jrô jê̆ sŏk ntŭk âk lơn lĕ dĭng lĕ jrô klơ.$b$,false),
('bunong-vn','EZK',42,6,null,$b$Yor lah geh pe dăp, ƀiă lah mâu geh meh ôh nâm bu meh tâm nkual pa dih; pô ri lĕ rngôch jrô klơ jêh ri lĕ jrô ta nklang huêt lơn jrô tâm dâng.$b$,false),
('bunong-vn','EZK',42,7,null,$b$Mpir pa dih njok tĭng jrô leo mpeh mơ nkual pa dih, pa năp lĕ jrô nây, geh prăm jât hăt jong.$b$,false),
('bunong-vn','EZK',42,8,null,$b$Yor lah nau jong tâm lĕ jrô nkual pa dih jêng prăm jât hăt, bi ma, mpeh pa năp ngih brah geh du rhiăng hăt.$b$,false),
('bunong-vn','EZK',42,9,null,$b$Mpeh tâm dâng lĕ jrô nây, mơ pa lơ, geh du mlâm mpông lăp ăn ma lĕ rngôch bunuyh tă pa dih nkual văch tât.$b$,false),
('bunong-vn','EZK',42,10,null,$b$Tâm ban lĕ mpeh pa lơ ta ntŭk njok n'gŏ rŏ mpir, geh âk jrô mpeh ma nkual jêh ri mpeh ma ngih;$b$,true),
('bunong-vn','EZK',42,11,null,$b$geh trong nsong pa năp lĕ jrô nây, tâm ban mpeh pa năp jrô mpeh dor; lĕ rngôch jrô nây jong jêh ri dĭ tâm ban, trong luh trong lăp rup tâm ban da dê.$b$,false),
('bunong-vn','EZK',42,12,null,$b$Lĕ rngôch jrô mpeh rđŭng nâm bu nây lĕ. Ntŭk trong lăp, pa năp mpir tâm tra mpeh pa lơ, geh du mlâm mpông, bu lăp ta nây.$b$,true),
('bunong-vn','EZK',42,13,null,$b$Rnôk nây păng lah ma gâp: “Lĕ rngôch jrô mpeh dor jêh ri lĕ jrô mpeh rđŭng, mpeh nkual jêng jrô kloh ueh, jêng ntŭk phung kôranh ƀư brah hăn dăch Yêhôva mra sa ndơ nhhơr kloh ueh lơn ndơ nhhơr rnih muy, ndơ nhhơr chuai tih. Yor rlau nau vay jêh ri chuai nau tih; yor lah ntŭk nây jêng kloh ueh.$b$,true),
('bunong-vn','EZK',42,14,null,$b$Tơ lah phung kôranh ƀư brah hŏ lăp jêh ta ntŭk kloh ueh nây, khân păng mâu dơi luh du tă bơh nây lăp tâm nkual pa dih ôh kŏ tât khân păng doh lĕ ao khân păng nsoh dôl pah kan, yor lah bok ao aơ jêng kloh ueh. Ăn khân păng nsoh bok ao êng ê lor ma khân păng hăn dăch ntŭk prăp ma phung ƀon lan.”$b$,false),
('bunong-vn','EZK',42,15,null,$b$Tơ lah lĕ jêh păng hŏ veh mpeh tâm trôm ngih brah, păng leo gâp luh ta mpông pa lơ, jêh nây veh rvang jŭm ngih brah.$b$,true),
('bunong-vn','EZK',42,16,null,$b$Păng veh ta pŭng pa lơ ma mâng veh, geh du rhiăng bông mâng.$b$,true),
('bunong-vn','EZK',42,17,null,$b$Păng veh mpeh dor ma mâng veh, geh du rhiăng bông mâng.$b$,false),
('bunong-vn','EZK',42,18,null,$b$Păng veh mpeh rđŭng ma mâng veh, geh du rhiăng bông mâng.$b$,true),
('bunong-vn','EZK',42,19,null,$b$Păng plơ̆ tay mpeh pa dâng gay veh, geh du rhiăng bông mâng.$b$,false),
('bunong-vn','EZK',42,20,null,$b$Păng veh ntŭk nây lĕ puăn pŭng. Geh mpir văr jŭm ntŭk nây, geh prăm hăt jong jêh ri prăm rhiăng hăt rkăng. Mpir aơ gay tâm pă rnglah ntŭk kloh ueh ma đah ntŭk ƀon lan.$b$,true),
('bunong-vn','EZK',43,1,null,$b$Pa kơi ta nây păng leo gâp lăp mpông pêr pa lơ.$b$,true),
('bunong-vn','EZK',43,2,null,$b$Aơ, gâp saơ nau chrêk ma lơp bơh Brah Ndu Israel tă bơh lơ văch tât. Nteh bâr Păng nâm bu nteh n'gôr dak toyh, jêh ri tâm neh nchrat ang yor nau chrêk ma lơp Păng.$b$,false),
('bunong-vn','EZK',43,3,null,$b$Nau tâm saơ gâp saơ rnôk nây, tâm ban đah nau tâm saơ hŏ mpơl tơ lah păng văch ƀư rai ƀon Yêrusalem. Nây jêng nau tâm saơ tâm ban đah nau gâp hŏ tâm saơ ta kơh dak krong Kêbar, jêh ri gâp chŭn muh măt chon mon tâm neh.$b$,false),
('bunong-vn','EZK',43,4,null,$b$Chrêk ma lơp Brah Ndu lăp tâm ngih ta mpông pêr mpeh pa lơ.$b$,false),
('bunong-vn','EZK',43,5,null,$b$Brah Huêng chông gâp leo klơ jêh ri njŭn gâp lăp tâm trôm; jêh ri, aơ, nau chrêk ma lơp Yêhôva bêng ngih brah.$b$,false),
('bunong-vn','EZK',43,6,null,$b$Gâp tăng geh bunuyh ngơi ma gâp tă tâm trôm ngih brah; geh du huê bunuyh dâk êp gâp,$b$,true),
('bunong-vn','EZK',43,7,null,$b$jêh ri lah ma gâp: “Hơi kon bu nuyh, aơ yơh jêng ntŭk dơm sưng hađăch gâp, jêng ntŭk ăn mpang jâng gâp, ta aơ gâp mra gŭ ƀa ƀơ n'ho ro ta nklang phung kon sau ƀon lan Israel. Ngih Israel mâu mra ƀư ƀơ̆ đŏng ôh amoh kloh ueh gâp, khân păng, mâu lah hađăch khân păng, mâu dơi ƀư nau dŏng tĭr khân păng, jêh ri yor ma săk jăn khĭt phung hađăch khân păng ta klơ yôk prêh;$b$,false),
('bunong-vn','EZK',43,8,null,$b$yor khân păng hŏ ndâk ntŭk lăp ngih khân păng, dăch ntŭk lăp ngih gâp; jêh ri ndâk n'gâng mpông khân păng, dăch n'gâng mpông gâp; kŏ tât vah vang gâp jêh ri khân păng knŏng geh mpir dơm. Nây yơh nau khân păng hŏ ƀư ƀơ̆ ƀơch amoh kloh ueh gâp yor nây gâp tâm rmot ma khân păng hŏ ƀư tih jêh; pô ri dĭng gâp ƀư rai khân păng tâm nau gâp ji nuih.$b$,false),
('bunong-vn','EZK',43,9,null,$b$Aƀaơ ri ăn khân păng cha lơi lĕ nau khân păng mbah rup brah, jêh ri ăn ngai đah săk jăn khĭt phung hađăch khân păng; ri mơ gâp mra gŭ ta nklang khân păng ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','EZK',43,10,null,$b$“Bi may, Hơi kon bu nuyh, rblang hom ăn ma phung Israel gĭt, mâng ngih brah he nây jêng; jêh ri rup bu chih ma păng, gay ma khân păng prêng yor nau tih khân păng.$b$,true),
('bunong-vn','EZK',43,11,null,$b$Tơ lah khân păng prêng tâm lĕ rngôch nau khân păng ƀư, may nhhiơ rup bu chih ngih nây ma khân păng, mbor kan păng, trong lăp, mpông luh, lĕ rngôch rup geh tâm ngih nây, lĕ rngôch nau ntăm, rup păng; jêh ri ăn lĕ rngôch phung Israel gĭt nau vay tâm ngih brah; jêh ri chih nau nây ta năp măt khân păng, gay ma khân păng djôt prăp jêh ri ƀư tĭng nâm nau vay jêh ri nau ntăm.$b$,false),
('bunong-vn','EZK',43,12,null,$b$Aơ yơh jêng nau vay ngih brah: Lĕ lam bri neh ntu yor păng ta klơ yôk mra jêng ntŭk kloh ueh. Nây, jêng nau vay ma ngih brah.$b$,false),
('bunong-vn','EZK',43,13,null,$b$“Aơ jêng nau veh nơng đah hăt (hăt nây jêng du hăt, mpang ti): Mbon păng prêh du hăt, jêh ri rkăng du hăt, geh ndor năp jŭm nây prêh du nđam; Nây jêng nau jong nơng.$b$,true),
('bunong-vn','EZK',43,14,null,$b$Ntơm bơh mbon tâm neh tât ma ndor năp tâm dâng geh bar hăt, huy du hăt. Jêh ri ntơm bơh ndor năp jê̆ tât năp toyh geh puăn hăt, huy du hăt,$b$,true),
('bunong-vn','EZK',43,15,null,$b$Ntŭk dơm ŭnh ta nơng geh puăn hăt; jêh ri ntơm bơh ntŭk ăn ta nơng tât rlet klơ, geh puăn mlâm nke.$b$,false),
('bunong-vn','EZK',43,16,null,$b$Ntŭk ăn ŭnh ta nơng jêng puăn blon, jât ma bar hăt njok jêh ri jât ma bar hăt rkăng.$b$,true),
('bunong-vn','EZK',43,17,null,$b$Năp tâm ban lĕ jêng puăn blon đŏng, jât ma puăn hăt njok jêh ri jât ma puăn hăt rkăng, geh năp văr jŭm geh n'gul hăt huy; jêh ri mbon păng du hăt văr jŭm. Trong hao ta nơng bu mra dơm mpeh pa lơ.”$b$,true),
('bunong-vn','EZK',43,18,null,$b$Jêh ri păng lah ma gâp: “Hơi kon bu nuyh, pô aơ Yêhôva Brah Ndu lah: Aơ jêng nau ntăm ma nơng: Ta nar bu ndâk păng gay nhhơr ndơ nhhơr gŭch ta klơ păng jêh ri ŭch tŏ mham ta păng,$b$,true),
('bunong-vn','EZK',43,19,null,$b$may mra ăn du mlâm ndrôk nkuăng prăp ma ndơ nhhơr yor nau tih ma phung kôranh ƀư brah Lêvi tâm băl mpôl Y-Sadôk, phung văch dăch ŭch pah kan ma gâp, Yêhôva$b$,false),
('bunong-vn','EZK',43,20,null,$b$Ăn may sŏk ƀa ƀă mham păng jêh ri mhĭng ta puăn mlâm nke nơng, jêh ri ta puăn njônh ndor năp, jêh ri ta ndor năp văr jŭm; pô ri khân may mra ƀư kloh nơng jêh ri ƀư nau ăn kloh nau tih păng.$b$,false),
('bunong-vn','EZK',43,21,null,$b$Tâm ban lĕ, ăn may sŏk ndrôk nkuăng prăp ma ndơ nhhơr yor nau tih, jêh ri bu mra gŭch păng ta ntŭk tâm nal jêh dăch ngih brah, pa dih ntŭk kloh ueh.$b$,false),
('bunong-vn','EZK',43,22,null,$b$Ta nar năng bar, ăn may nhhơr du mlâm be nkuăng mâu geh sôt prăp ma ndơ nhhơr yor nau tih; jêh ri bu mra ăn kloh nơng tâm ban bu ƀư kloh jêh ma ndrôk nkuăng.$b$,true),
('bunong-vn','EZK',43,23,null,$b$Tơ lah khân may hŏ ƀư jêh nau ƀư kloh, ăn khân may nhhơr hom du mlâm ndrôk nkuăng mâu geh sôt, jêh ri mlâm biăp nkuăng mâu geh sôt, sŏk tă tâm phung păng.$b$,false),
('bunong-vn','EZK',43,24,null,$b$May djôt leo bar mlâm mpa nây dăch pa năp măt Yêhôva, jêh ri phung kôranh ƀư brah mra suy boh ta klơ ndơ nhhơr nây jêh ri nhhơr ndơ nây jêng ndơ nhhơr gŭch ma Yêhôva.$b$,false),
('bunong-vn','EZK',43,25,null,$b$Dôl tâm pơh nar ăn khân may prăp ăn ăp nar du mlâm be prăp ndơ nhhơr yor nau tih; tâm ban lĕ ăn khân may prăp du mlâm ndrôk nkuăng jêh ri du mlâm biăp nkuăng mâu geh sôt, sŏk tă tâm phung.$b$,false),
('bunong-vn','EZK',43,26,null,$b$Dôl pơh nar ăn khân păng ƀư nau ƀư kloh nau tih ăn ma nơng, ƀư kloh păng, jêh ri prăp êng păng ăn kloh.$b$,false),
('bunong-vn','EZK',43,27,null,$b$Tơ lah khân păng ƀư lôch lĕ nar aơ, pô ri ntơm bơh nar năng pham rlet pa kơi taơ, tơ lah phung Kôranh ƀư brah mra nhhơr ndơ nhhơr gŭch jêh ri ndơ khân may nhhơr nau đăp mpăn; jêh ri gâp mra vơt khân may, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',44,1,null,$b$Pô nây păng leo gâp tât mpông pêr pa dih jrô kloh ueh, mpông pêr nây mpeh pa lơ. Mpông lĕ bu ntĭl jêh.$b$,true),
('bunong-vn','EZK',44,2,null,$b$Yêhôva lah ma gâp: “Mpông pêr aơ bu mra ntĭl mro, mâu pơk đŏng ôh. Mâu geh nuyh dơi lăp mpông pêr aơ, yor lah Yêhôva Brah Ndu Israel hŏ lăp tă bơh mpông; pô ri mpông nây mra ntĭl lơi.$b$,true),
('bunong-vn','EZK',44,3,null,$b$Knŏng nơm jêng kôranh, mơ dơi tât gŭ ta mpông pêr nây gay sa piăng let ta năp Yêhôva. Păng mra lăp ta trong ndring mpông pêr, jêh ri luh trong nây lĕ.”$b$,false),
('bunong-vn','EZK',44,4,null,$b$Jêh ri păng leo gâp ta mpông pêr mpeh dor lơ tât pa năp ngih brah. Gâp uănh treng, jêh ri aơ, nau chrêk ma lơp Yêhôva nchrat bêng ngih brah Yêhôva; pô ri gâp chŭn muh măt ta neh.$b$,true),
('bunong-vn','EZK',44,5,null,$b$Rnôk nây Yêhôva lah ma gâp pô aơ: “Hơi kon bu nuyh, sek uănh ăn nanê̆ ngăn; uănh ma măt jêh ri iăt ma tôr lĕ rngôch ntil nau gâp mra ngơi ma may, ma lĕ rngôch nau ntăm kan ngih brah Yêhôva, jêh ri lĕ rngôch nau vay păng. Njrăng hom mêt uănh nanê̆ ntŭk lăp ngih brah, jêh ri lĕ dĭng lĕ trong luh tă bơh jrô kloh ueh.$b$,false),
('bunong-vn','EZK',44,6,null,$b$Ăn may lah hom ma phung vay tâm rdâng, lah ma ngih Israel, ‘Pô aơ nau Yêhôva Brah Ndu lah: Hơi ngih Israel, lĕ rngôch nau gâp tâm rmot khân may hŏ ƀư lĕ găp jêh.$b$,true),
('bunong-vn','EZK',44,7,null,$b$Khân may hŏ leo jêh phung bu năch, jêng phung mâu koh ntâu tâm nuih n'hâm khân păng nđâp tâm săk jăn khân păng, ăn hăn lăp tâm ntŭk jrô kloh ueh gâp gay ƀư ƀơ̆ ƀơch ngih brah gâp, tơ lah khân may nhhơr piăng let, ngi jêh ri mham ndơ sông sa gâp; pô nây khân may hŏ ƀư tih rlau nau tâm rnglăp yor tă lĕ rngôch nau gâp tâm rmot jêh ma khân may.$b$,true),
('bunong-vn','EZK',44,8,null,$b$Jêh ri khân may mâu mât njrăng ôh ndơ kloh ueh gâp; ƀiă lah khân may hŏ njêng phung bu năch dơm ăn mât mray ndơ kloh ueh tâm ntŭk jrô kloh ueh gâp.$b$,false),
('bunong-vn','EZK',44,9,null,$b$Yor nây, pô aơ nau Yêhôva Brah Ndu lah: Lơi ta ăn du huê bu năch lăp tâm ntŭk jrô kloh ueh gâp, phung mâu koh ôh ntâu tâm nuih n'hâm jêh ri tâm săk jăn, tâm lĕ rngôch phung bu năch gŭ ta nklang phung ƀon lan Israel.$b$,false),
('bunong-vn','EZK',44,10,null,$b$“Ƀiă lah phung Lêvi nkhah du ngai jêh tă bơh gâp, gay ŭch tĭng ndô̆ rup brah khân păng tơ lah phung Israel hŏ vĭ nkhah du jêh, mra anh nau tih khân păng nơm.$b$,true),
('bunong-vn','EZK',44,11,null,$b$Nđâp lah pô nây kđôi lĕ, khân păng dơi pah kan tâm ntŭk kloh gâp, chiă uănh mpông ngih brah, jêh ri pah kan tâm ngih brah; mra ƀư yor ƀon lan dơi nkhĭt lĕ ndơ nhhơr gŭch jêh ri ndơ ƀư brah êng đŏng, mra dâk pa năp phung ƀon lan pah kan păng.$b$,false),
('bunong-vn','EZK',44,12,null,$b$Yor lah khân păng hŏ pah kan jêh ma khân ô băl ta năp rup brah khân păng, jêh ri jêng nau tih ƀư chêh prah ngih Israel; yor nau nây gâp hŏ yơr ti ƀư ma khân păng, pô ri khân păng mra anh nau tih khân păng nơm, Yêhôva Brah Ndu lah nau nây.$b$,false),
('bunong-vn','EZK',44,13,null,$b$Khân păng mâu mra văch dăch gâp ôh gay ƀư lôch nau kan kôranh ƀư brah gŭ ta năp măt gâp. Mâu lĕ dơi văch dăch ôh ma moh ndơ kloh ueh gâp, mâu lah ndơ nhhơr kloh ueh lơn; ƀiă lah mra anh nau bêk prêng jêh ri lĕ rngôch nau mhĭk gâp rmot khân păng hŏ ƀư jêh.$b$,false),
('bunong-vn','EZK',44,14,null,$b$Ƀiă lah ăt gâp mra njêng dơm khân păng mât uănh ngih brah, gay ƀư ăn jêh lĕ kan pah jêh ri lĕ rngôch nau kan khlay tâm ngih brah.$b$,false),
('bunong-vn','EZK',44,15,null,$b$“Văch nâm bu phung Lêvi jêng kôranh ƀư brah, phung kon sau Y-Sadôk; phung chiă uănh kan jrô kloh ueh gâp tơ lah phung ƀon lan Israel vĭ nkhah du ngai đah gâp, lĕ rngôch phung nây mra văch dăch gâp gay pah kan ma gâp; jêh ri khân păng mra dâk ta năp gâp gay nhhơr ngi jêh ri mham, Yêhôva Brah Ndu$b$,true),
('bunong-vn','EZK',44,16,null,$b$Nây jêng phung mra dơi lăp tâm jrô kloh ueh gâp, văch dăch sưng gâp gay chiă uănh ndơ kan gâp.$b$,false),
('bunong-vn','EZK',44,17,null,$b$Tơ lah khân păng lăp ta mpông pêr tâm nkual ta trôm, ăn khân păng nsoh bok ao mhay; khân păng mâu dơi nsoh bok ao rsau biăp ôh dôl khân păng pah kan ta mpông pêr tâm nkual ta trôm jêh ri trôm ngih brah.$b$,true),
('bunong-vn','EZK',44,18,null,$b$Khân păng mpân bôk khân păng ma bok mhay, jêh ri nsoh kho gleh ma bok mhay;$b$,false),
('bunong-vn','EZK',44,19,null,$b$Ƀiă lah lah khân păng hăn rlet ma nkual pa dih, jêng ntŭk phung ƀon lan dâk, ăn khân păng doh lơi ao jâr khân păng nsoh dôl pah kan, jêh ri ăn ao nây tâm jrô kloh, jêh ri nsoh ao êng, gay mâu ăn sŏk ôh ao păng ƀư ăn ƀon lan jêng kloh.$b$,false),
('bunong-vn','EZK',44,20,null,$b$Khân păng mâu poih plưn bôk, jêh ri mâu om sŏk (sŏk) jong, ƀiă lah mra kreh sŏk gleh oi đê̆.$b$,false),
('bunong-vn','EZK',44,21,null,$b$Mâu dơi geh ôh du huê kôranh ƀư brah dơi nhêt ndrănh tơ lah păng lăp tâm nkual ta trôm.$b$,false),
('bunong-vn','EZK',44,22,null,$b$Khân păng mâu dơi sŏk ur đah bu ur ndrô mâu lah bu ur bu lĕ lơi jêh; ƀiă lah dơi sŏk bu ur druh tang-tat bơh mpôl noi phung Israel, mâu lah bu ur ndrô ur du huê kôranh ƀư brah.$b$,false),
('bunong-vn','EZK',44,23,null,$b$Khân păng mra nti ma phung ƀon lan gĭt rnglah moh ndơ jêng kloh ueh ma đah moh ntil ndơ jêng mhĭk kơt kănđai; ăn ma phung ƀon lan gâp blau sek uănh nâm nau ƀơ̆ ƀơch jêh ri nau kloh ueh.$b$,false),
('bunong-vn','EZK',44,24,null,$b$Tơ lah geh nau tât, khân păng jêng kôranh phat dôih, jêh ri phat dôih tĭng nâm nau vay gâp. Khân păng mra djôt prăp nau vay gâp, jêh ri nau gâp ntăm tâm lĕ rngôch nar năng gâp tâm nal jêh, jêh ri khân păng mra kah gĭt yơk ma nar Saƀat gâp dơi jêng kloh ngăn.$b$,false),
('bunong-vn','EZK',44,25,null,$b$Mâu geh ôh du huê bunuyh tâm phung khân păng dơi prot dăch săk bunuyh khĭt, klach lah ƀư ƀơ̆ khân păng nơm; ƀiă lah khân păng dơi ƀư ƀơ̆ khân păng nơm yor mbơ̆ , mê̆, kon bu ur mâu lah kon bu klâu khân păng; yor oh nâu mâu lah oh nur ê-hŏ geh sai.$b$,true),
('bunong-vn','EZK',44,26,null,$b$Tơ lah jêh nau ƀư kloh păng, ăn păng kâp tâm pơh nar jêh ri mơ păng mra jêng kloh.$b$,false),
('bunong-vn','EZK',44,27,null,$b$Ta nar kôranh ƀư brah lăp tâm ntŭk kloh tâm nkual ta trôm gay pah kan ta nây, ăn păng nhhơr ndơ nhhơr yor nau tih păng nơm, Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',44,28,null,$b$“Bi ma drăp ndơn gay prăp ăn ma khân păng, gâp yơh jêng drăp ma khân păng ndơn. Lơi ta khân may ăn ôh neh mir ma khân păng tâm bri Israel; gâp jêng neh mir ma khân păng.$b$,true),
('bunong-vn','EZK',44,29,null,$b$Khân păng sa ndơ nhhơr piăng let rnih, ndơ nhhơr chuai nau tih jêh ri ndơ nhhơr chuai tih yor rlau nau vay; jêh ri lĕ rngôch ndơ bu prăp ma Brah Ndu tâm n'gor bri Israel, mra jêng ndơ khân păng.$b$,false),
('bunong-vn','EZK',44,30,null,$b$Jêh ri ndơ ueh lơn play bôk rah tă bơh lĕ ntil ndơ, jêh ri lĕ rngôch ndơ nhhơr ăp ntil tă bơh ndơ khân may nhhơr mra jêng ndơ phung kôranh ƀư brah. Khân may mra ăn đŏng ma phung kôranh ƀư brah, play bôk rah piăng rlet rnih khân may, gay ma nau ueh uĭn dơi gŭ tâm ngih khân may.$b$,true),
('bunong-vn','EZK',44,31,null,$b$Phung kôranh ƀư brah mâu dơi sa ôh du ntil ndơ khĭt măp mâu lah mpa êng kăp sa hêk, nkhêp lah sĭm och mâu lah mpô mpa.$b$,true),
('bunong-vn','EZK',45,1,null,$b$Tơ lah khân may tâm pă neh jêng nau ndơn drăp ma nau tâm nchroh, ăn khân may prăp êng ma Yêhôva du kô̆ neh jêng kô̆ kloh ueh, bar rmưn prăm rbăn hăt jong jêh ri bar rmưn hăt dĭ rkăng; kô̆ nây jêng kloh glom lĕ nây.$b$,true),
('bunong-vn','EZK',45,2,null,$b$Tă bơh kô̆ neh aơ ăn khân may prăp ma ntŭk kloh du kô̆ neh njok rkăng tâm ban prăm rhiăng hăt (cuđê) nđâp ma kô̆ neh prăm rhiăng hăt văr jŭm jêng ntŭk neh nsoih.$b$,false),
('bunong-vn','EZK',45,3,null,$b$Tâm kô̆ neh kloh ueh nây ăn khân may veh du kô̆ bar rmưn prăm rbăn hăt jong jêh ri du rmưn hăt dĭ rkăng, kô̆ nây mra prăp ma ntŭk kloh ueh; jêng Ntŭk Kloh Ueh Lơn.$b$,false),
('bunong-vn','EZK',45,4,null,$b$Kô̆ neh nây mra jêng kô̆ kloh ueh tâm bri nây prăp ma phung Kôranh ƀư brah, jêng phung pah kan tâm ntŭk kloh, jêh ri văch dăch Yêhôva gay ƀư kan khân păng nơm pah. Nây mra jêng ntŭk gay ndâk ngih ma khân păng, jêh ri jêng du ntŭk kloh prăp ma jrô kloh ueh.$b$,true),
('bunong-vn','EZK',45,5,null,$b$Kô̆ neh êng bar rmưn prăm rbăn hăt (cuđê) jong jêh ri du rmưn hăt dĭ rkăng mra prăp ma phung Lêvi phung pah kan ngih brah, jêng drăp ndơn ăn khân păng ƀư ƀon ma khân păng gŭ.$b$,false),
('bunong-vn','EZK',45,6,null,$b$“Ta meng kô̆ neh khân may prăp ăn jêng ntŭk kloh ueh, ăn khân may ƀư n'har kô̆ neh prăp ma ƀon toyh prăm rbăn hăt (cuđê) dĭ rkăng jêh ri bar rbăn prăm rhiăng hăt jong njok; kô̆ neh nây mra prăp ma lĕ rngôch phung Israel.$b$,false),
('bunong-vn','EZK',45,7,null,$b$“Ăn khân may prăp ma nơm jêng hađăch ta meng lĕ bar đah kô̆ neh kloh ueh jêh ri neh prăp ma ƀon toyh, ta meng kô̆ neh kloh ueh jêh ri neh prăp ƀon toyh mpeh mơ pa dâng jêh ri mpeh mơ pa lơ, tâm ban jong du kô̆ prăp du mpôl băl, ntơm bơh n'har pa dâng tât ma n'har pa lơ bri.$b$,true),
('bunong-vn','EZK',45,8,null,$b$Neh nây jêng drăp păng ndơn tâm bri Israel. Jêh ri phung hađăch gâp mâu mra tŭn jot phung ƀon lan gâp ôh; ƀiă lah khân păng mra ăn phung mpôl Israel geh neh tĭng nâm mpôl băl khân păng êng êng.$b$,false),
('bunong-vn','EZK',45,9,null,$b$“Pô aơ nau Yêhôva Brah Ndu lah: Găp jêh, Hơi phung hađăch Israel! Cha lơi hom nau ƀư djơh jêh ri tŭn jot, jêh ri ƀư nau di jêh ri nau sŏng; rlu hom nau mprơh ƀon lan gâp tă bơh bri dak, Yêhôva Brah Ndu lah nau nây.$b$,true),
('bunong-vn','EZK',45,10,null,$b$Ăn khân may geh njing veh nau sŏng; du êpha nau sŏng; du ƀat nau sŏng.$b$,false),
('bunong-vn','EZK',45,11,null,$b$Êpha jêh ri ƀat mra veh njing tâm ban; du bat geh du kô̆ tâm jât hômer, jêh ri du êpha geh du kô̆ jât hômer; hômer mra jêng njing bu veh.$b$,false),
('bunong-vn','EZK',45,12,null,$b$Rnoh sêkel mra jêng bar jât gêra; bar jât sêkel tâm rƀŭn đah bar jât ma prăm sêkel rƀŭn đah jât ma prăm sêkel mra jêng du mina.$b$,false),
('bunong-vn','EZK',45,13,null,$b$“Aơ jêng ndơ khân may mra nhhơr: Du kô̆ tâm prao êpha tă bơh ăp hômer ba răch (ba ƀlê), jêh ri du kô̆ tâm prao tă bơh êpha tă bơh ăp hômer ba ôrgơ,$b$,true),
('bunong-vn','EZK',45,14,null,$b$jêh ri njing rnhueh dak play ôlivơ du kô̆ tâm jât bat ăp kôr (kôr mâm bu hômer geh jât bat);$b$,false),
('bunong-vn','EZK',45,15,null,$b$jêh ri du mlâm biăp tă bơh ndrêch geh bar rhiăng mlâm tâm phung Israel. Aơ jêng ndơ nhhơr piăng let rnih, ndơ nhhơr gŭch, jêh ri ndơ nhhơr ma nau đăp mpăn, gay ƀư ăn kloh nau tih khân păng, Yêhôva Brah Ndu$b$,false),
('bunong-vn','EZK',45,16,null,$b$Lĕ rngôch phung ƀon lan tâm n'gor bri nây mra ăn ndơ nhhơr aơ ma nơm jêng hađăch tâm n'gor Israel.$b$,false),
('bunong-vn','EZK',45,17,null,$b$Ƀiă lah hađăch djôt prăp ndrăp nkra lĕ ndơ nhhơr gŭch, ndơ nhhơr piăng let rnih, jêh ri ndơ nhhơr nhêt dôl năng pôch khay, năng luh khay mhe, nar Saƀat, lĕ rngôch nar năng tâm nal ma phung Israel; Hađăch mra nhhơr ndơ nhhơr chuai nau tih, ndơ nhhơr piăng let rnih, ndơ nhhơr gŭch, jêh ri ndơ ăn nau đăp mpăn, gay ƀư nau ăn kloh nau tih ma phung Israel.$b$,false),
('bunong-vn','EZK',45,18,null,$b$“Pô aơ nau Yêhôva Brah Ndu lah: Nar năng nguay khay nguay, ăn may sŏk hom du mlâm ndrôk nkuăng ndăm mâu sôt-bliu, jêh ri ƀư kloh ntŭk jrô kloh ueh.$b$,true),
('bunong-vn','EZK',45,19,null,$b$Kôranh ƀư brah mra sŏk ƀa ƀă mham tă bơh ndơ nhhơr chuai nau tih jêh ri mhĭng mham nây ta jrŏng mpông ngih brah ta puăn njônh ndơ năp nơng, jêh ri jrŏng mpông pêr tâm nkual ta trôm.$b$,false),
('bunong-vn','EZK',45,20,null,$b$Khân may mra ƀư tâm ban nây lĕ ta nar năng pơh khay nây, ăn ma phung hŏ ƀư tih jêh yor nau vĭ mâu lah mâu gĭt rbăng ôh; pô ri khân may mra ƀư nau ƀư kloh ma ngih brah.$b$,false),
('bunong-vn','EZK',45,21,null,$b$“Nar năng jât ma puăn khay tal nguay, ăn khân may kah gĭt yơk nar năng Nau Găn, jêh ri ăn khân may sa piăng let mâu pot ndrui dôl pơh nar.$b$,true),
('bunong-vn','EZK',45,22,null,$b$Ta nar nây nơm jêng hađăch mra nhhơr yor păng nơm jêh ri yor lĕ rngôch phung ƀon lan tâm n'gor du mlâm ndrôk nkuăng ndăm jêng ndơ nhhơr chuai nau tih.$b$,false),
('bunong-vn','EZK',45,23,null,$b$Dôl lĕ lôch nar năng pơh, hađăch mra nhhơr ndơ nhhơr gŭch ma Yêhôva pơh mlâm ndrôk nkuăng ndăm jêh ri pơh mlâm biăp nkuăng mâu sôt-bliu ôh, tâm ăp nar dôl pơh năng nây; jêh ri du mlâm be nkuăng ăp nar prăp ma ndơ nhhơr chuai nau tih.$b$,false),
('bunong-vn','EZK',45,24,null,$b$Hađăch ntop đŏng tâm nây tâm ăp ndrôk nkuăng du êpha, ăp mlâm biăp nkuăng du êpha, ăp êpha du hin dak play ôlivơ, păng nhhơr jêng ndơ nhhơr piăng let rnih.$b$,false),
('bunong-vn','EZK',45,25,null,$b$Tâm nar bŏng khay pơh, năng jât ma prăm khay nây jêh ri dôl pơh nar năng nây, hađăch mra prăp tâm ban lĕ jêng nau nhhơr ndơ nhhơr chuai nau tih, ndơ nhhơr gŭch, jêh ri ndơ nhhơr piăng let rnih, jêh ri ma dak play ôlivơ.$b$,false),
('bunong-vn','EZK',46,1,null,$b$“Pô aơ nau Yêhôva Brah Ndu lah: Mpông pêr tâm nkual ta trôm mpeh pa lơ păng mra ntĭl dôl prao nar pah kah; ƀiă lah ta nar Saƀat jêh ri tâm nar ntơm luh khay mhe bu mra pơk păng.$b$,true),
('bunong-vn','EZK',46,2,null,$b$Hađăch mra lăp ta ndring mpông pêr pa dih, jêh ri dâk dăch jrŏng mpông pêr dôl phung kôranh ƀư brah mra nhhơr ndơ nhhơr gŭch, jêh ri ndơ nhhơr ăn nau đăp mpăn. Hađăch yơk mbah ta mbong mpông pêr, jêh ri păng du luh, jêh ri mpông pêr mâu ăn bu ntĭl ôh tât măng.$b$,true),
('bunong-vn','EZK',46,3,null,$b$Phung ƀon lan mra yơk mbah ta ntŭk lăp mpông pêr nây ta năp Yêhôva tâm nar Saƀat jêh ri tâm nar ntơm luh khay mhe.$b$,false),
('bunong-vn','EZK',46,4,null,$b$Ndơ nhhơr gŭch ndơ hađăch nhhơr ma Yêhôva ta nar Saƀat mra geh prao mlâm biăp kon jêh ri du mlâm biăp nkuăng mâu geh sôt-bliu ôh;$b$,false),
('bunong-vn','EZK',46,5,null,$b$jêh ri ndơ nhhơr piăng let rnih ndrel ma biăp nkuăng mra geh du êpha, jêh ri ndơ nhhơr piăng let rnih; bi ma biăp kon moh ndơ hađăch nhhơr tĭng nâm dơi, jêh ri du êpha ntop du hin dak play ôlivơ.$b$,false),
('bunong-vn','EZK',46,6,null,$b$Ta nar ntơm luh khay mhe păng mra nhhơr du mlâm ndrôk nkuăng ndăm, prao mlâm biăp kon, jêh ri du mlâm biăp nkuăng, lĕ rngôch ndơ nây mâu geh sôt-bliu (khap men);$b$,false),
('bunong-vn','EZK',46,7,null,$b$bi ma ndơ nhhơr piăng let rnih, păng mra nhhơr du êpha ndrel ma ndrôk nkuăng; jêh ri du êpha ndrel ma biăp nkuăng, jêh ri bi ma kon biăp mâu lĭn moh ndơ hađăch nhhơr tĭng nâm dơi, jêh ri du êpha pot du hin dak play ôlivơ.$b$,false),
('bunong-vn','EZK',46,8,null,$b$Tơ lah hađăch lăp, păng mra lăp ta ndring mpông pêr, jêh ri păng luh trong nây lĕ.$b$,false),
('bunong-vn','EZK',46,9,null,$b$“Tơ lah phung ƀon lan tâm n'gor bri văch ta năp Yêhôva tâm nar nal năng jêh, mbu nơm lăp ta mpông pêr mpeh dor gay yơk mbah mra luh ta mpông pêr mpeh rđŭng; jêh ri mbu nơm lăp mpông pêr mpeh rđŭng mra luh ta mpông pêr dor; mâu geh du huê nuyh dơi plơ̆ sĭt ôh ta mpông pêr păng lăp sa ơm. Ăp nơm mra luh sŏng tra năp păng nơm.$b$,true),
('bunong-vn','EZK',46,10,null,$b$Tơ lah khân păng lăp, hađăch jêh ri phung ƀon lan lăp ndrel du tơ̆ ; jêh ri mbu moh luh pô ri hađăch mra luh lĕ.$b$,false),
('bunong-vn','EZK',46,11,null,$b$“Ma nau năng jêh ri yan tâm nal jêh ndơ nhhơr piăng let rnih mra jêng du êpha ndrel ndrôk nkuăng, du êpha ndrel ma biăp nkuăng, jêh ri bi ma nau biăp kon pô ri moh ndơ hađăch ŭch nhhơr tĭng nâm dơi, ăp du êpha pot du hin dak play ôlivơ.$b$,true),
('bunong-vn','EZK',46,12,null,$b$Tơ lah hađăch nhhơr ndơ ma Yêhôva ndơ nhhơr tĭng ŭch, ndơ nhhơr gŭch mâu lah ndơ nhhơr ăn nau đăp mpăn, pô ri mra pơk ma păng mpông pêr mpeh pa lơ; jêh ri păng mra nhhơr ndơ nhhơr gŭch jêh ri ndơ nhhơr ăn nau đăp mpăn nâm bu păng ƀư ta nar Saƀat. Jêh nây mơ păng mra luh, tơ lah jêh păng luh bu mra ntĭl mpông pêr.$b$,true),
('bunong-vn','EZK',46,13,null,$b$“Ăp nar păng nhhơr ma Yêhôva du mlâm biăp kon bêng năm, mâu sôt-bliu (khap men) ăp ôi ơm păng nhhơr ndơ nây.$b$,true),
('bunong-vn','EZK',46,14,null,$b$Ăp ôi ơm ăn păng nhhơr ndrel biăp kon du kô̆ tâm prao êpha ndrel ma du kô̆ tâm pe hin dak play ôlivơ gay pot li rnih, ƀư ndơ nhhơr piăng let rnih. Ndơ nhhơr piăng let rnih ma Yêhôva ăp ôi tĭng nau vay ntăm nhhơr ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','EZK',46,15,null,$b$Pô ri bu mra nhhơr biăp kon, ndơ nhhơr piăng let rnih, jêh ri dak play ôlivơ prăp nhhơr ndơ nhhơr gŭch mro mrăng ăp nar ơm ôi.$b$,false),
('bunong-vn','EZK',46,16,null,$b$“Pô aơ nau Yêhôva Brah Ndu lah: Tơ lah du huê hađăch ăn drăp ndơ ma du huê tâm phung kon bu klâu păng ndơn drăp pô ri ndơ nây jêng drăp ma phung kon sau păng; nây jêng drăp ma khân ô băl ndơn.$b$,true),
('bunong-vn','EZK',46,17,null,$b$Ƀiă lah tơ lah du huê hađăch ăn du ntil drăp ndơ păng geh ma du huê tâm phung gŭ nglăp săk (mâu lah oh mon) păng, ndơ nây mra jêng ndơ bunuyh nglăp săk (oh mon) ma păng kŏ tât ma năm nau jêng kon me. Rnôk nây ndơ nây mra mplơ̆ sĭt ma hađăch nơm; knŏng phung kon bu klâu păng dơi ndơn drăp hađăch nây.$b$,true),
('bunong-vn','EZK',46,18,null,$b$Hađăch mâu sŏk du kô̆ ôh drăp ndơ tă bơh phung ƀon lan, mprơh khân ô băl tă bơh neh mir khân ô băl; hađăch mra sŏk drăp ndơ êng păng nơm ri mơ dơi ăn phung kon bu klâu păng ndơn drăp; gay ma mâu geh du huê tâm phung ƀon lan gâp mra roh drăp khân păng ndơn.”$b$,false),
('bunong-vn','EZK',46,19,null,$b$Jêh ta nây, păng leo gâp tĭng trong lăp ta meng mpông pêr, tât ma mbor ta dor; lăp tâm jrô kloh ueh ma phung kôranh ƀư brah, jêh ri ta aơ, gâp saơ geh du ntŭk bôl dŭt mpeh pa dâng jrô nây.$b$,true),
('bunong-vn','EZK',46,20,null,$b$Păng lah ma gâp, “Aơ jêng ntŭk phung kôranh ƀư brah mra gâm ndơ nhhơr chuai nau tih jêh ri chuai tih rlau nau vay, jêh ri n'hôl ndơ nhhơr piăng let rnih, gay ma khân păng mâu djôt leo ôh ndơ nây tâm ntŭk nkual pa dih; gay ăn phung ƀon lan jêng kloh.”$b$,false),
('bunong-vn','EZK',46,21,null,$b$Pô ri păng leo gâp hăn tât nkual pa dih, jêh ri leo gâp tât puăn njônh nkual; ta aơ, ăp njônh nkual geh du nkuĭl.$b$,true),
('bunong-vn','EZK',46,22,null,$b$Tâm puăn njônh nkual geh nkual jê̆, puăn jât hăt njok jêh ri pe jât hăt rkăng; lĕ puăn nkual jê̆ nây tâm ban da dê.$b$,false),
('bunong-vn','EZK',46,23,null,$b$Tâm trôm văr jŭm lĕ puăn nkual jê̆ geh du mbor lŭ, geh ŭnh năk tâm dâng mbor lŭ văr jŭm.$b$,false),
('bunong-vn','EZK',46,24,null,$b$Jêh ri păng lah ma gâp, “Aơ jêng ngih n'gon ma phung pah kan tâm ngih brah mra gâm ndơ ƀư brah ma phung ƀon lan.”$b$,false),
('bunong-vn','EZK',47,1,null,$b$Jêh ta nây, păng leo gâp hăn đŏng rlet ma mpông pêr ngih brah; jêh ri aơ, geh dak luh tă bơh tâm dâng mbong ngih brah hoch rlet pa lơ (yor lah ngih brah rle năp leo pa lơ), jêh ri dak hoch njŭr tă bơh tâm dâng pŭng pa ma mbong ngih brah, mpeh rđŭng pa dâng nơng.$b$,true),
('bunong-vn','EZK',47,2,null,$b$Jêh ri păng leo gâp luh mpông pêr ta dor, jêh ri leo gâp ndăch pa dih mpâr ƀon tât ta mpông pêr pa dih, mpông pêr nây rle năp leo pa lơ; jêh ri dak luh tă mpeh pa ma.$b$,false),
('bunong-vn','EZK',47,3,null,$b$Păng hăn rlet pa lơ ta ti djôt du njăr rse jêh ri veh du rbăn hăt, jêh ri leo gâp rgăn dak; dak nây jru dah seng jâng (rmăng iăr).$b$,true),
('bunong-vn','EZK',47,4,null,$b$Păng veh đŏng du rbăn hăt, jêh ri gâp rgăn dak; dak nây jru dah kômâk. Păng veh đŏng du rbăn hăt, jêh ri leo gâp rgăn dak; dak nây jru dah bŭt.$b$,true),
('bunong-vn','EZK',47,5,null,$b$Păng veh đŏng du rbăn hăt, jêh ri dak nây jêng dak krong gâp mâu dơi rgăn ôh, yor lah dak lĕ hao jêh; jêng jru dơi re, du n'hong dak krong bu mâu dơi rgăn ôh.$b$,false),
('bunong-vn','EZK',47,6,null,$b$Jêh ri păng lah ma gâp, “Hơi kon bu nuyh, may lĕ saơ jêh hĕ ndơ aơ?” Jêh ri păng leo gâp plơ̆ sĭt tĭng rŏ kơh dak krong.$b$,false),
('bunong-vn','EZK',47,7,null,$b$Tơ lah tât jêh ta nây, ta aơ, mpeh đah aơ jêh ri mpeh kơh đah ri dak krong geh âk ngăn tơm si.$b$,false),
('bunong-vn','EZK',47,8,null,$b$Păng lah ma gâp, “Dak aơ hoch rlet mpeh bri lơ jêh ri hoch njŭr bri neh lâng; jêh ri tơ lah dak nây lăp tâm dak mƀŭt ƀơ̆ ƀơch, dak nây rgâl jêng rsang.$b$,false),
('bunong-vn','EZK',47,9,null,$b$Ăp ntŭk dak krong hoch lĕ rngôch ndơ blau mpât mra rêh, jêh ri mra geh âk ngăn ka; yor lah dak aơ hoch rlet ta nây gay ma dak mƀŭt jêng rsang; pô ri lĕ rngôch mpa mra rêh ta ntŭk dak hoch.$b$,false),
('bunong-vn','EZK',47,10,null,$b$Phung seng yơk jal mra gŭ ta kơh dak mƀŭt; tă bơh ƀon Êngêdi tât ma ƀon Ênêglaim mra jêng ntŭk ih mphiar nhuăl (mong ka); păng mra geh ka âk ntil êng êng, nâm bu ka tâm Dak Mƀŭt toyh.$b$,false),
('bunong-vn','EZK',47,11,null,$b$Ƀiă lah djut jêh ri trâp mâu mra jêng dak sât ôh (mâu kah); bu prăp khân păng ma neh boh.$b$,false),
('bunong-vn','EZK',47,12,null,$b$Dăch dak krong nây, kơh đah aơ jêh ri kơh đah ri, mra hon geh ăp ntil tơm si geh play sa; n'ha păng mâu blau kro ôh, jêh ri play păng mâu tăch yơt lĕ. Ăp khay khân păng mra geh play mhe, yor lah dak prăp ma khân păng tă bơh jrô kloh ueh. Play khân păng jêng ndơ sa jêh ri n'ha păng prăp ma nau ƀư bah.”$b$,false),
('bunong-vn','EZK',47,13,null,$b$Pô aơ nau Yêhôva Brah Ndu lah: Aơ jêng n'har neh tĭng nâm khân may mra tâm pă ăn ma jât ma bar mpôl băl Israel ƀư drăp ndơn (drăp chăm). Y-Yôsep mra geh bar kô̆.$b$,true),
('bunong-vn','EZK',47,14,null,$b$Ăn khân may tâm pă ăn tâm ban; gâp ơm ton jêh gay ăn neh aơ ma phung chô-yau khân may, jêh ri neh aơ ma khân may yơh chăm, jêng drăp khân may ndơn.$b$,false),
('bunong-vn','EZK',47,15,null,$b$“Aơ jêng n'har neh: Mpeh ta dor đă bơh Dak Mƀŭt Toyh n'gŏ trong ƀon Hêtlôn tât ntŭk lăp ƀon Hamat, jêh ri hăn tât ta ƀon Sêdat,$b$,true),
('bunong-vn','EZK',47,16,null,$b$ƀon Bêrôtha, ƀon Sibraim (gŭ n'har vah vang ƀon Damas đah ƀon Hamat), tât ta ƀon Haserhatikôn, ƀon nây gŭ ta n'har ƀon Hauran.$b$,false),
('bunong-vn','EZK',47,17,null,$b$Pô nây n'har neh mra ntơm bơh dak mƀŭt tât ma ƀon Haserênon, gŭ ta n'har ta dor ƀon Damas, ndrel ma n'har ƀon Hamat mpeh dor. Nây mra jêng n'har neh mpeh dor.$b$,false),
('bunong-vn','EZK',47,18,null,$b$Mpeh pa lơ, n'har mra ntơm bơh vah vang ƀon Hauran jêh ri ƀon Damas, bri Galaat jêh ri bri Israel, ƀơi n'gŏ dak krong Yurdan; Khân may mra veh tă bơh n'har dor tât ma dak krong pa lơ. Nây mra jêng n'har mpeh pa lơ.$b$,false),
('bunong-vn','EZK',47,19,null,$b$“Mpeh rđŭng, pa dâng, n'har neh mra ntơm bơh ƀon Tamar tât ma dak Mêribat-Kadês, ntơm bơh nây ƀoi n'gŏ Dak N'hong Êjipt tât ma Dak Krong Toyh. Nây mra jêng n'har mpeh rđŭng.$b$,false),
('bunong-vn','EZK',47,20,null,$b$“Mpeh pa dâng, jêng Dak Mƀŭt Toyh tă bơh n'har rđŭng, pa dâng tât ma ntŭk mpeh ma ntŭk lăp ƀon Hamat. Nây mra jêng n'har mpeh pa dâng.$b$,false),
('bunong-vn','EZK',47,21,null,$b$“Pô ri ăn khân may tâm pă bri aơ ndrăng khân may tĭng nâm mpôl băl Israel.$b$,true),
('bunong-vn','EZK',47,22,null,$b$Ăn khân may tâm pă bri nây jêng drăp ma khân may nơm chăm jêh ri phung bu năch gŭ ta nklang khân may, jêh ri deh kon hon sau jêh ta nklang khân may. Ăn khân may kơp khân păng nâm bu kon bu klâu bri nơm tâm bri Israel; ndrel ma khân may bu mra tâm pă drăp ma khân păng ndơn ta nklang phung mpôl băl Israel.$b$,true),
('bunong-vn','EZK',47,23,null,$b$Tâm moh phung mpôl bu năch mra gŭ, ta nây yơh khân may sŏk drăp ăn khân păng, ndơn chăm, Yêhôva Brah Ndu lah nau nây. Nau Tâm Pă Neh Mhe. Amoh Ƀon Jêng “Yêhôva Gŭ Ta Nây”$b$,false),
('bunong-vn','EZK',48,1,null,$b$Aơ jêng amoh phung ntil mpôl: Ntơm bơh n'har mpeh dor, jêh ri hăn ngai tă mpeh dăch ƀon Hêtlôn tât ma ntŭk lăp ƀon Hamat, tât ma Hasarênon (gŭ ta n'har dor ƀon Damas mpeh ma ƀon Hamat), jêh ri hăn tă mpeh pa lơ tât mơ pa dâng, prăp ma phung Dan du kô̆.$b$,true),
('bunong-vn','EZK',48,2,null,$b$Mbot đah neh phung Dan, tă mpeh pa lơ tât mơ pa dâng, prăp ma phung Aser du kô̆.$b$,false),
('bunong-vn','EZK',48,3,null,$b$Mbot đah neh phung Aser, tă mpeh pa lơ tât mơ pa dâng, prăp ma phung Naptali du kô̆ .$b$,false),
('bunong-vn','EZK',48,4,null,$b$Mbot đah neh phung Naptali, tă mpeh pa lơ tât mơ pa dâng, prăp ma phung Manasê du kô̆.$b$,true),
('bunong-vn','EZK',48,5,null,$b$Mbot đah neh Manasê, tă mpeh pa lơ tât mơ pa dâng, prăp ma phung Êphraim du kô̆.$b$,false),
('bunong-vn','EZK',48,6,null,$b$Mbot đah neh Êphraim, tă mpeh pa lơ tât mơ pa dâng, prăp ma phung Ruben du kô̆ .$b$,false),
('bunong-vn','EZK',48,7,null,$b$Mbot đah neh phung Ruben, tă mpeh pa lơ tât mơ pa dâng, prăp ma khŭng Yuđa du kô̆.$b$,false),
('bunong-vn','EZK',48,8,null,$b$“Mbot đah neh phung Yuđa, tă mpeh pa lơ tât mơ pa dâng mra jêng kô̆ khân may prăp êng, bar rmưn prăm rbăn mâng veh rkăng, jêh ri jong (njok) tâm ban kô̆ prăp ma phung ntil mpôl, tă mpeh pa lơ tât mơ pa dâng, nđâp ma jrô kloh ueh ta nklang kô̆ nây.$b$,true),
('bunong-vn','EZK',48,9,null,$b$Kô̆ khân may mra prăp êng ma Yêhôva mra geh bar rbăn prăm rhiăng jong, jêh ri du rmưn mâng veh rkăng.$b$,false),
('bunong-vn','EZK',48,10,null,$b$Aơ mra jêng nau tâm pă prăp ăn ma kô̆ kloh ueh; phung kôranh ƀư brah mra geh du kô̆ bu tâm pă veh jêh bar rbăn prăm rhiăng mâng veh mpeh dor, du rmưn mâng veh rkăng mpeh pa dâng, du rmưn mâng veh mpeh pa lơ, jêh ri bar rmưn prăm rbăn mâng veh jong mpeh rđŭng, geh jrô kloh ueh Yêhôva ta nklang kô̆ neh nây.$b$,false),
('bunong-vn','EZK',48,11,null,$b$Aơ mra jêng kô̆ di ma phung kôranh ƀư brah prăp ăn jêng kloh ueh, phung kon bu klâu Y-Sadôk, phung chiă uănh jêh kan gâp, mâu nkhah du ôh tơ lah phung ƀon lan Israel nkhah du jêh, nâm bu phung Lêvi nkhah du jêh.$b$,false),
('bunong-vn','EZK',48,12,null,$b$Kô̆ neh nây mra prăp ma khân păng du kô̆ êng tă bơh kô̆ kloh ueh tâm n'gor bri, du ntŭk kloh ueh lơn, mbot đah neh phung Lêvi.$b$,true),
('bunong-vn','EZK',48,13,null,$b$Mbot đah neh phung kôranh ƀư brah, phung Lêvi mra geh du kô̆ tâm pă bar rmưn prăm rbăn mâng veh jong jêh ri du rmưn mâng veh rkăng. Lôch jong mra geh bar rmưn prăm rbăn mâng veh jêh ri lôch rkăng bar rmưn prăm rbăn mâng veh.$b$,false),
('bunong-vn','EZK',48,14,null,$b$Khân păng mâu dơi tăch, mâu lah tâm rgâl ôh, du kô̆ neh nây; khân păng mâu dơi ăn play bôk rah tă bơh neh ma bu êng, yor păng prăp jêng kloh ăn ma Yêhôva.$b$,true),
('bunong-vn','EZK',48,15,null,$b$Bi ma neh, bu veh prăm rbăn bông mâng rkăng tâm bar rmưn prăm mâng veh jong, mra prăp ma ntŭk ƀư ƀon, ma ntŭk ƀư ngih, jêh ri ndrêch gơ̆ ; ƀon toyh mra gŭ ta nklang.$b$,true),
('bunong-vn','EZK',48,16,null,$b$Aơ jêng nau veh ƀon păng: Mpeh dor puăn rbăn prăm rhiăng mâng veh, mpeh rđŭng puăn rbăn prăm rhiăng mâng veh, mpeh pa lơ puăn rbăn prăm rhiăng mâng veh, mpeh pa dâng puăn rbăn prăm rhiăng vâng veh.$b$,false),
('bunong-vn','EZK',48,17,null,$b$Pa dih ƀon geh neh mir: Mpeh dor bar rhiăng prăm jât mâng veh, mpeh rđŭng bar rhiăng prăm jât mâng veh, mpeh pa lơ bar rhiăng prăm jât mâng veh, mpeh pa dâng bar rhiăng prăm jât mâng veh.$b$,false),
('bunong-vn','EZK',48,18,null,$b$Bi ma neh hôm e rmeh, chor tĭng kô̆ neh kloh ueh, jong păng du rmưn mâng veh mpeh pa lơ jêh ri du rmưn mâng veh mpeh pa dâng, jêng nau jong kô̆ neh kloh ueh nây, lĕ play đo tă bơh neh nây mra dŏng jêng ndơ sông sa ăn ma phung pah kan tâm ƀon toyh.$b$,false),
('bunong-vn','EZK',48,19,null,$b$Phung pah kan tâm ƀon toyh, jêng phung lĕ rngôch mpôl băl Israel, mra jik tuch kô̆ neh nây.$b$,false),
('bunong-vn','EZK',48,20,null,$b$Glom lĕ rngôch kô̆ neh khân may mra prăp êng nây mra geh bar rmưn prăm rbăn mâng veh tâm ban njok rkăng, nâm bu ntĭt kô̆ neh kloh ueh ndrel ma kô̆ neh prăp ma ƀon toyh.$b$,false),
('bunong-vn','EZK',48,21,null,$b$Kô̆ neh hôm e prăp ăn phung hađăch, lĕ mơ bar đah neh kloh ueh hŏ prăp êng jêh ri kô̆ neh ƀon toyh, veh jong bar rmưn prăm rbăn bông mâng veh ma kô̆ neh bu prăp êng, tât ma n'har neh mpeh pa lơ; jêh ri mơ mpeh pa dâng, nau jong bar rmưn prăm rbăn mâng veh kŏ tât n'har neh mpeh pa dâng, bu chor tĭng phung kô̆ neh ma phung mpôl băl. Nây mra jêng kô̆ neh ma hađăch; jêh ri kô̆ neh kloh ueh hŏ prăp êng ndrel ma ntŭk kloh ueh ngih brah gŭ ta nklang.$b$,true),
('bunong-vn','EZK',48,22,null,$b$Pô nây, kô̆ neh ăn ma hađăch mra jêng lĕ du nkual ta nklang n'har neh Yuđa jêh ri n'har neh Benjamin, knŏng êng ma kô̆ neh hŏ prăp ma phung Lêvi jêh ri kô̆ neh prăp ma ƀon toyh, bi ma lĕ rngôch mra ăn ma hađăch.$b$,false),
('bunong-vn','EZK',48,23,null,$b$“Bi ma phung mpôl băl hôm e: Ntơm bơh pa lơ tât pa dâng du kô̆ neh ăn phung Benjamin;$b$,true),
('bunong-vn','EZK',48,24,null,$b$rŏ n'har neh Benjamin, ntơm pa lơ tât pa dâng, du kô̆ ăn phung Simêôn;$b$,false),
('bunong-vn','EZK',48,25,null,$b$rŏ n'har neh phung Simêôn, ntơm pa lơ tât pa dâng, du kô̆ neh ăn ma phung Isakar.$b$,false),
('bunong-vn','EZK',48,26,null,$b$Mbot đah neh phung Isakar, ntơm pa lơ tât pa dâng, du kô̆ neh prăp ma phung Sabulôn;$b$,true),
('bunong-vn','EZK',48,27,null,$b$rŏ n'har neh phung Sabulôn, ntơm pa lơ tât pa dâng, du kô̆ neh prăp ma phung Gat;$b$,false),
('bunong-vn','EZK',48,28,null,$b$jêh ri rŏ n'har neh phung Gat ntŭk rđŭng rle mơ mpeh rđŭng, n'har neh n'gŏ ntơm bơh ƀon Tamar tât ma dak Mêribat-Kadês, tă bơh nây ƀoi N'hong Dak Bri Êjipt tât ma Dak Mƀŭt Toyh.$b$,false),
('bunong-vn','EZK',48,29,null,$b$Aơ jêng neh khân may mra tâm pă jêng drăp ndơn ta nklang phung mpôl băl Israel, jêh ri aơ jêng kô̆ neh khân păng jêng êng êng,” Yêhôva Brah Ndu lah.$b$,false),
('bunong-vn','EZK',48,30,null,$b$“Aơ jêng ntŭk trong luh tă ƀon toyh: Mpeh dor, bu veh geh mpeh dor; puăn rbăn prăm rhiăng mâng veh;$b$,true),
('bunong-vn','EZK',48,31,null,$b$Lĕ mpông pêr ƀon toyh ma amoh ntơ tĭng nâm amoh phung mpôl băl Israel. Mpeh dor geh mpông pêr: Mpông pêr Ruben jêng nguay; mpông pêr Yuđa nguay; jêh ri mpông pêr Benjamin nguay.$b$,false),
('bunong-vn','EZK',48,32,null,$b$Mpeh pa lơ puăn rbăn prăm rhiăng mâng veh, jêh ri pe mpông pêr: Mpông pêr Yôsep nguay; mpông pêr Benjamin nguay; jêh ri mpông pêr Dan nguay.$b$,false),
('bunong-vn','EZK',48,33,null,$b$Mpeh rđŭng bu veh geh puăn rbăn prăm rhiăng mâng veh, pe mlâm mpông pêr: Mpông pêr Simêôn nguay, mpông pêr Isakar nguay, jêh ri mpông pêr Sabulôn nguay.$b$,false),
('bunong-vn','EZK',48,34,null,$b$Mpeh pa dâng bu veh geh puăn rbăn prăm rhiăng mâng veh, geh pe mlâm mpông pêr: Mpông pêr Gat nguay, mpông pêr Aser nguay, jêh ri mpông pêr Naptali nguay.$b$,false),
('bunong-vn','EZK',48,35,null,$b$Ndăch jŭm ƀon toyh mra geh du rmưn pham rbăn mâng veh. Ntơ amoh ƀon ntơm aƀaơ tât ô klak mra jêng: YÊHÔVA GŬ TA NÂY.”$b$,false);
