('bunong-vn','HOS',10,1,0,'heading',$b$Nau Rai Yot Bri Dak Geh Jât Ndŭl Mpôl$b$),
('bunong-vn','HOS',11,1,0,'heading',$b$Brah Ndu Ŭch Ngăn Phung Ƀon Lan Plơ̆ Sĭt Đŏng$b$),
('bunong-vn','HOS',12,1,0,'heading',$b$Nau Nduyh Ma Phung Êphraim Yor Nau Tih$b$),
('bunong-vn','HOS',13,1,0,'heading',$b$Nau Mbơh Lor Ma Nau Ƀư Rai Lĕ N'gor Êphraim$b$),
