('bunong-vn','JOL',1,8,null,$b$a$b$,null,$b$Ao kroh: Ao bu tanh ma brai rse ƀau. 998$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'AMO', $b$Y-Amôt$b$, $b$["Ndrom Sămƀŭt", "Y-AMÔT"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','AMO',1,1,null,$b$Aơ nau Y-Amôt ngơi, păng jêng du huê tâm phung rmăk biăp ƀon Tôkôa. Nau aơ sŭk nsôr păng ma nau Israel tâm rnôk Y-Usia hađăch Yuđa, jêh ri tâm rnôk Y-Jêrôbôam, kon bu klâu Y-Jôas hađăch Israel, lor bar năm ma nau n'găr neh ntu.$b$,true),
('bunong-vn','AMO',1,2,null,$b$Păng lah: “Yêhôva rđuh tă bơh yôk Siôn, jêh ri ngơi nâm bu nglaih dah bơh ƀon Yêrusalem; ndrêch gơ̆ phung chiăp biăp mra vơl nđor, jêh ri n'glơn yôk Karmel kro đang.”$b$,true),
('bunong-vn','AMO',1,3,null,$b$Yêhôva lah pô aơ: “Yor tă bơh nau djơh mhĭk Damas rlau nau vay pe ntil nđâp puăn ntil đŏng, pô ri gâp mâu mra rgâl ôh nau gâp tâm rmal păng, yor lah khân păng klôn blĭt n'gor Galaat ma ndeh geh sêk loih.$b$,true),
('bunong-vn','AMO',1,4,null,$b$Pô ri gâp mra njuăl ŭnh tât tâm ngih Y-Hasael, jêh ri ŭnh nây mra sa pôih nâp Y-Benhadat.$b$,true),
('bunong-vn','AMO',1,5,null,$b$Gâp mra nkêch lơi rnăng nđăng mpông Damas; gâp mra ƀư rai phung gŭ tâm rlŭng Aven, jêh ri nơm djôt mâng hađăch ta Bet-Êđen; bi ma phung ƀon lan Siri mra jêng bună ta n'gor bri Kir,” Yêhôva lah.$b$,true),
('bunong-vn','AMO',1,6,null,$b$Yêhôva lah pô aơ: “Yor nau tih mhĭk Gaxa rlau nau vay pe ntil nđâp puăn ntil đŏng, yor ri gâp mâu ŭch rgâl ôh nau gâp tâm rmal păng, yor lah khân păng hŏ nhŭp ndjôt lĕ phung ƀon lan leo hăn ƀư bună jao khân ô băl ma phung Êđôm.$b$,true),
('bunong-vn','AMO',1,7,null,$b$Pô ri gâp mra njuăl ŭnh ta klơ mpêr ƀon Gaxa, ŭnh nây mra sa pôih nâp păng.$b$,true),
('bunong-vn','AMO',1,8,null,$b$Gâp mra ƀư rai phung gŭ tâm ƀon Asdôt, jêh ri nơm djôt mâng hađăch ta ƀon Askalon; gâp mra yơr ti gâp ƀư ma ƀon Êkron, jêh ri đơ phung Philistin hôm klen mra rai lôch,” Kôranh Brah Yêhôva lah.$b$,true),
('bunong-vn','AMO',1,9,null,$b$Yêhôva lah pô aơ: “Yor nau tih mhĭk ƀon Tir rlau nau vay pe ntil nđâp puăn ntil đŏng, gâp mâu ŭch rgâl ôh nau gâp tâm rmal păng; yor lah khân păng jao jêh Êđôm lĕ du phung ƀon lan, jêh ri mâu kah gĭt ôh nau tâm rnglăp ndrăng oh nâu.$b$,true),
('bunong-vn','AMO',1,10,null,$b$Pô ri gâp mra njuăl ŭnh ta klơ ƀon Tir, jêh ri ŭnh mra sa pôih nâp păng.”$b$,true),
('bunong-vn','AMO',1,11,null,$b$Yêhôva lah pô aơ: Yor nau tih mhĭk Êđôm rlau nau vay, Pe ntil nđâp puăn ntil đŏng, gâp mâu ŭch Rgâl ôh nau gâp tâm rmal păng; Yor lah khân păng tĭng ntâp oh nâu khân păng nơm, cha lơi lĕ nau tâm yô̆, jêh ri khân păng djôt nau ji nuih tâm sa hêk mâu blau rlu, jêh ri khân păng djang nuih mra mrăng.$b$,true),
('bunong-vn','AMO',1,12,null,$b$Pô ri gâp mra njuăl ŭnh ka klơ ƀon Têman, jêh ri ŭnh nây mra sa pôih nâp ƀon Bôsra.”$b$,true),
('bunong-vn','AMO',1,13,null,$b$Yêhôva lah pô aơ: “Yor nau tih mhĭk Amôn rlau nau vay, pe ntil nđâp puăn ntil đŏng, gâp mâu ŭch rgâl ôh nau gâp tâm rmal păng; yor lah khân păng lông jêh ndŭl phung bu ur dôl ntro tâm n'gor Galaat, gay ăn toyh n'har bri khân păng.$b$,true),
('bunong-vn','AMO',1,14,null,$b$Pô ri gâp mra mpoh ŭnh su tâm mpêr ƀon Raba, jêh ri ŭnh nây mra sa pôih nâp păng, ma nau lŭng nter tâm nar tâm lơh, ta nklang phŭt chuănh tâm nar sial vănh blông;$b$,true),
('bunong-vn','AMO',1,15,null,$b$jêh ri hađăch khân păng mra hăn jêng bună, nđâp ma phung kôranh păng mra hăn ndrel.” Yêhôva lah.$b$,false),
('bunong-vn','AMO',2,1,null,$b$Yêhôva lah pô aơ: “Yor nau tih mhĭk Môap rlau nau vay, pe ntil nđâp puăn ntil đŏng, gâp mâu ŭch rgâl ôh nau gâp tâm rmal păng; yor lah khân păng su jêh nting hađăch n'gor Êđôm tât jêng buh.$b$,true),
('bunong-vn','AMO',2,2,null,$b$Pô ri gâp mra njuăl ŭnh sa pôih nâp ƀon Kêriôt, jêh ri Môap mra khĭt ta nklang nau drơu drơu, ta nklang bâr lŭng nter jêh ri uh nŭng.$b$,true),
('bunong-vn','AMO',2,3,null,$b$Gâp mra ƀư rai hađăch bơh ta nklang păng, jêh ri nkhĭt lĕ rngôch phung kôranh ndrel ma păng,” Yêhôva lah.$b$,true),
('bunong-vn','AMO',2,4,null,$b$Yêhôva lah pô aơ: “Yor nau tih mhĭk Yuđa rlau nau vay mra, pe ntil nđâp puăn ntil đŏng, gâp mâu ŭch rgâl ôh nau gâp tâm rmal păng; yor lah khân păng dun jêh ma nau vay Yêhôva, jêh ri mâu djôt prăp ôh nau păng ntĭnh, khân păng hŏ tĭng kơt nau mƀruh bơh chô yau khân păng, ƀư vĭ trong ma khân păng.$b$,true),
('bunong-vn','AMO',2,5,null,$b$Pô ri gâp mra njuăl ŭnh sa pôih nâp ƀon Yêrusalem.”$b$,true),
('bunong-vn','AMO',2,6,null,$b$Yêhôva lah pô aơ: “Yor nau tih mhĭk Israel rlau nau vay, pe ntil nđâp puăn ntil đŏng, gâp mâu ŭch rgâl ôh nau gâp tâm rmal păng; yor lah khân păng tăch bunuyh sŏng sŏk prăk, tăch phung ndĭt trơi sŏk du gu ntâu jot.$b$,true),
('bunong-vn','AMO',2,7,null,$b$Khân păng jot plên bôk phung ndĭt trơi tâm neh muy, jêh ri ƀư kue trong ma bunuyh rvưt. Du huê bu klâu jêh ri mbơ̆ păng hăn nsum ma du huê bu ur, pô nây ƀư ƀơ̆ amoh kloh ueh gâp.$b$,true),
('bunong-vn','AMO',2,8,null,$b$Khân păng bêch êp ăp nơng, ta klơ ao jâr bu hŏ ƀư ndơ mphiar jêh ri nhêt ndrănh phung bu mra kuh tâm ngih brah khân păng.$b$,true),
('bunong-vn','AMO',2,9,null,$b$Nđâp tơ lah pô nây, “gâp nơm ƀư rai jêh phung Amôrit ta năp măt khân păng, jêng phung bunuyh prêh, săk juat khân păng nâm bu prêh tơm si sêdar, jêh ri dăng ktang nâm bu tơm si sen. Gâp ƀư rai jêh play khân păng ta klơ jêh ri reh khân păng tâm dâng.$b$,true),
('bunong-vn','AMO',2,10,null,$b$Tâm ban lĕ gâp ngluh jêh khân may tă bơh n'gor bri Êjipt, jêh ri njŭn khân may tâm puăn jât năm gŭ tâm bri rdah, gay ăn khân may sŏk sĭt krâm bri phung Amôrit.$b$,true),
('bunong-vn','AMO',2,11,null,$b$Gâp hŏ njêng bơh phung kon bu klâu khân may jêng phung kôranh nơm mbơh lor, jêh ri ƀa ƀă phung bu klâu ndăm gâp njêng phung Nasirit. Yêhôva lah: Hơi phung kon sau Israel, mâu di hĕ pô nây?”$b$,true),
('bunong-vn','AMO',2,12,null,$b$Ƀiă lah khân may hŏ ăn ma phung Nasirit nhêt ndrănh jêh ri buay phung kôranh nơm mbơh lor lah: ‘Lơi khân may mbơh lor ôh!’$b$,true),
('bunong-vn','AMO',2,13,null,$b$Aơ, gâp mra mpet khân may tâm ntŭk khân may nâm bu du bôk ndeh rdeng lĕ roch jêh nchăp ba tâm tŭn mpet.$b$,false),
('bunong-vn','AMO',2,14,null,$b$Bunuyh nchuăt dŭt prăl mâu mra dơi du ôh; bunuyh ngăch dăng kôranh mâu dơi lĕ têm n'hâm suan păng, jêh ri bunuyh janh ktang kŏ mâu dơi lĕ tâm rklaih nau rêh păng nơm.$b$,true),
('bunong-vn','AMO',2,15,null,$b$Nơm djôt na mâu mra dơi tâm rdâng ôh, jêh ri bunuyh nchuăt prăl mâu mra dơi lăn klaih păng nơm ôh; bunuyh ncho seh kŏ mâu dơi klaih lĕ păng nơm.$b$,true),
('bunong-vn','AMO',2,16,null,$b$Jêh ri bunuyh janh lơn tâm phung ta han, mra nchuăt rhôk tâm nar nây,” Yêhôva lah.$b$,true),
('bunong-vn','AMO',3,1,null,$b$Hơi phung kon sau Israel, iăt hom nau Yêhôva ngơi tâm rdâng đah khân may, tâm rdâng đah lĕ rngôch băl mpôl gâp hŏ ngluh jêh bơh n'gor bri Êjipt:$b$,true),
('bunong-vn','AMO',3,2,null,$b$“Knŏng êng khân may yơh gâp lĕ năl jêh tâm lĕ rngôch phung băl mpôl bunuyh ta neh ntu; yor nây gâp mra tâm rmal khân may yor lĕ nau kue khân may.”$b$,false),
('bunong-vn','AMO',3,3,null,$b$Tơ lah bar hê mâu du ai nau, pô ri mâu hĕ hăn ndrel?$b$,true),
('bunong-vn','AMO',3,4,null,$b$Tơ lah yau mŭr mâu geh kăp ôh jun, mâu hĕ păng rđuh tâm krŏng? Yau mŭr kon tơ lah mâu geh ndơ Păng kăp, mâu hĕ ngrông tă tâm ntŭk trôm jru păng?$b$,true),
('bunong-vn','AMO',3,5,null,$b$Du mlâm sĭm, tơ lah mâu geh sân dăk ôh, păng lăp geh dăk gŭ lĕ ta neh? Tơ lah păng mâu geh nhŭp du ntil ndơ ôh, nau plĕch dăk nây mpât tâm neh?$b$,true),
('bunong-vn','AMO',3,6,null,$b$Bu uh nŭng tâm ƀon toyh jêh ri phung ƀon lan mâu hĕ klach? Nau mhĭk tât lĕ ma du rplay ƀon toyh tơ lah Brah Ndu mâu ƀư nau nây?$b$,true),
('bunong-vn','AMO',3,7,null,$b$Tâm ban lĕ, kôranh Brah Yêhôva mâu ƀư du ntil nau ôh tơ lah Păng mâu mbơh nau ndâp Păng ma phung oh mon Păng, jêng phung kôranh nơm mbơh lor.$b$,true),
('bunong-vn','AMO',3,8,null,$b$Tơ lah yau mŭr rđuh, mbu nơm mâu klach? Tơ lah kôranh Brah Yêhôva hŏ ngơi jêh mbu nơm mâu dơi mbơh lor?$b$,true),
('bunong-vn','AMO',3,9,null,$b$Mbơh hom ma pôih nâp tâm n'gor Asdôt, jêh ri ma pôih nâp tâm n'gor Êjipt, jêh ri lah: “Khân may tâm rgum hom ta klơ yôk Samari, uănh hom âk nau uh ah toyh ngăn ta nây, jêh ri nau tŭn jot ta nklang păng.”$b$,true),
('bunong-vn','AMO',3,10,null,$b$Yêhôva lah: “Khân păng mâu gĭt ƀư nau sŏng jêh ri di; khân păng bun prăp ndơ mhĭk ƀai jêh ri ƀư nau ntŭng tâm pôih nâp khân păng.$b$,true),
('bunong-vn','AMO',3,11,null,$b$Yor nây kôranh Brah Yêhôva lah pô aơ: Aơ, phung rlăng mra văch tât nchueng bri neh aơ; păng mra n'glưh nau ktang may, jêh ri pit in pôih nâp may.”$b$,true),
('bunong-vn','AMO',3,12,null,$b$Yêhôva lah pô aơ: “Nâm bu phung rmăk biăp đŏt mphâk tă bơh trôm mbung yau mŭr, knŏng bar mlâm nglu mâu lah du đah tôr, pô nây lĕ nau bu koh dŏng phung ƀon lan Israel, jêng phung gŭ tâm n'gor Samari, ta ntŭk njônh du mlâm sưng bêch jêh ri tâm ban pô nây lĕ mra dơi rklaih ta ƀon Damas.$b$,true),
('bunong-vn','AMO',3,13,null,$b$Kôranh Brah Yêhôva, Brah Ndu phung ta han, lah: “Iăt hom jêh ri tâm rdâng đah nghi Y-Yakôb.”$b$,true),
('bunong-vn','AMO',3,14,null,$b$Tâm nar gâp tâm rmal phung Israel yor ma nau tih păng, tâm ban lĕ gâp mra ƀư rai nơng ƀon Bêthel; bu ma koh lơi nke nơng jêh ri mƀăr ta neh.$b$,true),
('bunong-vn','AMO',3,15,null,$b$Rnôk nây gâp mra ƀư rai ngih yan sĭt puh jêh ri ngih yan ta vai; ngih ƀư ma la mra, jêh ri ngih toyh mra rai tâm ban lĕ.” Yêhôva lah.$b$,true),
('bunong-vn','AMO',4,1,null,$b$Hơi phung ndrôk me phung Basan, iăt hom, gŭ ta klơ yôk Samari; tŭn jot phung o ach jêh ri jot plên phung mâu geh mâu jêng, lah ma sai khân păng, ‘Ndơ̆ hom, he dơi nhêt!’$b$,true),
('bunong-vn','AMO',4,2,null,$b$Kôranh Brah Yêhôva hŏ dŏng nau kloh ueh Păng sơm ton pô aơ: “Aơ, nar mra tât jêh ma khân may, bu mra djôt nglĕ klĕ yơk khân may, nđâp phung hôm pa kơi lơn tâm phung khân may bu mra klĕ ma nglĕ ndar$b$,false),
('bunong-vn','AMO',4,3,null,$b$Khân may mra luh du ta trôm lĕ bŏng, ăp nơm mra hăn sŏng tra năp păng nơm, jêh ri khân may bu mra klŭp tâm Harmôn,” Yêhôva lah.$b$,false),
('bunong-vn','AMO',4,4,null,$b$“Hăn hom tât ta ƀon Bêthel, jêh ri ƀư tih; hăn hom ma ƀon Gilgal ƀư tih tay! Ăp ôi leo hom ndơ khân may ƀư brah, jêh ri pe nar du tơ̆ nhhơr du kô̆ tâm jât!$b$,true),
('bunong-vn','AMO',4,5,null,$b$Nhhơr ndơ ƀư brah nau tâm rnê geh ndrui, jêh ri mbơh hom ndơ nhhơr ma nay ŭch. Ăn bu gĭt nau nây, Hơi phung kon sau Israel! Yor lah khân may ŭch nau nây.” Kôranh Brah Yêhôva lah.$b$,true),
('bunong-vn','AMO',4,6,null,$b$“Bi ma gâp, gâp ăn jêh ma khân may ât ji ngot tâm lĕ rngôch ƀon toyh khân may, ƀiă lah khân may mâu lĕ ŭch plơ̆ sĭt ma gâp!” Yêhôva lah.$b$,true),
('bunong-vn','AMO',4,7,null,$b$“Jêh ri tâm ban lĕ gâp mâu ăn ôh dak mih ma khân may hôm pe khay ma tât yan rek ba; gâp hŏ ăn mih ta ƀon toyh aơ jêh ri mâu ăn mih ta ƀon toyh êng. Du lôk mir aơ lĕ geh dak mih, jêh ri lôk mir êng mâu geh dak mih ôh lĕ nhop kro.$b$,true),
('bunong-vn','AMO',4,8,null,$b$Pô nây, bunuyh tâm bar pe rplay ƀon toyh lĕ hăn jêh ma du rplay ƀon toyh êng ŭch nhêt dak, mâu dơi joi dak gay bah ji hir. Ƀiă lah khân may mâu lĕ ŭch sĭt ma gâp,” Yêhôva lah.$b$,true),
('bunong-vn','AMO',4,9,null,$b$“Gâp hŏ dŏng sial duh jêh ri krah sa ba ƀư rai khân may. Geh âk n'gar trao, đang play kriăk ƀâu, tơm play rvi, jêh ri tơm play ôlivơ khân may lĕ krah sa lơi. Ƀiă lah khân may mâu lĕ ŭch sĭt ôh ma gâp.” Yêhôva lah.$b$,true),
('bunong-vn','AMO',4,10,null,$b$“Gâp njuăl jêh ma khân may nau ji tưp, nâm bu tâm n'gor bri Êjipt; gâp nkhĭt jêh phung bu klâu ndăm khân may ma đao, jêh ri phung seh khân may lĕ gâp nchuăn jêh. Gâp hŏ ăn nau ƀâu ôm ntŭk khân may njơh n'hôl tât ma trôm muh khân may, ƀiă lah khân may mâu lĕ ŭch plơ̆ sĭt ôh ma gâp.” Yêhôva lah.$b$,true),
('bunong-vn','AMO',4,11,null,$b$“Gâp hŏ ƀư rai ƀa ƀă khân may nâm bu Brah Ndu ƀư rai Sôdôm jêh ri Gômôrơ jêh ri khân may nâm bu rlŭt ŭnh bu rhuăt bơh ntŭk ŭnh sa; ƀiă lah khân may mâu lĕ ŭch plơ̆ sĭt ôh ma gâp.” Yêhôva lah.$b$,true),
('bunong-vn','AMO',4,12,null,$b$“Hơi Israel, yor nây gâp mra ƀư nau aơ ma may; Hơi Israel, yor nây gâp mra ƀư nau aơ ma may, nkra hom ma nau tâm mâp đah Brah Ndu may.”$b$,true),
('bunong-vn','AMO',4,13,null,$b$N'hêl nanê̆, aơ jêng Păng hŏ njêng yôk jêh ri rhăk njêng sial. Aơ jêng Păng ƀư mbơh ma bunuyh moh nau păng mĭn; nơm ăn ôi rlơ̆ ngo, jêh ri hăn tâm ntŭk prêh ta neh ntu Amoh Păng jêng Yêhôva Brah Ndu phung ta han!$b$,true),
('bunong-vn','AMO',5,1,null,$b$Hơi ngih Israel, iăt hom nau aơ, nau gâp nhĭm vơl ma khân may!$b$,true),
('bunong-vn','AMO',5,2,null,$b$“Bu ur druh tang tat Israel lĕ cha lôt jêh, mâu mra dâk đŏng ôh. Bu mƀăr lơi jêh păng ta bri păng nơm, mâu geh bunuyh kơl rdâk.$b$,true),
('bunong-vn','AMO',5,3,null,$b$Yor lah Yêhôva lah pô aơ: “Ƀon toyh prơh hăn du rbăn nuyh ta han mra hôm e knŏng du rhiăng nuyh; jêh ri ƀon prơh hăn du rhiăng nuyh ta han mra hôm e jât nuyh tâm ngih Israel.”$b$,true),
('bunong-vn','AMO',5,4,null,$b$Yor lah Yêhôva lah ma ngih Israel pô aơ: “Joi hom gâp, jêh ri khân may mra rêh!$b$,true),
('bunong-vn','AMO',5,5,null,$b$Ƀiă lah lơi joi ôh ƀon Bêthel jêh ri lơi lăp ôh ƀon Gilgal, mâu lah lơi hăn tât ôh ma ƀon Bêr-Sêba; Yor lah n'hêl nanê̆ ƀon Gilgal mra hăn jêng bună, jêh ri ƀon Bêthel mra jêng ntŭk dơm dam.”$b$,true),
('bunong-vn','AMO',5,6,null,$b$Joi hom Yêhôva, khân may mra rêh; klach păng hit nâm bu ŭnh tâm ngih Yôsep, jêh ri ŭnh nây sa, mâu geh ôh nơm nhhât ta ƀon Bêthel$b$,true),
('bunong-vn','AMO',5,7,null,$b$Khân may rgâl nau sŏng jêh ri di luh jêng si tăng jêh ri mƀăr nau sŏng srăng ta neh!$b$,false),
('bunong-vn','AMO',5,8,null,$b$Joi hom Nơm hŏ rhăk njêng mănh Plêat jêh ri Ôrlon, jêh ri rlơ̆ nau ngo klĕng jêng ơm ôi, jêh ri rgâl nô nar jêng măng, kuăl dak ăn păng hoch ta klơ neh. Amoh păng jêng Yêhôva.$b$,true),
('bunong-vn','AMO',5,9,null,$b$Păng nơm yơh ăn nau ƀư rai tât ƀât lât ma phung ktang, kŏ tât nau ƀư rai nây tât tâm pôih nâp.$b$,true),
('bunong-vn','AMO',5,10,null,$b$Khân păng tâm rmot ma nơm nduyh khân păng mpông pêr, jêh ri khân păng ntêh rmot nsot ach ma nơm ngơi nau nanê̆ ngăn.$b$,true),
('bunong-vn','AMO',5,11,null,$b$Pô ri yor lah khân may jot jêh bunuyh o ach, jêh ri sŏk hưn ba răch (ba ƀlê) tă bơh khân păng, nđâp tơ lah khân păng ndâk jêh ngih lŭ trah, khân may mâu mra gŭ tâm khân păng ôh, nđâp tơ lah khân may tăm jêh đang play kriăk ƀâu ueh, khân may mâu mra nhêt dak păng ôh.$b$,true),
('bunong-vn','AMO',5,12,null,$b$Yor lah gâp gĭt nau tih mhĭk jêng âk, jêh ri nau tih khân may toyh ngăn, khân may jêng phung tŭn jot phung sŏng, khân may dơn sŏk rdăp bu nkhôm, jêh ri khân may dun nau di ma phung ach ndơ tâm ntŭk phat dôih.$b$,true),
('bunong-vn','AMO',5,13,null,$b$Yor nây nơm blau njrăng gŭ klêm tâm rnôk tâm ban pô aơ; yor lah rnôk aơ jêng rnôk mhĭk.$b$,true),
('bunong-vn','AMO',5,14,null,$b$Tĭng joi hom nau ueh, mâu di nau mhĭk ôh, gay ma khân may dơi gŭ rêh; pô ri mơ Yêhôva Brah Ndu phung ta han mra gŭ ndrel ma khân may nâm bu khân may lah jêh.$b$,true),
('bunong-vn','AMO',5,15,null,$b$Tâm rmot hom ma nau mhĭk, jêh ri rŏng hom ma nau ueh, ăn nâp nau sŏng ta mpông pêr. Klăp lah Yêhôva Brah Ndu phung ta han mra kơp ma phung Yôsep hôm klen!$b$,true),
('bunong-vn','AMO',5,16,null,$b$Yor nây Yêhôva Brah Ndu phung ta han kôranh Brah, lah pô aơ: “Tâm lĕ rngôch nkual bu mra nhhiăng nhĭm, jêh ri lĕ rngôch trong sâng bu mra lah, ‘Rêh ni ngăn, Rêh ni ngăn!’ Bu mra kuăl nơm ƀư mir văch ma nau klân rvê, jêh ri phung blau nhhiăng nhĭm ma nau nhĭm vơl$b$,true),
('bunong-vn','AMO',5,17,null,$b$Lĕ rngôch đang play kriăk ƀâu geh nau nhĭm vơl, yor lah gâp mra rgăn ta nklang khân may.” Yêhôva lah.$b$,false),
('bunong-vn','AMO',5,18,null,$b$Rêh ni ngăn ma khân may Khân may ŭch ngăn ma nar Yêhôva! Moh nau khân may ŭch ngăn ma nar Yêhôva? Nây jêng nau ngo, mâu di nau ang ôh;$b$,true),
('bunong-vn','AMO',5,19,null,$b$nâm bu du huê bunuyh nchuăt klach bơh yau mŭr, jêh ri nkhơng mâp tay kau; mâu lah nâm bu bunuyh lăp tâm ngih, mbim ti ta mpin, jêh ri du mlâm bêh geh chôk păng.$b$,false),
('bunong-vn','AMO',5,20,null,$b$Mâu di hĕ nar Yêhôva jêng nau ngo, ang mâu kloh rah vah, jêh ri ngo vêt vê mâu geh chrat ang ôh?$b$,true),
('bunong-vn','AMO',5,21,null,$b$“Gâp tâm rmot: Gâp biănh ma nar năng khân may; gâp mâu maak ôh ma nau khân may tâm rƀŭn ma nau yơk.$b$,true),
('bunong-vn','AMO',5,22,null,$b$Nđâp tơ lah khân may nhhơr ma gâp ndơ nhhơr gŭch jêh ri ndơ nhhơr rnih môi, gâp mâu mra dơn ndơ nây ôh. Gâp mâu mra chrê ôh ma ndơ lay khân may nhhơr ma nau đăp mpăn.$b$,true),
('bunong-vn','AMO',5,23,null,$b$Ăn ngai lơi đah gâp bât khân may mprơ; gâp mâu mra iăt ôh bâr maak gong rêng khân may.$b$,true),
('bunong-vn','AMO',5,24,null,$b$Ƀiă lah ăn nau sŏng rlă hoch nâm bu dak, jêh ri nau sŏng srăng nâm bu du n'hor dak hoch ƀa ƀơ.$b$,true),
('bunong-vn','AMO',5,25,null,$b$“Hơi ngih Israel, khân may lĕ mâp leo ma gâp lĕ ndơ ƀư brah jêh ri ndơ nhhơr dôl puăn jât năm tâm bri rdah?$b$,true),
('bunong-vn','AMO',5,26,null,$b$Khân may tung Sikut hađăch khân may, phung rup brah khân may ma khân may nơm.$b$,true),
('bunong-vn','AMO',5,27,null,$b$Yor nây gâp mra sŏk leo khân may jêng bu nă đah ri ƀon Damas,” Yêhôva lah, amoh păng jêng Brah Ndu phung ta han.$b$,true),
('bunong-vn','AMO',6,1,null,$b$Rêh ni ngăn ma phung gŭ đăp mpăn tâm ƀon Siôn, jêh ri phung gŭ đăp rmên ta yôk Samari, phung kôranh tâm phung bri dak ƀư bôk, ma khân păng yơh Israel sĭt ndrel!$b$,true),
('bunong-vn','AMO',6,2,null,$b$Pô ri rgăn hom ta ƀon Kalnê jêh ri uănh; ntơm bơh nây hăn hom tât ta Hamat, ƀon toyh, n'hot hăn tât ta ƀon Gat phung Philistin Khân păng jêng ueh lơn ma phung ƀon bri hađăch aơ lĕ? Bri neh khân păng jêng toyh lơn ma bri khân may lĕ?$b$,true),
('bunong-vn','AMO',6,3,null,$b$Hơi phung khân may mĭn n'hŭch lơi nar mhĭk, ƀiă lah nau khân may ƀư ăn nau ƀai gơnh tât!$b$,true),
('bunong-vn','AMO',6,4,null,$b$Rêh ni ngăn ma phung gŭ bêch ta sưng bêch ƀư ma la, gŭ rlu ta klơ sưng bêch khân păng, jêh ri sa biăp kon săch tâm phung jêh ri phung ndrôk tă bơh ndrung.$b$,true),
('bunong-vn','AMO',6,5,null,$b$Nanê̆ khân may mprơ nau dơm dam tâm vơt đah nteh gong rêng, jêh ri nâm bu Y-Đavit nklă êng ma khân păng nơm gong rêng;$b$,true),
('bunong-vn','AMO',6,6,null,$b$phung nhêt dak play kriăk ƀâu ma khăl mlŭng, jêh ri mhĭng khân păng nơm ma dak kôlônh ueh reh, ƀiă lah mâu rngot ôh yor nau ƀư rai tât ma Y-Yôsep!$b$,false),
('bunong-vn','AMO',6,7,null,$b$Yor nây aƀaơ khân păng mra jêng phung hăn jêng bună lor bôk dak tâm phung bu nhŭp, jêh ri rnôk nây mơ dĭng roh nau nter hao hâk phung đŭp-đŭl (hao sôl) nây!$b$,true),
('bunong-vn','AMO',6,8,null,$b$Kôranh Brah Yêhôva jêng Brah Ndu phung ta han lah: Kôranh Brah Yêhôva sơm săk păng nơm lah: “Gâp tâm rmot ma phung Yakôb sưr, jêh ri ji nuih ma pôih nâp păng; jêh ri gâp mra jao ƀon toyh ndrel ma lĕ rngôch ndơ tâm păng.”$b$,true),
('bunong-vn','AMO',6,9,null,$b$Tơ lah tâm du rnăk vâl, hôm jât nuyh khân păng mra khĭt tâm ban lĕ.$b$,true),
('bunong-vn','AMO',6,10,null,$b$Tơ lah du huê ndŭl mpôl, jêng nơm su săk nuyh khĭt, sŏk lơi nting ngluh pa dih tă bơh trôm vâl, jêh ri lah ma nơm hôm tâm vâl, “Hôm geh lĕ bunuyh ndrel may?” Ô băl mra lah: “Mâu hôm” jêh ri păng mra lah: “Gŭ rklăk hom! Lơi ăn ngơi tât ma Amoh Yêhôva ôh.”$b$,true),
('bunong-vn','AMO',6,11,null,$b$Yor lah, Yêhôva ntĭnh jêh, aơ, ngih toyh mra chôt chah lĕ, jêh ri ngih jê̆ chah hăch rhên.$b$,true),
('bunong-vn','AMO',6,12,null,$b$Seh nchuăt ta klơ lŭ lĕ? Bu leo ndrôk kai lŭ nây lĕ? Ƀiă lah khân may ăn nau sŏng rlơ̆ jêng nkhơng dak kăch, jêh ri rgâl play sŏng srăng rlơ̆ jêng tơm tăng.$b$,true),
('bunong-vn','AMO',6,13,null,$b$Khân may hâk răm tâm ƀon Lô- Dêbar jêh ri lah pô aơ: “Mâu hĕ di ma nau ktang he nơm sŏk jêh ƀon Karnaim ma he nơm?”$b$,true),
('bunong-vn','AMO',6,14,null,$b$Yêhôva Brah Ndu phung ta han lah: “Aơ, Hơi ngih Israel, gâp mra ăn du bri dak văch tâm rdâng đah may, jêh ri khân păng mra tŭn jot khân may, ntơm bơh ntŭk lăp ƀon Hamat tât ta n'hor dak Arabah.”$b$,true),
('bunong-vn','AMO',7,1,null,$b$Pô aơ nau Yêhôva tâm mpơl jêh ma gâp: Aơ, păng njêng krah tâm dôl gơ̆ ntơm hon nse tay; nây jêng gơ̆ chăt tay jêh hađăch ăn bu muih ma păng.$b$,true),
('bunong-vn','AMO',7,2,null,$b$Tơ lah krah sa lĕ rngôch jêh gơ̆ tâm bri nây, gâp lah: “Hơi kôranh Brah Yêhôva, gâp vơh vơl ma may yô̆ an hom! Mâm Yêhôva dơi hôm e? Khân păng djê̆ lê̆ dơm!”$b$,true),
('bunong-vn','AMO',7,3,null,$b$Yêhôva rgâl nau kan aơ. Yêhôva lah: “Nau aơ mâu mra tât ôh.”$b$,true),
('bunong-vn','AMO',7,4,null,$b$Kôranh Brah Yêhôva tâm mpơl ma gâp pô aơ: Aơ, kôranh Brah Yêhôva gŭ kuăl nau phat dôih ma ŭnh tât, jêh ri ăn ŭnh sa trôm ntu jru jêh ri ŭnh sa lĕ bri.$b$,true),
('bunong-vn','AMO',7,5,null,$b$Jêh ri gâp lah: “Hơi Kôranh Brah Yêhôva, gâp vơh vơl ma may, rlu hom! Mâm Yakôb dơi hôm e? Păng jêng djê̆ lê̆ dơm?”$b$,true),
('bunong-vn','AMO',7,6,null,$b$Yêhôva tâm rgâl nau kan aơ. Yêhôva lah: “Nau aơ tâm ban lĕ mâu mra tât ôh.”$b$,true),
('bunong-vn','AMO',7,7,null,$b$Păng tâm mpơl jêh ma gâp: Aơ, Kôranh Brah dâk ta meng mpêr ndâk jêh ma rse veh ma dak ndrak, jêh ri ta ti Păng djôt rse veh ma dak ndrak.$b$,true),
('bunong-vn','AMO',7,8,null,$b$Yêhôva lah ma gâp, “Hơi Y-Amôt moh may saơ?” Gâp lah, “Du njăr rse veh ma dak ndrak.” Kôranh Brah lah tay: “Aơ, gâp mra dơm rse veh ma ndrak ta nklang phung ƀon lan gâp Israel; gâp mâu mra nhhuach ma khân păng ôh.$b$,true),
('bunong-vn','AMO',7,9,null,$b$Lĕ ntŭk prêh Y-Săk ma jêng rngol, jêh ri ntŭk kloh ueh Israel mra rai, jêh ri gâp mra du dâk tâm rdâng ma ngih Y-Jêrôbôam ma đao.”$b$,true),
('bunong-vn','AMO',7,10,null,$b$Rnôk nây, Y-Amasia kôranh ƀư brah ƀon Bêthel prơh bu hăn mbơh ma Y-Jêrôbôam hađăch Israel, lah, “Y-Amôt thăm ŭch ƀư ma may ta nklang ngih Israel; bri dak mâu ŭch dơn ôh lĕ nau păng ngơi.”$b$,true),
('bunong-vn','AMO',7,11,null,$b$Yor lah pô aơ nau Y-Amôt lah jêh, “Y-Jêrôbôam mra khĭt ma đao, jêh ri nanê̆ ngăn Israel mra jêng bună, ngai ma bri dak khân păng nơm.”$b$,true),
('bunong-vn','AMO',7,12,null,$b$Jêh ri Y-Amasia lah ma Y-Amôt, “Hơi bunuyh tâm saơ, dâk hăn hom ma n'gor Yuđa; sa piăng let ta nây jêh ri mbơh lor ta nây.$b$,true),
('bunong-vn','AMO',7,13,null,$b$Ƀiă lah lơi hôm mbơh lor ôh ta ƀon Bêthel, yor lah păng jêng ntŭk kloh ueh ma hađăch, jêh ri jêng ngih brah ma ƀon bri hađăch.”$b$,true),
('bunong-vn','AMO',7,14,null,$b$Jêh ri Y-Amôt plơ̆ lah ma Y-Amasia, “Gâp mâu jêng du huê kôranh nơm mbơh lor ôh, mâu lĕ jêng kon du huê kôranh nơm mbơh lor; ƀiă lah gâp jêng du huê rmăk biăp, jêh ri nơm nkra tơm play Sikamôr.$b$,true),
('bunong-vn','AMO',7,15,null,$b$Yêhôva sŏk gâp tă bơh ntŭk chiăp biăp, jêh ri Yêhôva lah ma gâp, ‘Hăn mbơh lor hom ma phung ƀon lan gâp Israel’.$b$,true),
('bunong-vn','AMO',7,16,null,$b$Yor nây aƀaơ iăt hom nau Yêhôva ngơi May nơm lah: Lơi mbơh lor tâm rdâng ôh ma Israel, jêh ri lơi nti tâm rdâng ôh ma ngih Y-săk!$b$,true),
('bunong-vn','AMO',7,17,null,$b$Yor nây Yêhôva lah pô aơ; Ur may jêng du huê bu ur ka n'hong tâm ƀon toyh, phung kon bu klâu jêh ri phung kon bu ur may mra cha lôt ma đao, jêh ri bri may bu mra tâm pă ma rse bu veh, jêh ri may nơm mra khĭt tâm du n'gor bri mâu geh kloh ôh; jêh ri nanê̆ ngăn Israel mra hăn jêng bună ngai ma bri khân păng nơm.$b$,true),
('bunong-vn','AMO',8,1,null,$b$Aơ jêng nau Kôranh Brah Yêhôva tâm mpơl ma gâp, lah: “Aơ, geh du bĭ play yan ta vai.$b$,true),
('bunong-vn','AMO',8,2,null,$b$Rnôk nây Păng lah pô aơ: “Hơi Y-Amôt, moh may saơ?” Gâp lah, “Du bĭ play yan ta vai.” Jêh ri Yêhôva lah ma gâp, “Nau dăch lôch tât jêh ma ƀon lan gâp Israel; gâp mâu mra nhhuach ma khân păng ôh.$b$,true),
('bunong-vn','AMO',8,3,null,$b$Tâm nar nây nau mprơ tâm ngih brah mra jêng nau nhĭm nhhiăng, “Kôranh Brah Yêhôva lah. “Săk jăn khĭt mra jêng âk, lam ntŭk bu mra mƀăr khân păng ma nau klăk klêm.”$b$,true),
('bunong-vn','AMO',8,4,null,$b$Iăt hom nau aơ, khân may jêng phung bunuyh jot plên phung ndĭt trơi, jêh ri nkhĭt phung o ach, lah,$b$,true),
('bunong-vn','AMO',8,5,null,$b$“Ndah nâm jŏ khay mhe mra lôch, gay ma he dơi tăch lơi ba? Jêh ri ndah nâm jŏ lôch nar Saƀat, gay ăn he dơi tăch rgâl ba răch (ba ƀlê)? Gay ăn he dơi hŭch êpha jêh ri ntop jâk Sêkel, jêh ri ndơm ma njing bu veh mâu di ôh;$b$,false),
('bunong-vn','AMO',8,6,null,$b$gay ma he dơi rvăt phung o ach tâm rgâl ma prăk, jêh ri rgâl bunuyh ndĭt trơi sŏk du gŭ ntâu jot, jêh ri tăch ba răch nsiăp?”$b$,false),
('bunong-vn','AMO',8,7,null,$b$Yêhôva sơm săk jêh sŏk nau chrêk rmah bơh Y-Yakôp, “N'hêl nanê̆ gâp mâu mra chuêl ôh du ntil kan khân may ƀư.$b$,true),
('bunong-vn','AMO',8,8,null,$b$Mâu hĕ di bri neh bu tŭn jot yor nau nây, jêh ri ăp nơm gŭ ta nây mra nhĭm nhhiăng? Lĕ lam bri mra hao ler lip nâm bu dak krong toyh, mra trâm tŭp rdjŭm nâm bu dak Krong Êjipt nây lĕ.$b$,true),
('bunong-vn','AMO',8,9,null,$b$Kôranh Brah Yêhôva lah: “Tâm nar nây gâp mra ăn măt nar tŭp dôl nar nklang bôk jêh ri ăn ngo neh ntu dôl nôk nar.$b$,true),
('bunong-vn','AMO',8,10,null,$b$Gâp mra rlơ̆ nar năng khân may jêng nar klân rvê, jêh ri lĕ nau mprơ khân may jêng nau nhhiăng nhĭm. Gâp mra vân ƀau ta bŭt lĕ rngôch, jêh ri ƀư ăn bôk plưn da dê Gâp mra ƀư nau nây jêng nâm bu nau klân rvê ma du huê kon bu klâu bu geh knŏng du huê, jêh ri nau nglĕ dŭt păng nâm bu du nar rngot ngăn ngên.$b$,true),
('bunong-vn','AMO',8,11,null,$b$Kôranh Brah Yêhôva lah: “Aơ yơh, nar mra tât.” Tơ lah gâp njuăl nau sa sât ji ngot tâm bri neh, mâu di ôh nau ji ngot mâu geh piăng let sa, mâu lĕ di ji hir ma dak nhêt, ƀiă lah nau ât ji ngot iăt nau Yêhôva ngơi.$b$,true),
('bunong-vn','AMO',8,12,null,$b$Rnôk nây khân păng mra hăn vât vâng ntơm bơh dak mƀŭt aơ tât dak mƀŭt êng, ntơm mpeh bơh dor tât mpeh bơh lơ; nchuăt ta aơ ta ri gay ŭch joi nau. Yêhôva ngơi, ƀiă lah khân păng mâu mra saơ ôh.$b$,true),
('bunong-vn','AMO',8,13,null,$b$Tâm nar nây, “phung du druh tang tat ueh jêh ri phung bu klâu ndăm mra khĭt huăr yor ji hir.$b$,true),
('bunong-vn','AMO',8,14,null,$b$Lĕ rngôch phung sơm săk ma brah Asima n'gor Samari, jêh ri lah, ‘Tĭng nâm brah may gŭ rêh, Hơi Dan,’ jêh ri ‘Tĭng nâm brah ƀon Bêr-Sêba gŭ rêh’ khân păng mra cha lôt jêh ri mâu mra dâk đŏng ôh.”$b$,true),
('bunong-vn','AMO',9,1,null,$b$Gâp saơ Kôranh Brah dâk ta meng nơng; jêh ri păng lah: “Dong ta chiông meh gâng jêh ri ntơng mpông ăn n'gơ, nchah khân păng hăch rhên ta klơ bôk phung ƀon lan; jêh ri gâp mra ƀư rai phung hôm klen ma đao, mâu geh ôh du huê tâm phung khân păng mra nchuăt du, mâu geh ôh tâm phung khân păng mra klaih.$b$,true),
('bunong-vn','AMO',9,2,null,$b$Nđâp tơ lah khân păng kuyh tât Ƀon Phung Khĭt, ti gâp mra klĕ ngluh khân păng; nđâp tơ lah khân păng hao ta klơ trôk gâp mra ntrŭnh khân păng tă bơh ntŭk nây.$b$,true),
('bunong-vn','AMO',9,3,null,$b$Nđâp tơ lah khân păng du krap tâm yôk Karmel, gâp mra joi sŏk lơi khân păng bơh ntŭk nây. Nđâp tơ lah khân păng pôn săk khân păng nơm bơh trôm măt gâp tâm dâng săt dak mƀŭt, ta nây gâp mra ntĭnh ma bêh jêh ri păng mra chôk khân păng.$b$,true),
('bunong-vn','AMO',9,4,null,$b$Nđâp tơ lah khân păng hăn jêng bună ta năp phung rlăng khân păng; ta nây gâp mra ntĭnh ma đao, hăn nkhĭt lơi khân păng, jêh ri gâp mra gŭ uănh ma khân păng, ŭch ƀư nau mhĭk mâu di nau ueh ôh.”$b$,true),
('bunong-vn','AMO',9,5,null,$b$Yor Kôranh Brah, Yêhôva ma phung ta han pah bi neh ntu jêh ri păng lêk ro, lĕ rngôch phung ƀon lan gŭ tâm păng mra klân rvê, lĕ bri dak mra hao lip ler nâm bu dak krong toyh jêh ri djoh hŭch nâm bu dak krong n'gor bri Êjipt.$b$,true),
('bunong-vn','AMO',9,6,null,$b$Nơm ndâk jrô Păng klơ phung trôk, jêh ri Păng ƀư jrô păng tâm dâng ta klơ neh ntu; Păng kuăl dak mƀŭt jêh ri tŏ ta klơ neh ntu. Amoh Păng jêng Yêhôva.$b$,true),
('bunong-vn','AMO',9,7,null,$b$Kôranh Brah Yêhôva lah: “Hơi phung kon sau Israel, mâu di hĕ gâp uănh khân may nâm bu kon sau phung Êthiôpi lĕ?” Mâu geh gâp hĕ ngluh khân may luh du tă bơh n'gor bri Êjipt, phung Philistin tă bơh bri Kăptôr jêh ri phung Siri tă bơh bri Kir?$b$,true),
('bunong-vn','AMO',9,8,null,$b$Aơ, trôm măt Kôranh Brah Yêhôva gŭ uănh ma ƀon bri hađăch geh nau tih aơ, jêh ri gâp mra ƀư rai lơi păng bơh klơ neh ntu; ƀiă lah gâp mâu mra ƀư rai ôh lĕ rngôch ngih Yakôb,” Yêhôva lah.$b$,true),
('bunong-vn','AMO',9,9,null,$b$“Yor lah aơ, gâp mra ntĭnh jêh ri nsiăng ngih Israel ta nklang mpôl băl bunuyh, nâm bu nsiăng ma dông n'hiăng ƀiă lah mâu geh du găr jê̆ mra tŭp ôh ta neh.$b$,true),
('bunong-vn','AMO',9,10,null,$b$Lĕ rngôch phung tih tâm phung ƀon lan gâp mra khĭt ma đao, geh phung lah, ‘Nau mhĭk mâu mra ban mâu lah tâm mâp đah he ôh.’$b$,true),
('bunong-vn','AMO',9,11,null,$b$“Tâm nar nây, gâp mra ndâk tay ngih bok Y-Đavit lĕ rlâm jêh, jêh ri kơi nkra đŏng ntŭk trôm bluh păng, jêh ri ndâk păng nâm bu rnôk kăl e,$b$,false),
('bunong-vn','AMO',9,12,null,$b$gay ma phung Êđôm hôm klen jêh ri lĕ rngôch phung mpôl bunuyh bu mra kuăl amoh gâp, Yêhôva jêng Nơm ƀư lôch lĕ ntil nau aơ, lah nau nây.$b$,false),
('bunong-vn','AMO',9,13,null,$b$Yêhôva lah: “Aơ, nar mra tât, tơ lah nơm kai mra tĭng ban nơm rek, jêh ri nơm jot play kriăk ƀâu tĭng ban nơm srih ntil. Phung yôk ăn truh dak play kriăk ƀâu njŭng, jêh ri păng mra hoch ma lĕ rngôch gôl yôk.$b$,true),
('bunong-vn','AMO',9,14,null,$b$Gâp mra njŭn leo bu nă phung ƀon lan Israel gâp plơ̆ sĭt, jêh ri khân păng mra ndâk ƀon toyh lĕ rai jêh, jêh ri gŭ ta nây. Khân păng ƀư đang play kriăk ƀâu jêh ri nhêt dak păng.$b$,true),
('bunong-vn','AMO',9,15,null,$b$Gâp mra tăm khân păng tâm bri khân păng nơm, rngôch bu mâu mra rôk lơi khân păng đŏng ôh bơh bri gâp ăn jêh ma khân păng.” Yêhôva Brah Ndu lah.$b$,true);
