insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'OBA', $b$Y-Apdia$b$, $b$["Ndrom Sămƀŭt Bơh", "Y-APDIA"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','OBA',1,1,null,$b$Nau Y-Apdia tâm saơ, Kôranh Brah Yêhôva lah ma bri Êđôm: He lĕ tăng nau mbơh tă bơh Yêhôva, jêh ri bu prơh hăn du huê nơm mbơh ta nklang phung mpôl băl bunuyh: Dâk hom khân may! He dâk hom rdâng tâm lơh đah păng!$b$,true),
('bunong-vn','OBA',1,2,null,$b$Aơ, gâp mra ăn may jêng jê̆ ta nklang phung mpôl băl bunuyh. May, bu tâm rmot hâu ngăn.$b$,true),
('bunong-vn','OBA',1,3,null,$b$Hơi nơm gŭ tâm trôm lŭ, nơm gŭ tâm ntŭk prêh, bunuyh lah tâm nuih n'hâm păng nơm, Mbu dơi nklơ̆ gâp tŭp ta neh? Nau sưr tă bơh nuih n'hâm may hŏ ndơm may nơm.$b$,true),
('bunong-vn','OBA',1,4,null,$b$Nđâp lah may mpăr ta klơ nâm bu klang, nđâp tơ lah may ƀư rsuăn may ta nklang phung mănh, gâp mra nklơ̆ may tă bơh ntŭk nây, Yêhôva Brah Ndu lah.$b$,true),
('bunong-vn','OBA',1,5,null,$b$Bunuyh ƀư rai yot mâm păng jêng! Tơ lah phung ntŭng mâu lah bunuyh pit ndô ndơ dôl măng văch ta may, mâu di hĕ khân păng mra ntŭng knŏng man tŏng ăp ma khân păng nơm? Tơ lah phung pĕ play kriăk ƀâu văch ma may, mâu di hĕ khân păng om bar pe rkŭm ma phung dônh?$b$,true),
('bunong-vn','OBA',1,6,null,$b$Ndơ Y-Êsau lĕ bu joi sek pit in jêh drăp păng!$b$,true),
('bunong-vn','OBA',1,7,null,$b$Lĕ rngôch phung tâm rnglăp đah may ndơm may nơm, mprơh may tât ta n'har bri; phung băl may dơi jêh đah may, phung mĭt jiăng may nsing lĕ sân jêh dăk tâm dâng may. Jêh ri may mâu gĭt vât ôh ma nau nây.$b$,true),
('bunong-vn','OBA',1,8,null,$b$Yêhôva lah: Mâu di hĕ tâm nar nây gâp mra ƀư rai phung blau mĭn bơh bri Êđôm, jêh ri nau blau mĭn tă bơh yôk Êsau?$b$,true),
('bunong-vn','OBA',1,9,null,$b$Phung janh ktang may mra uh ah, hơi bri Têman, phung ta han tâm lơh bu mra ƀư rai tă bơh yôk Êsau ma nau nkhĭt.$b$,true),
('bunong-vn','OBA',1,10,null,$b$Yor ma nau djơh, nau mhĭk may hŏ ƀư jêh ma oh may Y-Yakôb, nau prêng mra nkŭm may, jêh ri bu mra ƀư rai may ƀa ƀơ n'ho ro!$b$,true),
('bunong-vn','OBA',1,11,null,$b$Ta nar may hŏ ƀư jêh nau mâu chrê ôh, ta nar phung bu năch pit in drăp ndơ păng, jêh ri phung bu năch lăp tâm mpông pêr păng jêh ri ƀư nau tâm nchroh ma ƀon Yêrusalem, may jêng nâm bu du huê tâm phung khân păng.$b$,true),
('bunong-vn','OBA',1,12,null,$b$Ƀiă lah lĕ tih jêh nau may n'hơm trôm măt may tâm nar oh may geh nau rêh ri; tih jêh may sưr tâm nar khân păng uh ah.$b$,true),
('bunong-vn','OBA',1,13,null,$b$Tih jêh nau may lăp tâm mpông pêr ƀon lan gâp tâm nar khân păng rai lôch; tih jêh may sưr yor nau rêh ni khân păng, tâm nar khân păng rêh ni;$b$,false),
('bunong-vn','OBA',1,14,null,$b$tih nau may gŭ ta rdjŭm nglah trong ŭch nkhĭt phung khân păng nchuăt du; tih jêh nau may jao phung păng klaih tâm nar nau uh ah.$b$,false),
('bunong-vn','OBA',1,15,null,$b$Yor lah nar Yêhôva dăch tât jêh ma lĕ rngôch mpôl băl bunuyh. Bu mra ƀư ma may nâm bu may hŏ ƀư jêh ma bu, kan may hŏ ƀư jêh mra mplơ̆ sĭt ta klơ bôk may nơm.$b$,true),
('bunong-vn','OBA',1,16,null,$b$Yor lah nâm bu may hŏ nhêt jêh ta klơ yôk kloh ueh gâp, tâm ban nây lĕ rngôch mpôl băl bunuyh gŭ jŭm may mra nhêt. Khân păng mra nhêt jêh ri plơ̆ nhêt đŏng, jêh ri mra jêng nâm bu khân păng ê hŏ mâp jêng ôh.$b$,true),
('bunong-vn','OBA',1,17,null,$b$Ƀiă lah mra geh phung klaih gŭ ta yôk Siôn, yôk nây mra jêng kloh ueh; jêh ri ngih Yakôb mra geh bri ma khân păng nơm đŏng.$b$,true),
('bunong-vn','OBA',1,18,null,$b$Ngih Yakôb mra jêng ŭnh, jêh ri ngih Yôsep mpiăt ŭnh, ngih Êsau mra jêng rhe; khân păng mra su jêh ri ŭnh sa ngih Êsau, jêh ri mâu mra hôm klen du huê hôm e rêh ôh tâm ngih Êsau, yor lah Yêhôva ngơi jêh nau nây.$b$,true),
('bunong-vn','OBA',1,19,null,$b$Phung tă bơh bri rđŭng mra sŏk ndơn yôk Êsau, jêh ri phung tă bơh neh lâng mra sŏk ndơn bri Philistin; khân păng mra sŏk ndơn bri Êphraim jêh ri bri Samari, jêh ri phung Benjamin mra sŏk ndơn bri Galaat.$b$,true),
('bunong-vn','OBA',1,20,null,$b$Phung Israel hŏ hăn jêh jêng bună tă bơh ƀon Yêrusalem gŭ tâm bri Sarepta; jêh ri phung hăn jêng bună tă bơh ƀon Yêrusalem gŭ tâm bri Sêpharat mra sŏk ndơn ƀon tâm bri rđŭng.$b$,true),
('bunong-vn','OBA',1,21,null,$b$Phung tâm rklaih mra hao yôk Siôn gay chiă uănh yôk Êsau. Jêh ri ƀon bri hađăch mra jêng ndơ Yêhôva.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','OBA',1,1,0,'heading',$b$Nau Mbơh Lor Ma Nau Êđôm Roh Rai$b$),
('bunong-vn','OBA',1,17,1,'heading',$b$Nau Ƀư Bah N'gor Bri Israel$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'JON', $b$Y-Yôna$b$, $b$["Ndrom Sămƀŭt Bơh", "Y-YÔNA"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','JON',1,1,null,$b$Yêhôva ngơi ma Y-Yôna, kon bu klâu, Y-Amitai, lah:$b$,true),
('bunong-vn','JON',1,2,null,$b$“Dâk hăn hom may! Rlet ma ƀon Ninivơ, ƀon toyh nây, jêh ri may nter tâm rdâng đah păng, yor lah gâp gĭt nau djơh, nau mhĭk khân păng hao jêh tât ma gâp.”$b$,false),
('bunong-vn','JON',1,3,null,$b$Ƀiă lah Y-Yôna dâk hăn du ndĕ ma bri Tarsis pôn krap bơh pa năp măt Yêhôva. Păng hăn jŭr ta ƀon Jôpa, jêh ri saơ du mlâm (du bôk) Kŭmpăn hăn ma bri Tarsis; pô ri păng nkhôm jêh ri ncho, gay hăn ndrel khân păng ma bri Tarsis, du ndĕ bơh pa năp Yêhôva.$b$,true),
('bunong-vn','JON',1,4,null,$b$Ƀiă lah Yêhôva njuăl phŭt toyh ta dak mƀŭt, jêh ri dak mƀŭt rbuh kŏ tât Kŭmpăn bơi chah.$b$,true),
('bunong-vn','JON',1,5,null,$b$Phung rmăk ƀĭt kŭmpăn klach, jêh ri ăp nơm nter vơl ma brah păng nơm; jêh ri khân păng mƀăr lơi ndơ kŭmpăn rdeng tâm dak mƀŭt gay ma n'gơch kŭmpăn. Ƀiă lah Y-Yôna trŭnh hăn jêh tâm trôm săt kŭmpăn jêh ri lâng bêch.$b$,false),
('bunong-vn','JON',1,6,null,$b$Pô ri kôranh kŭmpăn hăn ma păng jêh ri lah, “Moh may ƀư, Hơi nơm gŭ bêch? Dâk hom may, kuăl brah may! Nanê̆ brah nây mra mĭn ma he ƀă ŭch ma he mâu mra rai ôh.”$b$,false),
('bunong-vn','JON',1,7,null,$b$Jêh ri khân păng tâm lah ndrăng khân păng, “Kay lŏng, ăn he tâm nchroh gay gĭt mbu yor, nơm geh nau mhĭk aơ tât ma he.” Pô ri khân păng tâm nchroh, jêh ri nau nchroh di ma Y-Yôna.$b$,false),
('bunong-vn','JON',1,8,null,$b$Pô ri khân lah ma ô băl, “Mbơh hom ma hên yor mbu nơm nau mhĭk aơ tât? Moh nau kan may? Jêh ri mbah tă may?”$b$,true),
('bunong-vn','JON',1,9,null,$b$Ô băl plơ̆ lah ma khân păng, “Gâp jêng du huê Hêbrơ, jêh ri gâp klach yơk ma Yêhôva Brah Ndu klơ trôk, nơm njêng dak mƀŭt jêh ri neh sơh.”$b$,true),
('bunong-vn','JON',1,10,null,$b$Jêh ri phung nây klach ngăn jêh ri lah ma ô băl, Moh nau aơ may hŏ ƀư jêh? Yor lah khân păng gĭt jêh ô băl du ndĕ tă bơh Yêhôva, yor lah păng hŏ nkoch jêh ma khân păng.$b$,false),
('bunong-vn','JON',1,11,null,$b$Jêh ri khân păng ôp ô băl, “Mâm nau hên mra ƀư ma may gay ma dak mƀŭt dơi gŭ rngân ma he?” Yor lah dak mƀŭt rbuh lơ hâu ktang lơn.$b$,false),
('bunong-vn','JON',1,12,null,$b$Ô băl lah ma khân păng, “Sŏk hom gâp jêh ri mƀăr gâp tâm nklang dak mƀŭt, rnôk nây dak mƀŭt mra gŭ rngân ma khân may; Yor lah gâp gĭt yor gâp yơh phŭt toyh chuănh aơ tât ma khân may.”$b$,false),
('bunong-vn','JON',1,13,null,$b$Ƀiă lah phung bu nuyh nây ƀĭt vah kŭmpăn ma nau hŏt ngăn gay mplơ̆ kŭmpăn sĭt rlet ma kơh, ƀiă lah khân păng mâu dơi ôh, yor lah dak mƀŭt rbuh lơ hâu ktang lơn.$b$,true),
('bunong-vn','JON',1,14,null,$b$Yor nây khân păng nter ma Yêhôva, “Ơ Yêhôva, hên vơh vơl ma may lơi ăn hên rai lôch yor nau rêh bu nuyh aơ, jêh ri lơi ta ntŭp ma hên mham mâu geh tih ôh; yor lah may. Ơ Yêhôva hŏ ƀư jêh nau ƀư maak ma may.”$b$,false),
('bunong-vn','JON',1,15,null,$b$Pô ri khân păng sŏk Y-Yôna mƀăr păng tâm dak mƀŭt; jêh ri dak mƀŭt rngân mâu hôm rbuh ktang ôh.$b$,false),
('bunong-vn','JON',1,16,null,$b$Rnôk nây phung bunuyh nây klach hâu ngăn ma Yêhôva, jêh ri nhhơr ndơ nhhơr ƀư brah ma Yêhôva jêh ri ƀư nau ton ma Yêhôva.$b$,true),
('bunong-vn','JON',1,17,null,$b$Jêh ri Yêhôva rơm du mlâm ka toyh ăn rvăn Y-Yôna; jêh ri Y-Yôna gŭ tâm ndŭl ka pe nar pe năng. Nau Y-Yôna Mbơh Sơm Tâm Rnê$b$,false),
('bunong-vn','JON',2,1,null,$b$Jêh ri Y-Yôna mbơh sơm ma Yêhôva Brah Ndu păng tă bơh ndŭl ka,$b$,true),
('bunong-vn','JON',2,2,null,$b$lah: Găp kuăl ma Yêhôva tâm nau rêh ni gâp, jêh ri păng plơ̆ sĭt lah ma gâp. Tă bơh ndŭl Ƀon Phung Khĭt gâp nter, jêh ri may tăng jêh bar gâp.$b$,false),
('bunong-vn','JON',2,3,null,$b$Yor lah may hŏ mƀăr jêh gâp tâm ntŭk jru, ta nklang dak mƀŭt, jêh ri dak nkŭm jŭm gâp. Lĕ rngôch mpiăt dak jêh ri dak rbuh may rgăn jêh ta klơ gâp.$b$,true),
('bunong-vn','JON',2,4,null,$b$Rnôk nây gâp lah, Bu mƀăr gâp tă bơh pa năp may; ƀiă lah ăt gâp mra plơ̆ uănh đŏng ma ngih kloh ueh may.$b$,true),
('bunong-vn','JON',2,5,null,$b$Dak văch nkŭm bơi ŭch nkhĭt gâp, ntŭk jru gŭ jŭm gâp; mbrĭng dak lĕ put bôk gâp.$b$,true),
('bunong-vn','JON',2,6,null,$b$Gâp hŏ jŭr jêh tât mbon jâng yôk; Neh hŏ sŏk rnăng păng rdâl ta klơ gâp n'ho ro ƀiă lah may sâm mphâk nau rêh gâp tă bơh Trôm Jru, Ơ Yêhôva Brah Ndu gâp.$b$,true),
('bunong-vn','JON',2,7,null,$b$Tơ lah huêng gâp lĕ huơi jêh tâm trôm gâp, gâp kah gĭt ma Yêhôva; jêh ri nau gâp mbơh sơm tât jêh ma may tâm ngih kloh ueh may.$b$,true),
('bunong-vn','JON',2,8,null,$b$Phung yơk ma rup brah ndơ mâu khlay, pô ri cha lơi nau bu yô̆ klâng ma khân păng.$b$,true),
('bunong-vn','JON',2,9,null,$b$Ƀiă lah gâp mra tâm rnê ma may gâp mra nhhơr ndơ ƀư brah ma may; moh nau gâp ton jêh gâp mra ƀư ngăn. Nau tâm rklaih luh tă bơh Yêhôva!$b$,true),
('bunong-vn','JON',2,10,null,$b$Pô ri Yêhôva ntăm ma ka jêh ri ô băl hok lơi Y-Yôna ta neh sơh.$b$,true),
('bunong-vn','JON',3,1,null,$b$Nau Yêhôva ngơi ma Y-Yôna tơ̆ bar, lah;$b$,true),
('bunong-vn','JON',3,2,null,$b$“Dâk hom may, hăn rlet ma Ninivơ, ƀon toyh nây, jêh ri mbơh ma păng nau nti gâp mra tâm mpơl ma may.”$b$,false),
('bunong-vn','JON',3,3,null,$b$Pô ri Y-Yôna dâk jêh ri hăn ma ƀon Ninivơ tĭng nâm nau Yêhôva ngơi. Ƀon Ninivơ jêng ƀon toyh ngăn, bu dơi hăn tâm pe nar hăn trong.$b$,false),
('bunong-vn','JON',3,4,null,$b$Y-Yôna ntơm lăp tâm ƀon nây du nar hăn. Păng nter lah, “Hôm puăn jât nar jêh ri bu mra ƀư rai ƀon Ninivơ!”$b$,false),
('bunong-vn','JON',3,5,null,$b$Phung ƀon lan Ninivơ chroh ma Brah Ndu lah, khân păng ntĭnh du nau ât sông sa, jêh ri nsoh ao ƀau, ntơm bơh bu ranh ngăn tât ma kon se jê̆ lơn tâm khân păng.$b$,true),
('bunong-vn','JON',3,6,null,$b$Nau mhe mhan nây tât ma hađăch ƀon toyh Ninivơ, păng dâk tă bơh sưng hađăch păng doh lơi ao jâr păng, nsoh ƀau, jêh ri gŭ tâm ŭnh buh.$b$,true),
('bunong-vn','JON',3,7,null,$b$Păng ăn nau ntăm jêh ri njuăl sămƀŭt ntăm nây lam ƀon Ninivơ, “Tĭng nâm nau hađăch jêh ri phung kôranh ntăm pô aơ: Lơi ta ăn bunuyh mâu lah mpô mpa, ndrôk mâu lah biăp, be chiăm lep du ntil ndơ ôh; lơi ăn khân păng sông sa mâu lah nhêt dak ôh,$b$,false),
('bunong-vn','JON',3,8,null,$b$ƀiă lah ăn phung bunuyh nđâp ma mpô mpa nsoh ƀau da dê, jêh ri ăn lĕ rngôch mbơh sơm ma lĕ nuih n'hâm ma Brah Ndu, n'hêl nanê̆ ăn ăp nơm cha lơi trong mhĭk jêh ri nau kue.$b$,false),
('bunong-vn','JON',3,9,null,$b$Mbu gĭt, mâu lah Brah Ndu mra tâm rgâl nau mĭn jêh ri lơi lĕ nau păng ji nuih, gay ma he lơi geh nau roh yot ôh?”$b$,false),
('bunong-vn','JON',3,10,null,$b$Tơ lah Brah Ndu saơ nau khân păng ƀư, nau khân păng cha lơi lĕ trong mhĭk khân păng, Brah Ndu tâm rgâl nau mĭn jêh ri mâu ƀư ôh nau mhĭk păng lah jêh mra ƀư ma khân păng.$b$,true),
('bunong-vn','JON',4,1,null,$b$Ƀiă lah nau nây mâu maak ma Y-Yôna ôh, jêh ri păng ji nuih.$b$,true),
('bunong-vn','JON',4,2,null,$b$Păng mbơh sơm ma Yêhôva, lah: “Gâp vơh vơl ma may, Ơ Yêhôva mâu di hĕ nau aơ gâp hŏ lah jêh dôl gâp ăt hôm gŭ tâm bri gâp? Yor nây yơh gâp ndal hăn du ma bri Tarsis; yor lah gâp gĭt may jêng Brah Ndu gĭt nau ueh, blau yô̆, mâu gơnh ji nuih ôh, bêng ma nau ueh, jêh ri tâm rgâl nau mĭn mâu ƀư nau mhĭk ôh.$b$,false),
('bunong-vn','JON',4,3,null,$b$Yor nây aƀaơ aơ, Ơ Yêhôva, gâp vơl ma may, nkhĭt hom gâp, ueh lơn gâp khĭt ma đah gŭ rêh.”$b$,false),
('bunong-vn','JON',4,4,null,$b$Yêhôva lah, “Tơ lah may ji nuih jêng nau may ƀư di lĕ?”$b$,true),
('bunong-vn','JON',4,5,null,$b$Jêh ri Y-Yôna luh du tă bơh ƀon toyh, jêh ri ta nây păng ƀư du mlâm ndưp ma păng nơm. Păng gŭ nde ta nâm n'hâm păng, kŏ tât păng saơ moh nau mra tât ma ƀon nây.$b$,true),
('bunong-vn','JON',4,6,null,$b$Jêh ri Yêhôva Brah Ndu ăn du n'gâng tơm si chăt n'ha, jêh ri ăn păng prêh nkâm ta klơ Y-Yôna, gay geh n'hâm si ta klơ bôk păng, gay rklaih păng tă bơh nau păng rgel rgănh. Pô ri Y-Yôna maak hâu ngăn yor tơm si nây.$b$,false),
('bunong-vn','JON',4,7,null,$b$Ƀiă lah Tơ lah tât ang ôi, Brah Ndu ăn du mlâm ndrŭng ƀư ma tơm si nây, pô ri păng nhop klêu.$b$,true),
('bunong-vn','JON',4,8,null,$b$Tơ lah luh nar, Brah Ndu ăn sial duh tă pa lơ khôm, jêh ri nar nđat duh ta klơ bôk Y-Yôna kŏ tât păng huơi. Jêh ri păng dăn ŭch khĭt, yor lah păng lah: “Ueh lơn gâp khĭt đah gŭ rêh.”$b$,false),
('bunong-vn','JON',4,9,null,$b$Ƀiă lah Brah Ndu lah ma Y-Yôna, “Tơ lah may nuih yor tơm si nây, lĕ nau may ƀư di lĕ?” Păng lah, “Jêng nau di yơh tơ lah gâp ji nuih, nuih tât khĭt.”$b$,true),
('bunong-vn','JON',4,10,null,$b$Yêhôva lah, “May yô̆ ma tơm si may mâu mâp pah kan ôh, mâu lĕ may mâp ăn păng hon. Ô băl chăt hon du năng, jêh ri ô băl rai lôch tâm du năng lĕ.$b$,false),
('bunong-vn','JON',4,11,null,$b$Mâu di hĕ gâp yô̆ ma ƀon Ninivơ, ƀon toyh nây, tâm ƀon nây geh rmeh ma du rsen bar rmưn bunuyh mâu gĭt nau êng ôh ti pa ma đah ti pa chiau, jêh ri tâm ban lĕ geh âk mpô mpa-mâu lah mâu?”$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','JON',1,1,0,'heading',$b$Y-Yôna Du Tă Bơh Yêhôva$b$),
('bunong-vn','JON',3,1,0,'heading',$b$Nau Phung Ninivơ Rmal Ma Nau Tih$b$),
('bunong-vn','JON',4,1,0,'heading',$b$Nau Y-Yôna Mâu Maak Ôh Jêh Ri Nau Brah Ndu Yô̆$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'MIC', $b$Y-Mika$b$, $b$["Ndrom Sămƀŭt Bơh", "Y-MIKA"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','MIC',1,1,null,$b$Nau Yêhôva ngơi lah ma Y-Mika, bunuyh ƀon Môrêset, tâm rnôk Y-Jôtham, Y-Ahas, jêh ri Y-Hêsêkia, phung hađăch n'gor Yuđa, jêng nau păng tâm saơ di ma ƀon Samari jêh ri ƀon Yêrusalem.$b$,true),
('bunong-vn','MIC',1,2,null,$b$Hơi lĕ rngôch phung ƀon lan, iăt hom! Hơi neh ntu jêh ri lĕ rngôch ndô ndơ tâm păng, rkêng tôr iăt hom! Dăn ăn Kôranh Brah Yêhôva tă bơh ƀon kloh ueh Păng, jêng nơm mbơh nau tâm rdâng đah khân may!$b$,true),
('bunong-vn','MIC',1,3,null,$b$Yor lah, aơ, Yêhôva du luh tă bơh ntŭk păng gŭ, jŭr jêh ri jot ta ntŭk prêh tâm neh ntu.$b$,true),
('bunong-vn','MIC',1,4,null,$b$Lĕ yôk yang mra roh rai tâm dâng jâng Păng, lĕ rlŭng mra lêk hăch nâm bu jrêng bu nđông ma ŭnh, nâm bu dak hoch njŭr sop,$b$,true),
('bunong-vn','MIC',1,5,null,$b$Lĕ rngôch nau nây mra tât yor ma Yakôp rlau nau vay, jêh ri yor nau tih ngih Israel. Moh nau Yakôp dĭng rlau nau vay? Mâu di nây jêng ƀon Samari? Mbu jêng lĕ ntŭk prêh phung Yuđa? Mâu di hĕ nây jêng ƀon Yêrusalem?$b$,false),
('bunong-vn','MIC',1,6,null,$b$Yor nây gâp mra ăn ƀon Samari jêng nâm bu du mbŭch rsong chah bun nklang bri; nâm bu du ntŭk bu tăm tơm play kriăk ƀâu; jêh ri gâp tuh rsong lŭ păng tâm rlŭng, jêh ri lĕ rngôch mbon păng mpơl pa dih.$b$,true),
('bunong-vn','MIC',1,7,null,$b$Lĕ rngôch rup trah mra chah hăch rhên, lĕ rngôch rnoh nkhôm păng mra su tâm ŭnh. Jêh ri gâp mra ƀư rai lơi lĕ rngôch ƀhiau rup brah păng. Yor lah păng hŏ sŏk dơn ndơ nây ma rnoh nkhôm tă bơh nau văng tĭr, pô ri păng mra dŏng ndơ nây ƀư rnoh nkhôm ăn du huê bu ur văng tĭr.$b$,true),
('bunong-vn','MIC',1,8,null,$b$Yor nây gâp mra nter vơl jêh ri nhĭm nhhiăng, jêh ri gâp mra chuat jâng dơm, hăn săk hưl. Gâp nhhiăng nhĭm mblu nâm bu so bri, jêh ri nhĭm rêng nâm bu chui (sĭm ôtrus).$b$,true),
('bunong-vn','MIC',1,9,null,$b$Yor lah ntŭk têl rmanh păng mâu blau jĭr ôh, jêh ri nau sôt nây trêng tât n'gor Yuđa tâm ban lĕ, tât jêh ta mpông pêr phung ƀon gâp ta ƀon Yêrusalem.$b$,true),
('bunong-vn','MIC',1,10,null,$b$Lơi ta nkoch ôh nau tât aơ tâm ƀon Gat, lơi ta nhĭm nhhiăng ôh. Ta ƀon Bet-Lê-Aphra, gâp rlĭ-rlang tâm neh muy.$b$,true),
('bunong-vn','MIC',1,11,null,$b$Hơi phung gŭ tâm ƀon Saphir, gŭ rhôk hom dơn nau bêk prêng, dĭng hăn rgăn! Phung gŭ tâm ƀon Sanan mâu dơi geh du luh ôh. Phung ƀon Bet-Êsel gŭ nhĭm nhhiăng, ăn ma khân may mâu hôm geh ntŭk nde krap.$b$,true),
('bunong-vn','MIC',1,12,null,$b$Yor lah phung ƀon lan gŭ ta ƀon Marôt rdja ngăn dôl kâp gân nau ueh, yor lah nau rêh ni jŭr jêh tă bơh Yêhôva hŏ tât ta ƀon Yêrusalem.$b$,true),
('bunong-vn','MIC',1,13,null,$b$Hơi phung gŭ ta ƀon Lakis, sŏk hom seh gơnh kât ta ndeh, tă khân may yơh jêng tơm ăn kon bu ur ƀon Siôn ƀư tih; yor lah nau tih mhĭk phung Israel bu saơ tă tâm may.$b$,true),
('bunong-vn','MIC',1,14,null,$b$Yor nây, may mra ăn ndơ nhhơr ma ƀon Môrêset-Gat dôl may dâk hăn; phung ƀon lan Aksip mra jêng ndơ ndơm ma phung hađăch Israel.$b$,true),
('bunong-vn','MIC',1,15,null,$b$Hơi phung gŭ tâm ƀon Marêsa, gâp mra leo du huê bunuyh ndơn drăp may tât ma may; nau chrêk ma lơp phung Israel mra tât ta ƀon Adulam.$b$,true),
('bunong-vn','MIC',1,16,null,$b$Kreh plưn hom bôk sŏk (sŏk) may, yor ma kon may rŏng; di jêh, ƀư plưn hom bôk may nâm bu klang, yor lah lĕ rngôch khân păng nkhah du đah may hăn ƀư bună da dê.$b$,true),
('bunong-vn','MIC',2,1,null,$b$Rêh ni ngăn ma phung nchră ŭch ƀư nau kue jêh ri mĭn ŭch ƀư nau mhĭk gŭ ta klơ sưng bêch păng, jêh ri tât ang ôi khân păng ƀư ro nau khân păng hŏ mĭn; yor lah khân păng geh nau ktang dơi ƀư nau nây!$b$,true),
('bunong-vn','MIC',2,2,null,$b$Khân păng kơnh neh mir pit in ro, khân păng kơnh ngih vâl jêh ri sŏk gŭ ro. Khân păng sŏk gro drăp ndơ bu, nâm bu ntĭt bunuyh bunun jêh ri drăp ndơ khân păng đŏng.$b$,true),
('bunong-vn','MIC',2,3,null,$b$Yor nây, Yêhôva lah pô aơ: “Aơ, gâp mĭn ŭch ƀư mhĭk ma mpôl băl aơ, du nau rêh ni nây khân may mâu dơi du klaih ôh, jêh ri khân may mâu mra ngơk bôk chuat hăn đŏng ôh; yor lah nây jêng rnôk rêh ni ngăn.$b$,true),
('bunong-vn','MIC',2,4,null,$b$Tâm nar nây, bu mra rŏ du nau ntĭt ndrĭng gơm mưch ma khân may, jêh ri rŏ nau mprơ nhĭm vơl rngot ngăn ngên jêh ri lah: ‘He rai yot lĕ rngôch jêh! Păng tâm rgâl kô̆ neh gŭ chăm phung ƀon lan gâp, gay sŏk lơi tă bơh gâp, sŏk neh mir gâp jêh nây tâm pă ăn ma phung ƀlêp ƀlêr.’ ”$b$,true),
('bunong-vn','MIC',2,5,null,$b$Yor nây tâm phung Yêhôva tâm rƀŭn, may mâu mra geh du huê bunuyh ôh gay nthăng rse tâm pă neh.$b$,true),
('bunong-vn','MIC',2,6,null,$b$Khân păng mbơh lor pô aơ: “Khân may lơi ta mbơh lor.” “Khân păng mâu mra mbơh lor ôh đah phung bunuyh aơ: Nau bêk prêng mâu blau bah ôh.$b$,true),
('bunong-vn','MIC',2,7,null,$b$Hơi ngih Yakôp! Di lĕ bu lah nau aơ, “Brah Yêhôva dơi hŭnh lĕ mâu? Di lĕ pô aơ nau păng ƀư?” Di lĕ ƀơh nau gâp ngơi ƀư ueh ma nơm chuat hăn ma nau sŏng?$b$,true),
('bunong-vn','MIC',2,8,null,$b$Ƀiă lah phung ƀon lan gâp du dâk ƀư nâm bu du huê rlăng. Phung bunuyh hăn rgăn ma nau ueh mpăn, mâu ŭch ôh ma nau tâm lơh, pô ri khân may doh pit lơi ao jâr khân păng, knŏng hôm e ăn ao ta săk.$b$,true),
('bunong-vn','MIC',2,9,null,$b$Khân may mprơh du lơi phung bu ur ƀon lan gâp tă bơh ngih ueh maak khân păng; jêh ri khân may sŏk lơi nau chrêk rmah gâp tă bơh phung kon khân păng n'ho ro.$b$,true),
('bunong-vn','MIC',2,10,null,$b$Dâk hom khân may jêh ri hăn ro! Yor lah ta aơ mâu di jêng ntŭk ma khân may gŭ rlu ôh; yor lĕ tă bơh nau ƀơ̆ ƀơch ƀư rai roh jêh, jêng nau rai roh ngăn ngên.$b$,true),
('bunong-vn','MIC',2,11,null,$b$Tơ lah geh bunuyh tĭng ndô̆ nau dơm dam, jêh ri ngơi mƀruh lah: Gâp mra mbơh lor ma may ma nau ndrănh jêh ri ndrănh ktang, nây jêng nơm mbơh lor khư ma phung tâm ƀon lan aơ!$b$,true),
('bunong-vn','MIC',2,12,null,$b$“Hơi Yakôp! N'hêl nanê̆ gâp mra tâm rƀŭn lĕ rngôch phung may, Nanê̆ ngăn gâp mra rgum lĕ đơ phung Israel hôm e, jêh ri dơm ăn khân păng gŭ nsum nâm bu phung biăp âk tâm du ndrung, nâm bu du phung biăp tâm ndrêch khân păng, nây mra geh bâr ngơi n'gôr phung bunuyh âk.$b$,true),
('bunong-vn','MIC',2,13,null,$b$Bunuyh blŏng trong hăn lor ma khân păng. Khân păng rduh ran tât ta mpông pêr jêh ri luh du ta nây. Hađăch khân păng hăn rgăn lor ma khân păng, jêng Yêhôva nơm njŭn trong,”$b$,true),
('bunong-vn','MIC',3,1,null,$b$Nây dĭng gâp lah: “Iăt hom, Hơi phung kôranh Yakôp jêh ri khân may jêng bunuyh chiă uănh ngih Israel! Mâu di hĕ nau nây gay ăn khân may gĭt nau sŏng?$b$,true),
('bunong-vn','MIC',3,2,null,$b$Pô nây, khân may ji nuih đah nau ueh, ŭch ma nau mhĭk; n'huk ntâu phung aơ jêh ri tah doih puăch tâm nting khân păng,$b$,true),
('bunong-vn','MIC',3,3,null,$b$khân may sa puăch phung ƀon lan gâp, chroi ntâu khân păng, choh hăch nting khân păng, jêh ri siăt rhên nâm bu puăch tâm trôm glah, nâm bu puăch tâm glah ƀŭng.$b$,false),
('bunong-vn','MIC',3,4,null,$b$Rnôk nây khân păng mra nter vơl ma Yêhôva, ƀiă lah păng mâu mra plơ̆ sĭt lah ôh ma khân păng. Ngăn yơh, Păng mra pôn muh măt ma khân păng dôl nôk nây tĭng nâm nau mhĭk khân păng hŏ ƀư jêh.$b$,true),
('bunong-vn','MIC',3,5,null,$b$Aơ jêng nau Yêhôva ngơi lah ma lĕ phung kôranh nơm mbơh lor, ƀư vĭ nhhơt trong ăn ma ƀon lan gâp, jêng phung kăp sêk neng khân păng nơm, jêh ri lah: “Nau đăp mpăn.” Tơ lah mâu geh ndơ gĭnh tâm trôm mbung khân păng, pô ri jêng ndrăp nkra ma nau tâm lơh đah nơm mâu ăn ndơ sông sa ma khân păng.$b$,true),
('bunong-vn','MIC',3,6,null,$b$Yor nây, bri măng ngo klĕng mra nkŭm khân may mâu geh nau mpơl dơi saơ tâm ntŭk ndâp ôh; mâu hôm dơi mbơh lor ôh. Măt nar mra tŭp ta klơ phung kôranh nơm mbơh lor nây, jêh ri nôk nar mra ngo jŭm khân păng.$b$,true),
('bunong-vn','MIC',3,7,null,$b$Phung lĕ tă tâm saơ mra prêng, jêh ri phung mbơh lor bu mra ntêh rmot. Lĕ rngôch khân păng mra rdêp mbung nơm, yor lah mâu hôm geh nau plơ̆ lah ôh tă bơh Brah Ndu.$b$,true),
('bunong-vn','MIC',3,8,null,$b$Ƀiă lah bi ma gâp, gâp bêng ler ma nau dăng ktang, nau phat dôih, jêh ri nuih n'hâm janh bơh Brah Huêng ueh Yêhôva, gay mbơh ma phung Yakôp ma nau khân păng rlau nau vay, jêh ri ma phung Israel nau tih khân păng.$b$,true),
('bunong-vn','MIC',3,9,null,$b$Hơi phung kôranh ngih Yakôp, jêh ri khân may phung chiă uănh ngih Israel, iăt hom nau aơ, khân may tâm rmot nau di nanê̆ ngăn, jêh ri nsŭk bu ƀư tih lĕ nau sŏng srăng.$b$,true),
('bunong-vn','MIC',3,10,null,$b$Khân may ndâk ƀon Siôn ma nau pling mham jêh ri ƀon Yêrusalem ma nau kue.$b$,true),
('bunong-vn','MIC',3,11,null,$b$Phung kôranh phat dôih yor drăp bu blŏl phung kôranh ƀư brah păng nti yor rnoh bu nkhôm, phung kôranh nơm mbơh lor hăn mbơh lor yor ma prăk; jêh nây khân păng nsing ma Yêhôva pô aơ: “Mâu hĕ di Yêhôva gŭ ta nklang he? Mâu geh nau mhĭk ôh mra tât ma he.”$b$,true),
('bunong-vn','MIC',3,12,null,$b$Pô nây, yor khân may bu mra chuar rlơk yôk Siôn nâm bu lôk mir; ƀon Yêrusalem mra jêng du mbŭch rsong lĕ rai jêh, jêh ri yôk ngih brah mra jêng yôk tâm krŏng.$b$,true),
('bunong-vn','MIC',4,1,null,$b$Mra tât tâm rnôk nglĕ dŭt yôk ngih brah Yêhôva bu mra ndâk ăn jêng yôk prêh lơn, jêh ri n'hao păng ta klơ lơn ma lĕ rngôch gôl yôk, jêh ri lĕ rngôch phung ƀon lan hăn ran ma păng.$b$,true),
('bunong-vn','MIC',4,2,null,$b$Geh âk n'gor bri mra văch tât ta nây, jêh ri lah: “Kay lŏng, hao hom he ta klơ yôk Yêhôva, ntŭk ngih Brah Ndu Yakôp.” Gay na Păng mra nti ma he trong Păng, jêh ri he mra dơi chuat hăn tâm trong Păng.” Yor lah nau vay tă luh bơh yôk Siôn, jêh ri nau Yêhôva ngơi luh bơh ƀon Yêrusalem.$b$,true),
('bunong-vn','MIC',4,3,null,$b$Yor lah Păng mra phat dôih ta nklang âk ntil mpôl bunuyh, jêh ri phat dôih ma phung mpôl băl bunuyh gŭ ngai; jêh ri khân păng mra sŏk đao chiăr njêng kau kai, sŏk tak chiăr njêng nhuĕ. Du mpôl băl bunuyh mâu hôm mra tŏk đao lơh đah du mpôl băl bunuyh êng ôh, mâu lĕ hôm khân păng nti tay nau tâm lơh.$b$,true),
('bunong-vn','MIC',4,4,null,$b$Ƀiă lah ăp nơm khân păng mra gŭ tâm dâng tơm play kriăk ƀâu păng jêh ri tâm dâng tơm play rvi păng, jêh ri mâu geh ôh nơm nkrit nhhu khân păng; yor lah trôm mbung Yêhôva ma phung ta han hŏ lah jêh nau nây.$b$,true),
('bunong-vn','MIC',4,5,null,$b$Yor lah lĕ rngôch ntil mpôl dơi chuat tâm amoh brah păng; jêh ri he mra chuat tĭng ndô̆ amoh Yêhôva Brah Ndu he ƀa ƀơ n'ho ro!$b$,true),
('bunong-vn','MIC',4,6,null,$b$Yêhôva lah, “Tâm nar nây, gâp mra rgum phung tơng glơt jâng, jêh ri rgum tay bunuyh bu hŏ mprơh du, jêh ri phung bunuyh gâp nkrit jêh.$b$,true),
('bunong-vn','MIC',4,7,null,$b$Jêh nây gâp mra dơm ăn phung tơng glơt jâng jêng phung hôm e klen, jêh ri ăn phung bu mprơh jêh jêng du mpôl băl janh ktang; jêh ri Yêhôva mra chiă uănh khân păng ta yôk Siôn ntơm bơh nây tât n'ho ro.$b$,true),
('bunong-vn','MIC',4,8,null,$b$Bi may, Hơi ngih tŭm ma phung biăp, yôk ma kon bu ur Siôn, nau chiă uănh tât đŏng ăn ma may, jêng ƀon bri hađăch kon bu ur ƀon Yêrusalem.”$b$,true),
('bunong-vn','MIC',4,9,null,$b$Ƀiă lah aƀaơ ri mâm ƀư may nter bâr huy ngăn? Mâu geh hađăch hĕ ta nklang may? Mâu lah bunuyh sâm nchră lĕ khĭt, kŏ tât may ji chuănh hâu ngăn nâm bu du huê bu ur ji deh?$b$,true),
('bunong-vn','MIC',4,10,null,$b$Hơi kon bu ur Siôn, mpât nter nâm bu bu klâu bu ur ji deh! Yor lah may mra du luh bơh ƀon toyh jêh ri may mra gŭ tâm mir, may mra hăn ta bri Babilôn. Ƀiă lah ta nây, bu mra koh dŏng may; ta nây yơh Yêhôva mra chuai may du luh tă bơh ti phung rlăng đah may.$b$,true),
('bunong-vn','MIC',4,11,null,$b$Aƀaơ ri geh âk ntil mpôl bunuyh lĕ rgum băl jêh ŭch tâm lơh đah may. Jêh ri lah: “Ƀư ƀơ̆ ƀơch hom khân păng, jêh ri ăn măt he uănh nau he ŭch leo ma ƀon Siôn.”$b$,true),
('bunong-vn','MIC',4,12,null,$b$Ƀiă lah khân păng mâu gĭt năl ôh nau mĭn Yêhôva, khân păng mâu gĭt rbăng ôh mbor kan Păng yor lah Păng hŏ rgum jêh khân păng nâm bu nchăp ba tât ta ntŭk bu mprah ba.$b$,true),
('bunong-vn','MIC',4,13,null,$b$Pô ri, Hơi kon bu ur ƀon Siôn, dâk mprah hom, yor lah gâp mra ăn ay geh nke loih jêh ri nchop kông; ay mra jot rchiăt âk phung ƀon lan, jêh ri gâp mra jao drăp ndơ khân păng ma Yêhôva, jêh ri nau ndrŏng kuăng khân păng ma kôranh Brah tâm lam neh ntu.$b$,true),
('bunong-vn','MIC',4,14,null,$b$Pô ri, hơi kon bu ur phung ta han, aƀaơ ri dăp hom phung ta han ay! Yor lah bu lĕ nchueng lơh he. Khân păng mra dong phung kôranh mât uănh phung Israel ta bom ma mâng.$b$,true),
('bunong-vn','MIC',5,1,null,$b$Hơi Ƀêtlehem Êphrata, nđâp tơ lah may jêng jê̆ lơn ta nklang mpôl băl n'gor Yuđa, tă bơh may du luh ma gâp du huê mra jêng kôranh chiă uănh tâm phung Israel, nơm jêng tơm bơh rnôk kăl e, bơh r'nôk sa ơm n'ho ro.$b$,true),
('bunong-vn','MIC',5,2,null,$b$Yor nây Păng mra jao khân păng kŏ tât rnôk bu ur ji deh hŏ deh jêh; jêh ri phung oh nâu Păng hôm e mra plơ̆ sĭt tay ma phung ƀon lan Israel.$b$,true),
('bunong-vn','MIC',5,3,null,$b$Păng mra gŭ nâp, jêh ri nsing nau ktang bơh Yêhôva ma nau rnam amoh Yêhôva Brah Ndu păng dơi mât chiă lĕ phung biăp păng; jêh ri khân păng gŭ đăp rmên, yor lah rnôk nây Păng mra jêng toyh tât ta bôl dŭt neh ntu.$b$,true),
('bunong-vn','MIC',5,4,null,$b$Ma Păng nây yơh mra ƀư nau đăp mpăn ma he. Tơ lah bunuyh Asiri mra lăp tâm bri he, jêh ri jot tâm pôih he, pô ri he mra du dâk pơh nuyh rmăk biăp, jêh ri pham nuyh phung kôranh tâm rdâng đah păng.$b$,true),
('bunong-vn','MIC',5,5,null,$b$Khân păng sŏk đao lơh rai bri dak Asiri, jêh ri lĕ mpông pêr bri Nimrôt; jêh ri Păng mra rklaih he tă bơh phung Asiri, tơ lah păng mra lăp tâm bri dak he jot tâm trôm n'har bri he.$b$,true),
('bunong-vn','MIC',5,6,null,$b$Rnôk nây phung hôm e klen bơh Yakôp mra gŭ ta nklang âk phung ƀon lan, nâm bu truh dak ngom văch tât bơh Yêhôva, nâm bu mih n'hach ta gơ̆ nse, jêh ri nâm bu ndơ mâu kâp geh bunuyh ôh, mâu lĕ njong nar ma phung kon bunuyh.$b$,true),
('bunong-vn','MIC',5,7,null,$b$Phung hôm e klen bơh Yakôp mra gŭ ta nklang phung mpôl băl bunuyh, jêh ri ta nklang âk phung ƀon lan, nâm bu yau mŭr ta nklang mpô mpa bri, jêh ri nâm bu kon yau mŭr ta nklang âk phung biăp, tơ lah păng rgăn, păng jot jêh ri sa hêk, mâu geh nơm dơi rklaih ôh.$b$,true),
('bunong-vn','MIC',5,8,null,$b$Ti Kôranh Brah yơr ƀư ma phung rlăng păng, jêh ri phung rlăng mra roh rai.$b$,true),
('bunong-vn','MIC',5,9,null,$b$Yêhôva lah: “Tâm nar nây geh nau tât, gâp mra ƀư rai lơi phung seh may jêh ri ndeh seh may bơh ta nklang may.$b$,true),
('bunong-vn','MIC',5,10,null,$b$Gâp mra ƀư rai ƀon toyh tâm bri may, jêh ri ƀư rlâm lơi lĕ rngôch pôih nâp may.$b$,true),
('bunong-vn','MIC',5,11,null,$b$Gâp mra ƀư rai lơi phung nau blau ƀŭk rƀên tă bơh may jêh ri may mâu hôm geh đŏng ôh phung n'hŭm.$b$,true),
('bunong-vn','MIC',5,12,null,$b$Gâp mra ƀư rai lơi rup brah jêh ri meh gâng trah rup brah bơh may, jêh ri khân may mâu mra chon mbah đŏng ôh pa năp ndơ ti may ƀư.$b$,true),
('bunong-vn','MIC',5,13,null,$b$Gâp mra rôk lơi rup brah Asêrim bơh ta nklang may, jêh ri ƀư rai ƀon toyh may.$b$,true),
('bunong-vn','MIC',5,14,null,$b$Gâp mra ƀư nau plơng bôk ma nau gâp nuih jêh ri ji nuih ma phung băl mpôl bunuyh mâu tông ôh bâr gâp.”$b$,true),
('bunong-vn','MIC',6,1,null,$b$Iăt hom moh nau Yêhôva lah: “Dâk hom may, tâm mpơl hom nau may ta năp phung yôk, jêh ri ƀư ăn phung gôl yôk iăt hom nau may!$b$,true),
('bunong-vn','MIC',6,2,null,$b$Hơi phung yôk, jêh ri mbon bu mon nâp ma neh ntu; iăt hom nau Yêhôva sŭk nsôr. Yor lah Yêhôva geh nau đah phung ƀon lan păng; păng mra tâm rlăch đah phung Israel.$b$,true),
('bunong-vn','MIC',6,3,null,$b$“Hơi phung ƀon lan gâp, moh nau gâp hŏ ƀư jêh ma may? Moh nau gâp ƀư dĭng rgănh ir may? Plơ̆ sĭt lah hom ma gâp!$b$,true),
('bunong-vn','MIC',6,4,null,$b$Yor lah gâp njŭn leo jêh may tă bơh n'gor bri Êjipt, jêh ri sâm chuai an jêh tă bơh ngih jêng bu nă; jêh ri gâp prơh jêh Y-Môis hăn pa năp may, nđâp Y-Arôn jêh ri H'Miriam tâm ban lĕ.$b$,true),
('bunong-vn','MIC',6,5,null,$b$Hơi phung ƀon lan gâp, ăn may kah gĭt moh nau Y-Balak hađăch bri Môap nchră, jêh ri moh nau Y-Balaam, kon bu klâu Y-Bêôr plơ̆ lah ma păng; jêh ri kah gĭt hom moh nau gâp hŏ ƀư jêh ntơm bơh Sitim tât Gilgal, gay ăn may gĭt kan sŏng bơh Yêhôva!$b$,true),
('bunong-vn','MIC',6,6,null,$b$“Mbă ndơ gâp mra tâm mpơl gâp nơm ta năp Yêhôva, jêh ri chon mbah tra năp măt Brah Ndu ta klơ? Gâp mra văch tât tra năp măt Păng ma ndơ nhhơr gŭch lĕ? Ma kon ndrôk bêng du năm lĕ?$b$,true),
('bunong-vn','MIC',6,7,null,$b$Yêhôva mra maak lĕ ma âk rbăn mlâm biăp nkuăng, ma âk rmưn rsen n'hor dak play ôlivơ lĕ? Gâp mra nhhơr lĕ kon gâp deh bôk rah yor nau gâp rlau nau vay? Play tă bơh ndŭl proch gâp mâm yor nau tih tâm huêng gâp?”$b$,true),
('bunong-vn','MIC',6,8,null,$b$Hơi bunuyh, Păng hŏ tâm mpơl ăn ma may moh ntil nau jêng ueh; jêh ri moh nau Yêhôva ntăm jêh ma may. Nây jêng ƀư nau sŏng, blau ƀư ueh jêh ri hăn ndrel ma Brah Ndu khân may ma nau dêh rhêt.$b$,true),
('bunong-vn','MIC',6,9,null,$b$Bâr Yêhôva nter lah ma ƀon toyh aơ bunuyh ueh ăn klach yơk ma amoh Păng. “Iăt hom mâng dong jêh ri gĭt mbu nơm hŏ săch nau nây.$b$,true),
('bunong-vn','MIC',6,10,null,$b$Dơi lĕ gâp ăn chuêl drăp ndơ nau ƀai tâm ngih nơm ƀai, jêh ri n'hŭch lơi njing lĕ di jêng nau rak rtăp?$b$,true),
('bunong-vn','MIC',6,11,null,$b$Gâp geh dŏng njing tih jêh ri play njing nklă tâm ƀau, pô ri gâp mâm dơi jêng kloh?$b$,true),
('bunong-vn','MIC',6,12,null,$b$Yor lah phung ndrŏng ƀon aơ bêng ma nau djơh mhĭk, phung bunuyh ƀon lan păng ngơi nau mƀruh, jêh ri tâm trôm mbung păng geh mpiăt vay ndơm bu.$b$,true),
('bunong-vn','MIC',6,13,null,$b$Yor nây gâp dong may, gay ăn sôt rmanh jru, jêh ri gay ƀư rai may yor nau tih may.$b$,true),
('bunong-vn','MIC',6,14,null,$b$May mra sông sa, ƀiă lah mâu hơm ôh; jêh ri mra geh nau ji ngot tâm ndŭl may. May mra bun ndơ may, ƀiă lah mâu dơi tâm rklaih ôh; bi ma ndơ may dơi tâm rklaih, pô ri gâp mra jao păng ma đao.$b$,true),
('bunong-vn','MIC',6,15,null,$b$May mra srih, ƀiă lah mâu geh roih rek ôh; may mra păt dak play ôlivơ, ƀiă lah mâu geh troch ôh dak nây ma may. May mra păt dak play kriăk ƀâu, ƀiă lah mâu geh nhêt ôh.$b$,true),
('bunong-vn','MIC',6,16,null,$b$Yor lah bu hôm e djôt prăp nau vay Y-Ômri, jêh ri lĕ rngôch kan pah ngih Y-Ahap; khân may chuat hăn tĭng nau khân păng chră nkhuch, gay ma gâp ƀư rai may, jêh ri ăn phung ƀon lan may jêng ndơ bu nsŭch; khân may mra anh nau prêng phung ƀon lan gâp.”$b$,true),
('bunong-vn','MIC',7,1,null,$b$Rêh ni ngăn gâp! Yor lah gâp jêng nâm bu Yan bu pĕ play ta vai, nâm bu yan kơi pĕ play kriăk ƀâu lĕ mpŭch; mâu geh du rkŭm play prăp sa ôh, mâu geh ôh play rvi dŭm lor lơn huêng gâp ŭch sa.$b$,true),
('bunong-vn','MIC',7,2,null,$b$Bunuyh klach yơk ma Brah Ndu rai yot jêh tă bơh neh ntu, jêh ri mâu geh ôh du huê sŏng srăng tâm phung bunuyh. Lĕ rngôch khân păng kâp rmiăt ŭch ƀư nau pling mham; ăp nơm sŏk nhuăl nthăng ma oh nâu păng nơm.$b$,true),
('bunong-vn','MIC',7,3,null,$b$Ti khân păng gơih ngăn ƀư nau mhĭk. Kôranh chiă uănh ŭch geh drăp ndơ, jêh ri kôranh phat dôih dăn ndơ bu blŏl, bi ma bunuyh toyh ŭch ngơi nau mhĭk păng ŭch tâm nuih n'hâm; pô ri khân păng tâm chră ndrel.$b$,true),
('bunong-vn','MIC',7,4,null,$b$Bunuyh ueh lơn tâm phung khân păng jêng nâm bu lok mâng glân. Bi ma nơm sŏng srăng lơn tâm phung khân păng jêng nâm bu mpach lok. Nau phung gak mbơh ma nar nau tâm rmal khân păng tât jêh; aƀaơ ri nau uh ah dăch tât jêh ma khân păng.$b$,true),
('bunong-vn','MIC',7,5,null,$b$Lơi ta iăt nchroh ma du huê bunuyh chiau meng khân may; jêh ri lơi ta rnơm nsing ma du huê mĭt jiăng may ôh. Njrăng hom ma nau may ngơi ndrel ma bu ur chŭn ta ntang ntơh may;$b$,true),
('bunong-vn','MIC',7,6,null,$b$yor lah kon bu klâu ƀư ma mbơ̆ păng ma nau tâm rmot, kon bu ur du dâk tâm rdâng đah mê̆ păng, ƀăn tâm rdâng đah me po, jêh ri bunuyh rlăng jêng bunuyh tâm ngih vâl may nơm.$b$,false),
('bunong-vn','MIC',7,7,null,$b$Bi ma gâp, gâp mra kâp uănh ma Yêhôva, gâp mra kâp gân Brah Ndu nơm tâm rklaih gâp; Brah Ndu gâp mra iăt gâp.$b$,true),
('bunong-vn','MIC',7,8,null,$b$Hơi nơm rlăng gâp, lơi ta răm maak ôh yor gâp, nđâp tơ lah gâp lĕ cha lôt, gâp mra dâk đŏng, nđâp tơ lah gâp gŭ tâm ntŭk ngo klĕng, Yêhôva mra jêng nau ang ma gâp.$b$,true),
('bunong-vn','MIC',7,9,null,$b$Gâp mra dơn nau Yêhôva nuih, yor lah gâp ƀư tih jêh ma păng, kŏ tât păng koh dŏng an dôih gâp jêh ri phat an dôih gâp. Pô ri păng mra njŭn leo gâp ma nau ang, Gâp mra saơ nau sŏng Păng.$b$,true),
('bunong-vn','MIC',7,10,null,$b$Rnôk nây nơm rlăng ma gâp mra saơ, jêh ri mra prêng. Păng jêng nơm hŏ lah ma gâp, “Ta ntŭk Yêhôva Brah Ndu may?” Măt gâp mra saơ nau gâp ŭch tât ma păng; aƀaơ ri mra bu jot nâm bu dak bŏk rŏ trong.$b$,true),
('bunong-vn','MIC',7,11,null,$b$Moh nar prăp ma nau ndâk đŏng pêr khân may! Tâm nar nây bu mra ăn huy ngai n'har bri may$b$,true),
('bunong-vn','MIC',7,12,null,$b$Tâm nar nây bu mra văch ma may, tă bơh bri Asiri jêh ri tă bơh ăp ƀon toyh n'gor bri Êjipt kŏ tât dak krong ur, ntơm bơh dak mƀŭt aơ tât ta dak mƀŭt ri yôk aơ tât yôk ri.$b$,false),
('bunong-vn','MIC',7,13,null,$b$Ƀiă lah neh ntu mra jêng rngol yor phung gŭ tâm păng, yor play tă bơh nau khân păng ƀư.$b$,true),
('bunong-vn','MIC',7,14,null,$b$Chiă uănh hom phung ƀon lan may ma mâng jra may, lĕ rngôch phung biăp jêng drăp ndơn may, phung gŭ êng tâm krŏng ta nklang Karmel; ăn khân păng sa gơ̆ ta bri Basan jêh ri tâm bri Galaat nâm bu rnôk sa ơm.$b$,true),
('bunong-vn','MIC',7,15,null,$b$“Nâm bu rnôk may du luh tă bơh n'gor bri Êjipt, gâp mra tâm mpơl ma khân păng kan khlay gâp ƀư”$b$,true),
('bunong-vn','MIC',7,16,null,$b$Phung mpôl băl bunuyh mra saơ jêh ri prêng nđâp ma lĕ nau ktang khân păng; khân păng mra gŭ klăk klêm mâu hôm geh nau ngơi ôh; tôr khân păng jêng tê̆ k.$b$,true),
('bunong-vn','MIC',7,17,null,$b$Khân păng mra sa ler neh muy nâm bu du mlâm bêh, nâm bu mpa vơr ta neh. Khân păng mra luh du pa dih pôih nâp khân păng ma nau râm nsâr, khân păng mra rle mpeh Yêhôva Brah Ndu he ma nau klach ngăn, jêh ri khân păng klach ma May.$b$,true),
('bunong-vn','MIC',7,18,null,$b$Mbu nơm jêng Brah Ndu nâm bu May, blau yô̆ an ma nau kue, jêh ri mâu klăp ndăng ôh nau rlau nau vay, ma phung hôm e jêng drăp ndơn păng? Păng mâu prăp mro ôh nau păng nuih Yor lah păng maak tâm nau ueh.$b$,true),
('bunong-vn','MIC',7,19,null,$b$Păng mra yô̆ an ma he, păng mra jot nau kue he tâm dâng jâng Păng, jêh ri klŭp lơi lĕ rngôch nau tih tâm klŏng jru dak mƀŭt.$b$,true),
('bunong-vn','MIC',7,20,null,$b$May mra tâm mpơl nau nanê̆ ngăn ma Y-Yakôp, jêh ri nau ueh ma Y-Abraham, nâm bu may sân săk jêh ma phung che hên tâm rnôk sa ơm.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','MIC',1,1,0,'heading',$b$Nau Tih Jêh Ri Nau Phat Dôih (Ntơm kô̆ 1 tât kô̆ 3) Nau Phat Dôih Ma N'Gor Israel Jêh Ri N'Gor Yuđa$b$),
('bunong-vn','MIC',2,1,0,'heading',$b$Rêh Ni Ngăn Yơh Ma Phung Tŭn Jot Phung O-ach$b$),
('bunong-vn','MIC',3,1,0,'heading',$b$Nau Ngơi Mhĭk Ma Phung Mât Uănh Phung Israel$b$),
('bunong-vn','MIC',4,1,0,'heading',$b$Nau Yêhôva Chiă Uănh Ma Nau Đăp Mpăn Lam Bri$b$),
('bunong-vn','MIC',4,6,1,'heading',$b$Nau Tâm Chuai Phung Israel Tă Bơh Nau Jêng Bună$b$),
('bunong-vn','MIC',5,1,0,'heading',$b$Nơm Tâm Rklaih Deh Văch Jêh Ri Chiă Uănh$b$),
('bunong-vn','MIC',5,9,1,'heading',$b$Nau Ƀư Rai Rup Brah$b$),
('bunong-vn','MIC',6,1,0,'heading',$b$Mâm Ƀư Gay Dơi Geh Nau Tâm Rklaih (Kô̆ 6 jêh ri 7) Yêhôva Nduyh Phung Ƀon Lan Păng$b$),
('bunong-vn','MIC',6,6,1,'heading',$b$Nau Yêhôva Ntăm$b$),
('bunong-vn','MIC',7,1,0,'heading',$b$Nau Phung Israel Gŭ Ngao Tih Mhĭk$b$),
('bunong-vn','MIC',7,7,1,'heading',$b$Yêhôva Leo Nau Ang Jêh Ri Nau Tâm Rklaih$b$),
('bunong-vn','MIC',7,14,2,'heading',$b$Yêhôva Yô̆ Ma Phung Israel$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'NAM', $b$Y-Nahum$b$, $b$["Ndrom Sămƀŭt Bơh", "Y-NAHUM"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','NAM',1,1,null,$b$Nau anh jâk ma ƀon Ninivơ. Ndrom sămƀŭt nau Y-Nahum bunuyh ƀon Êlkôs tâm saơ.$b$,true),
('bunong-vn','NAM',1,2,null,$b$Yêhôva jêng Brah Ndu blau ntôn jêh ri plơng bôk, Yêhôva har plơng, jêh ri ƀư nau ji nuih. Yêhôva har plơng phung tâm rdâng đah păng, jêh ri prăp nau ji nuih đah phung rlăng păng.$b$,true),
('bunong-vn','NAM',1,3,null,$b$Yêhôva mâu gơnh nuih ôh jêh ri geh nau brah Toyh; ƀiă lah Păng mâu mra ăn ôh nơm tih klaih tă bơh nau tâm rmal. Trong păng tâm phŭt chuănh jêh ri tâm sial vănh blông, ndâr tŭk jêng ndruyh neh jâng păng.$b$,false),
('bunong-vn','NAM',1,4,null,$b$Păng nduyh dak mƀŭt jêh ri ăn suăt lơi păng, păng ăn suăt lĕ rngôch dak krong; bri Basan jêh ri Yôk Karmel sơh đang, kao si bri Liban lĕ nhop.$b$,false),
('bunong-vn','NAM',1,5,null,$b$Yôk râm-nsâr ta năp păng, gôl tât lêk, rplay neh n'găr mpât ta năp păng, jêh ri neh ndrel phung ƀon lan ta klơ neh dâk ta năp măt Păng.$b$,false),
('bunong-vn','NAM',1,6,null,$b$Mbu dơi dâk ta năp nau păng ji nuih? Mbu nơm dơi srôih dơn nau păng duh nuih? Nau păng ji nuih nkhŭt jêh nâm bu ŭnh, jêh ri păng ăn chah lơi lŭ.$b$,true),
('bunong-vn','NAM',1,7,null,$b$Yêhôva jêng ueh, du pôih nâp tâm nar uh ah; păng mât njrăng phung du krap tâm păng.$b$,false),
('bunong-vn','NAM',1,8,null,$b$Ƀiă lah ma dak lip lam jŭm păng mra gay ngroh dơi phung rlăng păng tât ma nau ngo klĕng.$b$,false),
('bunong-vn','NAM',1,9,null,$b$Moh khân may mĭn ŭch ƀư ma Yêhôva? Păng mra ƀư rai lĕ ƀhiau, păng mâu mra har plơng bar tơ̆ ôh ma phung rlăng păng.$b$,true),
('bunong-vn','NAM',1,10,null,$b$Khân păng mra rai roh nâm bu lok tâm pêng, jêh ri nâm bu nhŭl ndrănh; khân păng roh yot nâm bu rhe kro.$b$,true),
('bunong-vn','NAM',1,11,null,$b$Du huê luh du jêh tă bơh may, nơm mĭn ŭch ƀư mhĭk ma Yêhôva, jêh ri tâm nchră nau djơh, nau mhĭk.$b$,false),
('bunong-vn','NAM',1,12,null,$b$Pô aơ nau Yêhôva lah: “Nđâp tơ lah khân păng jêng ktang jêh ri âk kđôi lĕ, bu mra ƀư rai jêh ri ngroh lơi khân păng. Nđâp tơ lah gâp ƀư nkrit khân may kđôi, gâp mâu mra ƀư nkrit khân may đŏng ôh.$b$,false),
('bunong-vn','NAM',1,13,null,$b$Aƀaơ ri gâp mra nkêch lơi mâng mbăk păng tă boh khân may, jêh ri ntăch lơi rse rvăk khân may.”$b$,true),
('bunong-vn','NAM',1,14,null,$b$Yêhôva ăn jêh nau ntăm ma may, May mâu mra geh phung kon sau đŏng ôh djôt amoh may. Gâp mra ƀư rai rup trah jêh ri rup tŏ, rup chiăr tă bơh ngih phung brah may. Gâp mra nkra môch ma may, Yor lah may jêng djơh ngăn.$b$,false),
('bunong-vn','NAM',1,15,null,$b$Aơ, ta klơ yôk, jâng phung leo nau mhe mhan ueh, nơm mbơh nau đăp mpăn! Djôt prăp năng nar may, Hơi Yuđa, ƀư di hom nau may ton, Yor lah nơm djơh mâu mra văch tâm rdâng đŏng ôh ma may, păng rai lĕ ƀhiau.$b$,true),
('bunong-vn','NAM',2,1,null,$b$Nơm ƀư rai văch jêh tâm rdâng đah may. Ăn bunuyh king njrăng pôih kâp uănh ta trong; Vân rse bŭt may, dŏng lĕ nau ktang may.$b$,true),
('bunong-vn','NAM',2,2,null,$b$Yor lah Yêhôva mra mplơ̆ sĭt đŏng nau chrêk rmah ma Yakôb, nâm bu nau chrêk rmah Israel, nđâp tơ lah phung tŭn jot khân păng jêh ri lơh rai n'gĭng tơm play khân păng.$b$,false),
('bunong-vn','NAM',2,3,null,$b$Khêl phung janh ktang jêng chăng, phung ta han păng nsoh ao rvanh chăng krăk. Loih ndeh seh khân păng nchrang nâm bu mpiăt ŭnh tơ lah sŏl ma nau tâm lơh; nđâp ma tak đao khân păng mpănh da dê.$b$,false),
('bunong-vn','NAM',2,4,null,$b$Ndeh seh nchuăt prăl tâm trong sâng, khân păng nkhŏk (ƀor) ta aơ ta ri tâm nkual ƀon; khân păng nchrang nâm bu ŭnh rdo, khân păng nchuăt nâm bu lơp nglaih.$b$,true),
('bunong-vn','NAM',2,5,null,$b$Bu kuăl phung ta han janh ktang văch, khân păng chêh prah dôl khân păng chuat hăn, khân păng ndal ŭch tât ta mpêr, jêh ri bu ndâk ndơ king drơ.$b$,true),
('bunong-vn','NAM',2,6,null,$b$Bu ƀư chah jêh mpông pêr dak n'hong, jêh ri ngih hađăch rai roh.$b$,false),
('bunong-vn','NAM',2,7,null,$b$Bu hŏ săch jêh: Hađăch bu ur hăn jêng bu nă jêh ri luh du tă bơh n'gor bri, oh mon bu ur nhĭm vơl nâm bu plŭk, jêh ri ndoch ntang ntơh khân păng nơm.$b$,false),
('bunong-vn','NAM',2,8,null,$b$Ƀon Ninivơ hŏ jêng nâm bu du ntu-lŭng dak, ƀiă lah khân păng lĕ luh du! Geh bu nuyh nter: Dâk hom! Dak hom! Ƀiă lah mâu geh du huê rle n'gĭl pa kơi ôh.$b$,true),
('bunong-vn','NAM',2,9,null,$b$Pit in prăk, pit in mah! Yor lah drăp khlay păng mâu geh dŭt ôh, jêh ri nau ndrŏng ma ăp ntil ndơ khlay.$b$,false),
('bunong-vn','NAM',2,10,null,$b$Păng lĕ bu ƀư rai, jêng rngol, jêh ri rai yot lĕ rngôch; nuih n'hâm khân păng lĕ phit phơr; kômâk lĕ râm nsâr, bŭt blu lĕ ji, muh măt lĕ brâp!$b$,false),
('bunong-vn','NAM',2,11,null,$b$Ta ntŭk trôm yau mŭr ntŭk khân păng siăm kon păng, jêng ntŭk yau mŭr nkuăng, yau mŭr me jêh ri kon khân păng rlet hăn, mâu geh nuyh khân păng klach, ta ntŭk aƀaơ ri?$b$,true),
('bunong-vn','NAM',2,12,null,$b$Yau mŭr nkuăng hêk ăp ntil mpô mpa ma kon păng, jêh ri gĭnh mpa ăn yau mŭr me, trôm păng bêng ma mpa păng kăp, jêh ri bêng ma puăch păng hŏ hêk jêh.$b$,false),
('bunong-vn','NAM',2,13,null,$b$Aơ, gâp tâm rdâng ma may, Yêhôva ma phung ta han lah, mra su ndeh seh may tâm ŭnh, jêh ri đao tak mra sa kon yau mŭr may. Gâp mâu mra om jun ma may ôh ta neh ntu, jêh ri bu mâu mra iăt đŏng ôh bâr phung may prơh hăn mbơh. Nau Tih Ninivơ. Ƀư Ăn Nau Rai Yot$b$,true),
('bunong-vn','NAM',3,1,null,$b$Rêh ni ngăn ma ƀon toyh vay pling mham, bêng ma nau mƀruh jêh ri bêng ma ndơ pit in, mâu rlu ôh nau păng pit in!$b$,true),
('bunong-vn','NAM',3,2,null,$b$Nteh mâng nê̆, nteh jâng ndeh, nteh nchuăt seh!$b$,false),
('bunong-vn','NAM',3,3,null,$b$Phung ncho seh sŏl hăn leo pa năp, đao tak rmah ƀlĭp, âk râk bunuyh khĭt âk bu bun drô phan, ntŭk bunuyh khĭt mâu blau lôch ôh, khân păng chêh prah cha lôt yor săk nuyh khĭt!$b$,false),
('bunong-vn','NAM',3,4,null,$b$Lĕ nau nây tât yor nau bu ur văng tĭr ƀư mâu blau kơp ôh, bêng ma nau ueh blau ƀư nau nklă nây; nơm rlăng ma mpôl băl bu nuyh ma nau văng tĭr păng, jêh ri phung ƀon lan ma kan n'hŭm păng.$b$,true),
('bunong-vn','NAM',3,5,null,$b$Aơ, gâp tâm rdâng ma may. Yêhôva ma phung ta han lah, gâp mra mbơk lơi ao jâr may rlơk tât muh măt may; jêh gâp mra ăn phung mpôl băl bunuyh, bu mra saơ nau rhôk may; mpơl nau bêk prêng ƀon bri hađăch may ăn ma lĕ bri dak êng.$b$,false),
('bunong-vn','NAM',3,6,null,$b$Gâp mra mƀăr nau ƀơ ƀơch ta may jêh ri ƀư ma may nau tâm rmot, jêh ri ăn may jêng ndơ bu hih rhâl ƀư ăn lĕ rngôch bu nuyh uănh.$b$,false),
('bunong-vn','NAM',3,7,null,$b$Lĕ rngôch phung uănh ma may mra du tă bơh may jêh ri lah, Rai ngăn jêh, ƀon Ninivơ, mbu nơm klâng ndrê ma păng? Ta ntŭk gâp dơi joi phung bonh leng may?$b$,false),
('bunong-vn','NAM',3,8,null,$b$May ŭch jêng ueh lơn ma ƀon Nô-Amôn lĕ, ƀon gŭ ta nklang dak krong, geh dak jŭm păng? Dak mƀŭt jêng mpêr ma păng, jêh ri dak jêng mpir ma păng.$b$,true),
('bunong-vn','NAM',3,9,null,$b$Bri Êthiôpi jêh ri bri Êjipt jêng nau ktang mâu geh bôl ôh; n'gor Put jêh ri phung Libi jêng phung kơl păng.$b$,false),
('bunong-vn','NAM',3,10,null,$b$Ƀiă lah bu leo rdu jêh păng, păng hăn jêng bună jêh; phung kon jê̆ jê̆ păng bu jot rchiăt ta kang ntŭk rdjŭm lĕ rngôch trong sâng ƀon toyh; bu nhŭp nchroh gay geh phung bu nuyh păng yơk, jêh ri lĕ rngôch phung bu klâu ƀư kan toyh păng bu nkông jêh ma rse rvăk.$b$,false),
('bunong-vn','NAM',3,11,null,$b$May tâm ban lĕ mra nhŭl ndrănh may tâm ban lĕ mra du krap; may mra joi ntŭk nde tă bơh nơm rlăng.$b$,false),
('bunong-vn','NAM',3,12,null,$b$Lĕ rngôch pôih may jêng nâm bu tơm play rvi ma play dŭm lor lơn; tơ lah bu rgu khân păng, khân păng rŭng tâm trôm mbung bunuyh sa.$b$,false),
('bunong-vn','NAM',3,13,null,$b$Aơ, phung ta han may jêng nâm bu bu ur ta nklang may. Mpông pêr bri may pơk huy jêh ma phung rlăng may; ŭnh sa jêh mâng rnăng mpông may.$b$,false),
('bunong-vn','NAM',3,14,null,$b$Ăn may bâk dak lor ma bu nchueng; ăn nâp hom pôih may; ăn may jot hom bŏk, jot rplach bŏk djôt ndơ mon neh yăng!$b$,true),
('bunong-vn','NAM',3,15,null,$b$Ta nây ŭnh mra sa may, đao tak mra ƀư rai may. Păng mra sa may nâm bu krah. Ăn bĭk rơ̆ hom may nơm nâm bu krah pŭ, ăn bĭk hom may nâm bu krah nsăt!$b$,false),
('bunong-vn','NAM',3,16,null,$b$May ăn bĭk jêh phung tăch rgâl may âk lơn nâm bu mah tâm trôk. Ƀiă lah nâm bu krah khân păng ƀư rai bri, jêh ri du mpăr.$b$,false),
('bunong-vn','NAM',3,17,null,$b$Phung gak may jêng nâm bu krah nsăt, phung kôranh may nâm bu phung krah pŭ drâm ta mpêr ta nar ji kăt-tơ lah luh nar, khân păng du mpăr, mâu geh nuyh gĭt ôh ta ntŭk khân păng gŭ.$b$,false),
('bunong-vn','NAM',3,18,null,$b$Phung rmăk biăp may lĕ bêch, Hơi hađăch Asiri; phung kôranh may gŭ rlu lâng săk. Phung ƀon lan may du pru tâm yôk, mâu geh nơm sâm rgum ô băl ôh.$b$,true),
('bunong-vn','NAM',3,19,null,$b$Mâu geh ôh dak si săm ntŭk rmanh may ntŭk sôt may lĕ glăm ngăn jêh; lĕ rngôch phung tăng nau bu nkoch ma may tap ti khân păng yor nau may cha lôt. Yor lah mbu mpôl băl bunuyh dĭng mâu; mâp dơn ôh tĭng nâm nau may ƀư djơh mro!$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','NAM',1,1,0,'heading',$b$Nau Mbơh Lor Rdâng Đah Ninivơ$b$),
('bunong-vn','NAM',1,15,1,'heading',$b$Nau Mhe Mhan Nau Ƀon Ninivơ Roh Rai$b$),
('bunong-vn','NAM',2,1,0,'heading',$b$Nau Sŏk Pit Jêh Ri Ƀư Rai Ninivơ$b$),
('bunong-vn','NAM',2,13,1,'heading',$b$Ƀon Ninivơ Rai Lôch$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'HAB', $b$Y-Habakuk$b$, $b$["Ndrom Sămƀŭt Bơh", "Y-HABAKUK"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','HAB',1,1,null,$b$Nau jâk tâm mpơl ma kôranh nơm mbơh lor Y-Habakuk.$b$,true),
('bunong-vn','HAB',1,2,null,$b$Hơi Yêhôva! Ndah nâm jŏ gâp mra nter nau gâp vơl dăn nau kơl jêh ri may mâu ŭch iăt ôh? Mâu lah nter ma may, “Bu ƀư nau djơh mhĭk!” jêh ri may mâu ŭch tâm rklaih ôh?$b$,true),
('bunong-vn','HAB',1,3,null,$b$Mâm ƀư may ăn gâp saơ nau mâu di jêh ri uănh ma nau uh ah? Nau ƀư rai jêh ri nau djơh mhĭk gŭ pa năp gâp; Geh nau tâm nhăt jêh ri nau tâm djrel.$b$,true),
('bunong-vn','HAB',1,4,null,$b$Bu mâu chrê ma nau vay ôh, bu mâu ƀư ma nau di ôh. Yor lah phung ƀai nchueng jêh phung sŏng, Pô nây bu phat dôih ma nau kue.$b$,true),
('bunong-vn','HAB',1,5,null,$b$“Uănh hom ma phung mpôl băl bunuyh jêh ri sek uănh; ăn may saơ hih rhâl jêh ri ndrŏt ndal. Yor lah gâp gŭ ƀư du ntil kan tâm rnôk khân may, nđâp tơ lah bu nkoch bri ma khân may, khân may kŏ mâu iăt lĕ.$b$,true),
('bunong-vn','HAB',1,6,null,$b$Aơ, gâp nsônh phung Kaldê du dâk, păng jêng phung ƀon lan djơh ngăn mâu djân ôh, vay hăn lam bri neh ntu, gay ŭch pit in ntŭk bu mâu jêng ntŭk ndrâm khân păng nơm ôh.$b$,true),
('bunong-vn','HAB',1,7,null,$b$Khân păng rnam ngăn jêh ri krit klach ngăn yơh; khân păng ƀư khư n'hao êng khân păng nơm jêh ri khân păng ndâk njêng êng nau vay tă bơh khân păng nơm da dê.$b$,true),
('bunong-vn','HAB',1,8,null,$b$Lĕ rngôch phung seh khân păng prăl rlau lơn yau brăch, jêh ri janh djơh ngăn rlau so bri nsong bri măng. Phung ta han ncho seh khân păng ran văch tă bơh bri ngai; khân păng mpăr nâm bu klang ngăch ran ma kăp sa hêk ro.$b$,true),
('bunong-vn','HAB',1,9,null,$b$Lĕ rngôch khân păng văch tât gay ŭch ƀư nau djơh mhĭk âk râk khân păng rduh ran rlet pa năp, jêh ri khân păng rƀŭn bună nâm bu choih.$b$,true),
('bunong-vn','HAB',1,10,null,$b$Khân păng gơm mưch ma phung hađăch, jêh ri ntêh rmot ma phung kôranh chiă uănh. Khân păng gơm mưch ma lĕ rngôch pôih, yor lah khân păng n'hao bun neh, jêh nây nhŭp pit in.$b$,true),
('bunong-vn','HAB',1,11,null,$b$Jêh ri khân păng rduh ran nâm bu n'hoch sial khôm; yor lah sơm đah nau ktang khân păng nơm jêng brah ma khân păng, pô ri jêng tih jru ngăn yơh!”$b$,true),
('bunong-vn','HAB',1,12,null,$b$Hơi Yêhôva Brah Ndu gâp, Nơm kloh ueh gâp! Mâu di hĕ may ơm geh ntơm bơh sa ơm ƀa ƀơ n'ho ro? Pô ri hên mâu mra khĭt! Hơi Yêhôva, may hŏ njêng jêh phung ƀon lan aơ gay prăp ma nau may phat dôih, jêh ri may, Hơi Lŭ Toyh, May hŏ dơm jêh khân păng prăp ma nau nduyh nkra!$b$,true),
('bunong-vn','HAB',1,13,null,$b$Măt may kloh ir mâu ŭch uănh treng ôh nau mhĭk, jêh ri mâu lĕ ŭch dơn ôh nau tih. Mâm ƀư may uănh ma nau yô̆ đah phung ƀlêp ƀlêr, jêh ri tơ lah bunuyh mhĭk sa rvăn bunuyh sŏng lơn ma păng, mâm ƀư may gŭ klăk klêm?$b$,true),
('bunong-vn','HAB',1,14,null,$b$Mâm ƀư may njêng kon bunuyh nâm bu ta mƀŭt jêh ri nâm bu ndrŭng rvơng mâu geh kôranh?$b$,true),
('bunong-vn','HAB',1,15,null,$b$Păng hŏ sŏk jêh nglĕ ndar klĕ ntơt khân ô băl, păng yơk huai khân ô băl ma yŭ jal păng, păng rƀŭn khân ô băl tâm trôm nhuăl păng; pô nây păng răm maak jêh ri rhơn ngăn.$b$,true),
('bunong-vn','HAB',1,16,null,$b$Yor nau nây, păng ƀư brah ma yŭ jal păng, jêh ri su ndơ ƀâu kah ma nhuăl păng; yor lah ma ndơ nây păng geh nau kuăng ndrŏng, jêh ri ndơ păng sông sa jêng ueh.$b$,true),
('bunong-vn','HAB',1,17,null,$b$Yor nây păng mra ăt hôm e văng ƀa ƀơ lĕ ka tă bơh yŭ jal păng gay nkhĭt lơi phung mpôl băl bunuyh mâu ŭch yô̆ ôh?$b$,true),
('bunong-vn','HAB',2,1,null,$b$Gâp mra gŭ dâk ta ntŭk gâp gak, jêh ri gŭ ta klơ mpêr pôih, jêh ri lŏng uănh moh ntil nau Păng đă gâp ƀư, jêh ri moh nau gâp mra plơ̆ lah yor nau jêr jŏk aơ.$b$,true),
('bunong-vn','HAB',2,2,null,$b$Yêhôva plơ̆ sĭt lah ma gâp pô aơ: “May chih hom nau may tâm saơ,” jêh ri chih ntoh rah vah ta klơ kđar, gay ma nơm mbơh nau nây rŏ săr lah.$b$,true),
('bunong-vn','HAB',2,3,null,$b$Yor lah nau tâm saơ hôm e kâp tâm di rnôk tâm nal đah păng, kêng nglĕ dŭt păng mra văch gơnh ro, păng mâu mƀruh ôh. Tơ lah păng băt tât, may gŭ kâp ƀât; N'hêl nanê̆ păng mra tât, păng mâu mbrĕ mbrơi ôh.$b$,true),
('bunong-vn','HAB',2,4,null,$b$“Aơ, nuih n'hâm păng jêng sưr; nau păng ŭch mâu geh nau sŏng ôh, ƀiă lah nơm sŏng mra gŭ rêh yor nau chroh.$b$,true),
('bunong-vn','HAB',2,5,null,$b$N'hêl nanê̆ păng rvĭk ndrănh, ƀư nau ƀlêp ƀlêr, nau sưr jêh ri mâu đăp gŭ du ntŭk păng ôh. Yor lah păng lĕ mơng kơnh nâm bu Ƀon Phung Khĭt, nâm bu nau khĭt păng mâu blau dĭl ôh; Păng tâm rƀŭn ma păng nơm lĕ rngôch mpôl băl bunuyh, păng sŏk lĕ rngôch phung ƀon lan jêng bună.$b$,true),
('bunong-vn','HAB',2,6,null,$b$“Mâu di hĕ lĕ rngôch phung aơ mra treo nau bu ntêh rmot jêh ri gơm mưch ma păng, jêh ri lah: “Rêh ni ngăn ma nơm prăp bun moh ntil ndơ mâu jêng ndơ păng nơm ôh, jêh ri ƀư ndrŏng păng nơm ma ndơ bu nchăm ma păng yor păng nchâp! Ndah nâm dơi jŏ păng gŭ ƀư pô nây?’$b$,true),
('bunong-vn','HAB',2,7,null,$b$Mâu di hĕ nơm ăn may chan mra dâk ƀât lât dơm, jêh ri phung ăn may râm sâr kah rngăl? Rnôk nây mra jêng ndơ khân păng pit in.$b$,false),
('bunong-vn','HAB',2,8,null,$b$Yor lah may hŏ pit in jêh ndô ndơ âk mpôl băl bunuyh, lĕ rngôch phung ƀon lan hôm e mra pit in ndơ may, yor lah may hŏ ƀư pling jêh mham bunuyh; may ƀư rai jêh bri neh, ƀon toyh, jêh ri lĕ rngôch phung gŭ tâm păng.$b$,true),
('bunong-vn','HAB',2,9,null,$b$“Rêh ni ngăn ma nơm joi sa kao mâu tâm di nsĭt ma ngih vâl păng, gay ƀư ntŭk gŭ tâm ntŭk prêh ta klơ, gay king njrăng nau mhĭk tât!$b$,true),
('bunong-vn','HAB',2,10,null,$b$May hŏ leo jêh nau bêk prêng ma ngih vâl may nơm, may hŏ ƀư rai âk ntil mpôl bunuyh, jêh ri ƀư ngroh săk may nơm.$b$,true),
('bunong-vn','HAB',2,11,null,$b$Yor lah lŭ rŏ mpir mra nter, rda ƀư ma si klơ chor mra plơ̆ sĭt lah.$b$,true),
('bunong-vn','HAB',2,12,null,$b$“Rêh ni ngăn ma nơm ndâk ƀon ma nau pling mham, jêh ri ƀư mbon neh ƀon ma nau kue!$b$,true),
('bunong-vn','HAB',2,13,null,$b$Nau nây mâu di tă bơh Yêhôva phung ta han ôh phung ƀon lan pah kan prăp ma ŭnh sa, jêh ri mâu hĕ di ma phung mpôl băl bunuyh hŏt rgănh khân păng nơm ma nau dơm dam?$b$,true),
('bunong-vn','HAB',2,14,null,$b$Yor lah gĭt năl nau chrêk rmah Yêhôva mra bêng ler tâm neh ntu nâm bu hoch dak lip nkŭm mbon dak mƀŭt.$b$,true),
('bunong-vn','HAB',2,15,null,$b$Rêh ni ngăn ma nơm n'hơk phung chiau meng păng nhêt kachok nau păng ji nuih, jêh ri ăn khân păng nhŭl đah ndrănh, ŭch uănh săk jăn khân ô băl gŭ rhôk!$b$,true),
('bunong-vn','HAB',2,16,null,$b$May mra bêng ma nau prêng, mâu di ôh ma nau chrêk rmah. Aƀaơ ri nhêt hom may nơm, jêh ri ƀư nâm bu bunuyh ê hŏ koh ntâu. Kachok tâm ti ma Yêhôva mra rvăch tât ma may, jêh ri nau prêng mra ƀư ƀơ̆ nau chrêk rmah may!$b$,true),
('bunong-vn','HAB',2,17,null,$b$Nau may ƀư djơh ma bri Liban mra dơi đah may, nau may ƀư rai mpô mpa mra ƀư nkrit may; yor lah may hŏ ƀư pling jêh mham bunuyh jêh ri ƀư rai bri neh, ƀon toyh, jêh ri lĕ rngôch phung gŭ tâm khân păng.$b$,true),
('bunong-vn','HAB',2,18,null,$b$“Mâm dĭng khlay du mlâm rup brah bu hŏ trah mon jêh păng? Du mlâm rup brah bu tŏ chiăr, jêng nơm nti nây mƀruh ngăn, moh ndơ khlay. Yor lah bunuyh yơh pah kan rup brah mlo nây jêh ri mâm rnơm ma kan ti bunuyh ƀư.$b$,true),
('bunong-vn','HAB',2,19,null,$b$Rêh ni ngăn ma nơm ngơi đah tơm si lah ‘Kah rngăl hom may,’ ma lŭ mlo ‘Dâk hom may!’ Ntơm bơh aƀaơ dơi ăn nau tâm mpơl lĕ? Aơ, bu mblum păng ma mah jêh ri prăk ƀiă lah tâm păng mâu geh djê̆ lê̆ ôh nsôr n'hâm, jêng dơm dam.$b$,true),
('bunong-vn','HAB',2,20,null,$b$Ƀiă lah Yêhôva gŭ tâm ngih brah kloh ueh păng; ăn lĕ rngôch neh ntu gŭ rklăk ta năp Păng.”$b$,true),
('bunong-vn','HAB',3,1,null,$b$Nau kôranh nơm mbơh lor Y-Habakuk mbơh sơm tĭng nâm Sigianôt.$b$,true),
('bunong-vn','HAB',3,2,null,$b$Hơi Yêhôva! Gâp tăng jêh nau lư n'găr bu nkoch may, jêh ri gâp klach ngăn nau kan may. Hơi Yêhôva! Tâm rnôk aơ, ƀư ăn mhe hom kan may, jêh ri rnôk aơ ăn bu saơ nau nây; tơ lah dôl may ji nuih ăn may kah gĭt ma nau yô̆ !$b$,true),
('bunong-vn','HAB',3,3,null,$b$Brah Ndu văch tă bơh bri Têman, Nơm kloh ueh tă bơh yôk Paran (Sêla) Nau chrêk ma lơp păng nkŭm jêh phung trôk, jêh ri neh ntu bêng ma nau tâm rnê ma păng.$b$,true),
('bunong-vn','HAB',3,4,null,$b$Nau lơp păng jêng nâm bu nau ang măt nar, nau nchrat luh tă bơh ti păng; ta nây păng nkŭm nau brah păng.$b$,true),
('bunong-vn','HAB',3,5,null,$b$Nau ji nkhĭt hăn ta năp păng Hăr ŭnh luh tă mpang jâng păng$b$,true),
('bunong-vn','HAB',3,6,null,$b$Păng dâk jêh rgu neh ntu; Păng gŭ uănh, ƀư ăn phung mpôl băl bunuyh râm nsâr; Phung yôk ntơm bơh rnôk sa ơm chah lĕ jêh ri phung gôl yôk gŭ lĕ jŏ rnôk rlâm dêh tâm dâng. Lĕ trong Păng tâm ban nâm bu kăl e.$b$,false),
('bunong-vn','HAB',3,7,null,$b$Gâp saơ ngih bok phung Kusan geh nau rêh ni; bok nching bri Midian râm nsâr.$b$,true),
('bunong-vn','HAB',3,8,null,$b$Di lĕ Yêhôva ji nuih tâm rdâng đah dak krong lĕ? Nau May nuih tâm rdâng đah Dak n'hor lĕ? May ji nuih tâm rdâng đah dak mƀŭt lĕ, Tơ lah may ncho seh may gay tâm rklaih lĕ?$b$,true),
('bunong-vn','HAB',3,9,null,$b$May tŏk lơi na may bơh ndrom păng, jêh ri dăp hăr ta rse (Sêla) Păng chor neh ƀư ăn dak krong hoch.$b$,true),
('bunong-vn','HAB',3,10,null,$b$Lĕ rngôch yôk saơ Păng klach krit ngăn; phung n'hor dak hoch thăng ngăn, Klŏng jru nteh n'gôr dak, Păng rbuh ta lô̆ leo klơ.$b$,true),
('bunong-vn','HAB',3,11,null,$b$Măt nar jêh ri khay gŭ gâng (gŭ râng) ntŭk păng klơ trôk. Yor nau nchrang hăr may tơ lah may pănh khân păng, Yor nau lơp tak may sol ang.$b$,true),
('bunong-vn','HAB',3,12,null,$b$May nsong ta neh ntu ma nau ji nuih, may jot plên phung mpôl băl bunuyh ma nau may nuih.$b$,true),
('bunong-vn','HAB',3,13,null,$b$May luh du jêh gay tâm rklaih phung ƀon lan may, ŭch tâm rklaih nơm may tŏ jêh dak ƀâu kah. May ntrâm ƀư chah jêh bôk nơm ƀai, ăn păng gŭ săk hưl ntơm bơh bôk tât ta jâng (Sêla)$b$,true),
('bunong-vn','HAB',3,14,null,$b$May ăn rluh lơi bôk păng ma tak păng nơm, tơ lah phung ta han păng văch nâm bu sial vănh blông gay rpuh hên, hâk răm nâm bu hêk sa phung o ach ma nau ndâp.$b$,false),
('bunong-vn','HAB',3,15,null,$b$May jot jêh dak mƀŭt ma seh may jêh ri Tâm dak thăng dak toyh ngăn$b$,true),
('bunong-vn','HAB',3,16,null,$b$Gâp hŏ tăng, pô ri săk jăn gâp klach nsâr, tơ lah tăng bâr may toh yoi gâp mprâm; nau rmuk ôm lăp tâm nting gâp, jêh ri gâp râm tâm ntŭk gâp. Yor lah gâp gŭ đăp rmên gay gŭ kâp ma nar rŭng răng tât ma phung ƀon lan lăp tâm lơh đah hên.$b$,false),
('bunong-vn','HAB',3,17,null,$b$Nđâp tơ lah tơm play rvi mâu kao ôh, jêh ri mâu lĕ geh play ta tơm play kriăk ƀâu, Tơm play ôlivơ mâu play đŏng. Jêh ri mir ba mâu geh luh ndơ sông sa; Phung biăp mra roh tă bơh n'gar Jêh ri phung ndrôk mâu geh đŏng tâm trôm n'gar$b$,true),
('bunong-vn','HAB',3,18,null,$b$Nđâp tơ lah pô nây, gâp ăt răm maak tâm Yêhôva. Gâp mra maak tâm Brah Ndu nơm tâm rklaih gâp.$b$,false),
('bunong-vn','HAB',3,19,null,$b$Brah Ndu Kôranh Brah jêng nau ktang gâp; păng ăn jâng gâp jêng nâm bu jâng jun me, păng ăn gâp jot tâm ntŭk ta klơ. Ma Kôranh phung mprơ: Ma gong rêng gâp.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','HAB',1,1,0,'heading',$b$Y-Habakuk Ngơi Ƀrôk Ma Nau Mâu Sŏng$b$),
('bunong-vn','HAB',1,5,1,'heading',$b$Nau Yêhôva Plơ̆ Sĭt Lah$b$),
('bunong-vn','HAB',2,1,0,'heading',$b$Nau Tâm Rmal Ma Phung Kaldê$b$),
('bunong-vn','HAB',2,2,1,'heading',$b$Nau Yêhôva Plơ̆ Sĭt Lah$b$),
('bunong-vn','HAB',2,6,2,'heading',$b$Nau Rêh Ni Ma Phung Mâu Sŏng Ôh$b$),
