insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'ZEP', $b$Y-Sôphôni$b$, $b$["Ndrom Sămƀŭt Bơh", "Y-SÔPHÔNI"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ZEP',1,1,null,$b$Aơ jêng nau Yêhôva ngơi ma Y-Sôphôni, kon bu klâu Y-Kusi, sau Y-Gêdalia, se Y-Amaria săn Y-Hêsakia, tâm rnôk Y-Jôsia, kon bu klâu Y-Amôn, hađăch n'gor Yuđa.$b$,true),
('bunong-vn','ZEP',1,2,null,$b$“Gâp ma ƀư rai lơi lĕ rngôch ndơ tă bơh klơ neh ntu,” Yêhôva lah.$b$,true),
('bunong-vn','ZEP',1,3,null,$b$“Gâp mra ƀư rai bunuyh jêh ri mpô mpa; gâp mra ƀư rai sĭm klơ trôk jêh ri ka tâm dak mƀŭt. Gâp mra n'glưh lơi nau phung djơh nking, jêh ri gâp mra ƀư rai lơi phung bunuyh ta klơ neh ntu,” Yêhôva lah.$b$,false),
('bunong-vn','ZEP',1,4,null,$b$“Gâp mra yơr ti gâp tâm rdâng đah phung Yuđa, jêh ri ma lĕ rngôch phung gŭ ta ƀon Yêrusalem; jêh ri gâp mra rai lĕ tă bơh ntŭk aơ phung hôm e yơk mbah ma brah Baal jêh ri kôranh ƀư brah ma rup brah;$b$,false),
('bunong-vn','ZEP',1,5,null,$b$Gâp mra ƀư rai phung chon mbah ma ndơ tâm trôk ta klơ chor bôk pho; jêh ri phung yơk mbah jêh ri sơm săk đah Yêhôva jêh ri ăt sơm săk đŏng đah hađăch khân păng;$b$,false),
('bunong-vn','ZEP',1,6,null,$b$phung lĕ cha lơi jêh Yêhôva, phung mâu ŭch joi Yêhôva, mâu ôp ôh ma păng.”$b$,false),
('bunong-vn','ZEP',1,7,null,$b$Gŭ klăk klêm hom ta năp Yêhôva Brah Ndu. Yor lah nar Yêhôva dăch tât, Yêhôva hŏ ndrăp nkra jêh ndơ nhhơr ƀư brah, prăp êng ma phung păng jă.$b$,false),
('bunong-vn','ZEP',1,8,null,$b$Ta nar Yêhôva ƀư brah, gâp mra tâm rmal phung kôranh jêh ri phung kon hađăch jêh ri lĕ rngôch phung nsoh kho ao bu năch.$b$,false),
('bunong-vn','ZEP',1,9,null,$b$Ta nar nây, gâp mra tâm rmal lĕ rngôch phung ta lô̆ ta klơ mbong ngih, jêh ri phung ăn bêng ngih kôranh khân păng ma nau djơh mhĭk jêh ri nau ndơm.$b$,false),
('bunong-vn','ZEP',1,10,null,$b$“Ta nar nây.” Yêhôva lah, “Bu mra tăng bâr bu nter huy ngăn bơh ntŭk Mpông Pêr Ka, nau nhĭm nter bơh ntŭk Nkual Tal Bar, nter huy ngăn bơh klơ yôk.$b$,true),
('bunong-vn','ZEP',1,11,null,$b$Hơi phung gŭ tâm ƀon dêh tâm dâng Maktes! Nhĭm nter hom; yor lah lĕ rngôch phung tăch rgâl lĕ rai roh, jêh ri phung njing prăk lĕ rai jêh.$b$,false),
('bunong-vn','ZEP',1,12,null,$b$Rnôk nây, gâp djôt ŭnh kađen sek uănh ƀon Yêrusalem, jêh ri gâp mra tâm rmal phung troch bêng thŭng ndrănh păng jêh ri lah tâm nuih n'hâm khân păng: ‘Yêhôva mâu mra ăn nau ueh ôh, mâu lĕ ăn nau mhĭk.’$b$,true),
('bunong-vn','ZEP',1,13,null,$b$Bu mra pit in drăp ndơ khân păng, ngih vâl khân păng lĕ bu ƀư rai lơi; khân păng mra ƀư ngih, ƀiă lah mâu geh gŭ ôh tăm tơm play kriăk ƀâu, ƀiă lah mâu geh nhêt dak păng.”$b$,false),
('bunong-vn','ZEP',1,14,null,$b$Nar toyh Yêhôva hŏ dăch tât, hŏ dăch ngăn jêh, păng mra tât gơnh ngăn, nar Yêhôva geh nau nteh n'găr ktang, rnôk nây phung janh ktang mra nhĭm nter hâu ngăn yơh.$b$,true),
('bunong-vn','ZEP',1,15,null,$b$Nar nây jêng nar ji nuih, nar rêh ni jêh ri nar rngot klâng, nar bu ƀư rai jêh ri rai lôch, nar nau ngo jêh ri gui nkâm, nar geh ndâr tŭk jêh ri ngo klĕng,$b$,false),
('bunong-vn','ZEP',1,16,null,$b$Nar geh bâr nŭng jêh ri nau nter tâm lơh đah ƀon toyh geh mpêr nâp jêh ri vâl tŭm pôih prêh ta njônh ƀon.$b$,false),
('bunong-vn','ZEP',1,17,null,$b$Gâp mra leo nau rêh ni tât ma bunuyh, pô ri khân păng mra chuat hăn nâm bu bunuyh chieh măt, yor lah khân păng ƀư tih jêh đah Yêhôva. Bu mra ƀư pling mham khân păng nâm bu njŏk ƀơ̆ ;$b$,true),
('bunong-vn','ZEP',1,18,null,$b$Mâu lah prăk mâu lah mah khân păng, mâu dơi tâm rklaih khân păng ôh tâm nar Yêhôva ji nuih; ƀiă lah lĕ rngôch bri dak aơ mra rai ma ŭnh nau păng ntôn, jêh ri Păng su ƀư rai lĕ rngôch bri dak; yor lah Păng mra ƀư rai ngăn yơh lĕ rngôch bri neh aơ ƀât lât mâu năn saơ.$b$,false),
('bunong-vn','ZEP',2,1,null,$b$Hơi mpôl băl bunuyh mâu gĭt nau prêng ôh, văch ndrel hom, tâm rgum ndrel,$b$,true),
('bunong-vn','ZEP',2,2,null,$b$Ê lor tơ lah nau ntăm ê hŏ tât, jêh ri nar nây rlau nâm bu lâk sial đô̆, lor tơ lah nar Yêhôva ji nuih ê hŏ tât ma khân may,$b$,false),
('bunong-vn','ZEP',2,3,null,$b$Hơi lĕ rngôch khân may, jêng phung hêt rhôi tâm bri neh, tĭng joi hom nau Kôranh Brah ntăm, joi hom Yêhôva, joi hom nau sŏng srăng, joi hom nau hêt rhôi, mâu lah bu ƀư pôn khân may mra ăn tâm nar Yêhôva ji nuih.$b$,false),
('bunong-vn','ZEP',2,4,null,$b$Yor nây, bu mra cha lơi ƀon Gaxa jêh ri ƀon Askalon mra jêng ntŭk rngol; bu mra mprơh ƀon Asdôt ta nklang bôk nar, bu mra đôk lơi ƀon Ekron.$b$,true),
('bunong-vn','ZEP',2,5,null,$b$Rêh ni ngăn ma khân may gŭ ta kơh dak mƀŭt, jêng phung mpôl Kêrêthit! Hơi Kanaan, jêng bri phung Philistin; nau Yêhôva ngơi tâm rdâng đah khân may; gâp mra ƀư rai lơi khân may kŏ tât mâu hôm geh bunuyh ôh.$b$,false),
('bunong-vn','ZEP',2,6,null,$b$Pô nây ta kơh dak mƀŭt mra jêng gơ̆ ndrêch, jêng ntŭk ndưp phung chiăp jêh ri ndrung phung biăp.$b$,false),
('bunong-vn','ZEP',2,7,null,$b$N'gor nây jêng ntŭk prăp ăn ma phung ngih Yuđa hôm e klen, ntŭk khân păng mât rong phung biăp, lah măng ngo mra bêch lâng măng tâm ăp rplay ngih vâl ƀon Askalon; yor lah Yêhôva Brah Ndu khân păng mra chop khâl khân păng, jêh ri leo sĭt phung tă ƀư bună ăn khân păng plơ̆ sĭt.$b$,false),
('bunong-vn','ZEP',2,8,null,$b$“Gâp hŏ tăng jêh nau Môap mưch rmot, nau phung kon sau Amôn suai rak, ma phung ƀon lan gâp, jêh ri thăm gay ŭch sŏk bri neh khân ô băl.$b$,true),
('bunong-vn','ZEP',2,9,null,$b$Yor nây, tĭng nâm gâp gŭ rêh,” Yêhôva phung ta han, lah, “Môap mra jêng nâm bu Sôdôm, jêh ri kon sau Amôn nâm bu Gômôrơ, du nkuĭl lok chăt hon geh ntu rlŭng boh, jêh ri jêng ntŭk rdah ƀa ƀơ n'ho ro; phung ƀon lan gâp hôm e klen mra pit in ndơ khân păng, phung băl mpôl gâp hôm e rêh mra ndơn sŏk khân păng.”$b$,false),
('bunong-vn','ZEP',2,10,null,$b$Nau nây mra tât ma khân păng yor nau sưr khân păng, yor khân păng mưch jêh ri ngơi sưr tâm rdâng đah Yêhôva phung ta han.$b$,false),
('bunong-vn','ZEP',2,11,null,$b$Yêhôva mra jêng du nau nkhĭt ăn khân păng klach; yor lah Păng nkrit ăn ma lĕ brah yang ta neh ntu ât ji ngot; jêh ri ăp ntil mpôl bunuyh mra chon mbah ta năp măt Păng; nđâp tâm kô dak mƀŭt, tâm lĕ n'gor bri tâm ban lĕ, yơk mbah tâm ntŭk păng nơm.$b$,true),
('bunong-vn','ZEP',2,12,null,$b$Tâm ban lĕ, Hơi phung Êthiôpi, khân may mra khĭt ma đao gâp.$b$,false),
('bunong-vn','ZEP',2,13,null,$b$Pô nây, Yêhôva mra yơr ti păng tâm rdâng đah phung ta dor, jêh ri ƀư rai bri Asiri; jêh ri păng mra ăn ƀon Ninivơ jêng rngol, neh sơh nâm bu bri rdah.$b$,true),
('bunong-vn','ZEP',2,14,null,$b$Phung biăp mra bêch kuen ta nklang khân păng, lĕ rngôch ntil mpô mpa êng, klang grât jêh ri blŏ ma mra gŭ tâm chiông meh gâng păng, klang kô ndrau ta mpông bloh ngih; ndơ bu ƀư ma tơm si sêdar lĕ bu rơih trơn jêh.$b$,false),
('bunong-vn','ZEP',2,15,null,$b$Aơ yơh ƀon toyh răm maak ngăn, hŏ gŭ jêh ma nau mpăn mâu hôm rvê mĭn ôh, jêh ri lah êng tâm nuih n'hâm khân păng: “Ta aơ, mâu hôm geh bunuyh êng ôh rlau lơn ma gâp.” Ƀiă lah păng nkhơng lah jêng rngol, jêng ntŭk ma phung mpô mpa bri bêch kuen ta nây! Ăp nuyh hăn rgăn ta nây bu gơm mưch jêh ri vơch ti nsŭch.$b$,false),
('bunong-vn','ZEP',3,1,null,$b$Rêh ni ngăn ma ƀon tâm rdâng, jêh ri ƀơ̆ ƀơch, ƀư nau tŭn jot!$b$,true),
('bunong-vn','ZEP',3,2,null,$b$Păng mâu tông bar bu ôh; păng mâu dơn nau bu lah nti păng. Păng mâu rnơm ma Yêhôva ôh, păng mâu hăn dăch Brah Ndu păng ôh.$b$,false),
('bunong-vn','ZEP',3,3,null,$b$Phung kôranh ta nklang păng nâm bu yau mŭr dôl ngrông; phung kôranh phat dôih păng jêng so bri rsong măng mâu têm om ôh tât kêng ôi taơ.$b$,true),
('bunong-vn','ZEP',3,4,null,$b$Phung kôranh nơm mbơh lor, păng ƀư tĭng nâm khân păng ŭch, jêh ri ƀư ma nau ndơm; phung kôranh ƀư brah păng ƀư ƀơ̆ ntŭk kloh ueh, jêh ri ƀư rlau nau vay.$b$,false),
('bunong-vn','ZEP',3,5,null,$b$Yêhôva ta nklang păng jêng sŏng, mâu ƀư nau djơh ôh; ăp ôi păng mpơl nau sŏng păng ta nklang nau ang, mâu blau lôch ôh; ƀiă lah bunuyh kue mâu gĭt prêng ôh.$b$,true),
('bunong-vn','ZEP',3,6,null,$b$Gâp hŏ ƀư rai jêh phung ntil mpôl bunuyh; vâl tŭm khân păng ta pôih njônh ƀon lah jêng vâl rŭng. Gâp ƀư jêh ntŭk rgum tăch ndơ lah jêng rngol, kŏ tât mâu geh ôh bunuyh hăn rgăn ta nây. Ƀon păng lah roh rai, mâu hôm geh du huê bunuyh, jêh ri kŏ mâu geh lĕ bunuyh gŭ ta nây.$b$,true),
('bunong-vn','ZEP',3,7,null,$b$Gâp lah ma ƀon nây: Nanê̆ ngăn, may knŏng klach yơk ma gâp, dơn nau bu lah nti, pô ri ntŭk păng gŭ mâu geh trơn ôh. Ƀiă lah khân păng sŏl ko, ŭch ƀư nau kan mhĭk khân păng nơm.$b$,false),
('bunong-vn','ZEP',3,8,null,$b$Yor nây, Yêhôva lah: Ăn khân may gŭ kâp gâp tât, kŏ tât nar gâp mra dâk mbơh ngăn; yor lah gâp ŭch mĭn gay sŏk rgum mpôl băl bunuyh jêh ri tâm rgum lĕ yor lah lĕ bri dak, gay gâp nkhŭt ma khân păng nau gâp nuih jêh ri lĕ nau gâp duh nuih, yor lah lĕ rngôch bri dak mra rai lôch.$b$,true),
('bunong-vn','ZEP',3,9,null,$b$Yor lah rnôk nây gâp mra ăn kloh trôm mbung phung ƀon lan, gay ăn lĕ rngôch khân păng kuăl amoh Yêhôva, jêh ri pah kan du ai ma păng.$b$,true),
('bunong-vn','ZEP',3,10,null,$b$Phung yơk mbah ma gâp, nâm bu ntĭt kon bu ur gâp nhhơt gŭ kơh đah ri dak krong Êthiôpi, mra leo ndơ nhhơr djôt ma gâp.$b$,false),
('bunong-vn','ZEP',3,11,null,$b$Tâm nar nây, may mâu mra bêk prêng ma bu ôh; yor lĕ nau may ƀư tih jêh ma gâp; yor lah rnôk nây gâp sŏk lơi tă bơh phung răm maak ma nau khân păng sưr ir ta nklang khân păng; ntơm aƀaơ tât kăndơ̆ khân păng mâu hôm sưr đŏng ôh ta klơ yôk kloh ueh gâp.$b$,true),
('bunong-vn','ZEP',3,12,null,$b$Ƀiă lah gâp mra lơi ta nklang may phung gĭt dêh-rhêt jêh ri rah rơch, phung blau nsing ma amoh Yêhôva.$b$,false),
('bunong-vn','ZEP',3,13,null,$b$Phung hôm e tâm n'gor Israel, mâu mra ƀư du ntil nau tih ôh, jêh ri mâu mra ngơi mƀruh ôh; mâu lĕ geh nau ngơi ndơm bơh mpiăt khân păng, yor lah khân păng mra sông sa jêh ri bêch rlu, jêh ri mâu geh ôh bunuyh ƀư nkrit khân păng.$b$,true),
('bunong-vn','ZEP',3,14,null,$b$Hơi kon bu ur Siôn, mprơ huy hôm! Hơi Israel, nter bâr ngơi huy! Hơi kon bu ur ƀon Yêrusalem! Răm jêh ri răm rhơn hom ma lĕ nuih n'hâm ay,$b$,true),
('bunong-vn','ZEP',3,15,null,$b$Yêhôva hŏ cha lơi jêh nau phat dôih ay, nsot phung rlăng du ngai ma ay; Hađăch Israel, jêng Yêhôva, gŭ ta nklang may, may mâu mra mâp nau mhĭk đŏng ôh.$b$,false),
('bunong-vn','ZEP',3,16,null,$b$Tâm nar nây, bu mra lah ma ƀon Yêrusalem pô aơ: Hơi Siôn, lơi klach ôh, lơi ăn ti may jêng ra ai ôh!$b$,true),
('bunong-vn','ZEP',3,17,null,$b$Yêhôva Brah Ndu may gŭ ta nklang may; Păng jêng nơm geh nau brah dơi tâm rklaih may; păng mra rhơn răm ngăn yor ma may, yor nuih n'hâm păng rŏng mpơl ma may. Jêh ri yor ma may păng mra mprơ ma nau rhơn răm.$b$,true),
('bunong-vn','ZEP',3,18,null,$b$“Gâp mra sŏk rgum phung dôl geh nau rngot, yor nhêt sa toyh; khân păng luh tă bơh may, dơn nau nduyh ƀư prêng jêh ri anh jâk.$b$,true),
('bunong-vn','ZEP',3,19,null,$b$Aơ, tâm rnôk nây, gâp mra ƀư rai lĕ rngôch phung ƀư nau rngot ma may, gâp mra tâm rklaih phung kuet rvĕn, jêh ri rgum sĭt phung tă mprơh du, gay ăn khân păng nau tâm rnê jêh ri nau lư n'găr tâm ăp n'gor bri bu hŏ ƀư bêk prêng jêh khân păng.$b$,true),
('bunong-vn','ZEP',3,20,null,$b$Tâm rnôk nây, gâp mra djôt leo khân may plơ̆ sĭt, tâm rnôk nây gâp mra tâm rgum ndrel đŏng khân may, yor lah gâp mra ăn khân may jêng lư n'găr jêh ri geh nau tâm rnê ta nklang lĕ rngôch phung ƀon lan tâm neh ntu, tơ lah gâp leo sĭt phung tă ƀư bună ta năp măt khân may,” Yêhôva lah nau nây.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','ZEP',1,1,0,'heading',$b$Nar Yêhôva Ji Nuih$b$),
('bunong-vn','ZEP',2,1,0,'heading',$b$Nau Ƀư Rai Ntil Mpôl Bunuyh Gŭ Jŭm$b$),
('bunong-vn','ZEP',3,1,0,'heading',$b$Nau Tih Jêh Ri Nau Tâm Chuai Ƀon Yêrusalem$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'HAG', $b$Y-Agê$b$, $b$["Ndrom Sămƀŭt Bơh", "Y-AGÊ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','HAG',1,1,null,$b$Năm rơh bar rnôk hađăch Darius, chiă uănh, ta nar sa ơm, khay prao, Yêhôva ngơi ma kôranh nơm mbơh lor Y-Agê lah ma Y-Sôrôbabel, kon bu klâu Y-Sêaltiêl kôranh chiă uănh n'gor Yuđa, jêh ri ma Y-Yôsuê, kon bu klâu Y-Jêhôsadak, kôranh ƀư brah toyh, lah:$b$,true),
('bunong-vn','HAG',1,2,null,$b$Pô aơ Yêhôva phung ta han lah, Phung ƀon lan aơ lah, Mông nar ê hŏ tât, jêng mông ndâk đŏng ngih Yêhôva.$b$,false),
('bunong-vn','HAG',1,3,null,$b$Yor nây dơi geh nau Yêhôva ngơi ma kôranh nơm mbơh lor Y-Agê:$b$,true),
('bunong-vn','HAG',1,4,null,$b$Aƀaơ di mông ma khân may lĕ, tâm trôm ngih ndop dơm ma kađar si, tơ lah ngih aơ jêng rngol?$b$,false),
('bunong-vn','HAG',1,5,null,$b$Pô ri aƀaơ, Yêhôva phung ta han lah pô aơ: Khân may mêt uănh hom nau khân may ŭch ƀư.$b$,true),
('bunong-vn','HAG',1,6,null,$b$Khân may srih âk ƀiă lah rek djê̆ dơm; sa mâu hơm, nhêt mâu mpay; nsoh n'gut mâu răm ntơh; jêh ri bunuyh pah kan nkhôm, geh rnoh bu nkhôm, ăn tâm trôm dŭng bluh.$b$,false),
('bunong-vn','HAG',1,7,null,$b$Yêhôva phung ta han lah: Ăn khân may mêt uănh hom nau khân may ŭch ƀư.$b$,true),
('bunong-vn','HAG',1,8,null,$b$Hao hom klơ yôk, djôt nsĭt tơm si, jêh ri ndâk ngih aơ, ri mơ gâp geh nau maak, jêh ri lư n'găr amoh gâp geh nau chrêk rmah, Yêhôva lah nau nây.$b$,false),
('bunong-vn','HAG',1,9,null,$b$Khân may joi ŭch geh âk, ƀiă lah aơ, geh djê̆; jêh ri tơ lah khân may djôt lao ta ngih, gâp khôm mpruh lơi ăn păng du. Yêhôva phung ta han lah: Mbah tă yor nau nây? Nây jêng yor tă ngih gâp lĕ rai, ƀiă lah ăp nơm khân may ŭch mĭn ndâk ngih gâp.$b$,false),
('bunong-vn','HAG',1,10,null,$b$Yor ri, yor tă khân may, trôk ta klơ mâu truh dak ngom, jêh ri neh ntu mâu hôm hon play đo.$b$,true),
('bunong-vn','HAG',1,11,null,$b$Gâp hŏ kuăl ăn trôk prăng phang tât tâm neh, tât ta klơ phung yôk, tât ma ntil gar, tât ma dak play kriăk ƀâu mhe, tât ma dak play Ôlivơ, tât ma ndơ chăt hon tă bơh neh, tât ma bunuyh, jêh ri ma ndrôk biăp, jêh ri ma lĕ rngôch kan khân may.$b$,false),
('bunong-vn','HAG',1,12,null,$b$Pô nây Y-Sôrôbabel, kon bu klâu Y-Sêatiêl, jêh ri Y-Yôsuê, kon bu klâu Y-Jêhôsadak, kôranh ƀư brah toyh ndrel ma lĕ rngôch phung ƀon lan hôm klen tông bâr ma Yêhôva Brah Ndu khân păng jêh ri ma phung kôranh nơm mbơh lor Y-Agê ngơi, nơm Yêhôva Brah Ndu khân păng prơh ô băl hăn, jêh ri phung ƀon lan klach yơk ma Yêhôva,$b$,true),
('bunong-vn','HAG',1,13,null,$b$Rnôk nây Y-Agê, ntuh bâr bơh Yêhôva, ngơi ma phung ƀon lan nau Yêhôva mbơh: Gâp gŭ ndrel ma khân may, Yêhôva lah.$b$,false),
('bunong-vn','HAG',1,14,null,$b$Pô nây, Yêhôva ntrôl nuih n'hâm Y-Sôrôbabel, kon bu klâu Y-Sêaltiêl, kôranh chiă, uănh n'gor Yuđa, jêh ri nuih n'hâm Y-Yôsuê, kon bu klâu Y-Jêhôsadak, kôranh ƀư brah toyh, jêh ri nuih n'hâm lĕ rngôch phung ƀon lan hôm e klen. Khân ô băl văch jêh ri ntơm pah kan ntŭk ngih Yêhôva phung ta han, jêng Brah Ndu khân păng.$b$,false),
('bunong-vn','HAG',1,15,null,$b$Nây jêng nar năng bar jât ma puăn, khay prao, tâm năm rơh bar rnôk hađăch Darius, chiă uănh.$b$,false),
('bunong-vn','HAG',2,1,null,$b$Tâm nar năng bar jât ma nguay, khay pơh, Yêhôva ngơi ma kôranh nơm mbơh lor Y-Agê, lah:$b$,true),
('bunong-vn','HAG',2,2,null,$b$Aƀaơ ngơi hom ma Y-Sôrôbabel, kon bu klâu Y-Sêaltiêl, kôranh chiă uănh n'gor Yuđa, jêh ri ma Y-Yôsuê, kon bu klâu Y-Jêhôsadak, kôranh ƀư brah toyh, jêh ri lĕ rngôch phung ƀon lan hôm e klen, lah,$b$,false),
('bunong-vn','HAG',2,3,null,$b$Tâm phung khân may, mbu nơm hôm e klen, nơm hŏ saơ ngih aơ tâm nau chrêk rmah păng ntơm sa ơm? Jêh ri aƀaơ mâm khân may uănh păng? Păng gŭ pa năp măt khân may, mâu hĕ di păng jêng dơm dam?$b$,false),
('bunong-vn','HAG',2,4,null,$b$Pô ri aƀaơ, Yêhôva lah: Hơi Y-Sôrôbabel, ăn may nănh nuih n'hâm; bi ma may, Y-Yôsuê, kon bu klâu Y-Jêhôsadak, kôranh ƀư brah toyh, ăn may nănh tâm ban lĕ; Yêhôva lah đŏng: Lĕ rngôch phung ƀon lan gŭ tâm n'gor, khân may nănh nuih n'hâm tâm ban đŏng, jêh ri pah kan hom; yor lah gâp mra gŭ ndrel ma khân may. Yêhôva phung ta han lah.$b$,true),
('bunong-vn','HAG',2,5,null,$b$Nau tâm rnglăp gâp hŏ ton jêh đah khân may dôl khân may du lah tă bơh n'gor bri Êjipt, Brah Huêng ueh gâp gŭ ta nklang khân may; lơi klach ôh!$b$,false),
('bunong-vn','HAG',2,6,null,$b$Yor lah Yêhôva phung ta han lah: Du tơ̆ đŏng, lăn djê̆ jêh ta nây, gâp mra ƀư n'găr trôk jêh ri neh ntu, dak mƀŭt, jêh ri neh sơh.$b$,true),
('bunong-vn','HAG',2,7,null,$b$Gâp mra rgu lĕ rngôch bri dak jêh ri drăp ndơ lĕ rngôch bri dak ŭch nau tât; jêh ta nây gâp ƀư ăn nau chrêk rmah bêng ngih aơ, Yêhôva phung ta han lah:$b$,false),
('bunong-vn','HAG',2,8,null,$b$Prăk jêng ndơ gâp, jêh ri mah jêng ndơ gâp. Yêhôva phung ta han lah.$b$,false),
('bunong-vn','HAG',2,9,null,$b$Nau chrêk rmah rơh aƀaơ mra jêng toyh lơn ma nau chrêk rmah ngih ntơm sa ơm. Yêhôva phung ta han lah nau nây; jêh ri gâp mra ăn nau đăp mpăn tâm ntŭk aơ, Yêhôva phung ta han lah.$b$,false),
('bunong-vn','HAG',2,10,null,$b$Nar bar jât ma puăn, khay sĭn, năm rơh bar Y-Darius, nau Yêhôva ngơi ma kôranh nơm mbơh lor, Y-Agê lah:$b$,true),
('bunong-vn','HAG',2,11,null,$b$Pô aơ Yêhôva phung ta han lah: Aƀaơ ri ôp hom ma phung kôranh ƀư brah ma nau vay pô aơ:$b$,false),
('bunong-vn','HAG',2,12,null,$b$Tơ lah geh du huê bunuyh klâm puăch kloh ueh tâm dŭng ao, jêh ri dŭng ao krêp piăng let mâu lah por, dak play kriăk ƀâu, đak play ôlivơ, mâu lah ndơ sông sa êng, pô ri ndơ nây jêng kloh ueh lĕ? Phung kôranh ƀư brah plơ̆ lah, pô aơ: Mâu ôh.$b$,false),
('bunong-vn','HAG',2,13,null,$b$Jêh ri Y-Agê lah, Tơ lah du huê jêng ƀơ̆ ƀơch yor brot rđĭl đah săk jăn bunuyh khĭt, pô ri lĕ ndơ nây geh tưp nau ƀơ̆ ƀơch lĕ? Phung kôranh ƀư brah plơ̆ lah: Lĕ ndơ nây jêng ƀơ̆ yơh.$b$,false),
('bunong-vn','HAG',2,14,null,$b$Jêh ri Y-Agê plơ̆ lah: Yêhôva lah: Tâm ban lĕ phung ƀon lan aơ, jêh ri phung bri dak aơ gŭ pa năp măt gâp. Lĕ rngôch kan ti khân păng ƀư jêng ƀơ̆ ƀơch tâm ban lĕ; jêh ri ndơ khân păng nhhơr ta aơ ăt ƀơ̆ tâm ban lĕ.$b$,true),
('bunong-vn','HAG',2,15,null,$b$Pô ri aƀaơ, ăn khân may mĭn rvê hom, ntơm bơh aƀaơ rlet lor sa ơm moh nau lĕ tât jêh ma khân may, tơ lah ê hŏ dơm lŭ aơ ta klơ lŭ ri ntŭk ngih brah Yêhôva.$b$,false),
('bunong-vn','HAG',2,16,null,$b$Du bông rnôk nây, tơ lah bu tât ta du mbŭch tâm di bar jât ndơ rnhueh, knŏng geh jât dơm; jêh ri tơ lah bu văch tât ta drŏng đak play kriăk ƀâu gâp ŭch bâk prăm jât ndơ rnhuch, geh knŏng bar jât.$b$,false),
('bunong-vn','HAG',2,17,null,$b$Gâp hŏ dŏng jêh lĕ nau prăng phang, ek găm, mih tŭp pler toyh tâm rmal phung khân may, tâm lĕ rngôch kan ti khân may ƀư, ƀiă lah khân may mâu hôm plơ̆ sĭt ma gâp ôh. Yêhôva lah.$b$,false),
('bunong-vn','HAG',2,18,null,$b$Aƀaơ ri mĭn rvê hom; ntơm bơh aƀaơ rlet lor sa ơm, nâm bu ntĭt ntơm bơh nar bar jât ma puăn, khay sĭn. Ntơm bơh nar bu ƀư jêh mbon ngih brah Yêhôva; mĭn rvê hom ăn nanê̆ nau nây!$b$,true),
('bunong-vn','HAG',2,19,null,$b$Khân may hôm e lĕ ntil tâm jay prăp? Tơm play pom gra nat, jêh ri tơm play Ôlivơ, tâm ban lĕ mâu geh ôh du tơm dơi geh play. Ƀiă lah ntơm bơh nar aơ, gâp mra ăn nau ueh uĭn ma khân may.$b$,false),
('bunong-vn','HAG',2,20,null,$b$Yêhôva ngơi rơh bar ma Y-Agê, nar bar jât ma puăn khay nây, pô aơ:$b$,true),
('bunong-vn','HAG',2,21,null,$b$Ngơi hom ma Y-Sôrôbabel, kôranh chiă uănh n'gor Yuđa, lah: Gâp mra rgu trôk jêh ri neh ntu.$b$,false),
('bunong-vn','HAG',2,22,null,$b$Gâp nklơ̆ lơi sưng hađăch lĕ rngôch ƀon bri hađăch, jêh ri ƀư roh lơi nau ktang lĕ rngôch ƀon bri hađăch phung ntil mpôl bunuyh; jêh ri ƀư rai lơi ndeh seh jêh ri phung ncho klơ, ăp nơm bu lơh nkhĭt ma đao oh nâu khân păng nơm.$b$,false),
('bunong-vn','HAG',2,23,null,$b$Yêhôva phung ta han lah: Hơi Y-Sôrôbabel, kon bu klâu Y-Sêaltiêl, tâm nar nây, gâp mra sŏk may, ƀư oh mon gâp! Yêhôva lah: Gâp mra dơm may nâm bu ndơ tâp pŏng, yor lah gâp hŏ săch may, Yêhôva phung ta han lah nây.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','HAG',1,1,0,'heading',$b$Nau Ntrôl Ndâk Ngih Brah$b$),
('bunong-vn','HAG',2,1,0,'heading',$b$Nau Chrêk Rmah Ngih Brah Yuđa Mhe$b$),
('bunong-vn','HAG',2,10,1,'heading',$b$Nau Nduyh Ma Phung Ƀon Lan Mâu Gŭ Răp Jăp$b$),
('bunong-vn','HAG',2,20,2,'heading',$b$Nau Yêhôva Ton Ma Y-Sôrôbabel$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'ZEC', $b$Y-Sakari$b$, $b$["Ndrom Sămƀŭt Bơh", "Y-SAKARI"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ZEC',1,1,null,$b$Khay pham năm tal bar Y-Darius chiă uănh, Yêhôva ngơi ma kôranh nơm mbơh lor Y-Sakari, kon bu klâu Y-Bêrêkia, sau Y-Idô, lah:$b$,true),
('bunong-vn','ZEC',1,2,null,$b$Yêhôva nuih ngăn ma chô- che khân may.$b$,false),
('bunong-vn','ZEC',1,3,null,$b$Pô ri may lah hom ma khân păng: Pô aơ nau Yêhôva ma phung ta han lah: Plơ̆ sĭt hom ma gâp, Yêhôva ma phung ta han lah, ri mơ gâp mra plơ̆ sĭt ma khân may. Yêhôva ma phung ta han lah.$b$,false),
('bunong-vn','ZEC',1,4,null,$b$Lơi ta ƀư nâm bu chô che khân may, phung kôranh nơm mbơh lor kăl e hŏ kuăl jêh khân păng, lah: Yêhôva ma phung ta han lah pô aơ, cha lơi hom trong mhĭk hên ri nau mhĭk khân may ƀư; ƀiă lah khân păng mâu iăt ôh, mâu lĕ ŭch tông ma gâp, Yêhôva lah.$b$,true),
('bunong-vn','ZEC',1,5,null,$b$Ta ntŭk chô che khân may gŭ? Jêh ri phung kôranh nơm mbơh lor geh nau rêh n'ho ro lĕ?$b$,false),
('bunong-vn','ZEC',1,6,null,$b$Ƀiă lah nau gâp ngơi jêh ri nau vay gâp hŏ ntăm jêh ma phung oh mon gâp jêng phung kôranh nơm mbơh lor, tât lĕ nau nây ma chô che khân may? Pô ri khân păng rmal nau tih jêh ri lah: Lĕ rngôch nau Yêhôva ma phung ta han hŏ mĭn jêh ma he tĭng nâm trong jêh ri kan he ƀư, tâm ban pô nây lĕ păng hŏ ƀư ma he.$b$,false),
('bunong-vn','ZEC',1,7,null,$b$Ta nar bar jât ma puăn, khay jât ma nguay, jêng khay Sêbat, tâm năm tal bar Y-Darius, chiă uănh, Yêhôva ngơi ma kôranh nơm mbơh lor Y-Sakari, kon bu klâu Y-Bêrêkia, Sau Y-Idô pô aơ:$b$,true),
('bunong-vn','ZEC',1,8,null,$b$Gâp saơ dôl bri măng: Aơ, geh du huê ncho seh chăng dâk tâm rlô tơm si mirtơ tâm rlŭng, jêh ri pa kơi păng geh phung seh chăng, seh guh, seh nglang.$b$,false),
('bunong-vn','ZEC',1,9,null,$b$Gâp lah: Hơi kôranh gâp, moh bu ntơ seh nây? Pô ri Tông mpăr ueh ngơi ma gâp, Gâp mra tâm mpơl moh khân păng jêng.$b$,false),
('bunong-vn','ZEC',1,10,null,$b$Pô nây bunuyh dâk tâm rlô tơm si mirtơ plơ̆ lah: Aơ jêng phung nơm Yêhôva prơh hăn nsong chop uănh neh ntu.$b$,false),
('bunong-vn','ZEC',1,11,null,$b$Khân păng plơ̆ lah ma Tông mpăr ueh dâk tâm rlô tơm si mirtơ pô aơ: Hên hŏ hăn nsong uănh jêh neh ntu aơ, lĕ rngôch neh ntu ăt gŭ răk klăk jêh ri đăp mpăn.$b$,true),
('bunong-vn','ZEC',1,12,null,$b$Rnôk nây Tông mpăr ueh bơh Yêhôva plơ̆ lah: Hơi Yêhôva ma phung ta han! Ndah nâm jŏ may yô̆ klâng ma ƀon Yêrusalem jêh ri lĕ ƀon tâm n'gor Yuđa, jêng ƀon Păng hŏ ji nuih jêh ri tâm rdâng đah păng tâm pơh jât năm aƀaơ ri?$b$,true),
('bunong-vn','ZEC',1,13,null,$b$Yêhôva plơ̆ sĭt lah ma nau ngơi ueh, nau ngơi bonh leng ma Tông mpăr ueh nơm ngơi đah gâp.$b$,false),
('bunong-vn','ZEC',1,14,null,$b$Pô nây, Tông mpăr ueh dôl ngơi ndrel gâp, lah pô aơ: Mbơh hom, jêh ri lah: Yêhôva ma phung ta han lah, gâp bêng ma nau ntôn ngăn ma ƀon Yêrusalem jêh ri yôk Siôn;$b$,true),
('bunong-vn','ZEC',1,15,null,$b$Jêh ri gâp nuih ngăn phung ntil mpôl bunuyh gŭ đăp mpăn; yor lah gâp bơi ma ji nuih, jêh ri khân păng lơ ntop nau rêh ni.$b$,false),
('bunong-vn','ZEC',1,16,null,$b$Yor nây Yêhôva lah: Gâp plơ̆ yô̆ đŏng ma ƀon Yêrusalem; yor lah ngih brah gâp mra ndâk tâm trôm păng, rse bu mra veh nthăng tâm ƀon Yêrusalem, Yêhôva ma phung ta han lah.$b$,true),
('bunong-vn','ZEC',1,17,null,$b$Mbơh tay đŏng: Yêhôva ma phung ta han lah: Lĕ rngôch ƀon toyh gâp mra hôm mbêng ma nau chăt jêng, Yêhôva hôm e bonh yôk Siôn jêh ri săch đŏng ƀon Yêrusalem.$b$,false),
('bunong-vn','ZEC',1,18,null,$b$Pô nây, gâp n'gơr măt, jêh ri saơ, aơ, geh puăn mlâm nke.$b$,false),
('bunong-vn','ZEC',1,19,null,$b$Gâp lah ma Tông mpăr ueh dôl ngơi đah gâp, lah: Moh ndơ nây? Păng plơ̆ lah: Nây jêng nke hŏ ƀư rai pru pra jêh phung Yuđa, phung Israel, jêh ri phung Yêrusalem.$b$,true),
('bunong-vn','ZEC',1,20,null,$b$Jêh ri Yêhôva mpơl ma gâp saơ puăn nuyh chiăr;$b$,true),
('bunong-vn','ZEC',1,21,null,$b$Pô ri gâp ôp: Phung aơ văch tât moh nau ƀư? Păng plơ̆ lah: Nây jêng nke hŏ ƀư rai ăn phung Yuđa pru pra, kŏ tât mâu geh nuyh n'gơr bôk ôh; ƀiă lah phung hŏ văch tât aơ gay ƀư nkrit khân păng, jêh ri gay klŭp lơi nke phung mpôl băl bunuyh bri bu hŏ tâm rdâng đah n'gor Yuđa gay ăn khân ô băl chah rai pru pra.$b$,false),
('bunong-vn','ZEC',2,1,null,$b$Gâp n'gơr măt jêh ri uănh; aơ, du huê bunuyh djôt rse veh tâm ti!$b$,true),
('bunong-vn','ZEC',2,2,null,$b$Gâp lah ma păng: Ntŭk may hăn? Păng plơ̆ lah: Gâp hăn veh ƀon Yêrusalem, gay saơ huêt huy jêh ri gleh jong păng.$b$,false),
('bunong-vn','ZEC',2,3,null,$b$Aơ, Tông mpăr ueh nơm ngơi đah gâp, hăn rlet pa năp, jêh ri geh du huê Tông mpăr ueh êng chuă vơt păng.$b$,false),
('bunong-vn','ZEC',2,4,null,$b$Jêh ri lah ma păng: Hăn nchuăt hom, ngơi lah ma bu klâu ndăm nây, Yêrusalem mra geh bunuyh gŭ nâm bu ƀon mâu geh mpêr ôh, yor geh âk ngăn bunuyh jêh ri mpô mpa ta nklang păng.$b$,false),
('bunong-vn','ZEC',2,5,null,$b$Yor lah gâp, Yêhôva lah: Gâp mra ƀư mpêr ma ŭnh gŭ jŭm păng, jêh ri mra ƀư nau chrêk rmah ta nklang păng.$b$,false),
('bunong-vn','ZEC',2,6,null,$b$Hơi! Hơi! Du hom tă bơh bri dor. Yêhôva lah: Yor lah gâp ƀư ăn khân may pru pra nâm bu puăn rlong sial tâm trôl. Yêhôva lah.$b$,true),
('bunong-vn','ZEC',2,7,null,$b$Hơi ƀon Siôn! Gŭ ndrel kon bu ur Babilôn, hơi, may du hom!$b$,false),
('bunong-vn','ZEC',2,8,null,$b$Yor lah Yêhôva ma phung ta han lah: Pa kơi jêh nau chrêk rmah, jêh nây păng prơh gâp hăn tât ma phung mpôl bunuyh pit in jêh ndơ khân may; yor lah mbu nơm pah bi khân may nâm bu ntĭt pah găr măt păng.$b$,false),
('bunong-vn','ZEC',2,9,null,$b$Yor lah aơ, gâp mra rvêh ti ta klơ khân păng, khân păng mra ƀư ndơ bu pit in ma phung pah kan khân păng; jêh ri khân păng mra gĭt Yêhôva ma phung ta han hŏ prơh gâp hăn tât.$b$,false),
('bunong-vn','ZEC',2,10,null,$b$Mprơ jêh ri hâk răm hom, Hơi kon Bu ur Ƀon Siôn; yor lah aơ, gâp văch tât, jêh ri gâp mra gŭ ta nklang may, Yêhôva lah.$b$,false),
('bunong-vn','ZEC',2,11,null,$b$Tâm nar nây âk bri dak mra tâm rnglăp đah Yêhôva, jêh ri mra jêng phung ƀon lan gâp; gâp mra gŭ ta nklang may, may mra gĭt Yêhôva ma phung ta han hŏ prơh jêh gâp hăn văch tât ma may.$b$,true),
('bunong-vn','ZEC',2,12,null,$b$Yêhôva mra dơn phung Yuđa nâm bu du kô̆ ăn ma păng tâm ntŭk kloh ueh, jêh ri păng mra hôm e săch đŏng Yêrusalem.$b$,false),
('bunong-vn','ZEC',2,13,null,$b$Ăn lĕ rngôch bunuyh gŭ rklăk pa năp măt Yêhôva; Yor lah păng hŏ kah rngăl tă bơh ntŭk kloh ueh păng.$b$,false),
('bunong-vn','ZEC',3,1,null,$b$Pô nây, Păng tâm mpơl ma gâp saơ kôranh ƀư brah toyh Y-Yôsuê dâk pa năp Tông mpăr ueh Yêhôva, jêh ri Satan gŭ mpeh pa ma păng ŭch phong ma păng.$b$,true),
('bunong-vn','ZEC',3,2,null,$b$Yêhôva lah ma Satan, Yêhôva geh nau dơi nduyh may, Hơi Satan! Yêhôva, jêng nơm hŏ săch jêh ƀon Yêrusalem, nduyh may! Mâu di hĕ ndơ aơ jêng rlŭt ŭnh bu rhuăt lơi tă bơh ŭnh?$b$,true),
('bunong-vn','ZEC',3,3,null,$b$Ta nây, Y-Yôsuê nsoh ao rmau ƀơ̆ , dâk tra năp Tông mpăr ueh Yêhôva,$b$,false),
('bunong-vn','ZEC',3,4,null,$b$Tông mpăr lah ma phung dâk ta năp păng; Doh lơi ao rmau păng. Jêh ri păng lah Y-Yôsuê: Uănh hom, gâp hŏ sŏk lơi jêh nau kue tă bơh may, jêh ri gâp mra ăn nsoh ao ueh ma may.$b$,false),
('bunong-vn','ZEC',3,5,null,$b$Gâp lah, ăn may ndô môk kloh klơ bôk păng. Pô ri bu ndô klơ bôk păng du mlâm môk kloh jêh ri bu ăn păng nsoh ao jâr; Tông mpăr ueh Yêhôva dôl dâk êp ta nây.$b$,false),
('bunong-vn','ZEC',3,6,null,$b$Tông mpăr ueh Yêhôva ntăm ma Y-Yôsuê, lah:$b$,false),
('bunong-vn','ZEC',3,7,null,$b$Pô aơ Yêhôva ma phung ta han lah: Tơ lah may chuat hăn tâm trong gâp, tông jêh ri djôt prăp nau gâp ntăm ri mơ may dơi phat dôih ngih gâp, jêh ri dơi gak njrăng mpông pêr gâp, gâp mra ăn ma may chuat lăp tâm nklang phung dâk ta aơ.$b$,false),
('bunong-vn','ZEC',3,8,null,$b$Hơi Y-Yôsuê, kôranh ƀư brah toyh, nđâp ma may jêh ri mĭt jiăng may gŭ pa năp măt may iăt hom, yor lah lĕ phung aơ jêng nau ntĭt ma nau mra tât: Aơ, n'hêl nanê̆ gâp mra ƀư phung Tông mpăr gâp jêng Nkŭr- keh chăt hao.$b$,true),
('bunong-vn','ZEC',3,9,null,$b$Yor lah aơ, ta lŭ gâp dơm jêh pa năp măt Y-Yôsuê, ta klơ lŭ nây geh pơh mlâm găr măt. Aơ, gâp mra tor rplay sămƀŭt ta klơ păng, jêh ri gâp mra sŏk lơi nau tih tă bơh bri dak aơ tâm du nar, Yêhôva ma phung ta han lah.$b$,true),
('bunong-vn','ZEC',3,10,null,$b$Tâm nar nây, Yêhôva ma phung ta han lah: Ăp nơm khân may mra jă bunuyh chiau meng păng gŭ tâm dâng tơm play kriăk ƀâu jêh ri tơm play rvi.$b$,false),
('bunong-vn','ZEC',4,1,null,$b$Tông mpăr ueh plơ̆ văch ngơi ma gâp, jêh ri rlay gâp, nâm bu du huê bunuyh dôl hăk bêch bu rlay.$b$,true),
('bunong-vn','ZEC',4,2,null,$b$Păng lah ma gâp pô aơ: Moh ndơ may saơ? Gâp plơ̆ lah: Aơ, gâp uănh saơ, du mlâm jâng jrêng lĕ nây ƀư đah mah, jêh ri du mlâm ngan rlŭ ta klơ păng, păng geh pơh mlâm ŭnh kađen; geh pơh mlâm dĭng ăn ăp ŭnh kađen gŭ ta klơ păng.$b$,false),
('bunong-vn','ZEC',4,3,null,$b$Gŭ êp kêng păng geh bar tơm play ôlivơ, ăp tơm play mpeh pa ma du mlâm ngan rlŭ, jêh ri du tơm play mpeh pa chiau.$b$,false),
('bunong-vn','ZEC',4,4,null,$b$Rnôk nây gâp ngơi ma phung Tông mpăr dôl ngơi đah gâp, Hơi kôranh gâp, moh nau aơ?$b$,true),
('bunong-vn','ZEC',4,5,null,$b$Tông mpăr ueh nơm ngơi đah gâp plơ̆ sĭt lah: May mâu gĭt ôh hĕ nau ntĭt ndơ aơ? Gâp lah: Mâu gĭt ôh, Hơi kôranh gâp.$b$,false),
('bunong-vn','ZEC',4,6,null,$b$Păng lah ma gâp: Aơ jêng nau ngơi bơh Yêhôva lah ăn Y-Sôrôbabel, pô aơ: Nau nây mâu di yor nau dơi ôh, kŏ mâu lĕ yor nau ktang, ƀiă lah yor Brah Huêng ueh gâp, Yêhôva ma phung ta han lah.$b$,false),
('bunong-vn','ZEC',4,7,null,$b$Hơi yôk toyh, Moh may jêng? Ta năp măt Y-Sôrôbabel may mra jêng neh lâng; jêh ri păng mra djôt leo lŭ ta klơ lơn; mra geh bâr bu nter lah: Yô̆ an păng, ăn nau yô̆ ma păng!$b$,false),
('bunong-vn','ZEC',4,8,null,$b$Jêh ri Yêhôva ngơi ma gâp, lah:$b$,false),
('bunong-vn','ZEC',4,9,null,$b$Ti Y-Sôrôbabel ndâk jêh mbon ngih aơ, pô ri ăt ti păng đŏng mra ƀư jêh; jêh ri may mra gĭt Yêhôva ma phung ta han hŏ prơh gâp hăn tât ndrel khân may.$b$,false),
('bunong-vn','ZEC',4,10,null,$b$Yor lah mbu moh mưch rmot ma nar geh nau jê̆ lê̆ ? Păng mra gŭ maak tơ lah saơ rse veh kăng n'har tâm ti Y-Sôrôbabel. Pơh mlâm gar măt aơ jêng măt Yêhôva hăn chop nhhol; lam bri neh ntu.$b$,true),
('bunong-vn','ZEC',4,11,null,$b$Jêh ri gâp lah ma Tông mpăr ueh: Moh nau ntĭt bar tơm play ôlivơ gŭ êp mpeh pa ma jêh ri mpeh pa chiau jâng jrêng mah nây?$b$,true),
('bunong-vn','ZEC',4,12,null,$b$Gâp ngơi đŏng tal ma tông bar, lah ma păng: Moh nau ntĭt bar n'gĭng play ôlivơ gŭ ta meng bar mlâm dĭng mah hoch dak play ôlivơ?$b$,false),
('bunong-vn','ZEC',4,13,null,$b$Păng lah ma gâp, May mâu gĭt hĕ lĕ nau nây? Gâp lah: Aơ jêng bar hê dơn Yêhôva troch dak ƀâu kah, dâk êp Kôranh Brah pah kan ma lam bri neh ntu.$b$,false),
('bunong-vn','ZEC',4,14,null,$b$Tông mpăr lah: “Nây jêng bar huê bunuyh hŏ mhing dak ngi gay ma pah kan ăn ma Kôranh Brah.”$b$,true),
('bunong-vn','ZEC',5,1,null,$b$Pô nây, gâp n'gơr đŏng măt uănh saơ, aơ geh du ndrom sămƀŭt ntâu mpăr.$b$,true),
('bunong-vn','ZEC',5,2,null,$b$Păng lah ma gâp: Moh may saơ? Gâp plơ̆ sĭt lah: Gâp saơ du ndrom sămƀŭt ntâu dôl mpăr; jong păng bar jât hăt, dĭ păng jât hăt.$b$,true),
('bunong-vn','ZEC',5,3,null,$b$Păng lah ma gâp: Nây jêng nau rak rtăp lam bri neh ntu; mbu moh ntŭng bu mra ƀư rai tĭng nâm nau chih mpeh du đah tâm sămƀŭt aơ; mbu moh ton sơm mƀruh bu mra ƀư rai lơi tĭng nâm nau chih đah ri tâm ndrom sămƀŭt aơ.$b$,true),
('bunong-vn','ZEC',5,4,null,$b$Yêhôva ma phung ta han lah: Gâp mra prơh ndrom sămƀŭt aơ hăn, păng mra lăp tâm ngih phung ntŭng, jêh ri tâm ngih phung ton sơm mƀruh ma amoh gâp; pô ri păng mra gŭ ta nklang ngih vâl nây jêh ri su vâl đah ŭnh sa nđâp ma kađar jêh ri lŭ.$b$,false),
('bunong-vn','ZEC',5,5,null,$b$Tông mpăr ueh nơm ngơi đah gâp hăn rlet pa năp jêh ri lah: Aƀaơ ri n'gơr hom măt uănh leo klơ moh ndơ luh du aơ.$b$,true),
('bunong-vn','ZEC',5,6,null,$b$Gâp lah: Moh ndơ nây? Păng plơ̆ sĭt lah: Nây jêng du mlâm êpha dôl luh. Păng lah đŏng: Nây jêng rup săk khân păng tâm lĕ bri neh.$b$,false),
('bunong-vn','ZEC',5,7,null,$b$Pô nây, gâp saơ du nklâm ndrak mlâm yơk lao klơ, jêh ri geh du huê bu ur gŭ ta nklang êpha!$b$,true),
('bunong-vn','ZEC',5,8,null,$b$Păng lah: Aơ jêng nau djơh mhĭk. Jêh nây păng nklơ̆ bunuyh bu ur gŭ đŏng tâm êpha, jêh ri rdêl lơi nklâm ndrak ta bâr êpha.$b$,false),
('bunong-vn','ZEC',5,9,null,$b$Rnôk nây gâp n'gơr uănh saơ, aơ, geh bar hê bu ur luh, sial khôm tâm nting năr khân păng; khân păng geh nting nar nâm bu nting nar klang kok; jêh ri khân păng chông lơi êpha vah vang trôk đah neh.$b$,false),
('bunong-vn','ZEC',5,10,null,$b$Gâp ôp Tông mpăr dôl ngơi đah gâp: Ta ntŭk khân păng chông leo êpha?$b$,true),
('bunong-vn','ZEC',5,11,null,$b$Păng plơ̆ lah ma gâp! Nây jêng gay ndâk du mlâm vâl ma êpha tâm bri Sinar; tơ lah hŏ nkra jêh, bu mra dơm êpha ta ntŭk păng.$b$,false),
('bunong-vn','ZEC',6,1,null,$b$Gâp n'gơr đŏng măt jêh ri uănh saơ; aơ, geh puăn mlâm ndeh seh luh tă bơh ta nklang bar mlâm yôk; jêh ri phung yôk nây jêng yôk ma kông.$b$,true),
('bunong-vn','ZEC',6,2,null,$b$Ntŭk ndeh seh sa ơm geh phung seh chăng; ndeh seh tal bar, geh seh krăk;$b$,false),
('bunong-vn','ZEC',6,3,null,$b$ndeh seh tal pe, seh nglang; ndeh seh tal puăn geh seh êr rvanh.$b$,false),
('bunong-vn','ZEC',6,4,null,$b$Pô nây gâp lah ma Tông mpăr ueh nơm ngơi đah gâp, lah: Hơi kôranh gâp! Moh bu ntĭt lĕ ndơ nây?$b$,true),
('bunong-vn','ZEC',6,5,null,$b$Tông mpăr ueh plơ̆ lah: Nây jêng puăn nuyh huêng brah tâm sial klơ trôk, luh tă bơh ntŭk khân păng dâk pa năp măt kôranh Brah lam bri neh ntu.$b$,false),
('bunong-vn','ZEC',6,6,null,$b$Phung seh krăk dui ndeh nƀuih tât n'gor bri dor, jêh ri phung seh nglang hăn tĭng păng; jêh ri phung seh rvanh êr hăn mpeh bri rđŭng.$b$,true),
('bunong-vn','ZEC',6,7,null,$b$Groi pa kơi phung seh dăng nđuih ueh hăn lam neh ntu. Tông mpăr lah ma khân păng: Hăn hom, chop uănh neh ntu. Pô ri khân păng chop uănh neh ntu.$b$,false),
('bunong-vn','ZEC',6,8,null,$b$Pô nây, păng kuăt gâp, jêh ri lah ma gâp: Aơ, phung seh hăn tât bri dor hă ƀư ăn Huêng Brah gâp gŭ mpăn tâm bri dor.$b$,false),
('bunong-vn','ZEC',6,9,null,$b$Pô aơ nau Y-Yêhôva ngơi ma gâp:$b$,true),
('bunong-vn','ZEC',6,10,null,$b$Ăn may sŏk sĭt lơi phung bună lĕ sĭt nây tă bơh Y-Hêldai, bơh Y-Tôbia jêh ri Y-Jêdaya phung hŏ tât jêh tă bơh ƀon Babilôn; jêh ri tâm nar nây ăn may hăn hom rlet ma ngih Y-Jôsia kon bu klâu Y-Sôphôni.$b$,false),
('bunong-vn','ZEC',6,11,null,$b$Sŏk dơn prăk jêh ri mah ƀư du mlâm đon hađăch ndơ klơ bôk kôranh ƀư brah toyh Y-Yôsuê kon bu klâu Y-Jêhôsadak.$b$,false),
('bunong-vn','ZEC',6,12,null,$b$Ăn may lah ma păng pô aơ: Yêhôva ma phung ta han lah: Ao, geh du huê bunuyh amoh păng jêng Nkŭr-keh, mra văch ma toyh nâm bu n'gĭng tă bơh ntŭk păng, jêh ri ndơ nây mra ndâk ngih brah Yêhôva.$b$,false),
('bunong-vn','ZEC',6,13,null,$b$Păng nơm yơh mra ndâk ngih brah Yêhôva; jêh ri păng nơm yơh mra bu yơk, gŭ chiă uănh ta klơ sŭng hađăch păng, ƀư kôranh ƀư brah gŭ klơ sưng hađăch păng; jêh ri mra geh nau tâm rnglăp ăn đăp mpăn ndăng lĕ bar nau kan.$b$,false),
('bunong-vn','ZEC',6,14,null,$b$Đon hađăch mra gŭ tâm ngih brah Yêhôva jêng du ntil ndơ kah gĭt ma Y-Hêldai, Y-Tôbia, Y-Jêlaya jêh ri Y-Hen kon bu klâu Y-Sôphôni.$b$,false),
('bunong-vn','ZEC',6,15,null,$b$Phung gŭ ngai mra tât, ndâk ngih brah Yêhôva; jêh ri khân may mra gĭt Yêhôva ma phung ta han prơh gâp hăn tât ma khân may; tơ lah khân may gơih srôih tông bâr Yêhôva may, pô ri nau nây mra tât ngăn.$b$,false),
('bunong-vn','ZEC',7,1,null,$b$Ta năm tal puăn hađăch Darius chiă uănh, Yêhôva ngơi ma Y-Sakari nar năng puăn khay sĭn, jêng khay Kislu.$b$,true),
('bunong-vn','ZEC',7,2,null,$b$Phung ƀon lan Bethel prơh hăn jêh Y-Sarêser jêh ri Rêgê-Mêlek ndrel ma phung bunuyh tĭng khân păng, gay ŭch dăn nau yô̆ an bơh Yêhôva;$b$,true),
('bunong-vn','ZEC',7,3,null,$b$jêh ri nkoch ma phung kôranh ƀư brah ngih Yêhôva ma phung ta han jêh ri ma phung kôranh nơm mbơh lor, lah: Gâp dơi nhĭm vơl lĕ jêh ri prăp êng gâp nơm tâm khay prăm nâm bu gâp hŏ ƀư âk năm ri?$b$,false),
('bunong-vn','ZEC',7,4,null,$b$Rnôk nây geh nau Yêhôva ma phung ta han lah ma gâp pô aơ:$b$,true),
('bunong-vn','ZEC',7,5,null,$b$Nkoch hom ma lĕ rngôch phung ƀon lan tâm n'gor jêh ri ndrel ma phung kôranh ƀư brah: Khân may ât sông sa jêh ri nhĭm vơl tâm khay prăm khay pơh hŏ pơh jât năm aơ jêh, di lĕ yor ma gâp, yor ma gâp ngăn, khân may ât sông sa nây?$b$,false),
('bunong-vn','ZEC',7,6,null,$b$Tơ lah khân may nhêt jêh ri sa, mâu hĕ yor ma khân may nơm dĭng nhêt jêh ri yor ma khân may dĭng sa?$b$,false),
('bunong-vn','ZEC',7,7,null,$b$Nau nây mâu di hĕ nau ngơi Yêhôva dŏng phung kôranh nơm mbơh lor rô̆ sa ơm hăn mbơh, tơ lah Yêrusalem jêh ri phung ƀon gŭ jŭm păng geh nau yach hao âk, jêh ri bri rđŭng jêh ri bri neh lâng geh bunuyh ƀon lan gŭ lĕ?$b$,true),
('bunong-vn','ZEC',7,8,null,$b$Pô nây, geh nau Yêhôva ngơi ma Y-Sakari, lah:$b$,true),
('bunong-vn','ZEC',7,9,null,$b$Pô aơ Yêhôva ma phung ta han lah: Ƀư hom moh nau ăn tâm di ngăn; jêh ri mpơl nau rah rơch, yô̆ klâng ndrăng oh nâu nơm;$b$,false),
('bunong-vn','ZEC',7,10,null,$b$Lơi ta ntêt ôh saơ ô băl jêng bu ur ndrô, kon đơi, nơm gŭ njơh tâm n'gor, mâu lah nơm o ach; may mĭn tâm nuih n'hâm ŭch ƀư nau mhĭk ma oh nâu păng.$b$,false),
('bunong-vn','ZEC',7,11,null,$b$Ƀiă lah khân păng dun mâu ŭch iăt, jêh ri ndôn kơi, nsêt lơi tôr khân păng gay lơi ăn khân păng dơi tăng ôh.$b$,true),
('bunong-vn','ZEC',7,12,null,$b$Khân păng ƀư ăn nuih n'hâm jêng dăng nâm bu lŭ, gay mâu tăng nau vay jêh ri lĕ nau ngơi Yêhôva ma phung ta han hŏ njuăl jêh ma Huêng Brah păng ma phung kôranh nơm mbơh lor kăl e ri. Yor nây Yêhôva ma phung ta han geh nau ji nuyh toyh ngăn.$b$,false),
('bunong-vn','ZEC',7,13,null,$b$Tơ lah gâp kuăl, khân păng mâu ŭch iăt ôh, pô ri lĕ, lah khân păng kuăl kŏ gâp mâu iăt lĕ, Yêhôva ma phung ta han lah.$b$,false),
('bunong-vn','ZEC',7,14,null,$b$Gâp ƀư ăn pru pra khân păng nâm bu sial vănh blông ta nklang lĕ rngôch ntil mpôl bunuyh khân păng mâu mâp gĭt ôh. Pô ri bri neh kŏ tât jêng rngol pa kơi khân păng mâu hôm geh bunuyh nsong mâu lah plơ̆ sĭt đŏng ôh; yor lah khân păng hŏ ƀư ăn bri dak ueh maak jêh, jêh ri jêng rngol.$b$,false),
('bunong-vn','ZEC',8,1,null,$b$Yêhôva ma phung ta han ngơi đŏng ma gâp, lah:$b$,true),
('bunong-vn','ZEC',8,2,null,$b$Pô aơ Yêhôva ma phung ta han lah: Gâp hŏ ntôn ngăn ma ƀon Siôn ma nau ntôn ktang ngăn, jêh ri gâp ntôn păng yor lah ma nau ji nuih toyh.$b$,false),
('bunong-vn','ZEC',8,3,null,$b$Pô aơ nau Yêhôva lah: Gâp mra plơ̆ sĭt đŏng ma Siôn jêh ri gŭ ta ƀon Yêrusalem Rnôk nây bu ntơ ƀon Yêrusalem jêng Ƀon Nanê̆ Ngăn, jêh ri yôk Yêhôva ma phung ta han bu mra ntơ Yôk Kloh ueh.$b$,false),
('bunong-vn','ZEC',8,4,null,$b$Yêhôva phung ta han lah: Mra hôm e phung bu ranh bu ur, bu klâu gŭ rŏ trong sâng ƀon Yêrusalem, ăp nơm djôt mâng jra ta ti, yor păng lĕ ranh ngăn.$b$,true),
('bunong-vn','ZEC',8,5,null,$b$Lĕ trong sâng tâm ƀon toyh mra bêng phung bu klâu ndăm bu ur druh gŭ pâl rlưn rŏ nây.$b$,false),
('bunong-vn','ZEC',8,6,null,$b$Yêhôva phung ta han lah: Tâm nar nây, nđâp tơ lah phung ƀon lan hôm e klen aơ, uănh ma nau nây nâm bu hih rhâl, ƀiă lah ma măt gâp uănh mâu hĕ khlay nau nây? Yêhôva phung ta han lah.$b$,true),
('bunong-vn','ZEC',8,7,null,$b$Yêhôva phung ta han lah: Aơ, gâp mra tâm nklaih phung ƀon lan gâp ntơm bơh mpeh pa lơ n'ho tât mpeh pa dâng,$b$,false),
('bunong-vn','ZEC',8,8,null,$b$jêh ri leo khân păng sĭt ăn gŭ ta nklang ƀon Yêrusalem; khân păng mra jêng phung ƀon lan gâp, bi gâp mra jêng Brah Ndu khân păng tâm nau nanê̆ ngăn jêh ri nau sŏng srăng.$b$,false),
('bunong-vn','ZEC',8,9,null,$b$Yêhôva phung ta han lah: Khân may jêng phung, gŭ nar aơ, ăn lĕ nau ngơi nây tă bơh bâr mbung phung kôranh nơm mbơh lor, phung mbơh rnôk bu ƀư mbon ngih Yêhôva phung ta han, nâm bu ntĭt ngih brah, gay bu dơi ndâk nkra, pô ri ăn khân may ƀư ăn nâp ti khân may dơi dăng ktang.$b$,true),
('bunong-vn','ZEC',8,10,null,$b$Yor lah lor pa năp nar nây mâu geh nau nkhôm ôh ma kan bu pah, ăt mâu geh lĕ nau nkhôm ma mpô mpa; jêh ri yor ma phung rlăng ŭch tâm rdâng, pô ri mâu geh ôh nau gŭ mpăn nơm rlăng nsong luh nsong lăp; yor gâp hŏ ăn lĕ rngôch bunuyh ăp nơm tâm rdâng đah phung chiau meng păng.$b$,false),
('bunong-vn','ZEC',8,11,null,$b$Ƀiă lah aƀaơ ri gâp mâu mra ƀư ôh ma phung ƀon lan hôm e aơ nâm bu gâp ƀư kăl e. Yêhôva phung ta han lah.$b$,false),
('bunong-vn','ZEC',8,12,null,$b$Yor gŭ ta nây mra geh ntil đăp mpăn; tơm kriăk ƀâu mra geh play, jêh ri neh mra geh play âk tât yan păng, bơh trôk ăn dak ngom; jêh ri gâp mra ăn phung ƀon lan hôm e mbơh ndơ aơ.$b$,false),
('bunong-vn','ZEC',8,13,null,$b$Hơi ngih Yuđa jêh ri Israel! Mra geh nau tât nâm bu khân may hŏ jêng jêh nau tâm ntĭt ma nau rak rtăp ta nklang ntil mpôl bunuyh êng, pô ri gâp mra tâm rklaih khân may, jêh ri khân may mra jêng du nau ueh uĭn. Lơi klach ôh, ƀiă lah ăn ti khân may jêng ktang.$b$,false),
('bunong-vn','ZEC',8,14,null,$b$Yor lah Yêhôva phung ta han lah: Nâm bu gâp hŏ ƀư jêh nau mhĭk ăn khân may, tơ lah chô yau khân may nsônh nau ji nuih gâp, gâp mâu yô̆ ôh. Yêhôva phung ta han lah,$b$,true),
('bunong-vn','ZEC',8,15,null,$b$pô ri nar aơ ăt tâm ban lĕ, gâp hŏ mĭn tay ăn nau ueh yô̆ ma ƀon Yêrusalem jêh ri ma ngih Yuđa: Khân may lơi ta klach ôh!$b$,false),
('bunong-vn','ZEC',8,16,null,$b$Aơ jêng nau ăn khân may ƀư: Ăp nơm sŏk nau ngơi ngăn ngơi ndrăng phung chiau meng păng; ƀư hom nau n'hêl nanê̆ jêh ri nau phat dôih ma nau đăp mpăn tâm mpông pêr ƀon khân may,$b$,true),
('bunong-vn','ZEC',8,17,null,$b$lơi ta mĭn tâm nuih n'hâm ŭch ƀư mhĭk ndrăng khân may; jêh ri lơi ta rŏng nau ton sơm mƀruh ôh, yor lah gâp tâm rmot ma lĕ rngôch nau nây. Yêhôva lah.$b$,false),
('bunong-vn','ZEC',8,18,null,$b$Yêhôva phung ta han ngơi đŏng ma gâp, lah:$b$,true),
('bunong-vn','ZEC',8,19,null,$b$Pô aơ Yêhôva phung ta han lah: Nau ât sông sa ta khay puăn, ta khay prăm ta khay pơh, jêh ri khay jât mra ƀư ăn ngih Yuđa geh nau maak jêh ri hâk năm, jêh ri nar năng pâl rlưn bêng ma nau maak. Yor nây rŏng hom ma nau n'hêl nanê̆ jêh ri đăp mpăn.$b$,false),
('bunong-vn','ZEC',8,20,null,$b$Yêhôva phung ta han lah: Âk phung ƀon lan ăt mra văch da dê, nâm bu ntĭt, phung gŭ tâm âk rplay ƀon toyh,$b$,true),
('bunong-vn','ZEC',8,21,null,$b$jêh ri phung gŭ tâm du rplay ƀon toyh mra hăn ma du rplay ƀon toyh êng, lah: Ăn he hăn ro gay vơl dăn nau yô̆ Yêhôva jêh ri ŭch joi Yêhôva phung ta han; gâp mra hăn tâm ban lĕ.$b$,false),
('bunong-vn','ZEC',8,22,null,$b$Pô nây âk phung ƀon lan jêh ri phung ntil mpôl bunuyh ktang mra văch ta ƀon Yêrusalem, jêh ŭch joi Yêhôva phung ta han jêh ri gŭ ta nây vơh vơl ma nau Yêhôva yô̆.$b$,false),
('bunong-vn','ZEC',8,23,null,$b$Pô aơ Yêhôva phung ta han lah: Mra geh du nau tât tâm nar nây, geh jât nuyh tă tâm ntil mpôl bunuyh ngơi êng êng, kuăn rdâng ta ntôr ao du huê Yuđa, lah: Ăn hên hăn ndrel khân may.$b$,false),
('bunong-vn','ZEC',9,1,null,$b$Nau anh jâk ma nau Yêhôva tâm rdâng đah bri Hadrak, păng mra nkhŭt ta ƀon Damas: Yor lah măt kon bunuyh jêh ri noi deh Israel gŭ uănh ma Yêhôva.$b$,true),
('bunong-vn','ZEC',9,2,null,$b$Nau ngơi nây tâm ban lĕ lah ma ƀon Hamat, tâm n'har đah ƀon Damas, nđâp ƀon Tir jêh ri ƀon Sidôn, yor lah lĕ ƀon nây jêng ƀon geh nau blau hâu ngăn.$b$,false),
('bunong-vn','ZEC',9,3,null,$b$Yor lah ƀon Tir hŏ ƀư du mlâm pôih nâp ma păng nơm, prăp nkrem prăk nâm bu ndruyh neh, jêh ri mah nâm bu dak bŏk rŏ trong sâng.$b$,false),
('bunong-vn','ZEC',9,4,null,$b$Aơ, kôranh brah mra sŏk pit lĕ ndơ păng, nklơ̆ lơi nau ndrŏng păng tâm dak mƀŭt, jêh ri ŭnh mra sa lơi păng.$b$,false),
('bunong-vn','ZEC',9,5,null,$b$Ƀon Askalon mra saơ nau nây jêh ri klach; nđâp ma ƀon Gaxa tâm ban lĕ mra saơ jêh ri rêh ni, nđâp ƀon Êkron tâm ban lĕ, yor lah nau păng kâp gân mra rai: Hađăch ƀon Gaxa mra roh, ƀon Askalon mra jêng rngol,$b$,true),
('bunong-vn','ZEC',9,6,null,$b$phung mpôl băl tâm rlŭk mra gŭ tâm ƀon Asdôt, jêh ri gâp mra ngroh lơi nau sưr phung Philistin.$b$,false),
('bunong-vn','ZEC',9,7,null,$b$Ƀiă lah gâp mra sŏk lơi mham păng tă bơh trôm mbung păng; jêh ri phung hôm e mra jêng phung Brah Ndu he, păng jêng kôranh noi deh Yuđa, jêh ri phung Êkron mra jêng nâm bu phung Jêbusit.$b$,true),
('bunong-vn','ZEC',9,8,null,$b$Gâp mra ƀư pôih gŭ jŭm ngih gâp tâm rdâng đah phung ta han păng, gay lơi geh du huê nuyh nsong ôh, jêh ri mâu hôm geh ôh bunuyh tŭn jot mra tŭn jot đŏng phung ƀon lan gâp, yor lah aƀaơ ri gâp hŏ mêt uănh đah trôm măt gâp nơm.$b$,false),
('bunong-vn','ZEC',9,9,null,$b$Hơi kon bu ur ƀon Siôn, lĕ rngôch hâk răm hom! Hơi kon bu ur ƀon Yêrusalem, troh nter răm maak! Aơ, hađăch may văch ma may, Păng jêng nau sŏng jêh ri ăn nau tâm rklaih, dêh rhêt jêh ri ncho seh bri kon, jêng kon bơh seh bri me.$b$,true),
('bunong-vn','ZEC',9,10,null,$b$Gâp mra ƀư rai lơi ndeh seh bơh bri Êphraim jêh ri seh tâm lơh tă bơh ƀon Yêrusalem, jêh ri na tâm lơh nklah lơi lĕ, jêh ri păng mra lah nau đăp mpăn ăn ma lĕ bri dak; nau dơi păng mra srih ntơm bơh dak mƀŭt aơ tât ma dak mƀŭt ri, ntơm bơh Dak Krong aơ tât ma bôl dŭt neh ntu.$b$,true),
('bunong-vn','ZEC',9,11,null,$b$Bi ma may tâm ban đŏng, yor lah mham gâp tâm rnglăp đah may, pô ri gâp mra mƀơk phung bună may tă bơh ntu jru mâu geh dak ôh.$b$,true),
('bunong-vn','ZEC',9,12,null,$b$Hơi phung bu krŭng geh nau kâp gân; ăn khân may bar tơ̆ âk lơn,$b$,false),
('bunong-vn','ZEC',9,13,null,$b$yor lah gâp van phung Yuđa, nâm bu na gâp, bi Êphraim nâm bu har păng. Gâp mra nsônh kon bu klâu may, Hơi ƀon Siôn, tâm rdâng đah kon bu klâu may, Hơi bri Grek; jêh ri gâp mra ăn may jêng nâm bu đao phung ta han tâm lơh.$b$,false),
('bunong-vn','ZEC',9,14,null,$b$Rnôk nây Yêhôva mra dơi saơ klơ khân păng, amoh păng luh du nâm bu lơp nglaih; Yêhôva mra uh nŭng, jêh ri hăn ndrel ma sial vănh blông mpeh rđŭng.$b$,true),
('bunong-vn','ZEC',9,15,null,$b$Yêhôva phung ta han mra mât njrăng khân păng, khân păng mra ƀư rai. Jêh ri khân păng dơi dôl klŭp lŭ; khân păng mra nhêt sa jêh ri ƀư drơu drơu nâm bu nhŭl ndrănh, mra ler bêng nâm bu tâm ngan rlŭ nâm bu lĕ njônh nơng ƀư brah.$b$,true),
('bunong-vn','ZEC',9,16,null,$b$Ta nar nây, Yêhôva Brah Ndu khân păng mra tâm rklaih phung khân păng nâm bu phung biăp, nâm bu lŭ khlay ta du mlâm đon hađăch, mra dơi ndâk ta klơ neh ntu.$b$,false),
('bunong-vn','ZEC',9,17,null,$b$Ngăn yơh, toyh ngăn nau ueh păng jêh ri mơih rmên păng! Ba mra ƀư ktang đŏng phung bu klâu mom ndăm, jêh ri play kriăk ƀâu mhe ăn ma phung bu ur druh ndơi chăt hao.$b$,true),
('bunong-vn','ZEC',10,1,null,$b$Dăn hom dak mih bơh Yêhôva tâm rnôk dak nuih lĕ dŭt yan, pô ri Yêhôva mra ƀư lơp jêh ri njêng ăn dak mih ma bunuyh, gay ma ăp nuyh dơi geh biăp trau tâm nkang mir.$b$,true),
('bunong-vn','ZEC',10,2,null,$b$Yor lah phung rup brah ngơi dơm dam, lĕ phung n'hăm saơ jêh nau mƀruh păng; khân păng nkoch mbơi mƀruh ndơm bu, jêh ri ăn nau bonh leng mâu khlay ôh. Yor nây phung ƀon lan mblêng nâm bu biăp, bu ƀư ăn khân păng rêh ni nâm bu mâu geh rmăk chiăp.$b$,false),
('bunong-vn','ZEC',10,3,null,$b$Nau gâp ji nuih duh n'hôl tâm rdâng đah phung rmăk biăp, jêh ri gâp mra tâm rmal phung be nkuăng; yor lah Yêhôva phung ta han hŏ chop phung biăp Păng, jêng ngih Yuđa; jêh ri dăp nthăng nâm bu seh ma nau tâm lơh.$b$,true),
('bunong-vn','ZEC',10,4,null,$b$Lŭ ta njônh luh tă bơh păng, kađĭn pâng tă bơh păng, hăr na tâm lơh luh tă bơh păng, jêh ri lĕ rngôch phung kôranh mât uănh ăt luh tă bơh păng đŏng.$b$,false),
('bunong-vn','ZEC',10,5,null,$b$Ƀiă lah khân păng jêng nâm bu phung dăng ktang jot phung rlăng tâm dak bŏk rŏ trong sâng tâm nôk tâm lơh; khân păng mra tâm lơh; yor lah Yêhôva gŭ ndrel ma khân păng, pô ri phung bunuyh ncho seh mra prêng.$b$,true),
('bunong-vn','ZEC',10,6,null,$b$Gâp mra ƀư ăn ma ngih Yuđa dơi ktang, jêh ri tâm rklaih ngih Yuđa dơi ktang, jêh ri tâm rklaih ngih Yôsep. Gâp mra leo khân păng plơ̆ sĭt, yor lah gâp geh nau yô̆ klâng khân păng, jêh ri khân păng mra jêng nâm bu gâp ê hŏ mâp dun ôh ma khân păng, yor lah gâp jêng Yêhôva Brah Ndu khân păng, jêh ri gâp mra plơ̆ sĭt lah ma khân păng.$b$,true),
('bunong-vn','ZEC',10,7,null,$b$Phung Êphraim mra jêng nâm bu phung dăng ktang, nuih n'hâm păng hâk răm nâm bu yor tă bơh ndrănh; phung kon khân păng mra saơ nau nây jêh ri răm maak, nuih n'hâm khân păng mra maak tâm Yêhôva.$b$,true),
('bunong-vn','ZEC',10,8,null,$b$Gâp mra kuăt khân păng jêh ri rgum khân păng, yor lah gâp hŏ chuai tay khân păng; khân păng mra jêng bĭk rơ̆ nâm bu kăl e.$b$,false),
('bunong-vn','ZEC',10,9,null,$b$Gâp mra srih khân păng ta nklang ntil mpôl bunuyh, tâm bri dak ngai ngăn khân păng mra kal gĭt vơl tay ma gâp; khân păng mra rêh ndrel ma phung kon khân păng jêh ri plơ̆ sĭt đŏng.$b$,false),
('bunong-vn','ZEC',10,10,null,$b$Pô nây gâp mra njŭn khân păng sĭt tă bơh n'gor bri Êjipt, jêh ri tâm rgum khân păng tă bơh bri Asiri; gâp mra njŭn khân păng ma bri Galaat jêh ri ma bri Liban, kŏ tât mâu geh ôh ntŭk ma khân păng gŭ.$b$,false),
('bunong-vn','ZEC',10,11,null,$b$Khân păng mra rgăn dak mƀŭt jêr ngăn, bu mra ƀư rngân n'ha dak rbuh, jêh ri lĕ rngôch klŏng jru dak krong Nil mra suăt. Bu mra n'glưh lơi nau sưr bri Asiri, jêh ri mâng jra hađăch n'gor bri Êjipt mra roh.$b$,false),
('bunong-vn','ZEC',10,12,null,$b$Gâp mra ƀư ktang khân păng tâm Yêhôva jêh ri khân păng mra chuat hăn tâm amoh păng Yêhôva lah.$b$,false),
('bunong-vn','ZEC',11,1,null,$b$Hơi bri Liban, ăn may pơk mpông may, gay ăn ŭnh sa tơm si sêdar may!$b$,true),
('bunong-vn','ZEC',11,2,null,$b$Hơi tơm si chiprơ, nhĭm vơl hom! Yor lah tơm si sêdar lĕ cha lôt jêh, lĕ tơm si ueh hŏ rai jêh. Hơi tơm sen bri Basan, nhĭm vơl hom, yor lah lĕ bu kăl jêh ri krŏng mbâl!$b$,false),
('bunong-vn','ZEC',11,3,null,$b$Geh bâr phung rmăk biăp nhĭm vơl! Yor lah ntŭk ndrêch gơ̆ ueh khân păng lĕ rai jêh; yor geh bâr yau mŭr ngrông! Yor nau sưr dak krong Yurdan hŏ rai jêh!$b$,false),
('bunong-vn','ZEC',11,4,null,$b$Pô aơ nau Yêhôva Brah Ndu ngơi, lah: Ăn hom phung biăp bu mra nkhĭt sa gơ̆ ;$b$,true),
('bunong-vn','ZEC',11,5,null,$b$phung nơm tơm rvăt nkhĭt khân păng, jêh ri mâu lah ôh ma khân păng tih; bi ma nơm tăch lah: Yêhôva mât ton ngăn, yor lah gâp jêng ndrŏng; jêh ri tâm phung rmăk biăp mâu geh du huê bunuyh yô̆ nhhuach ôh ma khân păng.$b$,false),
('bunong-vn','ZEC',11,6,null,$b$Yêhôva lah: Yor lah gâp mâu nhhuach ŭch yô̆ ma phung bunuyh ƀon lan gŭ tâm n'gor bri aơ đŏng ôh; ƀiă lah, aơ, gâp ma jao ăp nơm tâm ti phung chiau meng păng, jêh ri tâm ti hađăch păng; khân păng mra tŭn jot bri neh, jêh ri gâp mra tâm rklaih ôh khân păng tă bơh ti phung nây.$b$,false),
('bunong-vn','ZEC',11,7,null,$b$Yor ri gâp ăn phung biăp bu mra nkhĭt sa gơ̆ , jêng phung biăp rêh ni ngăn tâm phung mpôl păng. Yor nây, gâp sŏk bar mlâm mâng jra: Du mlâm mâng bu ntơ Ueh-Reh, du mlâm mâng bu ntơ Rse-chăp nâm bu ntĭt Nau Yô̆ jêh ri Nau Tâm Rnglăp; jêh ri gâp chiăp ăn phung biăp sa gơ̆ .$b$,true),
('bunong-vn','ZEC',11,8,null,$b$Knŏng tâm du khay dơm gâp ƀư rai jêh pe nuyh rmăk biăp; yor lah huêng gâp mâu ŭch srôih đah khân păng ôh, jêh ri tâm ban lĕ huêng khân păng tâm rmot ma gâp.$b$,false),
('bunong-vn','ZEC',11,9,null,$b$Pô ri gâp lah: Gâp mâu mra chiăp khân may ôh. Moh biăp khĭt, ăn păng khĭt, moh biăp roh, ăn păng roh, bi ma phung biăp hôm e tâm kăp tâm sa ndrăng khân păng.$b$,false),
('bunong-vn','ZEC',11,10,null,$b$Pô nây, gâp sŏk mâng jra gâp ntơ Ueh-Reh sreh rgăl khân păng tĭng gâl, gay ngroh lơi nau tâm rnglăp gâp hŏ tâm rnglăp jêh đah lĕ rngôch phung ƀon lan.$b$,false),
('bunong-vn','ZEC',11,11,null,$b$Pô ri păng ƀư rkhat lơi tâm nar nây, yor nây phung biăp bu nkrit tâm phung mpôl păng, rêh ni ngăn, jêng biăp iăt tĭng ndô̆ gâp, gĭt jêh nây jêng nau Yêhôva ngơi.$b$,false),
('bunong-vn','ZEC',11,12,null,$b$Gâp lah ma khân păng: Tơ lah khân may mĭn ueh, pô ri ăn hôm nau nkhôm ma gâp; lah mâu di pha lah lơi ăn. Pô ri khân păng rnhuch rnoh nkhôm nây ma gâp pe jât rlat prăk.$b$,false),
('bunong-vn','ZEC',11,13,null,$b$Yêhôva lah ma gâp: Sŏk hom rnoh prăk ueh khân păng mĭn ŭch ăn ma gâp nây, leo nsrih ma nơm mon ta trôm ngih Yêhôva.$b$,false),
('bunong-vn','ZEC',11,14,null,$b$Jêh ta nây gâp sreh lơi mâng jra tal bar bu ntơ Rse-chăp, gay tâm rkhat lơi nau jêng oh nâu ta nklang phung Yuđa đah Israel.$b$,false),
('bunong-vn','ZEC',11,15,null,$b$Jêh ri Yêhôva lah đŏng ma gâp, Sŏk hom ndô ndơ du huê rmăk biăp rluk ăn ma may.$b$,true),
('bunong-vn','ZEC',11,16,null,$b$Yor lah aơ, gâp mra ăn du huê rmăk biăp tâm bri neh aơ, nơm nây mâu mra chrê ôh ma biăp păng lĕ roh, mâu lĕ ŭch tĭng joi biăp păng nhhơt, kŏ mâu ŭch mât siăm biăp păng sôt rmanh; mâu ŭch mât siăm biăp păng ăn toyh lay; ƀiă lah păng ŭch sa gŭch biăp păng dŭt lay, jêh ri nkhêk lơi nchop ô băl.$b$,false),
('bunong-vn','ZEC',11,17,null,$b$Rêh ni ngăn ma rmăk biăp dơm dam, nơm cha lơi phung biăp păng! Ăn đao sreh ta nting tur păng jêh ri ta trôm măt pa ma păng! Ăn nting tur păng kro lĕ, jêh ri trôm măt pa ma păng chieh lĕ ƀhiau.$b$,false),
('bunong-vn','ZEC',12,1,null,$b$Anh jâk nau Yêhôva ngơi ma Israel, Yêhôva jêng Nơm pơk rvang phung trôk, jêh ri ƀư mbon neh ntu, jêh ri njêng huêng tâm trôm săk bunuyh, lah pô aơ:$b$,true),
('bunong-vn','ZEC',12,2,null,$b$Aơ, gâp mra ƀư ăn Yêrusalem jêng du mlâm kachok ƀư ve măt ma lĕ rngôch phung ƀon lan gŭ jŭm păng; jêh ri tơ lah bu nchueng jêh ƀon Yêrusalem ŭch tâm rdâng đah phung Yuđa tâm ban lĕ.$b$,false),
('bunong-vn','ZEC',12,3,null,$b$Nau tât tâm nar nây, gâp mra ăn ma ƀon Yêrusalem ƀư du mlâm lŭ toyh jâk ngăn ăn ma lĕ rngôch ntil mpôl bunuyh. Ma mbu moh chông anh păng mra geh nau sôt rmanh jru; jêh ri lĕ rngôch bri dak mra tâm rgum du ai tâm rdâng đah păng.$b$,false),
('bunong-vn','ZEC',12,4,null,$b$Yêhôva lah: Tâm nar nây, gâp mra ăn lĕ rngôch seh geh nau klach, ăn ma bunuyh ncho păng geh nau rluk brŭt, gâp mra lar măt gâp uănh klơ ngih Yuđa, jêh ri mbang lĕ rngôch seh phung ƀon lan ăn chieh măt.$b$,true),
('bunong-vn','ZEC',12,5,null,$b$Rnôk nây phung kôranh Yuđa mra lah tâm nuih n'hâm păng: Phung ƀon lan gŭ ta ƀon Yêrusalem geh nau ktang, Yor lah Yêhôva phung ta han, jêng Brah Ndu khân păng.$b$,true),
('bunong-vn','ZEC',12,6,null,$b$Tâm nar nây, gâp mra ƀư ma phung kôranh Yuđa nâm bu năk dơ glah ŭnh hit ta nklang nchăp ƀiă lah, khân păng mra ƀư rai sa lĕ mpeh pa ma jêh ri mpeh pa chiau lĕ rngôch phung ƀon lan gŭ jŭm păng; jêh ri phung ƀon lan gŭ ta ƀon Yêrusalem mra hôm e gŭ ta ntŭk păng nơm, nây jêng Yêrusalem.$b$,true),
('bunong-vn','ZEC',12,7,null,$b$Yêhôva mra tâm rklaih lor lơn phung ngih bok Yuđa, gay ma chrêk rmah ma ngih Y-Đavit jêh ri nau chrêk rmah phung ƀon lan gŭ ta ƀon Yêrusalem mâu dơi geh nau yơk rlau lơn phung Yuđa ôh.$b$,true),
('bunong-vn','ZEC',12,8,null,$b$Tâm nar nây, Yêhôva mra ƀư Nơm kâp kơl ma phung gŭ ta ƀon Yêrusalem, jêh ri ta nar nây phung ra ai ngăn tâm phung khân păng mra jêng nâm bu Y-Đavit, ngih Y-Đavit mra jêng nâm bu Brah Ndu, mra jêng nâm bu Tông mpăr Yêhôva hăn pa năp măt khân păng.$b$,true),
('bunong-vn','ZEC',12,9,null,$b$Nau tât tâm nar nây gâp mra ntơm ƀư rai lơi lĕ rngôch phung ntil mpôl bunuyh văch tât tâm rdâng đah ƀon Yêrusalem.$b$,false),
('bunong-vn','ZEC',12,10,null,$b$Gâp mra nkhŭt Brah huêng ueh nau yô̆ jêh ri nau vơh vơl ăn ta klơ ngih Y-Đavit, jêh ri ma phung gŭ tâm ƀon Yêrusalem; khân păng mra uănh ma gâp jêng Nơm khân păng hŏ ntâp; jêh ri khân păng mra nhĭm vơl ma păng, nâm bu bu nhĭm vơl ma kon bu klâu geh knŏng du huê, jêh ri nhĭm vơl ma nau rngot ma ô băl, nâm bu bu nhĭm vơl ma kon bu deh ntơm bôk rah.$b$,true),
('bunong-vn','ZEC',12,11,null,$b$Ta nar nây nau nhĭm vơl tâm ƀon Yêrusalem mra jêng toyh, nâm bu nau nhĭm vơl Hadat- Rimôn tâm neh lâng Mêgidô.$b$,false),
('bunong-vn','ZEC',12,12,null,$b$Bri dak bu nhĭm vơl, ăp ntil mpôl êng êng; mpôl ngih Y-Đavit êng păng, rđâp ma phung ur khân păng êng đŏng; mpôl ngih Y-Nathan êng păng, nđâp ma phung ur khân păng êng êng đŏng;$b$,true),
('bunong-vn','ZEC',12,13,null,$b$mpôl ngih Y-Lêvi êng păng, rđâp ma phung ur khân păng êng đŏng; mpôl Y-Simêa êng păng, jêh ri phung ur khân păng êng êng đŏng;$b$,false),
('bunong-vn','ZEC',12,14,null,$b$jêh ri lĕ rngôch phung mpôl hôm e, ăp mpôl êng êng jêh ri phung ur khân păng êng êng đŏng.$b$,false),
('bunong-vn','ZEC',13,1,null,$b$Ta nar nây bu mra pơk du tu dak ăn ma ngih Y-Đavit jêh ri phung gŭ tâm ƀon Yêrusalem, gay ƀư kloh khân păng, yor nau tih jêh ri nau ƀơ̆ ƀơch.$b$,true),
('bunong-vn','ZEC',13,2,null,$b$Yêhôva phung ta han lah: Tâm ban lĕ nau tât tâm nar nây, gâp mra ƀư roh lơi amoh lĕ rngôch rup brah tâm bri dak, gay ma bu mâu hôm kah gĭt ôh ma khân păng; gâp tâm ban lĕ mra mprơh nsot lơi tă bơh bri dak phung kôranh nơm mbơh lor jêh ri brah ƀơ̆ ƀơch.$b$,false),
('bunong-vn','ZEC',13,3,null,$b$Ntơm bơh aƀaơ tât kăndơ̆ tơ lah hôm e geh bunuyh mbơh lor, pô ri mbơ̆ jêh ri mê̆ jêng nơm hŏ deh jêh ăn păng, mra lah ma păng: May mâu mra rêh đŏng ôh, yor lah may ngơi nau mƀruh amoh Yêhôva? Mê̆ jêh ri mbơ̆ jêng nơm hŏ deh jêh ăn păng mra ntâp păng tơ lah păng mbơh lor.$b$,true),
('bunong-vn','ZEC',13,4,null,$b$Ta nar nây ăp nơm kôranh nơm mbơh lor mra prêng ma nau păng tâm saơ, tơ lah păng mbơh lor; khân păng tâm ban lĕ mâu mra nsoh ôh ao jâr ma rsau gay ngơi ndơm đŏng.$b$,true),
('bunong-vn','ZEC',13,5,null,$b$Ƀiă lah lah păng mra lah: Gâp mâu jêng nơm mbơh lor ôh, gâp jêng du huê bunuyh chuar lŏ sre; yor lah gâp hŏ ƀư mir ƀiă lah ntơm bơh jê̆.$b$,false),
('bunong-vn','ZEC',13,6,null,$b$Lah geh bu ôp: Moh geh nau sôt may ta nting tur? Pô ri păng plơ̆ lah: Nây jêng nau sôt hŏ geh tâm ngih jiăng gâp.$b$,false),
('bunong-vn','ZEC',13,7,null,$b$Yêhôva phung ta han lah: Hơi đao, kah rngăl hom may tâm rdâng đah rmăk biăp gâp, jêh ri tâm rdâng đah bunuyh ƀư mĭt jiăng đah gâp; Dong hom rmăk biăp, ăn phung biăp chah rai nhhơt blă blơ; jêh ri gâp mra rle ti gâp ƀư ma phung kon se jê̆.$b$,true),
('bunong-vn','ZEC',13,8,null,$b$Yêhôva lah: Nau tât tâm lam bri, bar kô̆ tâm păng mra ƀư rai jêh ri lĕ roh, ƀiă lah du kô̆ tâm pe mra hôm e.$b$,false),
('bunong-vn','ZEC',13,9,null,$b$Gâp mra leo du kô̆ tâm pe nây ăn tâm ŭnh, gâp mra kret păng ăn kloh khân păng nâm bu ƀư kloh prăk, jêh ri rlong srŏng păng nâm bu srŏng mah; khân păng mra vơh vơl amoh gâp, jêh ri gâp mra plơ̆ lah ma khân păng. Gâp mra lah: Khân păng jêng phung ƀon lan gâp; jêh ri khân păng mra lah: Yêhôva jêng Brah Ndu mra gâp.$b$,false),
('bunong-vn','ZEC',14,1,null,$b$Aơ, nar Yêhôva lĕ tât, lĕ rngôch ndơ may bu pit in mra tâm pă ta nklang may.$b$,true),
('bunong-vn','ZEC',14,2,null,$b$Yor nây gâp mra tâm rgum lĕ rngôch bri dak tâm lơh đak ƀon Yêrusalem, bu mra sŏk gro ƀon, jêh ri pit in ndô ndơ tâm ngih vâl jêh ri phung bu ur bu mra tom, n'gul ƀon mra hăn ƀư bună; ƀiă lah phung ƀon lan hôm e bu mâu mprơh ngluh ôh tă bơh ƀon.$b$,false),
('bunong-vn','ZEC',14,3,null,$b$Rnôk nây Yêhôva mra hăn tâm lơh đah phung ntil mpôl bunuyh nây, nâm bu Păng hŏ lơh jêh tâm nar tâm lơh.$b$,true),
('bunong-vn','ZEC',14,4,null,$b$Tâm nar nây, jâng Păng mra dâk ta klơ yôk Ôlivơ, jêng yôk tâm tra ƀon Yêrusalem mpeh pa lơ; jêh ri yôk Ôlivơ mra đang ta nklang tă bơh pa lơ tât mơ pa dâng, kŏ tât jêng rlŭng toyh ngăn; pô nây n'gul yôk trơn tĭt mpeh rđŭng.$b$,false),
('bunong-vn','ZEC',14,5,null,$b$Khân may mra nchuăt du tâm rlŭng yôk, yor lah rlŭng yôk nây jong mra tât ta ntŭk Asel. Khân may nchuăt du nâm bu khân may hŏ nchuăt jêh nôk n'găr neh ntu tâm rnôk rô̆ Y-Usia hađăch n'gor Yuđa. Rnôk nây Yêhôva Brah Ndu gâp mra văch, jêh ri phung kloh ueh ndrel ma păng.$b$,true),
('bunong-vn','ZEC',14,6,null,$b$Ta nar nây mâu mra geh nau ang ôh, mâu lĕ geh nau ji kăt mâu lah glo pler.$b$,false),
('bunong-vn','ZEC',14,7,null,$b$Yor lah nar nây mra geh knŏng du nar dơm nâm bu nây-mâu lĕ nôk nar, mâu lĕ măng, ƀiă lah nau tât kêng mhaơ mra geh nau ang.$b$,false),
('bunong-vn','ZEC',14,8,null,$b$Ta nar nây, dak rêh mra hoch tă bơh ƀon Yêrusalem, n'gul hoch leo mpeh dak mƀŭt pa lơ, jêh ri n'gul hoch mpeh dak mƀŭt pa dâng; mra geh da dê tâm yan ta vai jêh ri yan sĭt puh.$b$,false),
('bunong-vn','ZEC',14,9,null,$b$Yêhôva mra jêng hađăch ma lĕ neh ntu; tâm nar nây, mra geh knŏng du huê Yêhôva, jêh ri amoh Păng tâm ban lĕ knŏng geh nguay dơm.$b$,true),
('bunong-vn','ZEC',14,10,null,$b$Lĕ n'gor bri rlơ̆ jêng neh lâng ntơm bơh ƀon Gêba tât ta ƀon Rimôn mpeh rđŭng ƀon Yêrusalem. Ƀiă lah ƀon Yêrusalem mra n'hao klơ gŭ ta ntŭk ơm păng, ntơm bơh mpông pêr Benjamin kŏ tât ntŭk tal nguay, jêh ri tât mpông pêr Njônh, jêh ri ntơm bơh vâl tŭm Hananel tât ta ntŭk bu kĭn đak play kriăk ƀâu hađăch.$b$,false),
('bunong-vn','ZEC',14,11,null,$b$Bu mra gŭ ta nây, păng mâu geh nau rak rtăp đŏng ôh, ƀiă lah ƀon Yêrusalem mra gŭ đăp rmên.$b$,true),
('bunong-vn','ZEC',14,12,null,$b$Yor ri, aơ mra jêng nau rêh ni Yêhôva ƀư ma lĕ rngôch phung ƀon lan tâm lơh đah ƀon Yêrusalem: Nglay săk khân păng mra ôm dôl khân păng hôm đak, măt khân păng ôm tâm trôm ndăr păng, mpiăt khân păng ôm tâm trôm mbung păng.$b$,true),
('bunong-vn','ZEC',14,13,null,$b$Tâm nar nây, Yêhôva mra srih nau rŭng răng toyh tâm khân păng; pô ri ăp nơm mra kuăn ta ti băl păng, jêh ri khân păng tâm lơh ndrăng khân păng nơm.$b$,true),
('bunong-vn','ZEC',14,14,null,$b$Nđâp ma phung Yuđa đŏng tâm lơh ta ƀon Yêrusalem. Jêh ri lĕ rngôch drăp ndơ phung mpôl bunuyh chiau meng mra rgum du ntŭk ta nây: Mah, prăk jêh ri phung ao jâr âk ngăn.$b$,true),
('bunong-vn','ZEC',14,15,null,$b$Geh nau ji nkhĭt tâm ban lĕ ma phung seh, seh bri, seh samô, jêh ri lĕ rngôch mpô mpa tâm nkual ta han.$b$,false),
('bunong-vn','ZEC',14,16,null,$b$Rnôk nây lĕ rngôch phung hôm klen tâm lĕ ntil mpôl bunuyh lĕ tă lơh jêh ƀon Yêrusalem, mra hăn hao ta nây ăp năm gay yơk mbah ma hađăch, jêng Yêhôva phung ta han, jêh ri văch râng kah gĭt Nau Năng Vâl Ndưp.$b$,false),
('bunong-vn','ZEC',14,17,null,$b$Tâm lĕ phung mpôl băl bunuyh, ta neh ntu mâu văch tât ôh ma ƀon Yêrusalem gay yơk mbah ma Hađăch, jêng Yêhôva phung ta han, pô ri mâu mra geh ôh dak mih ma khân păng.$b$,true),
('bunong-vn','ZEC',14,18,null,$b$Tơ lah mpôl băl Êjipt mâu hăn hao ôh jêh ri văch tât ta nây tâm ban lĕ dak mih mâu geh ôh ma khân păng; jêh ri khân păng mra geh nau ji nkhĭt aơ, jêng nau ji nkhĭt bơh Yêhôva hŏ ƀư gay tâm rmal lĕ ntil mpôl bunuyh mâu hăn hao râng kah gĭt prăp Nau Năng Vâl Ndưp.$b$,false),
('bunong-vn','ZEC',14,19,null,$b$Nây jêng nau tâm rmal ma n'gor Êjipt jêh ri âk n'gor bri êng mra dơn. Tơ lah khân păng mâu hăn hao râng kah gĭt Nau Năng Vâl Ndưp$b$,true),
('bunong-vn','ZEC',14,20,null,$b$Ta nar nây mra geh nau chih ta nteng neng seh: KLOH UEH MA YÊHÔVA Jêh ri glah tâm ngih Yêhôva tâm ban ma ngan ta klơ nơng ƀư brah.$b$,false),
('bunong-vn','ZEC',14,21,null,$b$Lĕ rngôch glah tâm ƀon Yêrusalem jêh ri tâm n'gor Yuđa mra jêng ndơ kloh ueh prăp ăn ma Yêhôva phung ta han; gay ma mbu nơm nhhơr ndơ ƀư brah dơi văch, sŏk glah gâm; jêh ri tâm nar nây, mâu hôm geh bunuyh Kanaan ôh tâm ngih Yêhôva phung ta han.$b$,false);
